(window.BUNKAZAI_DETAIL=window.BUNKAZAI_DETAIL||{})["学校"]=[{"id":"00004685","register_sub_id":"101","register_pk":"105675","name":"遺愛学院（旧遺愛女学校）謝恩館","kana":"いあいがくいん（きゅういあいじょがっこう）しゃおんかん","category":"学校","subcategory":"建築物","type_guess":"記念館・資料室","type_guess_confidence":"high","period":"大正","pref":"北海道","address":"北海道函館市杉並町64-1","lat":41.787235,"lng":140.757645,"geo_status":"db","era":"大正11／昭和36増築","year":1922,"year_source":"db","year_min":1922,"year_max":1922,"year_label":null,"structure":"木造2階建、亜鉛メッキ鋼板葺、建築面積202㎡","structure_material":"木造2階建","registered":"2005.07.12(平成17.07.12)","register_no":"01 － 0063","desc":"遺愛学院本館の正面左手前に渡廊下で接続する木造２階建で，屋根は寄棟造の鉄板葺である。焼過煉瓦の基礎に建ち，外壁は柱形付の下見板張で，腰を縦羽目板張とする。胴蛇腹と引違いの連窓で水平線を強調している。本館と調和のとれた外観を呈している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004685"},{"id":"00002734","register_sub_id":"101","register_pk":"103724","name":"遺愛学院講堂","kana":"いあいがくいんこうどう","category":"学校","subcategory":"建築物","type_guess":"講堂","type_guess_confidence":"high","period":"昭和前","pref":"北海道","address":"北海道函館市杉並町64-1","lat":41.787518,"lng":140.757172,"geo_status":"db","era":"昭和10","year":1935,"year_source":"db","year_min":1935,"year_max":1935,"year_label":null,"structure":"木造平屋一部2階建、亜鉛葺、建築面積467㎡","structure_material":"木造平屋一部2階建","registered":"2002.06.25(平成14.06.25)","register_no":"01 － 0049","desc":"ヴォーリズ建築事務所の設計。本館内にあった既存講堂が手狭になったため，宣教師からの寄付金を基に建てられた。切妻造，亜鉛板葺で，正面にポーチを設けて入口とするほか，背面側で本館と廊下を介して接続している。過度に装飾を設けない簡素な外観が特色。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002734"},{"id":"00006962","register_sub_id":"101","register_pk":"107944","name":"星槎大学（旧頼城小学校）校舎","kana":"せいさだいがく（きゅうらいじょうしょうがっこう）こうしゃ","category":"学校","subcategory":"建築物","type_guess":"校舎","type_guess_confidence":"high","period":"昭和中","pref":"北海道","address":"北海道芦別市緑泉町5-14他","lat":43.4594,"lng":142.166153,"geo_status":"db","era":"昭和29／31・32増築・平成15改修","year":1954,"year_source":"db","year_min":1954,"year_max":1954,"year_label":null,"structure":"煉瓦造一部鉄筋コンクリート造2階建、鉄板葺、建築面積2232㎡","structure_material":"煉瓦造一部鉄筋コンクリート造2階建","registered":"2008.03.07(平成20.03.07)","register_no":"01 － 0095","desc":"煉瓦造２階建の学校建築である。西向きに玄関を開く職員室棟から東へ片廊下の北教室棟が延び、職員室棟の南にも片廊下の南教室棟が丁字形に接続する。屋根は寄棟造鉄板葺で、内・外壁とも煉瓦のイギリス積とする。１００ｍを超える長大な北教室棟は壮観である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006962"},{"id":"00006770","register_sub_id":"101","register_pk":"107752","name":"星槎大学（旧頼城小学校）体育館","kana":"せいさだいがく（きゅうらいじょうしょうがっこう）たいいくかん","category":"学校","subcategory":"建築物","type_guess":"体育館","type_guess_confidence":"high","period":"昭和中","pref":"北海道","address":"北海道芦別市緑泉町5-14他","lat":43.459724,"lng":142.166489,"geo_status":"db","era":"昭和29／平成15改修","year":1954,"year_source":"db","year_min":1954,"year_max":1954,"year_label":null,"structure":"木造平屋建、鉄板葺、建築面積757㎡","structure_material":"木造平屋建","registered":"2008.03.07(平成20.03.07)","register_no":"01 － 0096","desc":"職員室棟の北に渡り廊下で接続する木造平屋建の東西棟。屋根は切妻造の鉄板葺である。外壁は腰を鎧下見板張、上部をモルタル塗とし、上下２段に窓を開く。内部は東端にステージと器具庫、西端に物入を設ける。２ヒンジ・トラスの木造小屋組に構造美を見せる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006770"},{"id":"00001543","register_sub_id":"101","register_pk":"102533","name":"北海道教育大学函館校北方教育資料室（旧函館師範学校）","kana":"ほっかいどうきょういくだいがくはこだてこうほっぽうきょういくしりょうしつ（きゅうはこだてしはんがっこう）","category":"学校","subcategory":"建築物","type_guess":"記念館・資料室","type_guess_confidence":"high","period":"大正","pref":"北海道","address":"北海道函館市八幡町1-2","lat":41.793823,"lng":140.740448,"geo_status":"db","era":"大正3","year":1914,"year_source":"db","year_min":1914,"year_max":1914,"year_label":null,"structure":"木造2階建、瓦葺、建築面積320㎡","structure_material":"木造2階建","registered":"2000.04.28(平成12.04.28)","register_no":"01 － 0022","desc":"もと函館師範学校本館の中央部分を保存したもの。木造，２階建，下見板張で，正面中央に３階建のランタン付塔屋を建ち上げ，前面に切妻造の車寄を突出させる。全体骨格は明治調であるが，細部には大正期の簡略化された意匠が認められる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001543"},{"id":"00001541","register_sub_id":"101","register_pk":"102531","name":"北海道大学旧札幌農学校昆虫及養蚕学教室","kana":"ほっかいどうだいがくきゅうさっぽろのうがっこうこんちゅうおよびようさんがくきょうしつ","category":"学校","subcategory":"建築物","type_guess":"校舎","type_guess_confidence":"high","period":"明治","pref":"北海道","address":"北海道札幌市北区北9条西8丁目","lat":43.0709984,"lng":141.34250468,"geo_status":"db","era":"明治34","year":1901,"year_source":"db","year_min":1901,"year_max":1901,"year_label":null,"structure":"木造平屋建、鉄板葺、建築面積397㎡","structure_material":"木造平屋建","registered":"2000.04.28(平成12.04.28)","register_no":"01 － 0020","desc":"旧札幌農学校キャンパス内の東南端に位置したⅠ字型平面を持つ木造平屋建の建物。漆喰塗大壁造で，上げ下げ硝子窓が左右対称に配される。ピラスターとペディメントで構成される正面中央部が，寄棟屋根の両翼部と対照的に正面性を強調する。設計は中條精一郎。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001541"},{"id":"00001649","register_sub_id":"101","register_pk":"102639","name":"北海道大学旧札幌農学校図書館書庫","kana":"ほっかいどうだいがくきゅうさっぽろのうがっこうとしょかんしょこ","category":"学校","subcategory":"建築物","type_guess":"図書館","type_guess_confidence":"high","period":"明治","pref":"北海道","address":"北海道札幌市北区北9条西8丁目","lat":43.0711992,"lng":141.34174935,"geo_status":"db","era":"明治35","year":1902,"year_source":"db","year_min":1902,"year_max":1902,"year_label":null,"structure":"煉瓦造2階建、建築面積119㎡","structure_material":"煉瓦造2階建","registered":"2000.04.28(平成12.04.28)","register_no":"01 － 0025","desc":"中條精一郎により設計された札幌農学校新キャンパスの施設である図書館の書庫。煉瓦造２階建、切妻造の倉庫建築であるが、腰積に焼過煉瓦を用い、コーナーの要所に石を配し、妻の笠石をステップ状に積むなど細やかな造型的・構造的処理が認められる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001649"},{"id":"00001542","register_sub_id":"101","register_pk":"102532","name":"北海道大学旧札幌農学校図書館読書室","kana":"ほっかいどうだいがくきゅうさっぽろのうがっこうとしょかんどくしょしつ","category":"学校","subcategory":"建築物","type_guess":"図書館","type_guess_confidence":"high","period":"明治","pref":"北海道","address":"北海道札幌市北区北9条西8丁目","lat":43.07104109,"lng":141.34180213,"geo_status":"db","era":"明治35／昭和27増築","year":1902,"year_source":"db","year_min":1902,"year_max":1902,"year_label":null,"structure":"木造平屋建、鉄板葺、建築面積467㎡","structure_material":"木造平屋建","registered":"2000.04.28(平成12.04.28)","register_no":"01 － 0021","desc":"Ｔ字型平面を持つ木造平屋建の図書館閲覧棟。手前に張り出す棟には，２つの頂塔が載り，側面には三角・櫛形ペディメント付きの窓が交互に配置される。現キャンパスに移転した時のもので，旧昆虫及養蚕学教室とともに現位置に遺る。中條精一郎の設計。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001542"},{"id":"00001544","register_sub_id":"101","register_pk":"102534","name":"北海道大学農学部附属苫小牧地方演習林森林記念館（旧標本貯蔵室）","kana":"ほっかいどうだいがくのうがくぶふぞくとまこまいちほうえんしゅうりんしんりんきねんかん（きゅうひょうほんちょぞうしつ）","category":"学校","subcategory":"建築物","type_guess":"記念館・資料室","type_guess_confidence":"high","period":"昭和前","pref":"北海道","address":"北海道苫小牧市字高丘無番地","lat":42.67712887,"lng":141.59763375,"geo_status":"db","era":"昭和10","year":1935,"year_source":"db","year_min":1935,"year_max":1935,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積119㎡","structure_material":"木造平屋建","registered":"2000.04.28(平成12.04.28)","register_no":"01 － 0023","desc":"苫小牧演習林のもと標本貯蔵室。木造平屋建，バットレス付下見板張，切妻造の教会堂風建築の背後に，駒形屋根の牧畜舎風建築を配する。屋根窓の３連の連続窓や，側面バットレス間の横長窓などに時代的な特徴があらわれている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001544"},{"id":"00001540","register_sub_id":"101","register_pk":"102530","name":"北海道大学附属植物園庁舎（旧札幌農学校動植物学教室）","kana":"ほっかいどうだいがくふぞくしょくぶつえんちょうしゃ（きゅうさっぽろのうがっこうどうしょくぶつがくきょうしつ）","category":"学校","subcategory":"建築物","type_guess":"校舎","type_guess_confidence":"high","period":"明治","pref":"北海道","address":"北海道札幌市中央区北3条西8丁目","lat":43.06394736,"lng":141.34428132,"geo_status":"db","era":"明治34／昭和17移築","year":1901,"year_source":"db","year_min":1901,"year_max":1901,"year_label":null,"structure":"木造2階建、鉄板葺、建築面積132㎡","structure_material":"木造2階建","registered":"2000.04.28(平成12.04.28)","register_no":"01 － 0019","desc":"旧札幌農学校キャンパス内にあったⅠ字型平面からなる動植物講堂の東翼部を移築したもの。木造２階建，漆喰塗大壁。入口はピラスターとモディリオンに支えられた三角ペディメントで飾られる。当時文部省建築掛札幌出張所長の中條精一郎による設計。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001540"},{"id":"00000282","register_sub_id":"101","register_pk":"101272","name":"北海道大学古河記念講堂（旧東北帝国大学農科大学林学科教室）","kana":"ほっかいどうだいがくふるかわきねんこうどう（きゅうとうほくていこくだいがくのうかだいがくりんがくかきょうしつ）","category":"学校","subcategory":"建築物","type_guess":"校舎","type_guess_confidence":"high","period":"明治","pref":"北海道","address":"北海道札幌市北区北9条西7","lat":43.07126814,"lng":141.34359488,"geo_status":"db","era":"明治42","year":1909,"year_source":"db","year_min":1909,"year_max":1909,"year_label":null,"structure":"木造2階建，鉄板葺，建築面積414㎡","structure_material":"木造2階建","registered":"1997.09.03(平成9.09.03)","register_no":"01 － 0003","desc":"中央に入口を設け，左右に翼部を伸ばすルネッサンス様式の建築である。設計は文部省技師の新山平四郎。総２階建で，マンサード屋根をかけ，中央部にかつては時鐘が取りつけられていた小塔が設けられており，全体に簡素ではあるがまとまった意匠を示す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000282"},{"id":"00001222","register_sub_id":"101","register_pk":"102212","name":"北上市立博物館付属民俗資料館（旧黒沢尻実科高等女学校校舎）","kana":"きたかみしりつはくぶつかんふぞくみんぞくしりょうかん（きゅうくろさわじりじつかこうとうじょがっこうこうしゃ）","category":"学校","subcategory":"建築物","type_guess":"校舎","type_guess_confidence":"high","period":"昭和前","pref":"岩手県","address":"岩手県北上市立花14地割52","lat":39.269711,"lng":141.129776,"geo_status":"db","era":"昭和2／昭和52移築","year":1927,"year_source":"db","year_min":1927,"year_max":1927,"year_label":null,"structure":"木造２階建，スレート葺，建築面積456㎡","structure_material":"木造２階建","registered":"1999.08.23(平成11.08.23)","register_no":"03 － 0020","desc":"木造２階建、切妻屋根の学校建築。外装の基調は白色下見板貼で、階上階下の腰を竪羽目とし、階上中央部を黒色ドイツ壁とする。昭和期の竣工であるが、端部妻のハンマービーム風の収まり、開口部のペジメントなどに明治建築の面影を色濃く残す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001222"},{"id":"00012086","register_sub_id":"101","register_pk":"352885","name":"旧上有住小学校校舎","kana":"きゅうかみありすしょうがっこう","category":"学校","subcategory":"建築物","type_guess":"校舎","type_guess_confidence":"high","period":"昭和前","pref":"岩手県","address":"岩手県気仙郡住田町上有住字山脈地15-1","lat":39.197775,"lng":141.588165,"geo_status":"db","era":"昭和3年／昭和59年曳家・同60年改修","year":1928,"year_source":"db","year_min":1928,"year_max":1928,"year_label":null,"structure":"木造2階建、瓦葺一部金属板葺、建築面積459㎡","structure_material":"木造2階建","registered":"2018.03.27(平成30.03.27)","register_no":"03-106","desc":"昭和初期の小学校校舎。木造二階建、桟瓦葺で、正面中央部のみ鉄板葺とする。外壁は下見板張で、上部はドイツ壁とし、柱型を塗り分けて強調する洋風意匠でまとめている。中心にポーチを配して左右に延びる対称性の強い構成で、木造小学校校舎の好例である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012086"},{"id":"00013917","register_sub_id":"101","register_pk":"508177","name":"旧制第二高等学校正門","kana":"きゅうせいだいにこうとうがっこうせいもん","category":"学校","subcategory":"その他工作物","type_guess":"正門","type_guess_confidence":"high","period":"明治","pref":"宮城県","address":"宮城県仙台市青葉区片平二丁目1-1","lat":38.25244722,"lng":140.87287778,"geo_status":"db","era":"明治22年頃／昭和11年・同20年・同25年・同43年、平成8年移築","year":1889,"year_source":"db","year_min":1889,"year_max":1889,"year_label":null,"structure":"煉瓦造、間口4.4m、両脇門柱付","structure_material":"煉瓦造","registered":"2021.10.14(令和3.10.14)","register_no":"04 - 0205","desc":"東北大学正門から南約一〇〇メートルに所在する門。旧制第二高等学校校舎と共に設計。化粧煉瓦積角柱の上部に四角錐の笠石を載せる、間口四・四メートルの門柱二基。同形で一回り小さい脇門柱二基が立つ。移転を重ねたが、当初位置近くに旧観を取り戻した。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013917"},{"id":"00011844","register_sub_id":"101","register_pk":"211033","name":"旧仙台医学専門学校博物・理化学教室（東北大学本部棟３）","kana":"きゅうせんだいいがくせんもんがっこうはくぶつ・りかがくきょうしつ（とうほくだいがくほんぶとう３）","category":"学校","subcategory":"建築物","type_guess":"校舎","type_guess_confidence":"high","period":"明治","pref":"宮城県","address":"宮城県仙台市青葉区片平二丁目1-1","lat":38.254366,"lng":140.873492,"geo_status":"db","era":"明治37年／大正13年頃・昭和2年頃・同10年頃・同中期・平成17年改修","year":1904,"year_source":"db","year_min":1904,"year_max":1904,"year_label":null,"structure":"木造平屋建、瓦葺一部鋼板葺、建築面積504㎡","structure_material":"木造平屋建","registered":"2017.10.27(平成29.10.27)","register_no":"04-139","desc":"東北大学片平キャンパス内に所在する。木造平屋建、寄棟造、瓦葺一部銅板葺で、北を正面とする東西棟と、その東に接続する南北棟部分からなる。外壁は下見板張。内部は北側に片廊下を通し、南側に諸室を配す。キャンパス草創期の景観を今に伝える建物である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011844"},{"id":"00011845","register_sub_id":"101","register_pk":"211034","name":"旧仙台医学専門学校六号教室（東北大学魯迅の階段教室）","kana":"きゅうせんだいいがくせんもんがっこうろくごうきょうしつ（とうほくだいがくろじんのかいだんきょうしつ）","category":"学校","subcategory":"建築物","type_guess":"校舎","type_guess_confidence":"high","period":"明治","pref":"宮城県","address":"宮城県仙台市青葉区片平二丁目1-1","lat":38.254155,"lng":140.873398,"geo_status":"db","era":"明治37年／大正13年頃・昭和10年頃移築","year":1904,"year_source":"db","year_min":1904,"year_max":1904,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積138㎡","structure_material":"木造平屋建","registered":"2017.10.27(平成29.10.27)","register_no":"04-140","desc":"当初博物・理化学教室の東側に接して建っていたものが、二度の移築を経て向きを変え現在地に建っているもの。木造平屋建、桟瓦葺で、西を寄棟造、東を切妻造とする。内部は一室の階段教室とし、東側に講壇を設ける。明治期に遡る木造高等教育施設の好例。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011845"},{"id":"00013915","register_sub_id":"101","register_pk":"508175","name":"旧仙台高等工業学校建築学科棟","kana":"きゅうせんだいこうとうこうぎょうがっこうけんちくがっかとう","category":"学校","subcategory":"建築物","type_guess":"校舎","type_guess_confidence":"low","period":"昭和前","pref":"宮城県","address":"宮城県仙台市青葉区片平二丁目1-3","lat":38.25039444,"lng":140.87631111,"geo_status":"db","era":"昭和5年／平成26年改修","year":1930,"year_source":"db","year_min":1930,"year_max":1930,"year_label":null,"structure":"鉄筋コンクリート造3階建、建築面積480㎡","structure_material":"鉄筋コンクリート造3階建","registered":"2021.10.14(令和3.10.14)","register_no":"04 - 0203","desc":"鉄筋コンクリート造三階建。スクラッチタイル貼に横長の連続窓を開け、壁面を張出すバウハウスに連なる外観。階段室は階段勾配に沿ってアーチ窓を開く。ヴォールトの通路を通し、アーチにＳＫＫの学章を付す。内部は片廊下式。前衛的な意匠が印象的な校舎。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013915"},{"id":"00011846","register_sub_id":"101","register_pk":"211035","name":"旧第二高等学校書庫（東北大学文化財収蔵庫）","kana":"きゅうだいにこうとうがっこうしょこ（とうほくだいがくぶんかざいしゅうぞうこ）","category":"学校","subcategory":"建築物","type_guess":"図書館","type_guess_confidence":"high","period":"明治","pref":"宮城県","address":"宮城県仙台市青葉区片平二丁目1-1","lat":38.253001,"lng":140.874232,"geo_status":"db","era":"明治43年／平成24年改修","year":1910,"year_source":"db","year_min":1910,"year_max":1910,"year_label":null,"structure":"煉瓦造3階建、瓦葺、建築面積83㎡","structure_material":"煉瓦造3階建","registered":"2017.10.27(平成29.10.27)","register_no":"04-141","desc":"片平キャンパスの中程に建つ。煉瓦造三階建、寄棟造桟瓦葺。基礎部と各階腰部に褐色の煉瓦を水平に廻し、軒にはデンティルをつけ、四隅及び側背面の壁体中間に付柱を張出す。内部床組は木造独立柱で支える。当時書庫が重視されていたことを示す、煉瓦造の書庫。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011846"},{"id":"00005820","register_sub_id":"101","register_pk":"106807","name":"旧月立小学校校舎","kana":"きゅうつきだてしょうがっこうこうしゃ","category":"学校","subcategory":"建築物","type_guess":"校舎","type_guess_confidence":"high","period":"大正","pref":"宮城県","address":"宮城県気仙沼市塚沢72","lat":38.95229302,"lng":141.5194695,"geo_status":"db","era":"大正11年／昭和16年増築","year":1922,"year_source":"db","year_min":1922,"year_max":1922,"year_label":null,"structure":"木造2階建、瓦葺、建築面積573㎡","structure_material":"木造2階建","registered":"2007.07.31(平成19.07.31)","register_no":"04 － 0063","desc":"校庭北部に建つ，横一文字型，北廊下式の校舎。建築面積５７３㎡，木造２階建，東端は寄棟造，西端は切妻造，桟瓦葺。正面中央に玄関ポーチ，屋根には大きな切妻破風を設けて特徴付け，外観をスティックスタイルとする。県内でも数少ない木造校舎建築のひとつ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005820"},{"id":"00013913","register_sub_id":"101","register_pk":"508173","name":"旧東北帝国大学工学部機械学及び電気学教室","kana":"きゅうとうほくていこくだいがくこうがくぶきかいがくおよびでんきがくきょうしつ","category":"学校","subcategory":"建築物","type_guess":"校舎","type_guess_confidence":"high","period":"昭和前","pref":"宮城県","address":"宮城県仙台市青葉区片平二丁目1-1","lat":38.25321111,"lng":140.87585,"geo_status":"db","era":"昭和5年／平成19年改修","year":1930,"year_source":"db","year_min":1930,"year_max":1930,"year_label":null,"structure":"鉄筋コンクリート造3階地下1階建、建築面積1，662㎡","structure_material":"鉄筋コンクリート造3階地下1階建","registered":"2021.10.14(令和3.10.14)","register_no":"04 - 0201","desc":"鉄筋コンクリート造地上三階地下一階建のＬ字型平面中廊下式校舎で階段ホール吹抜とする。外壁は上層をリシン仕上、下層を煉瓦タイル貼に塗装吹付とする。正面中央は玄関を突出させアーチを付し、外壁を石張として塔屋を掲げ、装飾を集中させて意匠を凝らす。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013913"},{"id":"00013914","register_sub_id":"101","register_pk":"508174","name":"旧東北帝国大学工学部機械学及び電気学実験室","kana":"きゅうとうほくていこくだいがくこうがくぶきかいがくおよびでんきがくじっけんしつ","category":"学校","subcategory":"建築物","type_guess":"校舎","type_guess_confidence":"high","period":"昭和前","pref":"宮城県","address":"宮城県仙台市青葉区片平二丁目1-1","lat":38.25276389,"lng":140.8757,"geo_status":"db","era":"昭和4年／平成25年改修","year":1929,"year_source":"db","year_min":1929,"year_max":1929,"year_label":null,"structure":"鉄筋コンクリート造2階建、建築面積397㎡","structure_material":"鉄筋コンクリート造2階建","registered":"2021.10.14(令和3.10.14)","register_no":"04 - 0202","desc":"鉄筋コンクリート造二階建の校舎で矩形平面中廊下式で教室を並べる。外壁は一階は煉瓦タイル貼にアーチ窓を並べ、二階はリシン仕上に矩形窓を並べる。ステンドグラスを掲げた玄関と階段を中央に配する。教室校舎と同様上下二層の色使いが目立ち意匠平明。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013914"},{"id":"00013918","register_sub_id":"101","register_pk":"508178","name":"旧東北帝国大学正門（東北大学正門）","kana":"きゅうとうほくていこくだいがくせいもん（とうほくだいがくせいもん）","category":"学校","subcategory":"その他工作物","type_guess":"正門","type_guess_confidence":"high","period":"大正","pref":"宮城県","address":"宮城県仙台市青葉区片平二丁目1-1","lat":38.25304722,"lng":140.87216111,"geo_status":"db","era":"大正15年／昭和40年代改修","year":1926,"year_source":"db","year_min":1926,"year_max":1926,"year_label":null,"structure":"鉄筋コンクリート造、間口6.3m、両脇門柱付","structure_material":"鉄筋コンクリート造","registered":"2021.10.14(令和3.10.14)","register_no":"04 - 0206","desc":"東北大学片平キャンパス西面に所在する門。鉄筋コンクリート造御影石張の角柱に、ペン先状の三角形の柱頭を載せ前後に柱形を付す。間口六・三メートルの門柱二基、同形式で縮小した脇柱を両脇に立てる。南本柱に東北大学の門標を付し、帝大の景観を留める。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013918"},{"id":"00011847","register_sub_id":"101","register_pk":"211036","name":"旧東北帝国大学附属図書館閲覧室（東北大学史料館）","kana":"きゅうとうほくていこくだいがくふぞくとしょかんえつらんしつ（とうほくだいがくしりょうかん）","category":"学校","subcategory":"建築物","type_guess":"図書館","type_guess_confidence":"high","period":"大正","pref":"宮城県","address":"宮城県仙台市青葉区片平二丁目1-1","lat":38.253475,"lng":140.873349,"geo_status":"db","era":"大正15年／昭和61年・平成25年・同26年改修","year":1926,"year_source":"db","year_min":1926,"year_max":1926,"year_label":null,"structure":"鉄筋コンクリート造2階一部地下1階及び3階建、瓦葺、建築面積569㎡、塔屋付","structure_material":"鉄筋コンクリート造2階一部地下1階及び3階建","registered":"2017.10.27(平成29.10.27)","register_no":"04-142","desc":"鉄筋コンクリート造で、北面中央に玄関を開き、一階に事務室等を配し、二階は大空間の閲覧室とする。外壁は腰部石張、一階化粧煉瓦張、二階は漆喰塗とし、一階窓はセグメンタルアーチ、二階窓は半円アーチでまとめる。ロマネスク風の意匠でまとめる図書館建築。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011847"},{"id":"00013912","register_sub_id":"101","register_pk":"508172","name":"旧東北帝国大学法文学部第二研究室","kana":"きゅうとうほくていこくだいがくほうぶんがくぶだいにけんきゅうしつ","category":"学校","subcategory":"建築物","type_guess":"校舎","type_guess_confidence":"high","period":"昭和前","pref":"宮城県","address":"宮城県仙台市青葉区片平二丁目1-1","lat":38.25313889,"lng":140.87343611,"geo_status":"db","era":"昭和2年／平成16年改修","year":1927,"year_source":"db","year_min":1927,"year_max":1927,"year_label":null,"structure":"鉄筋コンクリート造3階建、建築面積374㎡","structure_material":"鉄筋コンクリート造3階建","registered":"2021.10.14(令和3.10.14)","register_no":"04 - 0200","desc":"鉄筋コンクリート造三階建。正面中央を張出して玄関を設け、頂部に切妻破風を掲げ、アーチ窓、矩形窓を縦に並べ間に煉瓦タイルを矢筈に貼る。外壁は吹付仕上で二連の矩形窓を並べる。内部は中廊下式。窓枠を煉瓦で縁取るなどアクセントを付けた愛らしい校舎。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013912"},{"id":"00011848","register_sub_id":"101","register_pk":"211037","name":"旧東北帝国大学理学部化学教室棟（東北大学本部棟１）","kana":"きゅうとうほくていこくだいがくりがくぶかがくきょうしつとう（とうほくだいがくほんぶとう１）","category":"学校","subcategory":"建築物","type_guess":"校舎","type_guess_confidence":"high","period":"昭和前","pref":"宮城県","address":"宮城県仙台市青葉区片平二丁目1-1","lat":38.254126,"lng":140.87364,"geo_status":"db","era":"昭和7年／昭和10年増築、平成15年・同25年改修","year":1932,"year_source":"db","year_min":1932,"year_max":1932,"year_label":null,"structure":"鉄筋コンクリート造3階一部地下1階建、建築面積871㎡","structure_material":"鉄筋コンクリート造3階一部地下1階建","registered":"2017.10.27(平成29.10.27)","register_no":"04-143","desc":"鉄筋コンクリート造三階建で、背面側を廊下として正面側に諸室を配する。外壁は正面側を中心にスクラッチタイル貼とし、柱形を強調するなど垂直性の強いデザインが特徴で、特に中央玄関廻りは柱形を石張として荘重な外観を見せる。昭和初期の大学校舎の好例。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011848"},{"id":"00013911","register_sub_id":"101","register_pk":"508171","name":"旧東北帝国大学理学部生物学教室","kana":"きゅうとうほくていこくだいがくりがくぶせいぶつがくきょうしつ","category":"学校","subcategory":"建築物","type_guess":"校舎","type_guess_confidence":"high","period":"大正","pref":"宮城県","address":"宮城県仙台市青葉区片平二丁目1-5","lat":38.25531111,"lng":140.86968333,"geo_status":"db","era":"大正13年／平成7年・令和元年改修","year":1924,"year_source":"db","year_min":1924,"year_max":1924,"year_label":null,"structure":"鉄筋コンクリート造3階建、建築面積668㎡","structure_material":"鉄筋コンクリート造3階建","registered":"2021.10.14(令和3.10.14)","register_no":"04 - 0199","desc":"鋭角な敷地にＶ字形平面を持つ鉄筋コンクリート造三階建校舎。腰を石積風モルタル塗、上部を煉瓦タイル貼とし縦長窓を並べる。Ｖ字の頂点は円筒形の壁を立上げる。平面は片廊下式で研究室、講義室等を配置。プロポーションと細部装飾にバランスが取れた逸品。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013911"},{"id":"00013919","register_sub_id":"101","register_pk":"508179","name":"東北学院大学正門","kana":"とうほくがくいんだいがくせいもん","category":"学校","subcategory":"その他工作物","type_guess":"正門","type_guess_confidence":"high","period":"大正","pref":"宮城県","address":"宮城県仙台市青葉区土樋一丁目1","lat":38.25011389,"lng":140.87726111,"geo_status":"db","era":"大正15年／昭和60年改修","year":1926,"year_source":"db","year_min":1926,"year_max":1926,"year_label":null,"structure":"鉄筋コンクリート造、間口4.2m","structure_material":"鉄筋コンクリート造","registered":"2021.10.14(令和3.10.14)","register_no":"04 - 0207","desc":"校地北辺中央に位置。三角アーチの脇門二基を一対とした正門。鉄筋コンクリート造洗出に目地切りで石張にみせる。間口は四・二メートルで両開鉄扉を吊る。脇門はコーニスやデンティルで飾り、十字架にＴＧを重ねた校章を付す。歴史ある私学の表構えを形成。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013919"},{"id":"00010246","register_sub_id":"101","register_pk":"199020","name":"東北学院大学大学院棟（旧シュネーダー記念東北学院図書館）","kana":"とうほくがくいんだいがくだいがくいんとう（きゅうしゅねーだーきねんとうほくがくいんとしょかん）","category":"学校","subcategory":"建築物","type_guess":"図書館","type_guess_confidence":"high","period":"昭和中","pref":"宮城県","address":"宮城県仙台市青葉区土樋1-1","lat":38.249943,"lng":140.877647,"geo_status":"db","era":"昭和28年／昭和38年改修","year":1953,"year_source":"db","year_min":1953,"year_max":1953,"year_label":null,"structure":"鉄筋コンクリート造5階建、瓦葺、建築面積613㎡","structure_material":"鉄筋コンクリート造5階建","registered":"2014.12.19(平成26.12.19)","register_no":"04-0096","desc":"当初は各面二二メートルの正方形で北西隅に玄関ホール、西半を吹抜けの閲覧室、東半を各階書庫とする。階高を抑えた鉄筋コンクリート造五階建であるが、縦長窓を巧妙に配して三階建風にまとめ、均整のとれた外観とする。本館北東に西面し、学院の核を構成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010246"},{"id":"00010244","register_sub_id":"101","register_pk":"199018","name":"東北学院大学本館（旧東北学院専門部校舎）","kana":"とうほくがくいんだいがくほんかん（きゅうとうほくがくいんせんもんぶこうしゃ）","category":"学校","subcategory":"建築物","type_guess":"校舎","type_guess_confidence":"high","period":"大正","pref":"宮城県","address":"宮城県仙台市青葉区土樋1-1","lat":38.249686,"lng":140.877262,"geo_status":"db","era":"大正15年","year":1926,"year_source":"db","year_min":1926,"year_max":1926,"year_label":null,"structure":"鉄筋コンクリート造3階建、建築面積647㎡","structure_material":"鉄筋コンクリート造3階建","registered":"2014.12.19(平成26.12.19)","register_no":"04-0094","desc":"学院中興期の建築になる鉄筋コンクリート造三階建。東西に細長い中廊下式平面で北面し、正面中央を塔屋状につくり玄関ポーチを構える。外観は地元産の秋保石を張り、いわゆるカレッジ・ゴシック様式で端正にまとめる。キャンパスの象徴的存在として親しまれる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010244"},{"id":"00013916","register_sub_id":"101","register_pk":"508176","name":"本多記念館","kana":"ほんだきねんかん","category":"学校","subcategory":"建築物","type_guess":"記念館・資料室","type_guess_confidence":"high","period":"昭和前","pref":"宮城県","address":"宮城県仙台市青葉区片平二丁目1-5","lat":38.25503889,"lng":140.8726,"geo_status":"db","era":"昭和16年／平成6年改修","year":1941,"year_source":"db","year_min":1941,"year_max":1941,"year_label":null,"structure":"鉄筋コンクリート造3階地下1階建、建築面積689㎡","structure_material":"鉄筋コンクリート造3階地下1階建","registered":"2021.10.14(令和3.10.14)","register_no":"04 - 0204","desc":"鉄筋コンクリート造地上三階地下一階建。柱形を強調したタイル貼の外壁に矩形窓を並べる。装飾的な要素はほぼ持たないが、玄関車寄から前方に張出す大キャノピーは目を引く。玄関ホールから楕円平面の階段室には大理石を張る。明快な意匠が時代相を表す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013916"},{"id":"00011849","register_sub_id":"101","register_pk":"211038","name":"南三陸町民俗資料館","kana":"みなみさんりくちょうみんぞくしりょうかん","category":"学校","subcategory":"建築物","type_guess":"記念館・資料室","type_guess_confidence":"high","period":"大正","pref":"宮城県","address":"宮城県本吉郡南三陸町歌津字伊里前123","lat":38.719287,"lng":141.52292,"geo_status":"db","era":"大正12年／昭和26年移築、昭和32年増築","year":1923,"year_source":"db","year_min":1923,"year_max":1923,"year_label":null,"structure":"木造平屋一部2階建、瓦葺、建築面積411㎡","structure_material":"木造平屋一部2階建","registered":"2017.10.27(平成29.10.27)","register_no":"04-144","desc":"伊里前小学校の校舎として建てられ、昭和二六年に移築されたもの。平屋部分は正面側に廊下を通し、背面側に教室を配する。南寄りの二階部は増築で、一階は調理室、二階は床棚を備えた大広間で、船底天井とする。作法室を備えるなど学校建築の特色を示す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011849"},{"id":"00010245","register_sub_id":"101","register_pk":"199019","name":"ラーハウザー記念東北学院礼拝堂","kana":"らーはうざーきねんとうほくがくいんれいはいどう","category":"学校","subcategory":"建築物","type_guess":"講堂","type_guess_confidence":"high","period":"昭和前","pref":"宮城県","address":"宮城県仙台市青葉区土樋1-1","lat":38.249915,"lng":140.876876,"geo_status":"db","era":"昭和7年","year":1932,"year_source":"db","year_min":1932,"year_max":1932,"year_label":null,"structure":"鉄筋コンクリート造2階地下1階建、建築面積619㎡","structure_material":"鉄筋コンクリート造2階地下1階建","registered":"2014.12.19(平成26.12.19)","register_no":"04-0095","desc":"南北に長い鉄筋コンクリート造建築で、南に玄関とホール、Ｔ字形の礼拝堂の北に教壇を構え、両脇とホール二階をバルコニーとする。扁平尖頭アーチの縦長窓や笠付の柱形が垂直性を強調するカレッジ・ゴシック様式の外観で、本館とともに学院の核を構成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010245"},{"id":"00009118","register_sub_id":"101","register_pk":"164671","name":"旧鮎川小学校屋内運動場","kana":"きゅうあゆかわしょうがっこうおくないうんどうじょう","category":"学校","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"秋田県","address":"秋田県由利本荘市町村字鳴瀬台65-1","lat":39.33411757,"lng":140.06590965,"geo_status":"db","era":"昭和28年／平成3年改修","year":1953,"year_source":"db","year_min":1953,"year_max":1953,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積548㎡","structure_material":"木造平屋建","registered":"2012.02.23(平成24.02.23)","register_no":null,"desc":"北校舎棟と、昇降口を介して接続する。東西棟の切妻造桟瓦葺で西面に下屋を付設。建築面積548平方メートル。内部は高く広い空間で、西面にステージなどを設け、平側に大きく開口を設けて外光を取込む。東妻の灰色壁面に高く延びる白い柱列が印象的。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009118"},{"id":"00009119","register_sub_id":"101","register_pk":"164672","name":"旧鮎川小学校北校舎棟","kana":"きゅうあゆかわしょうがっこうきたこうしゃとう","category":"学校","subcategory":"建築物","type_guess":"校舎","type_guess_confidence":"high","period":"昭和前","pref":"秋田県","address":"秋田県由利本荘市町村字鳴瀬台65-1","lat":39.33382311,"lng":140.06576093,"geo_status":"db","era":"昭和28年／昭和50年・平成3年・平成9年改修","year":1953,"year_source":"db","year_min":1953,"year_max":1953,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積571㎡","structure_material":"木造平屋建","registered":"2012.02.23(平成24.02.23)","register_no":null,"desc":"屋内運動場と中央校舎棟の間に東西棟で建ち、切妻造桟瓦葺、平屋建である。北側廊下で、東端に図書館、西端に音楽室、その間に普通教室を並べる。教室北面は両端を出入口とし、その間は腰板壁と引違窓とする。長廊下に木製建具が連続し、穏やかな空間を演出する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009119"},{"id":"00009120","register_sub_id":"101","register_pk":"164673","name":"旧鮎川小学校中央校舎棟","kana":"きゅうあゆかわしょうがっこうちゅうおうこうしゃとう","category":"学校","subcategory":"建築物","type_guess":"校舎","type_guess_confidence":"high","period":"昭和前","pref":"秋田県","address":"秋田県由利本荘市町村字鳴瀬台65-1","lat":39.33362383,"lng":140.06585908,"geo_status":"db","era":"昭和28年／平成3年・平成9年改修","year":1953,"year_source":"db","year_min":1953,"year_max":1953,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積649㎡","structure_material":"木造平屋建","registered":"2012.02.23(平成24.02.23)","register_no":null,"desc":"校地の西寄りに建ち並ぶ校舎の中央に位置する。東西に長い切妻造桟瓦葺、建築面積649平方メートル。東面北側に玄関を設け、昇降口と渡廊下で南校舎棟と繋ぐ。北側を廊下とし、東から校長室や職員室、特別教室等を並べる。下見板張の外観が安らぎを与える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009120"},{"id":"00009121","register_sub_id":"101","register_pk":"164674","name":"旧鮎川小学校南校舎棟","kana":"きゅうあゆかわしょうがっこうみなみこうしゃとう","category":"学校","subcategory":"建築物","type_guess":"校舎","type_guess_confidence":"high","period":"昭和前","pref":"秋田県","address":"秋田県由利本荘市町村字鳴瀬台65-1","lat":39.33340968,"lng":140.06597211,"geo_status":"db","era":"昭和29年／平成3年・平成9年改修","year":1954,"year_source":"db","year_min":1954,"year_max":1954,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積651㎡","structure_material":"木造平屋建","registered":"2012.02.23(平成24.02.23)","register_no":null,"desc":"中央校舎棟を中心に、北校舎棟と対称位置に建つ。北面の昇降口と渡廊下で中央棟と接続し、左右対称の整然とした立面をもつ。小屋はキングポストトラス。教室の配置計画や構造など当時の状況を伝えるとともに、木の温もりを感じさせる良質な学校建築。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009121"},{"id":"00002348","register_sub_id":"101","register_pk":"103338","name":"旧男鹿市立加茂青砂小学校屋内体操場","kana":"きゅうおがしりつかもあおさしょうがっこうおくないたいそうじょう","category":"学校","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和中","pref":"秋田県","address":"秋田県男鹿市戸賀加茂青砂字山道添38","lat":39.90926459,"lng":139.73272938,"geo_status":"db","era":"昭和26","year":1951,"year_source":"db","year_min":1951,"year_max":1951,"year_label":null,"structure":"木造平屋建、鉄板葺、建築面積192㎡","structure_material":"木造平屋建","registered":"2001.10.12(平成13.10.12)","register_no":"05 － 0073","desc":"校舎の北西に接続して建つ。木造平屋建，切妻造，鉄板葺で，南東正面にもと校舎にあった玄関が移設されて取り付いている。外観は一部改められているが，内部は，梁間約１１ｍに及ぶキングポストトラスにより，柱を立てない大空間を造る。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002348"},{"id":"00002347","register_sub_id":"101","register_pk":"103337","name":"旧男鹿市立加茂青砂小学校校舎","kana":"きゅうおがしりつかもあおさしょうがっこうこうしゃ","category":"学校","subcategory":"建築物","type_guess":"校舎","type_guess_confidence":"high","period":"昭和前","pref":"秋田県","address":"秋田県男鹿市戸賀加茂青砂字山道添38","lat":39.909176,"lng":139.733002,"geo_status":"db","era":"昭和3","year":1928,"year_source":"db","year_min":1928,"year_max":1928,"year_label":null,"structure":"木造2階建、鉄板葺、建築面積299㎡","structure_material":"木造2階建","registered":"2001.10.12(平成13.10.12)","register_no":"05 － 0072","desc":"木造２階建，寄棟造，鉄板葺で，正面中央に切妻造の玄関，背面中央に下屋を設ける。１，２階とも背面側に廊下を配し，正面側に教室や職員室を並べる。下見板張りと大きく開いた連続窓によって構成される明快な外観は，集落の歴史的景観の核となっている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002347"},{"id":"00009893","register_sub_id":"101","register_pk":"196040","name":"桜丘会館","kana":"おうきゅうかいかん","category":"学校","subcategory":"建築物","type_guess":"記念館・資料室","type_guess_confidence":"low","period":"昭和前","pref":"福島県","address":"福島県いわき市平字桜町5-1","lat":37.06238111,"lng":140.88715945,"geo_status":"db","era":"昭和13／昭和27改修","year":1938,"year_source":"db","year_min":1938,"year_max":1938,"year_label":null,"structure":"木造2階建、瓦葺、建築面積168㎡","structure_material":"木造2階建","registered":"2014.04.25(平成26.04.25)","register_no":"07 － 0148","desc":"敷地南に位置する旧磐城高等女学校の図書館兼同窓会館。一階を図書館、二階を畳敷の教室とする本館と、西の生徒生活実習寮である新館からなる。モルタル塗の外壁に丸窓や欠円アーチの縦長窓、隅部に横長窓を付すなど、昭和前期における建築潮流の影響を示す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009893"},{"id":"00012279","register_sub_id":"101","register_pk":"531603","name":"旧福島県立相馬中学校講堂","kana":"きゅうふくしまけんりつそうまちゅうがっこうこうどう","category":"学校","subcategory":"建築物","type_guess":"講堂","type_guess_confidence":"high","period":"昭和前","pref":"福島県","address":"福島県相馬市中村字大手先57-1","lat":37.79448056,"lng":140.91424722,"geo_status":"db","era":"昭和8年／昭和42年増築、平成28年改修","year":1933,"year_source":"db","year_min":1933,"year_max":1933,"year_label":null,"structure":"木造平屋建、スレート葺、建築面積530㎡","structure_material":"木造平屋建","registered":"2018.05.10(平成30.05.10)","register_no":"07-184","desc":"現県立相馬高校の講堂。木造平屋建妻入で、正面に玄関を張出し、大屋根と玄関の大小二つの切妻屋根を重ね、窓廻りを幾何学模様の意匠で整える。外壁は下見板張で、腰に人造石を横使いで張り、水平性を強調する。旧制中学校構内の構成を伝える学校建築。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012279"},{"id":"00007445","register_sub_id":"101","register_pk":"108427","name":"長井市立長井小学校第一校舎","kana":"ながいしりつながいしょうがっこうだいいちこうしゃ","category":"学校","subcategory":"建築物","type_guess":"校舎","type_guess_confidence":"high","period":"昭和前","pref":"山形県","address":"山形県長井市ままの上1764他","lat":38.10777931,"lng":140.04234062,"geo_status":"db","era":"昭和8／平成元改修","year":1933,"year_source":"db","year_min":1933,"year_max":1933,"year_label":null,"structure":"木造2階建、瓦葺、建築面積1157㎡","structure_material":"木造2階建","registered":"2009.01.08(平成21.01.08)","register_no":"06 － 0111","desc":"市役所に隣接する敷地に建つ。桁行９３ｍ梁間１１ｍ規模で、切妻造桟瓦葺とする東西に長い木造総２階建の学校建築。切妻造妻入の正面玄関を中心とする左右対称の外観とし、階段など内部の造作もよく残す。スティックスタイルによる丁寧なつくりの木造校舎。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007445"},{"id":"00002501","register_sub_id":"101","register_pk":"103491","name":"山形市立第一小学校校舎","kana":"やまがたしりつだいいちしょうがっこうこうしゃ","category":"学校","subcategory":"建築物","type_guess":"校舎","type_guess_confidence":"high","period":"昭和前","pref":"山形県","address":"山形県山形市本町1-5-19","lat":38.25061945,"lng":140.33596872,"geo_status":"db","era":"昭和2","year":1927,"year_source":"db","year_min":1927,"year_max":1927,"year_label":null,"structure":"鉄筋コンクリート造3階建、建築面積1483㎡","structure_material":"鉄筋コンクリート造3階建","registered":"2001.11.20(平成13.11.20)","register_no":"06 － 0037","desc":"山形県初の鉄筋コンクリート造３階建の校舎。コの字型の左右対称の平面で，正面となる北面中央を４階建に相当する塔屋とし，１階に玄関ポーチを設ける。簡明な外観であるが，随所に表現主義やアールデコの細部をあしらい，校舎の風格をつくり出している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002501"},{"id":"00002502","register_sub_id":"101","register_pk":"103492","name":"山形市立第一小学校門柱及び柵","kana":"やまがたしりつだいいちしょうがっこうもんちゅうおよびさく","category":"学校","subcategory":"その他工作物","type_guess":"正門","type_guess_confidence":"high","period":"昭和前","pref":"山形県","address":"山形県山形市本町1-5-19","lat":38.25061307,"lng":140.33640708,"geo_status":"db","era":"昭和2","year":1927,"year_source":"db","year_min":1927,"year_max":1927,"year_label":null,"structure":"鉄筋コンクリート造、柵折曲り延長100m","structure_material":"鉄筋コンクリート造","registered":"2001.11.20(平成13.11.20)","register_no":"06 － 0038","desc":"校舎の正面にある。敷地の北側を画し，中央に門柱２基が建ち，その東西に長さ約１００ｍの塀が延びる。方形の門柱は高さ約２．６ｍで上部飾りをつけ，塀は腰から立ち上げた柱を鋼管で結ぶ形式。簡素なものであるが，要所にアールデコ等の細部を備えている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002502"},{"id":"00000119","register_sub_id":"101","register_pk":"101109","name":"米沢女子高等学校校舎","kana":"よねざわじょしこうとうがっこうこうしゃ","category":"学校","subcategory":"建築物","type_guess":"校舎","type_guess_confidence":"high","period":"昭和前","pref":"山形県","address":"山形県米沢市門東町1-1-72","lat":37.9078408,"lng":140.10980572,"geo_status":"db","era":"昭和10","year":1935,"year_source":"db","year_min":1935,"year_max":1935,"year_label":null,"structure":"木造2階建，瓦葺，建築面積1713㎡","structure_material":"木造2階建","registered":"1997.05.07(平成9.05.07)","register_no":"06 － 0004","desc":"総二階建Ｌ型平面になる校舎で，中央部に垂直線を強調した素朴な意匠の玄関を設ける。外壁は下見板張りのハーフティンバーとし，２階窓枠の下に気抜きの小窓等を設けてアクセントとする。昭和初期の学校建築の好例で，風格のある外観は市民に親しまれている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000119"},{"id":"00000561","register_sub_id":"101","register_pk":"101551","name":"宇都宮高校旧本館","kana":"うつのみやこうこうきゅうほんかん","category":"学校","subcategory":"建築物","type_guess":"記念館・資料室","type_guess_confidence":"low","period":"明治","pref":"栃木県","address":"栃木県宇都宮市滝の原3-5-70","lat":36.54020125,"lng":139.86429524,"geo_status":"db","era":"明治26","year":1893,"year_source":"db","year_min":1893,"year_max":1893,"year_label":null,"structure":"木造２階建，瓦葺，建築面積684㎡","structure_material":"木造２階建","registered":"1998.07.23(平成10.07.23)","register_no":"09 － 0003","desc":"寄棟造の大屋根を架けた県内最古の学校建築。１階は事務室・職員室・校長室など，２階は広い１室の講堂で，木材は日光杉並木の杉材を用いている。全国中学校建築のモデルになるとともに，「白亜館」の名で卒業生のみならず多くの市民に広く親しまれている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000561"},{"id":"00011632","register_sub_id":"101","register_pk":"210648","name":"宇都宮大学峰ヶ丘講堂（旧宇都宮高等農林学校講堂）","kana":"うつのみやだいがくみねがおかこうどう（きゅううつのみやこうとうのうりんがっこうこうどう）","category":"学校","subcategory":"建築物","type_guess":"講堂","type_guess_confidence":"high","period":"大正","pref":"栃木県","address":"栃木県宇都宮市峰町350","lat":36.550853,"lng":139.911914,"geo_status":"db","era":"大正13年／平成21年改修","year":1924,"year_source":"db","year_min":1924,"year_max":1924,"year_label":null,"structure":"木造平屋一部2階建、瓦葺、建築面積384㎡","structure_material":"木造平屋一部2階建","registered":"2017.06.28(平成29.06.28)","register_no":"09-0234","desc":"大学構内の北西に北面して建つ講堂。切妻造桟瓦葺妻入で外壁は柱形付下見板張とする。内部は正面に演台を据え側背面にギャラリーを廻らす。直線を強調した平坦な壁面や柱頭飾、天井の緩やかな円弧状アーチ飾りなど、セセッション的意匠で全体をまとめた優作。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011632"},{"id":"00003056","register_sub_id":"101","register_pk":"104046","name":"宇都宮白楊高校旧講堂","kana":"うつのみやはくようこうこうきゅうこうどう","category":"学校","subcategory":"建築物","type_guess":"講堂","type_guess_confidence":"high","period":"明治","pref":"栃木県","address":"栃木県宇都宮市今泉町2021","lat":36.56449248,"lng":139.91151897,"geo_status":"db","era":"明治36／昭和24・41移築","year":1903,"year_source":"db","year_min":1903,"year_max":1903,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積161㎡","structure_material":"木造平屋建","registered":"2003.01.31(平成15.01.31)","register_no":"09 － 0061","desc":"宇都宮駅東側に建設された旧栃木県立農学校の施設。木造平屋建，寄棟造，瓦葺で外装下見板張。背面に物置を張出し，各側面に６つの上げ下げ窓を密に配する。全体的に簡素ながら丁寧な造りで，折上げ支輪，竿縁天井など和風を意識した意匠を随所に見せる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003056"},{"id":"00003057","register_sub_id":"101","register_pk":"104047","name":"宇都宮白楊高校正門","kana":"うつのみやはくようこうこうせいもん","category":"学校","subcategory":"その他工作物","type_guess":"正門","type_guess_confidence":"high","period":"明治","pref":"栃木県","address":"栃木県宇都宮市今泉町2021","lat":36.562714,"lng":139.9104,"geo_status":"db","era":"明治36","year":1903,"year_source":"db","year_min":1903,"year_max":1903,"year_label":null,"structure":"石造、間口3.6m、左右通用門付","structure_material":"石造","registered":"2003.01.31(平成15.01.31)","register_no":"09 － 0062","desc":"構内の南端に位置する。３．６ｍ間隔で配された高さ２．７５ｍの石造門柱の左右に，高さ２．５ｍの石造門柱を設置し，通用門とする。石材はいずれも花崗岩江戸切り仕上げで，雨仕舞を考慮し頂部を錐形とする。往時の学舎の姿を知る上で欠かせない施設。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003057"},{"id":"00011262","register_sub_id":"101","register_pk":"209098","name":"旧粟野中学校校舎","kana":"きゅうあわのちゅうがっこうこうしゃ","category":"学校","subcategory":"建築物","type_guess":"校舎","type_guess_confidence":"high","period":"昭和中","pref":"栃木県","address":"栃木県鹿沼市口粟野1812","lat":36.523269,"lng":139.669034,"geo_status":"db","era":"昭和24／昭和35増築","year":1949,"year_source":"db","year_min":1949,"year_max":1949,"year_label":null,"structure":"木造2階建、瓦葺、建築面積755㎡","structure_material":"木造2階建","registered":"2016.11.29(平成28.11.29)","register_no":"09－0230","desc":"木造二階建、桁行七三メートルの長大な中学校校舎。片廊下式の平面で、地元の木材を使用し柱を抱合せ柱とするなど堅牢なつくりとする。外観は下見板張で木製ガラス窓を並べ、切妻造桟瓦葺屋根を載せる。保存状態も良く、林業で栄えた地域の歴史を伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011262"},{"id":"00013505","register_sub_id":"101","register_pk":"504869","name":"旧木幡小学校校舎","kana":"きゅうきばたしょうがっこうこうしゃ","category":"学校","subcategory":"建築物","type_guess":"校舎","type_guess_confidence":"high","period":"昭和前","pref":"栃木県","address":"栃木県芳賀郡茂木町大字木幡252","lat":36.5039,"lng":140.16263056,"geo_status":"db","era":"昭和9年","year":1934,"year_source":"db","year_min":1934,"year_max":1934,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積754㎡","structure_material":"木造平屋建","registered":"2021.02.04(令和3.02.04)","register_no":"09 － 0256","desc":"平屋建切妻造桟瓦葺の小学校校舎。長大な矩形の平面を持ち、北に片廊下を通して南に教室六室及び職員室を並べる。南面に開口を大きくとり漆喰塗の小壁に菱形の飾りをつける。正面中ほどの腰折破風のハーフチンバーの玄関が印象的な戦前に遡る木造校舎。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013505"},{"id":"00011265","register_sub_id":"101","register_pk":"209101","name":"旧本山小学校講堂","kana":"きゅうほんざんしょうがっこうこうどう","category":"学校","subcategory":"建築物","type_guess":"講堂","type_guess_confidence":"high","period":"昭和前","pref":"栃木県","address":"栃木県日光市足尾町上間藤16-1","lat":36.657983,"lng":139.448058,"geo_status":"db","era":"昭和15","year":1940,"year_source":"db","year_min":1940,"year_max":1940,"year_label":null,"structure":"木造平屋建、鉄板葺、建築面積308㎡","structure_material":"木造平屋建","registered":"2016.11.29(平成28.11.29)","register_no":"09－0233","desc":"上間藤市街地の松木川対岸の旧校地に建つ。切妻造平屋建の講堂で、校庭側の西を正面とする。正側面には縦長の窓を並べ、その間には木製バットレスを付す。妻壁は木骨を意匠的に配したハーフティンバー風の造りとする。足尾銅山の歴史を伝える遺構。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011265"},{"id":"00001557","register_sub_id":"101","register_pk":"102547","name":"栃木高校記念館（旧栃木県尋常中学校栃木分校本館）","kana":"とちぎこうこうきねんかん（きゅうとちぎけんじんじょうちゅうがっこうとちぎぶんこうほんかん）","category":"学校","subcategory":"建築物","type_guess":"記念館・資料室","type_guess_confidence":"high","period":"明治","pref":"栃木県","address":"栃木県栃木市入舟町12-4","lat":36.384098,"lng":139.730347,"geo_status":"db","era":"明治29","year":1896,"year_source":"db","year_min":1896,"year_max":1896,"year_label":null,"structure":"木造2階建、瓦葺、建築面積397㎡","structure_material":"木造2階建","registered":"2000.04.28(平成12.04.28)","register_no":"09 － 0024","desc":"栃木県尋常中学校栃木分校の本館として明治２９年に建設。木造２階建，寄棟造・桟瓦葺，外壁下見板張ペンキ塗とした全体に質素な形式であり，明治期の中学校建築の様相を示すが，階上には陸軍大演習時の明治・大正天皇の行在所が保存されている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001557"},{"id":"00000563","register_sub_id":"101","register_pk":"101553","name":"栃木高校記念図書館","kana":"とちぎこうこうきねんとしょかん","category":"学校","subcategory":"建築物","type_guess":"図書館","type_guess_confidence":"high","period":"大正","pref":"栃木県","address":"栃木県栃木市入舟町12-4","lat":36.38315281,"lng":139.73091876,"geo_status":"db","era":"大正3","year":1914,"year_source":"db","year_min":1914,"year_max":1914,"year_label":null,"structure":"木造２階建，瓦葺，建築面積224㎡","structure_material":"木造２階建","registered":"1998.07.23(平成10.07.23)","register_no":"09 － 0005","desc":"同窓会の記念事業として建てられ，１階が図書閲覧室，２階が和室の大広間になる。１階平面は凸型になり，玄関ポーチの装飾を巧みに強調している。当時の専用図書館として珍しいだけでなく，瀟洒ながら全体に均衡のとれた意匠を持つところに特徴がある。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000563"},{"id":"00000562","register_sub_id":"101","register_pk":"101552","name":"栃木高校講堂","kana":"とちぎこうこうこうどう","category":"学校","subcategory":"建築物","type_guess":"講堂","type_guess_confidence":"high","period":"明治","pref":"栃木県","address":"栃木県栃木市入舟町12-4","lat":36.38326063,"lng":139.73010651,"geo_status":"db","era":"明治43","year":1910,"year_source":"db","year_min":1910,"year_max":1910,"year_label":null,"structure":"木造平屋建，瓦葺，建築面積409㎡","structure_material":"木造平屋建","registered":"1998.07.23(平成10.07.23)","register_no":"09 － 0004","desc":"木造平屋建の講堂建築。外観は上部半円型のルネッサンス風の窓が連続し，軒廻りの持送りや小壁の装飾と相俟って造形美のある意匠となっている。広い内部も，白漆喰の天井や飾り柱を備えた演壇廻りの本格的な細部意匠に，時代の特徴がよくあらわれている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000562"},{"id":"00000564","register_sub_id":"101","register_pk":"101554","name":"真岡高校記念館","kana":"もおかこうこうきねんかん","category":"学校","subcategory":"建築物","type_guess":"記念館・資料室","type_guess_confidence":"high","period":"明治","pref":"栃木県","address":"栃木県真岡市白布ヶ丘24-1","lat":36.44063381,"lng":139.99942247,"geo_status":"db","era":"明治36","year":1903,"year_source":"db","year_min":1903,"year_max":1903,"year_label":null,"structure":"木造２階建，瓦葺，建築面積744㎡","structure_material":"木造２階建","registered":"1998.07.23(平成10.07.23)","register_no":"09 － 0006","desc":"入母屋造・総２階建の旧本館で，１階が事務室・職員室・校長室など，２階が広い講堂になる。下見板張りに上げ下げ窓という素朴な外観は，「質実剛健」の校風をよく示している。現在は校史を物語る施設として整備・活用が図られ，広く卒業生に親しまれている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000564"},{"id":"00000122","register_sub_id":"101","register_pk":"101112","name":"真岡市久保講堂（旧真岡小学校久保講堂）","kana":"もおかしくぼこうどう（きゅうもおかしょうがっこうくぼこうどう）","category":"学校","subcategory":"建築物","type_guess":"講堂","type_guess_confidence":"high","period":"昭和前","pref":"栃木県","address":"栃木県真岡市田町1345-1","lat":36.43848524,"lng":140.0175479,"geo_status":"db","era":"昭和13","year":1938,"year_source":"db","year_min":1938,"year_max":1938,"year_label":null,"structure":"木造2階建左右塔屋付，瓦葺，建築面積651㎡","structure_material":"木造2階建左右塔屋付","registered":"1997.05.07(平成9.05.07)","register_no":"09 － 0001","desc":"遠藤新設計の木造二階建の旧小学校講堂。内部は広い板敷で，２階にはギャラリーがある。水平線を強調した正面バルコニーの左右に塔屋を設けた意匠に特徴があり，遠藤新の作風がよく現れている。昭和６２年移築保存され市の文化施設として活用されている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000122"},{"id":"00000723","register_sub_id":"101","register_pk":"101713","name":"川場村歴史民俗資料館（旧川場尋常高等小学校校舎）","kana":"かわばむられきしみんぞくしりょうかん（きゅうかわばじんじょうこうとうしょうがっこうこうしゃ）","category":"学校","subcategory":"建築物","type_guess":"校舎","type_guess_confidence":"high","period":"明治","pref":"群馬県","address":"群馬県利根郡川場村大字天神1122","lat":36.69303174,"lng":139.10540245,"geo_status":"db","era":"明治43／昭和61移築","year":1910,"year_source":"db","year_min":1910,"year_max":1910,"year_label":null,"structure":"木造平屋建，瓦葺，建築面積579㎡","structure_material":"木造平屋建","registered":"1998.09.02(平成10.09.02)","register_no":"10 － 0027","desc":"木造下見板貼，瓦葺の典型的な小学校建築で，正面中央に車寄を付す。川場村は旧会津街道の宿場で，教育村としても知られている。この校舎はその象徴として村民に愛され親しまれており，昭和６１年現在地に移築され資料館として保存活用されている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000723"},{"id":"00002509","register_sub_id":"101","register_pk":"103499","name":"旧東村花輪小学校校舎","kana":"きゅうあずまむらはなわしょうがっこうこうしゃ","category":"学校","subcategory":"建築物","type_guess":"校舎","type_guess_confidence":"high","period":"昭和前","pref":"群馬県","address":"群馬県みどり市東町花輪191","lat":36.522396,"lng":139.309067,"geo_status":"db","era":"昭和7","year":1932,"year_source":"db","year_min":1932,"year_max":1932,"year_label":null,"structure":"木造2階建、瓦葺、建築面積627㎡","structure_material":"木造2階建","registered":"2001.11.20(平成13.11.20)","register_no":"10 － 0086","desc":"当地の出身で「日本の製鋼・鋼管技術の先駆者」とされる今泉嘉一郎の寄付により建設。木造２階建，切妻造，フランス瓦葺，下見板張の学校建築で，北面片廊下とし正面中央に玄関ポーチを突出させる。昇降口部の窓構成や腰折れ屋根窓などに造形的特色がある。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002509"},{"id":"00002510","register_sub_id":"101","register_pk":"103500","name":"旧東村花輪小学校門柱","kana":"きゅうあずまむらはなわしょうがっこうもんちゅう","category":"学校","subcategory":"その他工作物","type_guess":"正門","type_guess_confidence":"high","period":"大正","pref":"群馬県","address":"群馬県みどり市東町花輪191","lat":36.521969,"lng":139.309494,"geo_status":"db","era":"大正5","year":1916,"year_source":"db","year_min":1916,"year_max":1916,"year_label":null,"structure":"石造、間口2.9m、高さ3.0m","structure_material":"石造","registered":"2001.11.20(平成13.11.20)","register_no":"10 － 0087","desc":"門柱は高さ３ｍ，３０ｃｍ角ほどの花崗石製で，江戸切り状に仕上げる。左の門柱側面に「大正五年二月建之」とあり，前身校舎時代の建立を示す。平成５年頃，前面道路の拡幅に伴い，校庭よりも低い道路沿いの現在地に移設されている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002510"},{"id":"00000948","register_sub_id":"101","register_pk":"132572","name":"旧桐生高等染織学校正門","kana":"きゅうきりゅうこうとうせんしょくがっこうせいもん","category":"学校","subcategory":"その他工作物","type_guess":"正門","type_guess_confidence":"high","period":"大正","pref":"群馬県","address":"群馬県桐生市天神町1-5-1","lat":36.42282269,"lng":139.3471222,"geo_status":"db","era":"大正5","year":1916,"year_source":"db","year_min":1916,"year_max":1916,"year_label":null,"structure":"煉瓦造，鉄製門扉附属，高さ3.7m，幅16.8m","structure_material":"煉瓦造","registered":"1998.12.11(平成10.12.11)","register_no":"10 － 0032","desc":"旧桐生高等染織学校創立時の正門。本館の移設に応じて，本館玄関前の現位置に移設保存された。煉瓦造の門柱上部四面にゴシック風のポーチコを付けて頂部に門灯を掲げる。東京大学本郷キャンパスの煉瓦塀に似た門として知られる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000948"},{"id":"00011634","register_sub_id":"101","register_pk":"210650","name":"群馬県立沼田高等学校屋内運動場（旧沼田中学校講堂）","kana":"ぐんまけんりつぬまたこうとうがっこうおくないうんどうじょう（きゅうぬまたちゅうがっこうこうどう）","category":"学校","subcategory":"建築物","type_guess":"講堂","type_guess_confidence":"high","period":"昭和前","pref":"群馬県","address":"群馬県沼田市西原新町1510","lat":36.646145,"lng":139.052839,"geo_status":"db","era":"昭和3年／平成27年改修","year":1928,"year_source":"db","year_min":1928,"year_max":1928,"year_label":null,"structure":"鉄骨鉄筋コンクリート造2階建、建築面積380㎡","structure_material":"鉄骨鉄筋コンクリート造2階建","registered":"2017.06.28(平成29.06.28)","register_no":"10-0338","desc":"管理教室棟の東に接して建つ。外観は管理教室棟と同じ簡素な仕上で、内部一階は武道場、二階は講堂であったが現在は屋内運動場となっている。鉄骨鉄筋コンクリート造で、二階床は水平、小屋組はアーチ状の鉄骨トラスを現し内部空間を特徴付ける。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011634"},{"id":"00011633","register_sub_id":"101","register_pk":"210649","name":"群馬県立沼田高等学校管理教室棟（旧沼田中学校校舎）","kana":"ぐんまけんりつぬまたこうとうがっこうかんりきょうしつとう（きゅうぬまたちゅうがっこうこうしゃ）","category":"学校","subcategory":"建築物","type_guess":"校舎","type_guess_confidence":"high","period":"昭和前","pref":"群馬県","address":"群馬県沼田市西原新町1510","lat":36.646052,"lng":139.05215,"geo_status":"db","era":"昭和3年／平成24年改修","year":1928,"year_source":"db","year_min":1928,"year_max":1928,"year_label":null,"structure":"鉄筋コンクリート造3階建一部地下1階建、建築面積921㎡、塔屋付","structure_material":"鉄筋コンクリート造3階建一部地下1階建","registered":"2017.06.28(平成29.06.28)","register_no":"10-0337","desc":"敷地北寄りに北面して建つ校舎建築。外観は装飾を排した簡素で平坦な仕上とするが、玄関周りや階段ホールなどにアールデコ風の装飾が見られる。平面は片廊下式で教室を並べ中央に塔屋を付す。県内最初の鉄筋コンクリート造学校建築として貴重。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011633"},{"id":"00000947","register_sub_id":"101","register_pk":"101937","name":"群馬大学工学部守衛所（旧桐生高等染織学校門衛所）","kana":"ぐんまだいがくこうがくぶしゅえいじょ（きゅうきりゅうこうとうせんしょくがっこうもんえいじょ）","category":"学校","subcategory":"建築物","type_guess":"正門","type_guess_confidence":"high","period":"大正","pref":"群馬県","address":"群馬県桐生市天神町1-5-1","lat":36.42269403,"lng":139.34690777,"geo_status":"db","era":"大正5","year":1916,"year_source":"db","year_min":1916,"year_max":1916,"year_label":null,"structure":"木造平屋建，瓦葺，建築面積18㎡","structure_material":"木造平屋建","registered":"1998.12.11(平成10.12.11)","register_no":"10 － 0031","desc":"桐生高等染織学校創立時の門衛所。木造平屋建，瓦葺切妻屋根，下見板張りで，本館と同系列の造りとし，規模に応じた簡略化を図っているが，下を三角に切り欠いた板を竪羽目にした妻面の意匠など相応の見所を造ることも忘れていない。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000947"},{"id":"00000946","register_sub_id":"101","register_pk":"101936","name":"群馬大学工学部同窓記念会館（旧桐生高等染織学校本館・講堂）","kana":"ぐんまだいがくこうがくぶどうそうきねんかいかん（きゅうきりゅうこうとうせんしょくがっこうほんかん・こうどう）","category":"学校","subcategory":"建築物","type_guess":"講堂","type_guess_confidence":"high","period":"大正","pref":"群馬県","address":"群馬県桐生市天神町1-5-1","lat":36.42299129,"lng":139.34723166,"geo_status":"db","era":"大正5","year":1916,"year_source":"db","year_min":1916,"year_max":1916,"year_label":null,"structure":"木造２階建，便所棟附属，瓦葺，建築面積592㎡","structure_material":"木造２階建","registered":"1998.12.11(平成10.12.11)","register_no":"10 － 0030","desc":"大正４年設置になる桐生高等染織学校の創立時の本館。正面玄関の奥に講堂を配置する。設計は，文部省大臣官房建築課桐生出張所長で文部技師の新山平四郎とされる。木造２階建，下見板張りで，ハンマービームを用いた妻飾りの意匠に特徴がある。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000946"},{"id":"00010110","register_sub_id":"101","register_pk":"197943","name":"玉村八幡宮末社国魂神社（旧玉村尋常高等小学校奉安殿）","kana":"たまむらはちまんぐうまっしゃくにたまじんじゃ（きゅうたまむらじんじょうこうとうしょうがっこうほうあんでん）","category":"学校","subcategory":"建築物","type_guess":"記念館・資料室","type_guess_confidence":"high","period":"明治","pref":"群馬県","address":"群馬県佐波郡玉村町大字下新田字八幡1","lat":36.305016,"lng":139.108594,"geo_status":"db","era":"明治43／昭和21移築","year":1910,"year_source":"db","year_min":1910,"year_max":1910,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積4.0㎡","structure_material":"木造平屋建","registered":"2014.10.07(平成26.10.07)","register_no":"10 － 0319","desc":"拝殿の西に建つ。旧玉村尋常高等小学校の奉安殿で、戦後移築され国魂神社とされた。神社建築を範とした切妻造平入、銅板葺の建物で、壁面全面を鉄板張とする。かつては棟に千木と堅魚木、破風の拝みに鞭掛がついていた。明治期に遡る木造奉安殿の遺例。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010110"},{"id":"00008416","register_sub_id":"101","register_pk":"134812","name":"富岡市講堂（旧富岡尋常高等小学校講堂）","kana":"とみおかしこうどう（きゅうとみおかじんじょうこうとうしょうがっこうこうどう）","category":"学校","subcategory":"建築物","type_guess":"講堂","type_guess_confidence":"high","period":"昭和前","pref":"群馬県","address":"群馬県富岡市富岡1753-1","lat":36.25871076,"lng":138.89359466,"geo_status":"db","era":"昭和8年／昭和26年・昭和52年・平成3年改修","year":1933,"year_source":"db","year_min":1933,"year_max":1933,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積909㎡","structure_material":"木造平屋建","registered":"2011.01.26(平成23.01.26)","register_no":"10 － 0303","desc":"富岡小学校敷地の西側に南面して建つ。木造平屋建。正面の玄関ポーチと、その奥の半切妻造桟瓦葺の講堂からなる。建築面積九〇九平方メートル。南正面はアーチを連続させた開口部や、レリーフにより左右対称の洋風の構成をみせ、堂々として風格を感じさせる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008416"},{"id":"00012292","register_sub_id":"101","register_pk":"531616","name":"新島学園短期大学研究棟（旧高崎市立女子高等学校円形校舎）","kana":"にいじまがくえんたんきだいがくけんきゅうとう（きゅうたかさきしりつじょしこうとうがっこうえんけいこうしゃ）","category":"学校","subcategory":"建築物","type_guess":"校舎","type_guess_confidence":"high","period":"昭和中","pref":"群馬県","address":"群馬県高崎市昭和町84-1他","lat":36.33707778,"lng":139.00504167,"geo_status":"db","era":"昭和31年","year":1956,"year_source":"db","year_min":1956,"year_max":1956,"year_label":null,"structure":"鉄筋コンクリート造3階建、建築面積491㎡、塔屋付","structure_material":"鉄筋コンクリート造3階建","registered":"2018.05.10(平成30.05.10)","register_no":"10-340","desc":"もと高崎市立女子高等学校の円形校舎。鉄筋コンクリート造三階建で、円筒形の塔屋を付ける。各階の中央部は中心に螺旋階段を置くホールで、外周を六分割し教室五室と階段・便所を配する。坂本鹿名夫の初期の作で地域のランドマークとして親しまれている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012292"},{"id":"00013226","register_sub_id":"101","register_pk":"366215","name":"旧埼玉県立松山中学校校舎（埼玉県立松山高等学校記念館）","kana":"きゅうさいたまけんりつまつやまちゅうがっこうこうしゃ（さいたまけんりつまつやまこうとうがっこうきねんかん）","category":"学校","subcategory":"建築物","type_guess":"校舎","type_guess_confidence":"high","period":"大正","pref":"埼玉県","address":"埼玉県東松山市松山町一丁目1041他","lat":36.04484167,"lng":139.39645,"geo_status":"db","era":"大正12年／昭和45年移築","year":1923,"year_source":"db","year_min":1923,"year_max":1923,"year_label":null,"structure":"木造2階建、金属板葺、建築面積324㎡","structure_material":"木造2階建","registered":"2020.04.03(令和2.04.03)","register_no":"11 － 0192","desc":"敷地西寄りに東面して建つ。外壁は下見板張、縦長の上下窓を規則的に配す。ドーマー等で屋根を装飾し、四面にペディメントを付した塔屋を中央に載せる。内部は中央に吹抜けの階段を配す。埼玉県内の旧制中学校の遺構として貴重である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013226"},{"id":"00001900","register_sub_id":"101","register_pk":"102890","name":"埼玉県立深谷商業高等学校記念館","kana":"さいたまけんりつふかやしょうぎょうこうとうがっこうきねんかん","category":"学校","subcategory":"建築物","type_guess":"記念館・資料室","type_guess_confidence":"high","period":"大正","pref":"埼玉県","address":"埼玉県深谷市原郷80","lat":36.19700018,"lng":139.29130061,"geo_status":"db","era":"大正11","year":1922,"year_source":"db","year_min":1922,"year_max":1922,"year_label":null,"structure":"木造2階建、瓦葺、建築面積608㎡、塔屋付","structure_material":"木造2階建","registered":"2000.10.18(平成12.10.18)","register_no":"11 － 0024","desc":"市中心部，国道17号線沿いに建つ学校建築。木造2階建，瓦葺，外装横板張で，意匠を凝らした塔屋・車寄付の中央部を軸に左右対称の外観構成をとる。4つの屋根窓，両翼端に櫛形ペディメントを設け，仏ルネサンス様式を基調とした高密度のデザインが施される。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001900"},{"id":"00007340","register_sub_id":"101","register_pk":"108322","name":"草加市立歴史民俗資料館（旧草加小学校西校舎）","kana":"そうかしりつれきしみんぞくしりょうかん（きゅうそうかしょうがっこうにしこうしゃ）","category":"学校","subcategory":"建築物","type_guess":"校舎","type_guess_confidence":"high","period":"大正","pref":"埼玉県","address":"埼玉県草加市住吉1-25-1","lat":35.832108,"lng":139.804291,"geo_status":"db","era":"大正15／昭和57改修","year":1926,"year_source":"db","year_min":1926,"year_max":1926,"year_label":null,"structure":"鉄筋コンクリート造2階建、建築面積333㎡","structure_material":"鉄筋コンクリート造2階建","registered":"2008.10.23(平成20.10.23)","register_no":"11 － 0123","desc":"道路に西面して建つＲＣ造２階建。外壁はモルタル仕上げで、柱型を現し、２連の縦長窓を開ける。パラペットの正・背面中央を山形に立ち上げる。西側に廊下、南北両端に階段室、各階に３教室を配し、屋上を運動場とする。県内最初期のＲＣ造の校舎建築。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007340"},{"id":"00013230","register_sub_id":"101","register_pk":"366219","name":"百間小学校すべり台","kana":"もんましょうがっこうすべりだい","category":"学校","subcategory":"その他工作物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"埼玉県","address":"埼玉県南埼玉郡宮代町字西原261-1","lat":36.00886111,"lng":139.72727778,"geo_status":"db","era":"大正15年","year":1926,"year_source":"db","year_min":1926,"year_max":1926,"year_label":null,"structure":"鉄筋コンクリート造、高さ3.1m、全長6.8m","structure_material":"鉄筋コンクリート造","registered":"2020.04.03(令和2.04.03)","register_no":"11 － 0196","desc":"校庭の南西隅に建つ。鉄筋コンクリート造で、柱脚上部の踊り場四隅に方形の支柱を立て、側面に枠を縁取った直線形の滑降部と階段を取り付ける。滑降面は人造石研出仕上とする。大正期に建設した鉄筋コンクリート造のすべり台として希少な現存例。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013230"},{"id":"00015141","register_sub_id":"101","register_pk":"530565","name":"わらび幼稚園円形園舎","kana":"わらびようちえんえんけいえんしゃ","category":"学校","subcategory":"建築物","type_guess":"校舎","type_guess_confidence":"high","period":"昭和中","pref":"埼玉県","address":"埼玉県蕨市南町二丁目12-5","lat":35.81997778,"lng":139.69750833,"geo_status":"db","era":"昭和38年／平成9年改修","year":1963,"year_source":"db","year_min":1963,"year_max":1963,"year_label":null,"structure":"鉄筋コンクリート造2階建、建築面積398㎡","structure_material":"鉄筋コンクリート造2階建","registered":"2024.12.03(令和6.12.03)","register_no":"11 - 0231","desc":"蕨市の市街地南東に位置する幼稚園舎。鉄筋コンクリート造二階建の円形平面で北側に玄関を開き、一階は中央遊戯室の周りに扇形の保育室を配す。二階は一階より一回り小さく、外周を屋上テラスとする。狭隘敷地で採光を考慮した坂本鹿名夫による巧みな園舎。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015141"},{"id":"00000027","register_sub_id":"101","register_pk":"101017","name":"茨城県立水戸商業高等学校旧本館玄関","kana":"いばらぎけんりつみとしょうぎょうこうとうがっこうきゅうほんかんげんかん","category":"学校","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"茨城県","address":"茨城県水戸市新荘３-７-２","lat":36.38717873,"lng":140.45454611,"geo_status":"db","era":"明治37","year":1904,"year_source":"db","year_min":1904,"year_max":1904,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積350㎡","structure_material":"木造平屋建","registered":"1996.12.20(平成8.12.20)","register_no":"08 － 0001","desc":"明治36年に着工し翌年竣工した校舎の玄関部分。設計は茨城県技師駒杵勤治で，施工は大倉土木である。ベルサイユ宮殿を模したと伝え，屋根・柱の形態や石貼りの外壁にその特徴があらわれている。茨城県に多くの作品を残した駒杵勤治の模範的作品のひとつ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000027"},{"id":"00012288","register_sub_id":"101","register_pk":"531612","name":"旧浅川小学校一号棟","kana":"きゅうあさかわしょうがっこう１ごうとう","category":"学校","subcategory":"建築物","type_guess":"校舎","type_guess_confidence":"low","period":"大正","pref":"茨城県","address":"茨城県久慈郡大子町浅川1253","lat":36.80136389,"lng":140.33406389,"geo_status":"db","era":"大正2年／昭和12年移築／昭和30年頃・平成9年・同18年改修","year":1913,"year_source":"db","year_min":1913,"year_max":1913,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積362㎡","structure_material":"木造平屋建","registered":"2018.05.10(平成30.05.10)","register_no":"08-311","desc":"桁行39メートルの長大な片廊下式の木造校舎。寄棟造桟瓦葺、外壁下見板張で、正面西寄りに切妻屋根の玄関を設ける。正面はガラス窓を二段に並べて教室の採光に配慮する。玄関奥の越屋根には時計を備える。谷あいにある集落の歴史的景観の核になっている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012288"},{"id":"00012289","register_sub_id":"101","register_pk":"531613","name":"旧浅川小学校二号棟","kana":"きゅうあさかわしょうがっこう２ごうとう","category":"学校","subcategory":"建築物","type_guess":"校舎","type_guess_confidence":"low","period":"昭和前","pref":"茨城県","address":"茨城県久慈郡大子町浅川1253","lat":36.801125,"lng":140.3344,"geo_status":"db","era":"昭和12年／平成3年・同7年改修","year":1937,"year_source":"db","year_min":1937,"year_max":1937,"year_label":null,"structure":"木造平屋建、金属板葺、建築面積419㎡","structure_material":"木造平屋建","registered":"2018.05.10(平成30.05.10)","register_no":"08-312","desc":"一号棟前方に矩折れに並んで建つ。一号棟と渡廊下で接続し、正面両端に簡易な昇降口を設ける。平屋建、切妻造の片廊下式で、一号棟とは広めの廊下や均質な教室配置など平面計画に違いがある。一号棟とともに、集落の歴史的景観の核となっている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012289"},{"id":"00010257","register_sub_id":"101","register_pk":"199031","name":"旧上岡小学校第一棟","kana":"きゅううわおかしょうがっこうだいいちとう","category":"学校","subcategory":"建築物","type_guess":"校舎","type_guess_confidence":"low","period":"明治","pref":"茨城県","address":"茨城県久慈郡大子町大字上岡914他","lat":36.778189,"lng":140.327019,"geo_status":"db","era":"明治43年／大正15年・昭和43年改修","year":1910,"year_source":"db","year_min":1910,"year_max":1910,"year_label":null,"structure":"木造平屋建、鉄板葺、建築面積373㎡","structure_material":"木造平屋建","registered":"2014.12.19(平成26.12.19)","register_no":"08-0263","desc":"東西棟の寄棟造鉄板葺で、校庭に南面する。中央に切妻造の玄関、東西両端に昇降口を設け、外壁は簓子下見板張、和小屋で一軒疎垂木である。平面は北側片廊下式で、玄関ホールを挟み東西各二室とする。改修はあるが、明治期木造校舎のかたちを今に伝えている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010257"},{"id":"00010259","register_sub_id":"101","register_pk":"199033","name":"旧上岡小学校第三棟","kana":"きゅううわおかしょうがっこうだいさんとう","category":"学校","subcategory":"建築物","type_guess":"校舎","type_guess_confidence":"low","period":"昭和中","pref":"茨城県","address":"茨城県久慈郡大子町大字上岡946他","lat":36.778089,"lng":140.327447,"geo_status":"db","era":"昭和38年","year":1963,"year_source":"db","year_min":1963,"year_max":1963,"year_label":null,"structure":"木造平屋建、鉄板葺、建築面積236㎡、渡廊下及び便所付","structure_material":"木造平屋建","registered":"2014.12.19(平成26.12.19)","register_no":"08-0265","desc":"第一棟東に南面して建つ、切妻造鉄板葺の校舎。平面は北側片廊下式で教室二室及び旧図書室からなる。採光のために南面の高窓を大きくしながらも、軸部は主柱と添柱の二本組とし、上部に方杖を入れるなど構造強化を図っており、木造校舎の構法の進展を物語る。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010259"},{"id":"00010258","register_sub_id":"101","register_pk":"199032","name":"旧上岡小学校第二棟","kana":"きゅううわおかしょうがっこうだいにとう","category":"学校","subcategory":"建築物","type_guess":"校舎","type_guess_confidence":"low","period":"昭和前","pref":"茨城県","address":"茨城県久慈郡大子町大字上岡914他","lat":36.778374,"lng":140.327069,"geo_status":"db","era":"昭和12年／昭和38年改修","year":1937,"year_source":"db","year_min":1937,"year_max":1937,"year_label":null,"structure":"木造平屋建、鉄板葺、建築面積326㎡、渡廊下付","structure_material":"木造平屋建","registered":"2014.12.19(平成26.12.19)","register_no":"08-0264","desc":"第一棟の北側に並立し、廊下で接続する。桁行三一メートル、木造平屋建、切妻造鉄板葺で、小屋組はキングポストトラス、外壁は下見板張である。平面は講堂と多目的室の二室であるが、もとは北側片廊下式の四教室であった。昭和前期の学校拡充の様相を示す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010258"},{"id":"00012281","register_sub_id":"101","register_pk":"531605","name":"旧岡田小学校女化分校校舎","kana":"きゅうおかだしょうがっこうおなばけぶんこうこうしゃ","category":"学校","subcategory":"建築物","type_guess":"校舎","type_guess_confidence":"high","period":"昭和前","pref":"茨城県","address":"茨城県牛久市女化町391-1","lat":35.94911944,"lng":140.17108333,"geo_status":"db","era":"昭和14年","year":1939,"year_source":"db","year_min":1939,"year_max":1939,"year_label":null,"structure":"木造平屋建、金属板葺、建築面積388㎡","structure_material":"木造平屋建","registered":"2018.05.10(平成30.05.10)","register_no":"08-304","desc":"旧校地の中央北寄りに南面して建つ。木造平屋建、外壁下見板張で、東寄りに切妻屋根の玄関を構える。片廊下式平面で北側を廊下とし、南側を大教室や中教室に仕切る。大教室は内部を二分でき、授業形態や多目的利用に対応する。市内現存唯一の戦前の木造校舎。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012281"},{"id":"00004119","register_sub_id":"101","register_pk":"105109","name":"旧樺穂小学校校舎","kana":"きゅうかばほしょうがっこうこうしゃ","category":"学校","subcategory":"建築物","type_guess":"校舎","type_guess_confidence":"high","period":"明治","pref":"茨城県","address":"茨城県桜川市真壁町真壁351","lat":36.27767117,"lng":140.10165725,"geo_status":"db","era":"明治中期／大正期移築","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"木造平屋建、瓦葺、建築面積127㎡","structure_material":"木造平屋建","registered":"2004.06.09(平成16.06.09)","register_no":"08 － 0133","desc":"桁行８間梁間３間規模，寄棟造，桟瓦葺の平屋建で，北面に半間幅の吹き放ち廊下を配し，中央東寄りに昇降口を張り出す。外観は押縁下見板張で，内部は中央で２室に分けていたものと見られる。旧長岡村の小学校校舎と推測されている。明治期学校建築の一事例。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004119"},{"id":"00010263","register_sub_id":"101","register_pk":"199037","name":"旧黒沢中学校屋内運動場","kana":"きゅうくろさわちゅうがっこうおくないうんどうじょう","category":"学校","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和中","pref":"茨城県","address":"茨城県久慈郡大子町大字上郷2572-1他","lat":36.839197,"lng":140.348889,"geo_status":"db","era":"昭和30年","year":1955,"year_source":"db","year_min":1955,"year_max":1955,"year_label":null,"structure":"鉄骨造平屋建一部地階付、鉄板葺、建築面積387㎡","structure_material":"鉄骨造平屋建一部地階付","registered":"2014.12.19(平成26.12.19)","register_no":"08-0269","desc":"本館北東に建つ切妻造の内部高大な施設で、西妻面にステージ部を張出し、南面東端にポーチ付出入口を設け、ステージ下に物置やシャワー室を備える。構造体の鉄骨は木部で覆い、大壁風のモルタル塗で、縦長窓と丸窓で外観を整えるなど、意匠面にも工夫がある。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010263"},{"id":"00010264","register_sub_id":"101","register_pk":"199038","name":"旧黒沢中学校音楽教室","kana":"きゅうくろさわちゅうがっこうおんがくきょうしつ","category":"学校","subcategory":"建築物","type_guess":"校舎","type_guess_confidence":"high","period":"昭和中","pref":"茨城県","address":"茨城県久慈郡大子町大字上郷2661-1他","lat":36.838605,"lng":140.347989,"geo_status":"db","era":"昭和37年","year":1962,"year_source":"db","year_min":1962,"year_max":1962,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積92㎡、渡廊下付","structure_material":"木造平屋建","registered":"2014.12.19(平成26.12.19)","register_no":"08-0270","desc":"校地南のやや高い場所に建ち、本館南端二階と渡廊下で接続する。東西棟の切妻造桟瓦葺で、小屋組はトラス、外壁は下見板張である。内部は広い一室で、添柱や方杖を用いた軸部、広く高い開口部が特徴的である。本館と一体となり施設全体の正面を構成している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010264"},{"id":"00010261","register_sub_id":"101","register_pk":"199035","name":"旧黒沢中学校技術教室","kana":"きゅうくろさわちゅうがっこうぎじゅつきょうしつ","category":"学校","subcategory":"建築物","type_guess":"校舎","type_guess_confidence":"high","period":"昭和中","pref":"茨城県","address":"茨城県久慈郡大子町大字上郷2600他","lat":36.839105,"lng":140.348225,"geo_status":"db","era":"昭和26年／昭和35年改修","year":1951,"year_source":"db","year_min":1951,"year_max":1951,"year_label":null,"structure":"木造平屋建、鉄板葺、建築面積118㎡","structure_material":"木造平屋建","registered":"2014.12.19(平成26.12.19)","register_no":"08-0267","desc":"本館背面に独立し、棟を直交させて建つ切妻造鉄板葺で、外壁は下見板張、小屋組はトラス組と思われる。桁行七間梁間四間の広い一室が当初部で、南面東端に出入口を設け、板張の床に棹縁天井とする。本館と一連の建物で、初期中学校施設のあり様を示している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010261"},{"id":"00010262","register_sub_id":"101","register_pk":"199036","name":"旧黒沢中学校調理室及び図書館","kana":"きゅうくろさわちゅうがっこうちょうりしつおよびとしょかん","category":"学校","subcategory":"建築物","type_guess":"図書館","type_guess_confidence":"high","period":"昭和中","pref":"茨城県","address":"茨城県久慈郡大子町大字上郷2600他","lat":36.838976,"lng":140.348139,"geo_status":"db","era":"昭和26年","year":1951,"year_source":"db","year_min":1951,"year_max":1951,"year_label":null,"structure":"木造平屋建、鉄板葺、建築面積141㎡","structure_material":"木造平屋建","registered":"2014.12.19(平成26.12.19)","register_no":"08-0268","desc":"本館の中央背面に建つ。南を図書室、北を調理室とし、ともに桁行五間梁間四間の広い一室で、室境で調理室を後方にずらし、切妻造で鉄板葺屋根も棟違いとする。小屋組はキングポストトラス、外壁は下見板張、床を板張とし、棹縁天井を張る。本館と一連の施設。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010262"},{"id":"00010260","register_sub_id":"101","register_pk":"199034","name":"旧黒沢中学校本館","kana":"きゅうくろさわちゅうがっこうほんかん","category":"学校","subcategory":"建築物","type_guess":"記念館・資料室","type_guess_confidence":"low","period":"昭和中","pref":"茨城県","address":"茨城県久慈郡大子町大字上郷2604他","lat":36.838926,"lng":140.348303,"geo_status":"db","era":"昭和25年","year":1950,"year_source":"db","year_min":1950,"year_max":1950,"year_label":null,"structure":"木造2階建、瓦葺、建築面積877㎡、渡廊下及び便所付","structure_material":"木造2階建","registered":"2014.12.19(平成26.12.19)","register_no":"08-0266","desc":"校庭に面して南東を向いて建つ。大規模な木造二階建で、小屋組はキングポストトラス、切妻造桟瓦葺とする。背面片廊下式で、正面中央に玄関、中央と両側に階段を設ける。外壁は下見板張で、添柱や方杖を用いた軸部、広い開口部など、初期中学校舎の一典型。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010260"},{"id":"00012285","register_sub_id":"101","register_pk":"531609","name":"旧西金小学校校舎","kana":"きゅうさいがねしょうがっこうこうしゃ","category":"学校","subcategory":"建築物","type_guess":"校舎","type_guess_confidence":"high","period":"昭和中","pref":"茨城県","address":"茨城県久慈郡大子町西金250","lat":36.69701667,"lng":140.38688333,"geo_status":"db","era":"昭和32年","year":1957,"year_source":"db","year_min":1957,"year_max":1957,"year_label":null,"structure":"木造2階建、瓦葺、建築面積533㎡","structure_material":"木造2階建","registered":"2018.05.10(平成30.05.10)","register_no":"08-308","desc":"切妻造、南北棟の大規模な木造校舎。総二階建、外壁下見板張で、中央玄関部をモルタル塗として南北に分節する。内部は片廊下式で西側に通し、玄関部に防火扉を設けて二分する。大きな改変なく、発足間もない新制小学校の建築形式を伝える好例。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012285"},{"id":"00012287","register_sub_id":"101","register_pk":"531611","name":"旧西金小学校調理室","kana":"きゅうさいがねしょうがっこうちょうりしつ","category":"学校","subcategory":"建築物","type_guess":"校舎","type_guess_confidence":"low","period":"昭和中","pref":"茨城県","address":"茨城県久慈郡大子町西金250","lat":36.69724167,"lng":140.38723611,"geo_status":"db","era":"昭和31年","year":1956,"year_source":"db","year_min":1956,"year_max":1956,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積42㎡","structure_material":"木造平屋建","registered":"2018.05.10(平成30.05.10)","register_no":"08-310","desc":"校舎の正面側北隅に南面して建ち、矩折れの渡廊下で校舎と接続する。木造平屋建、切妻造桟瓦葺で、外壁を軒裏までモルタル塗とし、内部も天井をボード張とするなど内外に防火対策を講じる。音楽室･理科室と同じく、新制小学校最初期の構内の構成を伝えている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012287"},{"id":"00012286","register_sub_id":"101","register_pk":"531610","name":"旧西金小学校理科室及び音楽室","kana":"きゅうさいがねしょうがっこうりかしつおよびおんがくしつ","category":"学校","subcategory":"建築物","type_guess":"校舎","type_guess_confidence":"low","period":"昭和中","pref":"茨城県","address":"茨城県久慈郡大子町西金250","lat":36.69739722,"lng":140.38721389,"geo_status":"db","era":"昭和39年","year":1964,"year_source":"db","year_min":1964,"year_max":1964,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積188㎡","structure_material":"木造平屋建","registered":"2018.05.10(平成30.05.10)","register_no":"08-309","desc":"校舎北側の高台に南面して建つ。南側に吹放ち下屋で外廊下を通し、その中央部を渡廊下で校舎二階と接続する。内部は東半を音楽室、西半を理科室とし、南北面ほとんどをガラス窓として採光を確保する。新制小学校最初期の構内の構成を伝える特別教室棟である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012286"},{"id":"00012282","register_sub_id":"101","register_pk":"531606","name":"旧初原小学校一号棟","kana":"きゅうはつばらしょうがっこう１ごうとう","category":"学校","subcategory":"建築物","type_guess":"校舎","type_guess_confidence":"low","period":"昭和前","pref":"茨城県","address":"茨城県久慈郡大子町初原960","lat":36.81323889,"lng":140.30815556,"geo_status":"db","era":"昭和17年／昭和35年・平成2年改修","year":1942,"year_source":"db","year_min":1942,"year_max":1942,"year_label":null,"structure":"木造平屋建、金属板葺、建築面積369㎡","structure_material":"木造平屋建","registered":"2018.05.10(平成30.05.10)","register_no":"08-305","desc":"切妻造の東西棟、片廊下式の学校校舎。北側に廊下を通し、南面には教室の採光等に配慮し、ガラス窓上にガラス欄間を並べる。軸部･小屋組とも規格材を用い、トラスや添柱で効率的に構造耐力を確保するなど、戦時中の限られた用材で建てるための工夫がみられる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012282"},{"id":"00012283","register_sub_id":"101","register_pk":"531607","name":"旧初原小学校二号棟","kana":"きゅうはつばらしょうがっこう２ごうとう","category":"学校","subcategory":"建築物","type_guess":"校舎","type_guess_confidence":"low","period":"昭和中","pref":"茨城県","address":"茨城県久慈郡大子町初原960","lat":36.81331944,"lng":140.30792222,"geo_status":"db","era":"昭和35年","year":1960,"year_source":"db","year_min":1960,"year_max":1960,"year_label":null,"structure":"木造2階建、金属板葺、建築面積100㎡","structure_material":"木造2階建","registered":"2018.05.10(平成30.05.10)","register_no":"08-306","desc":"一号棟西側に増築された木造二階建校舎で、上下階とも教室一室からなる。一号棟以上に教室の採光等を配慮し、南面のガラス窓上に大きなガラス欄間を並べ、構造耐力を確保するため、軸部を添柱や方杖で補強する。改造がほとんどなく建築当初の状態をよく残す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012283"},{"id":"00012284","register_sub_id":"101","register_pk":"531608","name":"旧初原小学校講堂","kana":"きゅうはつばらしょうがっこうこうどう","category":"学校","subcategory":"建築物","type_guess":"講堂","type_guess_confidence":"high","period":"昭和中","pref":"茨城県","address":"茨城県久慈郡大子町初原960","lat":36.81335556,"lng":140.30771389,"geo_status":"db","era":"昭和29年／昭和50年改修","year":1954,"year_source":"db","year_min":1954,"year_max":1954,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積103㎡","structure_material":"木造平屋建","registered":"2018.05.10(平成30.05.10)","register_no":"08-307","desc":"二号棟の北西方に渡廊下を延ばして接続する。木造平屋建、切妻造妻入で、外壁は軒裏までモルタル塗とし、ガラス窓を多用し採光を確保する。内部は一つの大空間で、天井を中央に向けて切上げて高くし、屋内運動場としても利用できるように工夫されている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012284"},{"id":"00012290","register_sub_id":"101","register_pk":"531614","name":"旧槙野地小学校校舎","kana":"きゅうまきのちしょうがっこうこうしゃ","category":"学校","subcategory":"建築物","type_guess":"校舎","type_guess_confidence":"high","period":"昭和中","pref":"茨城県","address":"茨城県久慈郡大子町槙野地2469","lat":36.8373,"lng":140.317775,"geo_status":"db","era":"昭和25年／昭和36年増築・平成10年改修","year":1950,"year_source":"db","year_min":1950,"year_max":1950,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積553㎡","structure_material":"木造平屋建","registered":"2018.05.10(平成30.05.10)","register_no":"08-313","desc":"桁行58メートルに及ぶ長大な木造校舎。内部が改変されているが、下見板張外壁の正面中央に切妻屋根の玄関、ガラス窓を二段に並べる外観は、当初の学校建築の形式をよく残している。地域の近代化を牽引した施設として、町民に広く親しまれている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012290"},{"id":"00003355","register_sub_id":"101","register_pk":"104345","name":"武道館（旧水海道小学校雨天体操場兼講堂）","kana":"ぶどうかん（きゅうみつかいどうしょうがっこううてんたいそうじょうけんこうどう）","category":"学校","subcategory":"建築物","type_guess":"講堂","type_guess_confidence":"high","period":"昭和前","pref":"茨城県","address":"茨城県常総市水海道栄町2680-1","lat":36.01996362,"lng":139.98847207,"geo_status":"db","era":"昭和7","year":1932,"year_source":"db","year_min":1932,"year_max":1932,"year_label":null,"structure":"木造平屋建、スレート葺、建築面積541㎡","structure_material":"木造平屋建","registered":"2003.07.01(平成15.07.01)","register_no":"08 － 0077","desc":"小学校の雨天体操場兼講堂として建設されたが，現在は武道館として活用。木造平屋建，切妻造，スレート葺で，外壁は妻面破風と側面上部が真壁造，他は柱をあらわした下見板張にする。保存状態も良好で，端正で品格のある外観は，地域景観のシンボル的存在。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003355"},{"id":"00014321","register_sub_id":"101","register_pk":"511310","name":"旧公正會舘","kana":"きゅうこうせいかいかん","category":"学校","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"千葉県","address":"千葉県銚子市新生町二丁目1-5","lat":35.73209167,"lng":140.83320278,"geo_status":"db","era":"大正15年／昭和後期改修","year":1926,"year_source":"db","year_min":1926,"year_max":1926,"year_label":null,"structure":"鉄筋コンクリート造一部鉄骨造2階建、建築面積524㎡","structure_material":"鉄筋コンクリート造一部鉄骨造2階建","registered":"2022.10.31(令和4.10.31)","register_no":"12 - 0318","desc":"市中心部に建つ鉄筋コンクリート造二階建で、夜間学校や図書館として建設された。二階は講堂で室内に映写室を張り出す。特に正面玄関廻りはセセッションを取り入れた円柱と垂直性の強い意匠で飾り立てる。地方都市で比較的早く鉄筋コンクリート造とした事例。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014321"},{"id":"00013510","register_sub_id":"101","register_pk":"504874","name":"旧佐倉市立志津小学校青菅分校校舎","kana":"きゅうさくらしりつしづしょうがっこうあおすげぶんこうこうしゃ","category":"学校","subcategory":"建築物","type_guess":"校舎","type_guess_confidence":"high","period":"昭和中","pref":"千葉県","address":"千葉県佐倉市青菅148","lat":35.74730833,"lng":140.15400278,"geo_status":"db","era":"昭和30年","year":1955,"year_source":"db","year_min":1955,"year_max":1955,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積174㎡","structure_material":"木造平屋建","registered":"2021.02.04(令和3.02.04)","register_no":"12 － 0306","desc":"佐倉市の青菅地区に位置し、志津小学校分校として建築された。平屋建切妻造桟瓦葺。玄関脇に職員室を配し、片廊下を通してわずか二室の教室が配される小規模木造校舎。下見板張や木製の建具の使用など、戦後の建築ながら戦前からの木造校舎の意匠を引き継ぐ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013510"},{"id":"00004875","register_sub_id":"101","register_pk":"105865","name":"千葉県立佐倉高等学校記念館","kana":"ちばけんりつさくらこうとうがっこうきねんかん","category":"学校","subcategory":"建築物","type_guess":"記念館・資料室","type_guess_confidence":"high","period":"明治","pref":"千葉県","address":"千葉県佐倉市鍋山町18","lat":35.723469,"lng":140.236816,"geo_status":"db","era":"明治43","year":1910,"year_source":"db","year_min":1910,"year_max":1910,"year_label":null,"structure":"木造2階建、銅板葺、建築面積691㎡","structure_material":"木造2階建","registered":"2005.07.12(平成17.07.12)","register_no":"12 － 0063","desc":"木造２階建の学校建築。正面ポーチに桜のレリーフを飾り，ドームを掲げた双塔，丸窓付の屋根窓，大棟の換気塔をスティック・スタイルでまとめる。建物端部にはハンマー・ビームの妻飾りがつく。外壁は柱形なしのドイツ下見板張。設計は久野節，後藤政次郎ら。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004875"},{"id":"00009435","register_sub_id":"101","register_pk":"194228","name":"千葉黎明学園生徒館","kana":"ちばれいめいがくえんせいとかん","category":"学校","subcategory":"建築物","type_guess":"記念館・資料室","type_guess_confidence":"low","period":"大正","pref":"千葉県","address":"千葉県八街市八街ほ628他","lat":35.66268651,"lng":140.30716342,"geo_status":"db","era":"大正13年","year":1924,"year_source":"db","year_min":1924,"year_max":1924,"year_label":null,"structure":"木造平屋建、鉄板葺、建築面積303㎡","structure_material":"木造平屋建","registered":"2013.03.29(平成25.03.29)","register_no":"12 － 0162","desc":"校地のほぼ中央に、木造平屋建の講堂兼武道場として建つ。半切妻屋根と屋根上のドーマー窓が特徴的であり、小屋組は木造変形トラスを組み、下弦をターンバックルで緊張させた独特な形式をもつ。八街市草創期の町の景観を直接伝える近代洋風建築物である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009435"},{"id":"00013960","register_sub_id":"101","register_pk":"508220","name":"野田市立中央小学校旧正門","kana":"のだしりつちゅうおうしょうがっこうきゅうせいもん","category":"学校","subcategory":"その他工作物","type_guess":"正門","type_guess_confidence":"high","period":"大正","pref":"千葉県","address":"千葉県野田市野田字東上町629","lat":35.94608333,"lng":139.86214722,"geo_status":"db","era":"大正6年","year":1917,"year_source":"db","year_min":1917,"year_max":1917,"year_label":null,"structure":"石造及び煉瓦造、間口3.5m、左右袖塀及び石敷付","structure_material":"石造及び煉瓦造","registered":"2021.10.14(令和3.10.14)","register_no":"12 - 0313","desc":"敷地西方の流山街道に面して建ち、石畳を経て３年館昇降口に至る。間口三・五メートル開放の花崗岩門柱に、煉瓦造モルタル洗出仕上脇柱と色モルタル仕上袖塀を付設する。柱は断面方形で頂部に水勾配を取る。脇柱に控壁付き。歴史ある小学校の表構えを形成。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013960"},{"id":"00013958","register_sub_id":"101","register_pk":"508218","name":"野田市立中央小学校３年館","kana":"のだしりつちゅうおうしょうがっこうさんねんかん","category":"学校","subcategory":"建築物","type_guess":"記念館・資料室","type_guess_confidence":"low","period":"昭和前","pref":"千葉県","address":"千葉県野田市野田字東上町619-1他","lat":35.94646111,"lng":139.86336389,"geo_status":"db","era":"昭和3年","year":1928,"year_source":"db","year_min":1928,"year_max":1928,"year_label":null,"structure":"鉄筋コンクリート造3階建、建築面積836㎡","structure_material":"鉄筋コンクリート造3階建","registered":"2021.10.14(令和3.10.14)","register_no":"12 - 0311","desc":"桁行八三メートルに及ぶ長大な三階建校舎。一階外壁は横目地を入れ、三階まで柱形を立上げ柱頭に野田醤油の亀甲紋を象る。西面の昇降口に花輪飾等を付す。内部は片廊下式で一階は校長室等、二、三階は教室を配す。野田市初の鉄筋コンクリート造小学校校舎。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013958"},{"id":"00013959","register_sub_id":"101","register_pk":"508219","name":"野田市立中央小学校７年館","kana":"のだしりつちゅうおうしょうがっこうしちねんかん","category":"学校","subcategory":"建築物","type_guess":"記念館・資料室","type_guess_confidence":"low","period":"昭和前","pref":"千葉県","address":"千葉県野田市野田字東上町611他","lat":35.94695,"lng":139.8638,"geo_status":"db","era":"昭和7年","year":1932,"year_source":"db","year_min":1932,"year_max":1932,"year_label":null,"structure":"鉄筋コンクリート造3階建、建築面積864㎡","structure_material":"鉄筋コンクリート造3階建","registered":"2021.10.14(令和3.10.14)","register_no":"12 - 0312","desc":"敷地北面に位置する桁行九一メートルの鉄筋コンクリート造三階建校舎。外壁は一階から三階までドイツ壁風仕上で柱形を付し、南面は軒上に立ち上げ煙突を兼ねる。内部は東西端を昇降口とし片廊下式で教室を配す。３年館を踏襲しつつ細部意匠に違いを見せる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013959"},{"id":"00007020","register_sub_id":"101","register_pk":"108002","name":"青山学院ベリーホール","kana":"あおやまがくいんべりーほーる","category":"学校","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"東京都","address":"東京都渋谷区渋谷4-22他","lat":35.66072331,"lng":139.71034935,"geo_status":"db","era":"昭和6","year":1931,"year_source":"db","year_min":1931,"year_max":1931,"year_label":null,"structure":"鉄筋コンクリート造3階地下1階建、建築面積817㎡","structure_material":"鉄筋コンクリート造3階地下1階建","registered":"2008.04.18(平成20.04.18)","register_no":"13 － 0230","desc":"キャンパス中央ロータリーに西面して建つ。ＲＣ造３階建の主体部北端に平屋建の礼拝堂を設け、これと対称性を保って南端にも平屋建が付く。主体部や正面車寄はバットレスで飾り、欠円アーチや尖頭アーチ、簡明な細部彫刻を配す。ネオ・ゴシック風意匠になる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007020"},{"id":"00007019","register_sub_id":"101","register_pk":"108001","name":"青山学院間島記念館","kana":"あおやまがくいんまじまきねんかん","category":"学校","subcategory":"建築物","type_guess":"記念館・資料室","type_guess_confidence":"high","period":"昭和前","pref":"東京都","address":"東京都渋谷区渋谷4-22他","lat":35.660297,"lng":139.710175,"geo_status":"db","era":"昭和4／昭和30・51改修","year":1929,"year_source":"db","year_min":1929,"year_max":1929,"year_label":null,"structure":"鉄筋コンクリート造3階建、建築面積208㎡","structure_material":"鉄筋コンクリート造3階建","registered":"2008.04.18(平成20.04.18)","register_no":"13 － 0229","desc":"キャンパス中央ロータリーに北面して建つ。正面入口は基壇状に扱い、アーチ開口を設け、２階にコリント式円柱を並べてペディメントを掲げてローマ神殿を模す。両翼部は縦長窓で垂直性を強調し、上部コーニスをデンティルで飾る。ネオ・ルネサンス様式の佳品。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007019"},{"id":"00011895","register_sub_id":"101","register_pk":"211060","name":"井草幼稚園園舎","kana":"いぐさようちえんえんしゃ","category":"学校","subcategory":"建築物","type_guess":"校舎","type_guess_confidence":"high","period":"昭和前","pref":"東京都","address":"東京都杉並区善福寺一丁目155-2他","lat":35.713307,"lng":139.598665,"geo_status":"db","era":"昭和8年／昭和27年・同37年増改築","year":1933,"year_source":"db","year_min":1933,"year_max":1933,"year_label":null,"structure":"木造平屋一部2階建、瓦葺及び鉄板葺、建築面積324㎡","structure_material":"木造平屋一部2階建","registered":"2017.10.27(平成29.10.27)","register_no":"13-392","desc":"講堂を中心としてＬ字型の平面を持ち、北寄りに住居部分を配する。園の創立者鈴木積善は浄土宗の僧侶であったが、寺院的意匠はほとんど見られない。小屋組はキングポストトラスで、外観は和風を基調とする。地域の歴史を今に伝える園舎である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011895"},{"id":"00014327","register_sub_id":"101","register_pk":"511316","name":"岡田日帰上人記念講堂","kana":"おかだにちきしょうにんきねんこうどう","category":"学校","subcategory":"建築物","type_guess":"講堂","type_guess_confidence":"high","period":"昭和前","pref":"東京都","address":"東京都杉並区堀ノ内二丁目337-1他","lat":35.69108056,"lng":139.64725278,"geo_status":"db","era":"昭和12年／同15年・同後期・平成12年改修","year":1937,"year_source":"db","year_min":1937,"year_max":1937,"year_label":null,"structure":"鉄筋コンクリート造地上4階地下2階建、建築面積878㎡","structure_material":"鉄筋コンクリート造地上4階地下2階建","registered":"2022.10.31(令和4.10.31)","register_no":"13 - 0466","desc":"堀之内妙法寺西方にある立正高等女学校の講堂。鉄筋コンクリート造４階建、正面ピラスターで垂直性を強調、全体に装飾排し時代相を示すが、車寄せ廻りは当初テラゾ貼円柱で、八角窓やファンライトで荘厳する。講堂客席は緩傾斜で、２階席平面は円弧を描く。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014327"},{"id":"00006805","register_sub_id":"101","register_pk":"107787","name":"お茶の水女子大学表門","kana":"おちゃのみずじょしだいがくおもてもん","category":"学校","subcategory":"その他工作物","type_guess":"正門","type_guess_confidence":"low","period":"昭和前","pref":"東京都","address":"東京都文京区大塚2-35","lat":35.7197039,"lng":139.7335399,"geo_status":"db","era":"昭和11／昭和30改修","year":1936,"year_source":"db","year_min":1936,"year_max":1936,"year_label":null,"structure":"門 鉄筋コンクリート造門柱2基、間口7.2m、左右通用門付 塀 鉄筋コンクリート造、総延長13m","structure_material":"門 鉄筋コンクリート造門柱2基","registered":"2008.03.07(平成20.03.07)","register_no":"13 － 0224","desc":"敷地北辺の中央、通りに面して建つ。門柱一対と左右の脇柱、鉄扉、塀からなり、鉄筋コンクリート造の表面に万成石を貼る。間口７．２ｍ、門柱の高さ４．１ｍ、塀の高さは３．２ｍである。幾何学的意匠を基調とし、当初の灯具や塀開口部のグリルなども良好に残る。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006805"},{"id":"00006804","register_sub_id":"101","register_pk":"107786","name":"お茶の水女子大学講堂","kana":"おちゃのみずじょしだいがくこうどう","category":"学校","subcategory":"建築物","type_guess":"講堂","type_guess_confidence":"high","period":"昭和前","pref":"東京都","address":"東京都文京区大塚2-35","lat":35.718605,"lng":139.732376,"geo_status":"db","era":"昭和7／平成18改修","year":1932,"year_source":"db","year_min":1932,"year_max":1932,"year_label":null,"structure":"鉄骨鉄筋コンクリート造2階建、建築面積1018㎡","structure_material":"鉄骨鉄筋コンクリート造2階建","registered":"2008.03.07(平成20.03.07)","register_no":"13 － 0223","desc":"本館の中庭、中央玄関の奥に建つ。建築面積１，０１８㎡ 、鉄骨鉄筋コンクリート造、２階建。本館と同様、外壁を全面スクラッチタイル貼、腰壁を万成石貼として統一的意匠とするが、２階には２連アーチ窓を連続させて、より穏やかな外観としている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006804"},{"id":"00006806","register_sub_id":"101","register_pk":"107788","name":"お茶の水女子大学附属幼稚園園舎","kana":"おちゃのみずじょしだいがくふぞくようちえんえんしゃ","category":"学校","subcategory":"建築物","type_guess":"校舎","type_guess_confidence":"high","period":"昭和前","pref":"東京都","address":"東京都文京区大塚2-35","lat":35.718193,"lng":139.733063,"geo_status":"db","era":"昭和6","year":1931,"year_source":"db","year_min":1931,"year_max":1931,"year_label":null,"structure":"鉄筋コンクリート造平屋建、建築面積1289㎡、砂場3ヶ所付","structure_material":"鉄筋コンクリート造平屋建","registered":"2008.03.07(平成20.03.07)","register_no":"13 － 0225","desc":"本館東側に位置する。園庭に東面する横長平面で、中廊下の両側に保育室などを配する。建築面積１，２８９㎡、鉄筋コンクリート造、平屋建。外壁はスクラッチタイル貼で、腰壁に万成石を貼る。保育室入口にステンドグラスをあしらうなど、洗練された意匠の園舎。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006806"},{"id":"00006803","register_sub_id":"101","register_pk":"107785","name":"お茶の水女子大学本館","kana":"おちゃのみずじょしだいがくほんかん","category":"学校","subcategory":"建築物","type_guess":"記念館・資料室","type_guess_confidence":"low","period":"昭和前","pref":"東京都","address":"東京都文京区大塚2-35","lat":35.71879704,"lng":139.73254518,"geo_status":"db","era":"昭和7／平成15改修","year":1932,"year_source":"db","year_min":1932,"year_max":1932,"year_label":null,"structure":"鉄筋コンクリート造3階建、建築面積2990㎡","structure_material":"鉄筋コンクリート造3階建","registered":"2008.03.07(平成20.03.07)","register_no":"13 － 0222","desc":"コ字形平面で、建築面積２，９９０㎡ 、鉄筋コンクリート造、３階建、外壁をスクラッチタイル貼とする。正面中央の大庇付の玄関まわりでは、外壁を白色とし、植物紋様のレリーフを配するなど装飾を集中させる。内部に貴賓室も備える。震災復興校舎の好例。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006803"},{"id":"00007619","register_sub_id":"101","register_pk":"108601","name":"学習院北別館（旧図書館）","kana":"がくしゅういんきたべっかん（きゅうとしょかん）","category":"学校","subcategory":"建築物","type_guess":"図書館","type_guess_confidence":"high","period":"明治","pref":"東京都","address":"東京都豊島区目白1-1057-1","lat":35.71950589,"lng":139.70937307,"geo_status":"db","era":"明治42／昭和53移築・平成9改修","year":1909,"year_source":"db","year_min":1909,"year_max":1909,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積393㎡","structure_material":"木造平屋建","registered":"2009.04.28(平成21.04.28)","register_no":"13 － 0240","desc":"校地の中央北寄りに建つ。東西２５ｍ南北２５ｍのＬ字形平面で、木造平屋建。急勾配の切妻造桟瓦葺とする。外壁はスティックスタイルとして柱間に下見板を張り、持送りや床下換気口は校章である桜花を模して飾る。木立の中、瀟洒で閑静な佇まいを醸している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007619"},{"id":"00007622","register_sub_id":"101","register_pk":"108604","name":"学習院厩舎","kana":"がくしゅういんきゅうしゃ","category":"学校","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"東京都","address":"東京都豊島区目白1-1057-1","lat":35.71688536,"lng":139.70847657,"geo_status":"db","era":"明治41／昭和2移築・昭和58改修","year":1908,"year_source":"db","year_min":1908,"year_max":1908,"year_label":null,"structure":"木造平屋建、スレート葺、建築面積293㎡","structure_material":"木造平屋建","registered":"2009.04.28(平成21.04.28)","register_no":"13 － 0243","desc":"校地南面の馬場門脇に建つ。桁行２６ｍ梁間９．７ｍ、木造平屋建、寄棟造スレート葺で、西側に切妻造の馬具置場を併設する。腰高の鉄筋コンクリート基礎上に上屋を建て、横一列の採光窓を開け、壁は下見板を張る。都心に残る数少ない明治期建設の現役厩舎である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007622"},{"id":"00007623","register_sub_id":"101","register_pk":"108605","name":"学習院正門","kana":"がくしゅういんせいもん","category":"学校","subcategory":"その他工作物","type_guess":"正門","type_guess_confidence":"high","period":"明治","pref":"東京都","address":"東京都豊島区目白1-1057-1","lat":35.7202149,"lng":139.709793,"geo_status":"db","era":"明治41","year":1908,"year_source":"db","year_min":1908,"year_max":1908,"year_label":null,"structure":"門 煉瓦造門柱4基、間口11m、左右通用門付、塀 石造、総延長36m","structure_material":"門 煉瓦造門柱4基","registered":"2009.04.28(平成21.04.28)","register_no":"13 － 0244","desc":"北面の目白通り沿いに開く間口１１ｍの正門で、左右に総延長３６ｍの石積塀を延ばし、生垣を植える。柱間６．３ｍの主柱に木製扉を吊り、その両側に脇柱を建てて脇門とする。門柱はいずれも煉瓦積で、頂部に花崗岩製の柱頭飾りを戴き、格調ある構えとする。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007623"},{"id":"00007618","register_sub_id":"101","register_pk":"108600","name":"学習院西一号館（旧中等科教場）","kana":"がくしゅういんにしいちごうかん（きゅうちゅうとうかきょうじょう）","category":"学校","subcategory":"建築物","type_guess":"記念館・資料室","type_guess_confidence":"low","period":"昭和前","pref":"東京都","address":"東京都豊島区目白1-1057-1","lat":35.71833089,"lng":139.70800324,"geo_status":"db","era":"昭和5／昭和29増築","year":1930,"year_source":"db","year_min":1930,"year_max":1930,"year_label":null,"structure":"鉄筋コンクリート造3階一部地下2階建、建築面積1366㎡","structure_material":"鉄筋コンクリート造3階一部地下2階建","registered":"2009.04.28(平成21.04.28)","register_no":"13 － 0239","desc":"南一号館の西側に矩折れに建つ。南北６６ｍ東西最長５０ｍ、鉄筋コンクリート造、地上３階一部地下２階建。南一号館と同様にネオゴシック様式を基調とした外観で、外壁をスクラッチタイル貼としており、並び建つ両館が重厚で格式のある一角を形成している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007618"},{"id":"00007621","register_sub_id":"101","register_pk":"108603","name":"学習院乃木館（旧総寮部）","kana":"がくしゅういんのぎかん（きゅうそうりょうぶ）","category":"学校","subcategory":"建築物","type_guess":"寄宿舎","type_guess_confidence":"high","period":"明治","pref":"東京都","address":"東京都豊島区目白1-1057-1","lat":35.71793,"lng":139.707443,"geo_status":"db","era":"明治41／昭和19移築","year":1908,"year_source":"db","year_min":1908,"year_max":1908,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積93㎡","structure_material":"木造平屋建","registered":"2009.04.28(平成21.04.28)","register_no":"13 － 0242","desc":"西一号館の南隣に建つ。桁行１３ｍ梁間７．３ｍ、木造平屋建、寄棟造桟瓦葺で、外壁は下見板張である。東に廊下、西に３室を並べ、中央の十畳に院長乃木希典が起居していた。内部は真壁造で、棹縁天井を張る。洋風建築が多いキャンパスに、和風の佇まいを見せる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007621"},{"id":"00007620","register_sub_id":"101","register_pk":"108602","name":"学習院東別館（旧皇族寮）","kana":"がくしゅういんひがしべっかん（きゅうこうぞくりょう）","category":"学校","subcategory":"建築物","type_guess":"寄宿舎","type_guess_confidence":"high","period":"大正","pref":"東京都","address":"東京都豊島区目白1-1057-1","lat":35.719265,"lng":139.71002755,"geo_status":"db","era":"大正2","year":1913,"year_source":"db","year_min":1913,"year_max":1913,"year_label":null,"structure":"木造2階建、瓦葺、建築面積457㎡","structure_material":"木造2階建","registered":"2009.04.28(平成21.04.28)","register_no":"13 － 0241","desc":"皇族のための別寮として計画されたもので、北別館の東側に並び建つ。並列する東西棟の建物２棟を繋ぐ形式で、東西３１ｍ南北２２ｍを測る。木造２階建、切妻及び寄棟造で桟瓦葺とする。北側に建ちの高い鋳鉄製の車寄を付設。大正初期の寄宿舎建築としても希少。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007620"},{"id":"00007617","register_sub_id":"101","register_pk":"108599","name":"学習院南一号館（旧理科特別教場）","kana":"がくしゅういんみなみいちごうかん（きゅうりかとくべつきょうじょう）","category":"学校","subcategory":"建築物","type_guess":"記念館・資料室","type_guess_confidence":"low","period":"昭和前","pref":"東京都","address":"東京都豊島区目白1-1057-1","lat":35.71779138,"lng":139.70850949,"geo_status":"db","era":"昭和2","year":1927,"year_source":"db","year_min":1927,"year_max":1927,"year_label":null,"structure":"鉄筋コンクリート造3階一部地下1階建、建築面積824㎡","structure_material":"鉄筋コンクリート造3階一部地下1階建","registered":"2009.04.28(平成21.04.28)","register_no":"13 － 0238","desc":"校地の中央南寄りに建つ。鉄筋コンクリート造、地上３階一部地下１階建。東西５４ｍのＩ字形の対称形平面で、北面中央に石貼の玄関ポーチを構える。１階窓の尖塔アーチなど、垂直性を強調したネオゴシック様式の外観をもち、外壁にはスクラッチタイルを貼る。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007617"},{"id":"00014462","register_sub_id":"101","register_pk":"512446","name":"国際基督教大学ディッフェンドルファー記念館","kana":"こくさいきりすときょうだいがくでぃっふぇんどるふぁーきねんかん","category":"学校","subcategory":"建築物","type_guess":"記念館・資料室","type_guess_confidence":"high","period":"昭和中","pref":"東京都","address":"東京都三鷹市大沢三丁目1500-1","lat":35.68601389,"lng":139.52980556,"geo_status":"db","era":"昭和33年／平成12年・令和3年改修","year":1958,"year_source":"db","year_min":1958,"year_max":1958,"year_label":null,"structure":"鉄筋コンクリート造地上3階地下1階建、建築面積1，175㎡","structure_material":"鉄筋コンクリート造地上3階地下1階建","registered":"2023.02.27(令和5.02.27)","register_no":"13 - 0478","desc":"国際基督教大学の校地内中央西寄りに建つ、講堂兼学生会館。設計はヴォーリズ建築事務所。北にオーディトリアムを有し、中央に広い中庭を設けた正方形平面で、広いガラス面、水平感の強調、初期のアルミサッシュなど戦後モダニズム建築の特徴を備えた秀作。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014462"},{"id":"00016499","register_sub_id":"101","register_pk":"574861","name":"国際基督教大学本館","kana":"こくさいきりすときょうだいがくほんかん","category":"学校","subcategory":"建築物","type_guess":"記念館・資料室","type_guess_confidence":"low","period":"昭和前","pref":"東京都","address":"東京都三鷹市大沢三丁目1500-1他","lat":35.68168583,"lng":139.538495,"geo_status":"db","era":"昭和19年／昭和28年増築、同56年・平成15年改修","year":1944,"year_source":"db","year_min":1944,"year_max":1944,"year_label":null,"structure":"鉄筋コンクリート造4階建、建築面積2，752㎡","structure_material":"鉄筋コンクリート造4階建","registered":"2026.02.10(令和8.02.10)","register_no":"13 - 0530","desc":"旧中島飛行機三鷹研究所設計本館を戦後に転用した大学校舎。キャンパス中心部に建つ鉄筋コンクリート造3階建で中央５スパンを４階建に増築し、正面性を強調。平面は各階中央ホールから左右に中廊下を延ばす。ヴォーリズ事務所改修による端正な外観の校舎。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00016499"},{"id":"00011888","register_sub_id":"101","register_pk":"211059","name":"国士舘大講堂","kana":"こくしかんだいこうどう","category":"学校","subcategory":"建築物","type_guess":"講堂","type_guess_confidence":"high","period":"大正","pref":"東京都","address":"東京都世田谷区世田谷四丁目28-1","lat":35.648315,"lng":139.653416,"geo_status":"db","era":"大正8年／昭和33年・同56年改修","year":1919,"year_source":"db","year_min":1919,"year_max":1919,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積285㎡","structure_material":"木造平屋建","registered":"2017.10.27(平成29.10.27)","register_no":"13-385","desc":"構内中央に建つシンボル的な大講堂。正面に入母屋造の大屋根妻面を見せ、妻飾の木連格子、舟肘木など伝統的な意匠を採る。内部はクイーンポストトラスにより一〇八畳の広間を造り、大床を備えた講壇や折上格天井の空間で威容を誇る創立期唯一の遺構。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011888"},{"id":"00001566","register_sub_id":"101","register_pk":"102556","name":"渋谷区立広尾小学校","kana":"しぶやくりつひろおしょうがっこう","category":"学校","subcategory":"建築物","type_guess":"校舎","type_guess_confidence":"high","period":"昭和前","pref":"東京都","address":"東京都渋谷区東3-3-3","lat":35.651825,"lng":139.712143,"geo_status":"db","era":"昭和7","year":1932,"year_source":"db","year_min":1932,"year_max":1932,"year_label":null,"structure":"鉄筋コンクリート造3階建、建築面積940㎡","structure_material":"鉄筋コンクリート造3階建","registered":"2000.04.28(平成12.04.28)","register_no":"13 － 0081","desc":"高台に立つＲＣ造３階建で，関東大震災後の震災復興末期に建設。装飾は主に玄関廻りに用い，装飾を排したスタイルへの移行期の作風を示す。消防署が同居したことから火の見櫓としての塔屋を備える。設計は東京府の市ノ瀬仁重郎，施工は佐藤平治による。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001566"},{"id":"00014460","register_sub_id":"101","register_pk":"512444","name":"墨田区立言問小学校校舎","kana":"すみだくりつことといしょうがっこうこうしゃ","category":"学校","subcategory":"建築物","type_guess":"校舎","type_guess_confidence":"high","period":"昭和前","pref":"東京都","address":"東京都墨田区向島五丁目40","lat":35.71876111,"lng":139.81139722,"geo_status":"db","era":"昭和11年／平成23年改修","year":1936,"year_source":"db","year_min":1936,"year_max":1936,"year_label":null,"structure":"鉄筋コンクリート造3階建、建築面積1，554㎡","structure_material":"鉄筋コンクリート造3階建","registered":"2023.02.27(令和5.02.27)","register_no":"13 - 0476","desc":"花柳街で栄えた向島にある小学校の現役の近代校舎。鉄筋コンクリート造三階建、大きな窓を並べる外観はいわゆるインターナショナルスタイル。階段から上下階廊下を見通す進歩的な造り。下町に所在するため校庭側に開放的で、街路側の1階昇降口を高窓とする。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014460"},{"id":"00014461","register_sub_id":"101","register_pk":"512445","name":"墨田区立言問小学校講堂","kana":"すみだくりつことといしょうがっこうこうどう","category":"学校","subcategory":"建築物","type_guess":"講堂","type_guess_confidence":"high","period":"昭和前","pref":"東京都","address":"東京都墨田区向島五丁目40","lat":35.71878333,"lng":139.811725,"geo_status":"db","era":"昭和11年","year":1936,"year_source":"db","year_min":1936,"year_max":1936,"year_label":null,"structure":"鉄筋コンクリート造2階建、建築面積508㎡","structure_material":"鉄筋コンクリート造2階建","registered":"2023.02.27(令和5.02.27)","register_no":"13 - 0477","desc":"向島北部にある小学校の現役の近代講堂。鉄骨造陸屋根、大空間を鉄骨トラスで確保する。震災復興の影響を見るリベット留めの太い鉄骨柱は壁の内側に立て、水平に窓を並べるインターナショナルスタイルの平明な外観。校舎と共に白亜の殿堂と呼ばれ親しまれる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014461"},{"id":"00002893","register_sub_id":"101","register_pk":"103883","name":"滝乃川学園本館","kana":"たきのがわがくえんほんかん","category":"学校","subcategory":"建築物","type_guess":"記念館・資料室","type_guess_confidence":"low","period":"昭和前","pref":"東京都","address":"東京都国立市谷保6312","lat":35.680962,"lng":139.42955,"geo_status":"db","era":"昭和3","year":1928,"year_source":"db","year_min":1928,"year_max":1928,"year_label":null,"structure":"木造2階建、瓦葺、建築面積324㎡","structure_material":"木造2階建","registered":"2002.08.21(平成14.08.21)","register_no":"13 － 0133","desc":"木造総２階建，寄棟造・もとスレート葺で，玄関ポーチ付の中央部が一段高く，左右に両翼を延ばした形態とする。１階は中央廊下の前後に各室を配し，両端に階段室を設け，２階中央を講堂とする。胴蛇腹による水平線や整然と配した窓などに当時の造形が伺える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002893"},{"id":"00009720","register_sub_id":"101","register_pk":"195549","name":"東京工業大学大岡山西一号館（旧分析化学実験室）","kana":"とうきょうこうぎょうだいがくおおおかやまにしいちごうかん（きゅうぶんせきかがくじっけんしつ）","category":"学校","subcategory":"建築物","type_guess":"校舎","type_guess_confidence":"high","period":"昭和前","pref":"東京都","address":"東京都目黒区大岡山2-1-1","lat":35.6053703,"lng":139.68291935,"geo_status":"db","era":"昭和6","year":1931,"year_source":"db","year_min":1931,"year_max":1931,"year_label":null,"structure":"鉄筋コンクリート造2階一部地下1階建、建築面積644㎡、塔屋付","structure_material":"鉄筋コンクリート造2階一部地下1階建","registered":"2013.12.24(平成25.12.24)","register_no":"13 － 0305","desc":"本館の北西側に東面する鉄筋コンクリート造二階建でＴ字形平面になる。外観はロマネスク風にまとめてスクラッチタイルを貼り、壁頂部に歯飾りを付す。正面中央には本館同様に石貼のポーチを構え、重厚さを醸す。灯具などの細部も良好に残る、風格ある復興校舎。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009720"},{"id":"00009721","register_sub_id":"101","register_pk":"195550","name":"東京工業大学七〇周年記念講堂","kana":"とうきょうこうぎょうだいがくななじっしゅうねんきねんこうどう","category":"学校","subcategory":"建築物","type_guess":"講堂","type_guess_confidence":"high","period":"昭和中","pref":"東京都","address":"東京都目黒区大岡山2-1-1","lat":35.6058914,"lng":139.68359035,"geo_status":"db","era":"昭和30","year":1955,"year_source":"db","year_min":1955,"year_max":1955,"year_label":null,"structure":"鉄筋コンクリート造2階地下1階建一部地下2階付、建築面積1066㎡","structure_material":"鉄筋コンクリート造2階地下1階建一部地下2階付","registered":"2013.12.24(平成25.12.24)","register_no":"13 － 0306","desc":"本館前のキャンパス中心軸に東面して建つ。斜面地形を利用したホールを主体とした平面で、薄い軒を水平に差出し、中央にヴォールト屋根をかける。南側面には縦長のサッシを雁行させて独特な陰影をもつ窓割とし、テラコッタの装飾壁と共に豊かな表情を創り出す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009721"},{"id":"00009719","register_sub_id":"101","register_pk":"195548","name":"東京工業大学本館","kana":"とうきょうこうぎょうだいがくほんかん","category":"学校","subcategory":"建築物","type_guess":"記念館・資料室","type_guess_confidence":"low","period":"昭和前","pref":"東京都","address":"東京都目黒区大岡山2-1-1","lat":35.60443993,"lng":139.68386875,"geo_status":"db","era":"昭和9","year":1934,"year_source":"db","year_min":1934,"year_max":1934,"year_label":null,"structure":"鉄骨鉄筋コンクリート造3階一部4階地下1階建、建築面積7063㎡、塔屋付","structure_material":"鉄骨鉄筋コンクリート造3階一部4階地下1階建","registered":"2013.12.24(平成25.12.24)","register_no":"13 － 0304","desc":"大岡山キャンパスの中ほどに北面して建つ。主体部は鉄骨鉄筋コンクリート造三階建で、正面中央に塔屋や玄関ポーチを設ける。外壁は白いスクラッチタイル貼で、伊豆石貼のポーチに半円アーチを並べる。四方の立面を相称形に整え、本館としての威厳を備える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009719"},{"id":"00000388","register_sub_id":"101","register_pk":"101378","name":"東京商船大学１号館","kana":"とうきょうしょうせんだいがくいちごうかん","category":"学校","subcategory":"建築物","type_guess":"記念館・資料室","type_guess_confidence":"low","period":"昭和前","pref":"東京都","address":"東京都江東区越中島2-1-6","lat":35.66817421,"lng":139.79114384,"geo_status":"db","era":"昭和7","year":1932,"year_source":"db","year_min":1932,"year_max":1932,"year_label":null,"structure":"鉄筋コンクリート造3階建，建築面積1769㎡","structure_material":"鉄筋コンクリート造3階建","registered":"1997.12.12(平成9.12.12)","register_no":"13 － 0003","desc":"関東大震災で多くの校舎が倒壊したが，昭和７年に再建。東京高等商船学校時代は，本館と呼ばれていた。外壁をスクラッチタイル貼りとし，正面に半円形の大アーチの玄関部を設ける。簡潔にまとめ上げられた意匠になる校舎の好例。設計は文部省・大蔵省。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000388"},{"id":"00000391","register_sub_id":"101","register_pk":"101381","name":"東京商船大学旧天体観測所（第一観測台）","kana":"とうきょうしょうせんだいがくきゅうてんたいかんそくじょ（だいいちかんそくだい）","category":"学校","subcategory":"建築物","type_guess":"校舎","type_guess_confidence":"low","period":"明治","pref":"東京都","address":"東京都江東区越中島2-1-6","lat":35.66869347,"lng":139.79094413,"geo_status":"db","era":"明治36","year":1903,"year_source":"db","year_min":1903,"year_max":1903,"year_label":null,"structure":"煉瓦造2階建，鉄板葺，建築面積26㎡","structure_material":"煉瓦造2階建","registered":"1997.12.12(平成9.12.12)","register_no":"13 － 0006","desc":"正門の脇に建つ煉瓦造，２階建の観測台で，経緯儀室または赤道儀室が置かれた。一階は八角，二階は円形の平面をもち，二階外壁を漆喰塗りとしドーム屋根をかける。小規模ながら丁寧な造りの建物で，現存する数少ない明治期の天体観測施設として価値がある。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000391"},{"id":"00000392","register_sub_id":"101","register_pk":"101382","name":"東京商船大学旧天体観測所（第二観測台）","kana":"とうきょうしょうせんだいがくきゅうてんたいかんそくじょ（だいにかんそくだい）","category":"学校","subcategory":"建築物","type_guess":"校舎","type_guess_confidence":"low","period":"明治","pref":"東京都","address":"東京都江東区越中島2-1-6","lat":35.66885324,"lng":139.79111722,"geo_status":"db","era":"明治36","year":1903,"year_source":"db","year_min":1903,"year_max":1903,"year_label":null,"structure":"煉瓦造平屋建，鉄板葺，建築面積25㎡","structure_material":"煉瓦造平屋建","registered":"1997.12.12(平成9.12.12)","register_no":"13 － 0007","desc":"第一観測台の脇に建つ煉瓦造，平屋建の小規模な観測台で，子午儀室が置かれた。平面は八角形で，屋根は八角錐，鉄板葺とする明治期の観測施設。壁面等に独特の観測用開口部を設ける。細部意匠は第一観測台と類似し，設計は両者とも三橋四郎と推定されている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000392"},{"id":"00000390","register_sub_id":"101","register_pk":"101380","name":"東京商船大学事務局管理棟","kana":"とうきょうしょうせんだいがくじむきょくかんりとう","category":"学校","subcategory":"建築物","type_guess":"校舎","type_guess_confidence":"low","period":"昭和前","pref":"東京都","address":"東京都江東区越中島2-1-6","lat":35.66824078,"lng":139.79046482,"geo_status":"db","era":"昭和7","year":1932,"year_source":"db","year_min":1932,"year_max":1932,"year_label":null,"structure":"鉄筋コンクリート造2階建，建築面積400㎡","structure_material":"鉄筋コンクリート造2階建","registered":"1997.12.12(平成9.12.12)","register_no":"13 － 0005","desc":"１号館と同時に，図書館として再建されたものである。設計は文部省・大蔵省。外壁をスクラッチタイル貼とし，船をイメージした造形になるといわれ，細部の意匠も１号館と共通した構成要素がみられる。背後に円形の張り出し部をもつ構成は，特徴的である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000390"},{"id":"00000389","register_sub_id":"101","register_pk":"101379","name":"東京商船大学２号館","kana":"とうきょうしょうせんだいがくにごうかん","category":"学校","subcategory":"建築物","type_guess":"記念館・資料室","type_guess_confidence":"low","period":"昭和前","pref":"東京都","address":"東京都江東区越中島2-1-6","lat":35.66660314,"lng":139.79312766,"geo_status":"db","era":"昭和8","year":1933,"year_source":"db","year_min":1933,"year_max":1933,"year_label":null,"structure":"鉄筋コンクリート造2階建，建築面積2269㎡","structure_material":"鉄筋コンクリート造2階建","registered":"1997.12.12(平成9.12.12)","register_no":"13 － 0004","desc":"水産講習所本館として昭和８年に再建されたもので，設計は文部省・大蔵省。左右対称型の簡素な外観になる。外壁は，当時流行したスクラッチタイル貼とし，正面中央に４本の柱型を立て垂直性を強調した意匠とする。近年の改修で，性能向上が図られた。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000389"},{"id":"00000647","register_sub_id":"101","register_pk":"101637","name":"東京女子大学講堂・礼拝堂","kana":"とうきょうじょしだいがくこうどう・れいはいどう","category":"学校","subcategory":"建築物","type_guess":"講堂","type_guess_confidence":"high","period":"昭和前","pref":"東京都","address":"東京都杉並区善福寺2-6-1","lat":35.70950127,"lng":139.59187469,"geo_status":"db","era":"昭和13","year":1938,"year_source":"db","year_min":1938,"year_max":1938,"year_label":null,"structure":"鉄筋コンクリート造２階建塔屋付，建築面積1186㎡","structure_material":"鉄筋コンクリート造２階建塔屋付","registered":"1998.09.02(平成10.09.02)","register_no":"13 － 0028","desc":"戦前期レーモンドの最後期の作品。担当は杉山雅則。塔とプレキャストのトレーサリーに特徴がある。オーギュスト・ペレのランシー教会堂をモデルとしたことで名高い。正門を入って右手に位置し，手前の礼拝堂部と奥の講堂部とから成る。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000647"},{"id":"00000649","register_sub_id":"101","register_pk":"101639","name":"東京女子大学７号館（西校舎）","kana":"とうきょうじょしだいがくななごうかん（にしこうしゃ）","category":"学校","subcategory":"建築物","type_guess":"校舎","type_guess_confidence":"high","period":"大正","pref":"東京都","address":"東京都杉並区善福寺2-6-1","lat":35.71008246,"lng":139.59092274,"geo_status":"db","era":"大正13","year":1924,"year_source":"db","year_min":1924,"year_max":1924,"year_label":null,"structure":"鉄筋コンクリート造２階建，瓦葺，建築面積806㎡","structure_material":"鉄筋コンクリート造２階建","registered":"1998.09.02(平成10.09.02)","register_no":"13 － 0030","desc":"本館の左手前に位置し，中庭を介して東校舎に向き合う。Ｅ字型平面で、玄関奥に講堂を張りだす。東校舎と同様な外観を呈するが，教室窓は東校舎よりも大きく，５連のスチールサッシをはめる。中央部の意匠は，ライト調がより濃厚である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000649"},{"id":"00000646","register_sub_id":"101","register_pk":"101636","name":"東京女子大学本館","kana":"とうきょうじょしだいがくほんかん","category":"学校","subcategory":"建築物","type_guess":"記念館・資料室","type_guess_confidence":"low","period":"昭和前","pref":"東京都","address":"東京都杉並区善福寺2-6-1","lat":35.71044319,"lng":139.59130352,"geo_status":"db","era":"昭和6","year":1931,"year_source":"db","year_min":1931,"year_max":1931,"year_label":null,"structure":"鉄筋コンクリート造地下１階地上４階建，一部瓦葺，建築面積1015㎡","structure_material":"鉄筋コンクリート造地下１階地上４階建","registered":"1998.09.02(平成10.09.02)","register_no":"13 － 0027","desc":"図書館として建設。レーモンドによる大正１０年のキャンパス計画に予定されており，着工は遅れて昭和期にずれこんだが，初期レーモンドの特徴であるライト調の面影を残す。校舎ゾーンの中心的建造物で，正門の突き当たりに位置する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000646"},{"id":"00000648","register_sub_id":"101","register_pk":"101638","name":"東京女子大学６号館（東校舎）","kana":"とうきょうじょしだいがくろくごうかん（ひがしこうしゃ）","category":"学校","subcategory":"建築物","type_guess":"校舎","type_guess_confidence":"high","period":"大正","pref":"東京都","address":"東京都杉並区善福寺2-6-1","lat":35.71009248,"lng":139.59174442,"geo_status":"db","era":"大正14","year":1925,"year_source":"db","year_min":1925,"year_max":1925,"year_label":null,"structure":"鉄筋コンクリート造地下１階地上２階建，瓦葺，建築面積1453㎡","structure_material":"鉄筋コンクリート造地下１階地上２階建","registered":"1998.09.02(平成10.09.02)","register_no":"13 － 0029","desc":"自然科学教室として建設。本館の右手前、中庭に面して正面を西に向け西校舎に相対するが、正面中央玄関以南が最初に建ち、北半分は後の増築になる。２階建、寄棟屋根の校舎で、スチールサッシ３連の教室窓をとる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000648"},{"id":"00001842","register_sub_id":"101","register_pk":"102832","name":"東京大学教養学部旧第一高等学校本館（時計台）","kana":"とうきょうだいがくきょうようがくぶきゅうだいいちこうとうがっこうほんかん（とけいだい）","category":"学校","subcategory":"建築物","type_guess":"記念館・資料室","type_guess_confidence":"low","period":"昭和前","pref":"東京都","address":"東京都目黒区駒場3-8","lat":35.66001254,"lng":139.68493528,"geo_status":"db","era":"昭和8","year":1933,"year_source":"db","year_min":1933,"year_max":1933,"year_label":null,"structure":"鉄筋コンクリート造3階建、建築面積2464㎡、塔屋付","structure_material":"鉄筋コンクリート造3階建","registered":"2000.09.26(平成12.09.26)","register_no":"13 － 0089","desc":"昭和３年に東大農学部敷地跡に計画された第一高等学校の中心的施設。ロ字形平面，スクラッチタイル貼のＳＲＣ造２階建一部３階建の建物。設計は内田祥三と清水幸重，施工は銭高組で，ゴシック風の外観を呈す東大本郷キャンパスの建築群と意匠的類似性をもつ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001842"},{"id":"00000816","register_sub_id":"101","register_pk":"101806","name":"東京大学工学部１号館","kana":"とうきょうだいがくこうがくぶいちごうかん","category":"学校","subcategory":"建築物","type_guess":"記念館・資料室","type_guess_confidence":"low","period":"昭和前","pref":"東京都","address":"東京都文京区本郷7-3-1","lat":35.71430893,"lng":139.7600506,"geo_status":"db","era":"昭和10","year":1935,"year_source":"db","year_min":1935,"year_max":1935,"year_label":null,"structure":"鉄筋コンクリート造４階建，建築面積3263㎡","structure_material":"鉄筋コンクリート造４階建","registered":"1998.10.09(平成10.10.09)","register_no":"13 － 0037","desc":"旧工科大学本館が関東大震災で損壊したため，その跡地に建築されたもので，昭和１０年に竣工。鉄骨鉄筋コンクリート造で煉瓦タイル貼になる。外観は正面にゴシックアーチのアプローチが付き，各柱筋にバットレス風の付柱を持つ。設計は内田祥三。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000816"},{"id":"00000820","register_sub_id":"101","register_pk":"101810","name":"東京大学工学部列品館","kana":"とうきょうだいがくこうがくぶれっぴんかん","category":"学校","subcategory":"建築物","type_guess":"記念館・資料室","type_guess_confidence":"low","period":"大正","pref":"東京都","address":"東京都文京区本郷7-3-1","lat":35.71325355,"lng":139.7600539,"geo_status":"db","era":"大正14","year":1925,"year_source":"db","year_min":1925,"year_max":1925,"year_label":null,"structure":"鉄筋コンクリート造３階建，建築面積766㎡","structure_material":"鉄筋コンクリート造３階建","registered":"1998.10.09(平成10.10.09)","register_no":"13 － 0041","desc":"正門の左手奥に建つ建物で，工学部の本部が置かれる。建築途中に震災を受けたが，内田祥三の設計で，彼の震災復興計画に符合する形で完成した最初の建物としても知られる。かつては伊東忠太や関野貞等の収集した中国や朝鮮での調査資料が陳列されていた。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000820"},{"id":"00001762","register_sub_id":"101","register_pk":"102752","name":"東京大学先端科学技術研究センター十三号館（旧東京帝国大学航空研究所本館）","kana":"とうきょうだいがくせんたんかがくぎじゅつけんきゅうせんたーじゅうさんごうかん（きゅうていこくだいがくこうくうけんきゅうじょほんかん）","category":"学校","subcategory":"建築物","type_guess":"記念館・資料室","type_guess_confidence":"low","period":"昭和前","pref":"東京都","address":"東京都目黒区駒場4-5","lat":35.66283238,"lng":139.67738869,"geo_status":"db","era":"昭和4","year":1929,"year_source":"db","year_min":1929,"year_max":1929,"year_label":null,"structure":"鉄骨鉄筋コンクリート造3階建、建築面積735㎡、塔屋付","structure_material":"鉄骨鉄筋コンクリート造3階建","registered":"2000.09.26(平成12.09.26)","register_no":"13 － 0088","desc":"関東大震災後に越中島から移転した東京帝国大学航空研究所の中心施設。耐震耐火を考慮しＳＲＣ造スクラッチタイル貼とする。地上３階地下１階建，時計台付，全体に９本の水平帯を周し，最上層を縦縞状とする。設計は内田祥三と清水幸重，施工は大倉土木。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001762"},{"id":"00000035","register_sub_id":"101","register_pk":"101025","name":"東京大学大講堂（安田講堂）","kana":"とうきょうだいがくだいこうどう（やすだこうどう）","category":"学校","subcategory":"建築物","type_guess":"講堂","type_guess_confidence":"high","period":"大正","pref":"東京都","address":"東京都文京区本郷7-3-1","lat":35.71342334,"lng":139.76229586,"geo_status":"db","era":"大正14","year":1925,"year_source":"db","year_min":1925,"year_max":1925,"year_label":null,"structure":"鉄筋コンクリート造4階建塔屋付、建築面積1818㎡","structure_material":"鉄筋コンクリート造4階建塔屋付","registered":"1996.12.20(平成8.12.20)","register_no":"13 － 0001","desc":"ゴシック及び表現主義の影響が色濃く見られる垂直性の強いデザインが特徴。外壁は赤茶色のタイル貼りで，意匠的に極めて優秀である。設計は内田祥三，施工は清水組。昭和63年から平成６年にかけて改修が行われている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000035"},{"id":"00000819","register_sub_id":"101","register_pk":"101809","name":"東京大学法学部３号館","kana":"とうきょうだいがくほうがくぶさんごうかん","category":"学校","subcategory":"建築物","type_guess":"記念館・資料室","type_guess_confidence":"low","period":"昭和前","pref":"東京都","address":"東京都文京区本郷7-3-1","lat":35.71262797,"lng":139.76025705,"geo_status":"db","era":"昭和2","year":1927,"year_source":"db","year_min":1927,"year_max":1927,"year_label":null,"structure":"鉄筋コンクリート造４階建，建築面積1727㎡","structure_material":"鉄筋コンクリート造４階建","registered":"1998.10.09(平成10.10.09)","register_no":"13 － 0040","desc":"正門のすぐ右手に建つ校舎で，工学部列品館とは東西軸を挟んで向かい合う。正面の出入り口は列品館と同様のゴシックアーチのアーケードを設けるが，東面の意匠は総合図書館と工学部１号館を結ぶ軸線を意識した垂直線を強調する構成になる。設計は内田祥三。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000819"},{"id":"00000817","register_sub_id":"101","register_pk":"101807","name":"東京大学法文１号館","kana":"とうきょうだいがくほうぶんいちごうかん","category":"学校","subcategory":"建築物","type_guess":"記念館・資料室","type_guess_confidence":"low","period":"昭和前","pref":"東京都","address":"東京都文京区本郷7-3-1","lat":35.71353323,"lng":139.76134764,"geo_status":"db","era":"昭和10","year":1935,"year_source":"db","year_min":1935,"year_max":1935,"year_label":null,"structure":"鉄筋コンクリート造３階建一部４階建，建築面積2695㎡","structure_material":"鉄筋コンクリート造３階建一部４階建","registered":"1998.10.09(平成10.10.09)","register_no":"13 － 0038","desc":"東大キャンパスの主軸をなす正門と大講堂を結ぶ東西軸に沿って建つ校舎の一つで，入口ポーチのフィニアルは，旧校舎のものを再用した。１階部分に三廊形式の教会内部を思わせるゴシック様式のアーケードを配し南北通路を跨ぐ構成とする。設計は内田祥三。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000817"},{"id":"00000818","register_sub_id":"101","register_pk":"101808","name":"東京大学法文２号館","kana":"とうきょうだいがくほうぶんにごうかん","category":"学校","subcategory":"建築物","type_guess":"記念館・資料室","type_guess_confidence":"low","period":"昭和前","pref":"東京都","address":"東京都文京区本郷7-3-1","lat":35.71302707,"lng":139.76144415,"geo_status":"db","era":"昭和13","year":1938,"year_source":"db","year_min":1938,"year_max":1938,"year_label":null,"structure":"鉄筋コンクリート造４階建，建築面積3435㎡","structure_material":"鉄筋コンクリート造４階建","registered":"1998.10.09(平成10.10.09)","register_no":"13 － 0039","desc":"法文１号館と東西軸を挟んで向かい合う位置に建つ校舎で，１号館同様１階部分にゴシック様式のアーケードを配し通路を設けるが，西端部は法学部３号館を意識したＬ字型の平面構成となる。法文１号館とも，近年４階の１部が増築された。設計は内田祥三。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000818"},{"id":"00000815","register_sub_id":"101","register_pk":"101805","name":"東京大学本郷正門及び門衛所","kana":"とうきょうだいがくほんごうせいもんおよびもんえいじょ","category":"学校","subcategory":"その他工作物","type_guess":"正門","type_guess_confidence":"high","period":"明治","pref":"東京都","address":"東京都文京区本郷7-3-1","lat":35.71294276,"lng":139.75966356,"geo_status":"db","era":"明治45","year":1912,"year_source":"db","year_min":1912,"year_max":1912,"year_label":null,"structure":"鉄筋コンクリート造平屋建，銅板葺，建築面積46㎡","structure_material":"鉄筋コンクリート造平屋建","registered":"1998.10.09(平成10.10.09)","register_no":"13 － 0036","desc":"東京大学の正面を飾る一連の施設で，左右対称型に正門・煉瓦塀・門衛所が建ち並ぶ。花崗岩製の正門は，冠木門を基調にデザインされたといわれ，むくり屋根の妻を見せる門衛所とも伝統的な様式形態を保ちつつ新たな時代性を追求している。設計は伊東忠太。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000815"},{"id":"00008260","register_sub_id":"101","register_pk":"133902","name":"東京大学野球場観覧席・ダッグアウト及びフェンス","kana":"とうきょうだいがくやきゅうじょうかんらんせき・だっぐあうとおよびふぇんす","category":"学校","subcategory":"その他工作物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"東京都","address":"東京都文京区弥生1-1-1","lat":35.71880215,"lng":139.76050338,"geo_status":"db","era":"昭和12年","year":1937,"year_source":"db","year_min":1937,"year_max":1937,"year_label":null,"structure":"観覧席及びダッグアウト 鉄筋コンクリート造3階建、建築面積460㎡、フェンス 鉄筋コンクリート造、延長352m","structure_material":"観覧席及びダッグアウト 鉄筋コンクリート造3階建","registered":"2010.09.10(平成22.09.10)","register_no":"13 － 0259","desc":"東京大学弥生キャンパス内に所在する。内部に記者席、更衣室等を配する階段状の観覧席に、片持ち支持のアーチ形屋根を架ける。観覧席の左右に配されたダッグアウト、グラウンドを囲むフェンスを含め、全体をＲＣでつくる。戦前に遡る数少ない現役の野球場施設。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008260"},{"id":"00001764","register_sub_id":"101","register_pk":"102754","name":"東京農工大学農学部本館","kana":"とうきょうのうこうだいがくのうがくぶほんかん","category":"学校","subcategory":"建築物","type_guess":"記念館・資料室","type_guess_confidence":"low","period":"昭和前","pref":"東京都","address":"東京都府中市幸町3-5-8","lat":35.68421261,"lng":139.48125327,"geo_status":"db","era":"昭和9","year":1934,"year_source":"db","year_min":1934,"year_max":1934,"year_label":null,"structure":"鉄骨鉄筋コンクリート造3階、建築面積2896㎡","structure_material":"鉄骨鉄筋コンクリート造3階","registered":"2000.09.26(平成12.09.26)","register_no":"13 － 0091","desc":"もと東京高等農林学校本館。Ｅ形平面を持つＳＲＣ造３階建で，中央部に時計台を冠する。外装はモルタル塗を基調とし，軒及び開口部周辺等にスクラッチ及び褐色タイルを貼る。東京帝大農学部実科の本館として計画されたもので，東京帝大営繕課が設計にあたる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001764"},{"id":"00007877","register_sub_id":"101","register_pk":"108857","name":"日本学園一号館","kana":"にほんがくえんいちごうかん","category":"学校","subcategory":"建築物","type_guess":"記念館・資料室","type_guess_confidence":"low","period":"昭和前","pref":"東京都","address":"東京都世田谷区松原2-735-3他","lat":35.66510615,"lng":139.64897741,"geo_status":"db","era":"昭和11／昭和53・平成7改修","year":1936,"year_source":"db","year_min":1936,"year_max":1936,"year_label":null,"structure":"鉄筋コンクリート造3階建、建築面積1118㎡","structure_material":"鉄筋コンクリート造3階建","registered":"2009.11.02(平成21.11.02)","register_no":"13-0248","desc":"正面玄関を東に向け、北敷地境と平行して教室棟を配する片廊下型校舎。ＲＣ造３階建、建築面積１１１８㎡。柱梁構造を外観に現し、南面する教室の窓を大きくとる。正門から前庭を介して望む三層分の高さの角柱が並ぶ正面玄関は、正統的で風格を備える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007877"},{"id":"00001765","register_sub_id":"101","register_pk":"102755","name":"一橋大学兼松講堂","kana":"ひとつばしだいがくかねまつこうどう","category":"学校","subcategory":"建築物","type_guess":"講堂","type_guess_confidence":"high","period":"昭和前","pref":"東京都","address":"東京都国立市中2-1","lat":35.69501172,"lng":139.44537877,"geo_status":"db","era":"昭和2","year":1927,"year_source":"db","year_min":1927,"year_max":1927,"year_label":null,"structure":"鉄筋コンクリート造2階建、建築面積1471㎡","structure_material":"鉄筋コンクリート造2階建","registered":"2000.09.26(平成12.09.26)","register_no":"13 － 0092","desc":"東京商科大学国立移転のシンボル的建築。神戸の名士兼松房治郎の13回忌を期に，寄付で建設される。ＲＣ造２階建，外装スクラッチタイル張り，腰石張りで，正面妻面に校章を掲げる。伊東忠太設計のロマネスク風建築として知られる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001765"},{"id":"00001766","register_sub_id":"101","register_pk":"102756","name":"一橋大学旧門衛所","kana":"ひとつばしだいがくきゅうもんえいじょ","category":"学校","subcategory":"建築物","type_guess":"正門","type_guess_confidence":"low","period":"昭和前","pref":"東京都","address":"東京都国立市中2-1","lat":35.694401,"lng":139.445984,"geo_status":"db","era":"昭和6","year":1931,"year_source":"db","year_min":1931,"year_max":1931,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積53㎡","structure_material":"木造平屋建","registered":"2000.09.26(平成12.09.26)","register_no":"13 － 0093","desc":"東京商科大学の門衛所として建設。２つの校門の間，キャンパスの中心軸線上の緑地帯に位置し，図書館に向きあう。外装はモルタル塗，腰スクラッチタイル矢筈積及び下見板張で，側面に鉄板葺の出窓を設けたフランス瓦葺ハーフティンバーの瀟洒な洋風建築。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001766"},{"id":"00001767","register_sub_id":"101","register_pk":"102757","name":"一橋大学東本館","kana":"ひとつばしだいがくひがしほんかん","category":"学校","subcategory":"建築物","type_guess":"記念館・資料室","type_guess_confidence":"low","period":"昭和前","pref":"東京都","address":"東京都国立市中2-1","lat":35.69557823,"lng":139.44787449,"geo_status":"db","era":"昭和4","year":1929,"year_source":"db","year_min":1929,"year_max":1929,"year_label":null,"structure":"鉄筋コンクリート造2階建、建築面積1711㎡","structure_material":"鉄筋コンクリート造2階建","registered":"2000.09.26(平成12.09.26)","register_no":"13 － 0094","desc":"一橋大学は，堤康次郎の構想による国立学園都市の中核施設として昭和２～５年に神田から移転。大学通り東側のキャンパス地に商学専門部本館として建設される。ロ字形平面ＲＣ造２階建で，兼松講堂と似たロマネスク風の意匠を基調とする。設計は文部省建築課。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001767"},{"id":"00011657","register_sub_id":"101","register_pk":"210673","name":"鎌倉市立御成小学校旧講堂","kana":"かまくらしりつおなりしょうがっこうきゅうこうどう","category":"学校","subcategory":"建築物","type_guess":"講堂","type_guess_confidence":"high","period":"昭和前","pref":"神奈川県","address":"神奈川県鎌倉市御成町625-3","lat":35.318187,"lng":139.547823,"geo_status":"db","era":"昭和8年","year":1933,"year_source":"db","year_min":1933,"year_max":1933,"year_label":null,"structure":"木造平屋建、鋼板葺、建築面積684㎡","structure_material":"木造平屋建","registered":"2017.06.28(平成29.06.28)","register_no":"14-0229","desc":"木造平屋建の講堂。南北棟の入母屋造鋼板葺で、棟上に塔屋二所を設け、小屋はクイーンポストトラスとする。東側面に玄関突出部を配し、内部は講堂の南に準備室二室、北の舞台裏側に控室および用具置場を配す。内外に和洋の要素を併せ持つ、希少な大規模講堂。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011657"},{"id":"00002021","register_sub_id":"101","register_pk":"103011","name":"横浜国立大学教育人間科学部附属横浜中学校校舎（旧横浜高等工業学校本館）","kana":"よこはまこくりつだいがくきょういくにんげんかがくぶふぞくよこはまちゅうがっこうこうしゃ（きゅうよこはまこうとうこうぎょうがっこうほんかん）","category":"学校","subcategory":"建築物","type_guess":"校舎","type_guess_confidence":"high","period":"昭和前","pref":"神奈川県","address":"神奈川県横浜市南区大岡2-31-3","lat":35.42283131,"lng":139.60291221,"geo_status":"db","era":"昭和13","year":1938,"year_source":"db","year_min":1938,"year_max":1938,"year_label":null,"structure":"鉄筋コンクリート造3階建、建築面積1800㎡","structure_material":"鉄筋コンクリート造3階建","registered":"2000.12.04(平成12.12.04)","register_no":"14 － 0046","desc":"文部省直轄学校における鉄筋コンクリート造校舎の戦前最後期のもの。両翼を前面に突出させたルネサンス様式的形態をとるが，外観は窓台・まぐさを連続させて水平線を強調するとともに，正面中央に縦長の連続窓を配するなどモダニズム的意匠でまとめる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002021"},{"id":"00001567","register_sub_id":"101","register_pk":"102557","name":"横浜国立大学名教自然碑","kana":"よこはまこくりつだいがくめいきょうしぜんひ","category":"学校","subcategory":"その他工作物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"神奈川県","address":"神奈川県横浜市保土ケ谷区常盤台79-5","lat":35.47412757,"lng":139.58829601,"geo_status":"db","era":"昭和12／昭和54移築","year":1937,"year_source":"db","year_min":1937,"year_max":1937,"year_label":null,"structure":"石造、高さ6.6m","structure_material":"石造","registered":"2000.04.28(平成12.04.28)","register_no":"14 － 0039","desc":"横浜国立大学工学部の前身，横浜高等工業学校の初代校長である鈴木達治の功績を讃えて建てられた。高さ６．６ｍ，方尖柱型の石碑で，設計は同校建築学科教授の中村順平。端整な比例と素材を生かした造形に，気品のある記念性がうかがわれる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001567"},{"id":"00009132","register_sub_id":"101","register_pk":"164685","name":"旧川上小学校体育館","kana":"きゅうかわかみしょうがっこうたいいくかん","category":"学校","subcategory":"建築物","type_guess":"体育館","type_guess_confidence":"high","period":"昭和前","pref":"新潟県","address":"新潟県上越市牧区切光1438-1","lat":37.08478541,"lng":138.42058062,"geo_status":"db","era":"昭和27年／平成22年改修","year":1952,"year_source":"db","year_min":1952,"year_max":1952,"year_label":null,"structure":"木造平屋一部2階建、鉄板葺、建築面積321㎡","structure_material":"木造平屋一部2階建","registered":"2012.02.23(平成24.02.23)","register_no":null,"desc":"木造平屋1部2階建、建築面積321平方メートル、切妻造鉄板葺。南妻面を入口とし、上部から体育館側に張出す中2階の礼法室を設ける。内部は天井を張らず、トラス組の小屋を現す。地元住民によって建設された、地域教育を象徴する体育館。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009132"},{"id":"00014153","register_sub_id":"101","register_pk":"508783","name":"新潟県立加茂農林高等学校正門","kana":"にいがたけんりつかものうりんこうとうがっこうせいもん","category":"学校","subcategory":"その他工作物","type_guess":"正門","type_guess_confidence":"high","period":"明治","pref":"新潟県","address":"新潟県加茂市神明町二丁目15-5","lat":37.66267222,"lng":139.05978889,"geo_status":"db","era":"明治37年／平成30年改修","year":1904,"year_source":"db","year_min":1904,"year_max":1904,"year_label":null,"structure":"煉瓦造、間口4.6m、脇門柱付","structure_material":"煉瓦造","registered":"2022.02.17(令和4.02.17)","register_no":"15-0565","desc":"前身の農林学校正門として建設された。旧三国街道に面する校地中央に位置する。主門柱は基礎石上に煉瓦のイギリス積の角柱を立て、柱頭は狭間を彫った鉢巻石や、歯形模様付の笠石で飾る。北の脇門柱も同意匠で、表構えを象徴的に演出する重厚な門である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014153"},{"id":"00014152","register_sub_id":"101","register_pk":"508782","name":"新潟県立加茂農林高等学校第二洋灯室（ランプ記念館）","kana":"にいがたけんりつかものうりんこうとうがっこうだいにようとうしつ(らんぷきねんかん)","category":"学校","subcategory":"建築物","type_guess":"記念館・資料室","type_guess_confidence":"high","period":"明治","pref":"新潟県","address":"新潟県加茂市神明町二丁目15-5","lat":37.66289167,"lng":139.06180556,"geo_status":"db","era":"明治40年／昭和60年移築","year":1907,"year_source":"db","year_min":1907,"year_max":1907,"year_label":null,"structure":"煉瓦造平屋建、瓦葺、建築面積19㎡","structure_material":"煉瓦造平屋建","registered":"2022.02.17(令和4.02.17)","register_no":"15-0564","desc":"前身の県立農林学校時代の建設で、寄宿舎で使うランプを消灯時に収容し、清掃や給油も行った。壁は煉瓦のオランダ積で内外とも現しとする。寄棟造桟瓦葺の小屋組はキングポスト・トラス。入口は両開き鉄扉で防火に配慮する。寄宿舎生活を支えた建物である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014152"},{"id":"00008833","register_sub_id":"101","register_pk":"162276","name":"新潟県立長岡高等学校（旧制長岡中學校）正門","kana":"にいがたけんりつながおかこうとうがっこう（きゅうせいながおかちゅうがっこう）せいもん","category":"学校","subcategory":"その他工作物","type_guess":"正門","type_guess_confidence":"high","period":"大正","pref":"新潟県","address":"新潟県長岡市学校町3-14-1","lat":37.44469685,"lng":138.85861222,"geo_status":"db","era":"大正5年","year":1916,"year_source":"db","year_min":1916,"year_max":1916,"year_label":null,"structure":"煉瓦造、間口10m","structure_material":"煉瓦造","registered":"2011.10.28(平成23.10.28)","register_no":"15 － 0342","desc":"敷地の西面中央に位置する。煉瓦造、高さ2.7ｍの親柱を6.9ｍ間隔で配し、その北側に高さ2.4ｍの脇柱を設置して通用門とする。頂部には歯飾りや持送を表現した洋風意匠の笠石をのせる。往時の学舎の面影を伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008833"},{"id":"00006963","register_sub_id":"101","register_pk":"107945","name":"新潟県立村松高等学校（旧新潟県立工業学校）正門","kana":"にいがたけんりつむらまつこうとうがっこう（きゅうにいがたけんりつこうぎょうがっこう）せいもん","category":"学校","subcategory":"その他工作物","type_guess":"正門","type_guess_confidence":"high","period":"明治","pref":"新潟県","address":"新潟県五泉市村松甲5545","lat":37.68730342,"lng":139.18121357,"geo_status":"db","era":"明治後期","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"煉瓦造門柱2基、間口4.5m、左側通用門付","structure_material":"煉瓦造門柱2基","registered":"2008.03.07(平成20.03.07)","register_no":"15 － 0277","desc":"校舎正面に建つ。門口４．５ｍ、高さ４ｍの門柱一対の片側に通用門を開く。門柱はいずれも煉瓦造で、柱頭にコーニスを付けて飾る。中央の門柱一対はイギリス積で、通用門側の脇柱はフランス積として変化をつける。県下初の工業学校に建てられた、記念碑的な校門。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006963"},{"id":"00004951","register_sub_id":"101","register_pk":"105941","name":"新潟大学旭町学術資料展示館（旧新潟師範学校記念館）","kana":"にいがただいがくあさひまちがくじゅつしりょうてんじかん（きゅうにいがたしはんがっこうきねんかん）","category":"学校","subcategory":"建築物","type_guess":"記念館・資料室","type_guess_confidence":"high","period":"昭和前","pref":"新潟県","address":"新潟県新潟市中央区旭町通2-746","lat":37.921192,"lng":139.036621,"geo_status":"db","era":"昭和4","year":1929,"year_source":"db","year_min":1929,"year_max":1929,"year_label":null,"structure":"鉄筋コンクリート造2階建、建築面積133㎡","structure_material":"鉄筋コンクリート造2階建","registered":"2005.11.10(平成17.11.10)","register_no":"15 － 0187","desc":"市内に残る初期の鉄筋コンクリート造２階建。昭和初期に流行したネオ・ゴシック様式で，北を正面とし，外壁は１階腰に人造石を廻し，他はスクラッチタイル張とする。正面と両側面は柱型を現し，窓は縦長とする。設計図面から，設計・施工は東京の清水組。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004951"},{"id":"00004952","register_sub_id":"101","register_pk":"105942","name":"新潟大学医学部（旧新潟医学専門学校）表門及び煉瓦塀","kana":"にいがただいがくいがくぶ（きゅうにいがたいがくせんもんがっこう）おもてもんおよびれんがべい","category":"学校","subcategory":"その他工作物","type_guess":"正門","type_guess_confidence":"low","period":"明治","pref":"新潟県","address":"新潟県新潟市中央区旭町通1-757","lat":37.92065408,"lng":139.03627852,"geo_status":"db","era":"明治44・大正3／昭和57移設","year":1911,"year_source":"db","year_min":1911,"year_max":1911,"year_label":null,"structure":"表門 煉瓦造、間柱高さ2.7m、煉瓦塀 煉瓦造、延長149m","structure_material":"表門 煉瓦造","registered":"2005.11.10(平成17.11.10)","register_no":"15 － 0188","desc":"新潟大学医学部の敷地北辺にある。大正３年建設の表門は煉瓦と白花崗岩の混合積とした高さ２．７ｍの門柱２本からなり，昭和５７年に移設されるが，形式は保持している。明治４４年建設の煉瓦塀は延長１４９ｍで，形状は土地勾配に合わせた階段式とする。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004952"},{"id":"00010765","register_sub_id":"101","register_pk":"201600","name":"旧大鋸屋小学校体育館","kana":"きゅうおがやしょうがっこうたいいくかん","category":"学校","subcategory":"建築物","type_guess":"体育館","type_guess_confidence":"high","period":"昭和前","pref":"富山県","address":"富山県南砺市大鋸屋125他","lat":36.499303,"lng":136.900313,"geo_status":"db","era":"昭和4","year":1929,"year_source":"db","year_min":1929,"year_max":1929,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積412㎡","structure_material":"木造平屋建","registered":"2015.11.17(平成27.11.17)","register_no":"16 ‐ 0111","desc":"柱形と柱間の下見板張を意匠的に表した外観をもち、妻壁は二段に迫出して下見板を台形に張り、意匠を凝らす。クイーンポストの小屋組は木材と鋼材を併用し、桁行方向もトラスで固めるという、独特な工法をもつ。県内に残る戦前の木造学校建築として希少な遺構。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010765"},{"id":"00011121","register_sub_id":"101","register_pk":"205228","name":"田中小学校旧本館","kana":"たなかしょうがっこうきゅうほんかん","category":"学校","subcategory":"建築物","type_guess":"記念館・資料室","type_guess_confidence":"low","period":"昭和前","pref":"富山県","address":"富山県滑川市加島町230-1","lat":36.759589,"lng":137.333968,"geo_status":"db","era":"昭和11／平成元・同25改修","year":1936,"year_source":"db","year_min":1936,"year_max":1936,"year_label":null,"structure":"木造2階建、瓦葺、建築面積621㎡","structure_material":"木造2階建","registered":"2016.08.01(平成28.08.01)","register_no":"16 - 0120","desc":"木造二階建の校舎。桁行六〇・〇メートル、梁間一〇・〇メートルで、正面側に片廊下を通して背面側に教室等を配する。天井・電気器具・内装木部・手摺などにルネサンス、アールデコ、幾何学模様などを用いるなど、意匠を凝らした昭和前期学校建築の好例。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011121"},{"id":"00011665","register_sub_id":"101","register_pk":"210681","name":"富山県立魚津高等学校講堂","kana":"とやまけんりつうおづこうとうがっこうこうどう","category":"学校","subcategory":"建築物","type_guess":"講堂","type_guess_confidence":"high","period":"昭和前","pref":"富山県","address":"富山県魚津市吉島945","lat":36.830277,"lng":137.411617,"geo_status":"db","era":"昭和12年／昭和30年・同62年・平成28年改修","year":1937,"year_source":"db","year_min":1937,"year_max":1937,"year_label":null,"structure":"鉄筋コンクリート造平屋一部2階建、瓦葺、建築面積535㎡","structure_material":"鉄筋コンクリート造平屋一部2階建","registered":"2017.06.28(平成29.06.28)","register_no":"16-0121","desc":"桁行二九・三メートル、梁間一六・四メートルの鉄筋コンクリート造講堂。屋根は切妻造で釉薬瓦を葺く。内部は三方にギャラリーを設け、小屋は鉄骨トラスとする。比較的早い時期の鉄筋コンクリート造で、柱型や屋根の端部を立ち上げるなど特色ある意匠を持つ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011665"},{"id":"00012889","register_sub_id":"101","register_pk":"367997","name":"吉江地区招魂社（旧吉江小学校奉安殿）","kana":"よしえちくしょうこんしゃ（きゅうよしえしょうがっこうほうあんでん）","category":"学校","subcategory":"建築物","type_guess":"記念館・資料室","type_guess_confidence":"high","period":"昭和前","pref":"富山県","address":"富山県南砺市荒木725","lat":36.55521389,"lng":136.88071111,"geo_status":"db","era":"昭和5年／昭和32年移築","year":1930,"year_source":"db","year_min":1930,"year_max":1930,"year_label":null,"structure":"石造平屋建、金属板葺、建築面積3.5㎡","structure_material":"石造平屋建","registered":"2019.09.10(令和1.09.10)","register_no":"16 － 146","desc":"地区公園の一角にあり、高い二重基壇上に北面して建つ。石造で、方形の主体部前面にエンタシス付の柱を立て、アーキトレーブと大振りのコーニスを廻し、切妻造の屋根を載せる。西洋古典様式を取り入れた和洋折衷の上質なつくりで、戦前の奉安殿の好例を示す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012889"},{"id":"00014795","register_sub_id":"101","register_pk":"519053","name":"金沢大学医学類（旧制金沢医学専門学校）西面北煉瓦塀","kana":"かなざわだいがくいがくるい（きゅうせいかなざわいがくせんもんがっこう）にしめんきたれんがべい","category":"学校","subcategory":"その他工作物","type_guess":"正門","type_guess_confidence":"low","period":"明治","pref":"石川県","address":"石川県金沢市宝町13-1","lat":36.55535278,"lng":136.67289722,"geo_status":"db","era":"明治45年","year":1912,"year_source":"db","year_min":1912,"year_max":1912,"year_label":null,"structure":"煉瓦造、延長18m","structure_material":"煉瓦造","registered":"2024.03.06(令和6.03.06)","register_no":"17 - 0316","desc":"敷地南西面、北西端に残る延長18メートルの煉瓦塀。道路との間に水路を設け、その敷地側に低い煉瓦塀を築く。切石積基礎及び延石の上に煉瓦を積み、人造石洗出の笠石を載せる。旧制金沢医学専門学校時代の貴重な遺構で、通りに沿って歴史的景観をつくる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014795"},{"id":"00014794","register_sub_id":"101","register_pk":"519052","name":"金沢大学医学類（旧制金沢医学専門学校）西面南旧正門及び煉瓦塀","kana":"かなざわだいがくいがくるい（きゅうせいかなざわいがくせんもんがっこう）にしめんみなみきゅうせいもんおよびれんがべい","category":"学校","subcategory":"その他工作物","type_guess":"正門","type_guess_confidence":"high","period":"明治","pref":"石川県","address":"石川県金沢市宝町13-1","lat":36.55460833,"lng":136.67386389,"geo_status":"db","era":"明治45年","year":1912,"year_source":"db","year_min":1912,"year_max":1912,"year_label":null,"structure":"旧正門控柱 石造、塀 煉瓦造、総延長202m","structure_material":"旧正門控柱 石造","registered":"2024.03.06(令和6.03.06)","register_no":"17 - 0315","desc":"敷地西面南、旧正門を挟んで道路に沿った総延長二○二メートルの低い煉瓦塀。旧正門は主門柱を欠失するが、花崗岩切石造の脇門柱が二本残る。塀は基礎及び延石を切石積、壁体を煉瓦積、笠石を人造石洗出仕上とする。旧制金沢医学専門学校時代の貴重な遺構。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014794"},{"id":"00014792","register_sub_id":"101","register_pk":"519050","name":"金沢大学医学類解剖標本庫（旧制金沢医科大学解剖学標本庫）","kana":"かなざわだいがくいがくるいかいぼうひょうほんこ（きゅうせいかなざわいかだいがくかいぼうがくひょうほんこ）","category":"学校","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"石川県","address":"石川県金沢市宝町13-1","lat":36.55583333,"lng":136.67489722,"geo_status":"db","era":"昭和9年／昭和61年改修","year":1934,"year_source":"db","year_min":1934,"year_max":1934,"year_label":null,"structure":"鉄筋コンクリート造平屋建、建築面積194㎡","structure_material":"鉄筋コンクリート造平屋建","registered":"2024.03.06(令和6.03.06)","register_no":"17 - 0313","desc":"旧制金沢医科大学の解剖標本庫。鉄筋コンクリート造平屋建陸屋根。外壁スクラッチタイル貼。柱形の列柱をみせ、各間に窓を開き、簡素ながらも重厚な意匠。内部は一室の土間で標本を陳列した木製棚を並べる。大学草創期の医学研究・教育の実像を現在に伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014792"},{"id":"00014791","register_sub_id":"101","register_pk":"519049","name":"金沢大学医学類旧書庫（旧制金沢医科大学附属図書館書庫）","kana":"かなざわだいがくいがくるいきゅうしょこ（きゅうせいかなざわいかだいがくふぞくとしょかんしょこ）","category":"学校","subcategory":"建築物","type_guess":"図書館","type_guess_confidence":"high","period":"大正","pref":"石川県","address":"石川県金沢市宝町13-1","lat":36.55548611,"lng":136.67425,"geo_status":"db","era":"大正15年／昭和60年改修","year":1926,"year_source":"db","year_min":1926,"year_max":1926,"year_label":null,"structure":"鉄筋コンクリート造3階建、建築面積142㎡","structure_material":"鉄筋コンクリート造3階建","registered":"2024.03.06(令和6.03.06)","register_no":"17 - 0312","desc":"旧制金沢医科大学の図書館書庫。鉄筋コンクリート造三階建陸屋根。外壁は人造石洗出、四隅に柱形を付け、各間に縦長窓を配し、直方体の外観に変化を付ける。内部は各階一室で廻り階段中央に当初の昇降機が残る。草創期からの貴重な鉄筋コンクリート造書庫。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014791"},{"id":"00014793","register_sub_id":"101","register_pk":"519051","name":"金沢大学医学類病理標本庫（旧制金沢医科大学病理学標本庫）","kana":"かなざわだいがくいがくるいびょうりひょうほんこ（きゅうせいかなざわいかだいがくびょうりがくひょうほんこ）","category":"学校","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"石川県","address":"石川県金沢市宝町13-1","lat":36.55645556,"lng":136.67466944,"geo_status":"db","era":"大正15年／昭和60年改修","year":1926,"year_source":"db","year_min":1926,"year_max":1926,"year_label":null,"structure":"鉄筋コンクリート造2階建、建築面積99㎡","structure_material":"鉄筋コンクリート造2階建","registered":"2024.03.06(令和6.03.06)","register_no":"17 - 0314","desc":"旧制金沢医科大学の病理標本庫。鉄筋コンクリート造二階建陸屋根。外壁は人造石洗出、柱形をみせ、窓廻りに煉瓦を貼り、簡素ながらも整然とした意匠。内部は各階一室とし、独立柱を立て、柱型と梁で繋ぐ。大学草創期から残り、構内の歴史的な景観に寄与する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014793"},{"id":"00012896","register_sub_id":"101","register_pk":"367999","name":"川上幼稚園園舎","kana":"かわかみようちえんえんしゃ","category":"学校","subcategory":"建築物","type_guess":"校舎","type_guess_confidence":"high","period":"大正","pref":"石川県","address":"石川県金沢市幸町378他","lat":36.55324167,"lng":136.65918889,"geo_status":"db","era":"大正7年頃／昭和40年頃・平成23年改修","year":1918,"year_source":"db","year_min":1918,"year_max":1918,"year_label":null,"structure":"木造2階建、瓦葺、建築面積299㎡","structure_material":"木造2階建","registered":"2019.09.10(令和1.09.10)","register_no":"17 － 285","desc":"市街地南部の住宅地にあり、敷地後方に東面して建つ。木造二階建、切妻造桟瓦葺妻入で、正面下屋の北端に玄関ポーチを突出する。外壁下見板張。トラス小屋組。上下階南半を大部屋として保育室にあてる。近代住宅地の閑静な景観に調和し、地域に親しまれる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012896"},{"id":"00014798","register_sub_id":"101","register_pk":"519056","name":"旧第四高等中学校門衛所","kana":"きゅうだいしこうとうちゅうがっこうもんえいじょ","category":"学校","subcategory":"建築物","type_guess":"正門","type_guess_confidence":"high","period":"明治","pref":"石川県","address":"石川県金沢市広坂二丁目65-2","lat":36.56228611,"lng":136.65561111,"geo_status":"db","era":"明治26年／大正8年改修、昭和42年移築、令和5年改修","year":1893,"year_source":"db","year_min":1893,"year_max":1893,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積23㎡","structure_material":"木造平屋建","registered":"2024.03.06(令和6.03.06)","register_no":"17 - 0319","desc":"旧第四高等中学校本館の南西に位置する門衛所。平屋建切妻造桟瓦葺の東西棟で、東西に庇を付す。外壁は下見板張とし、上下窓を開け、東西妻面にガラリを設ける。内部は三室に仕切り、北西旧の詰所は出窓を付す。本館とともに歴史的な景観を形成する門衛所。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014798"},{"id":"00008669","register_sub_id":"101","register_pk":"149390","name":"小浜市立小浜中学校洗心館（旧福井県立小浜尋常中学校図書館）","kana":"おばましりつおばまちゅうがっこうせんしんかん（きゅうふくいけんりつおばまじんじょうちゅうがっこうとしょかん）","category":"学校","subcategory":"建築物","type_guess":"図書館","type_guess_confidence":"high","period":"昭和前","pref":"福井県","address":"福井県小浜市雲浜2-1-1","lat":35.5067391,"lng":135.74673013,"geo_status":"db","era":"昭和7年／昭和中期移築増築","year":1932,"year_source":"converted","year_min":1932,"year_max":1932,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積139㎡","structure_material":"木造平屋建","registered":"2011.07.25(平成23.07.25)","register_no":"18 － 0090","desc":"北川の河口北岸にある校地の西南隅に位置する。桁行15ｍ梁間9.1ｍ、寄棟造桟瓦葺、北面玄関附属。1.8ｍ間隔で柱を整然と配り、木造キングポストトラスを架ける。外壁下見板張、小壁漆喰塗など、当時の設計基準に準拠した標準的な木造図書館。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008669"},{"id":"00010770","register_sub_id":"101","register_pk":"201605","name":"福井鉄道バス旧車庫","kana":"ふくいてつどうばすきゅうしゃこ","category":"学校","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"福井県","address":"福井県越前市北府二丁目5字中藤牧3-2","lat":35.91073,"lng":136.165937,"geo_status":"db","era":"大正8／昭和31頃移築","year":1919,"year_source":"db","year_min":1919,"year_max":1919,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積396㎡","structure_material":"木造平屋建","registered":"2015.11.17(平成27.11.17)","register_no":"18 ‐ 0138","desc":"北府駅車両工場の西側に近接して建つ。桁行二七メートル梁間一五メートル、切妻造の東西に長い木造平屋建で、両妻面にはバスが出入りする一〇メートル幅の開口部を設ける。小学校の講堂をバス車庫に転用した木造建築で、交通施設の近代化の一面を表す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010770"},{"id":"00000207","register_sub_id":"101","register_pk":"101197","name":"塩山市中央区区民会館（旧千野学校校舎）","kana":"えんざんしちゅうおうくくみんかいかん（きゅうちのがっこうこうしゃ）","category":"学校","subcategory":"建築物","type_guess":"校舎","type_guess_confidence":"high","period":"明治","pref":"山梨県","address":"山梨県甲州市塩山上於曽1157","lat":35.70692062,"lng":138.7290086,"geo_status":"db","era":"明治12","year":1879,"year_source":"db","year_min":1879,"year_max":1879,"year_label":null,"structure":"木造2階建，瓦葺，建築面積129㎡","structure_material":"木造2階建","registered":"1997.06.12(平成9.06.12)","register_no":"19 － 0009","desc":"いわゆる藤村式の学校建築で、学校廃校後昭和２３年に現在地に移築され、警察署や図書館分館として使用された。寄棟造、２階建の正面に切妻造の玄関棟が附属する独特の外観は、改造があるが、校舎としての面影を残しており、多くの人々に親しまれている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000207"},{"id":"00014358","register_sub_id":"101","register_pk":"511347","name":"山梨英和中学校・高等学校講堂グリンバンク・チャペル","kana":"やまなしえいわちゅうがっこう・こうとうがっこうこうどうぐりんばんく・ちゃぺる","category":"学校","subcategory":"建築物","type_guess":"講堂","type_guess_confidence":"high","period":"昭和中","pref":"山梨県","address":"山梨県甲府市愛宕町112","lat":35.66713333,"lng":138.57505833,"geo_status":"db","era":"昭和24年／同40年頃・平成17年改修","year":1949,"year_source":"db","year_min":1949,"year_max":1949,"year_label":null,"structure":"鉄筋コンクリート造及び木造3階建、スレート葺、建築面積379㎡","structure_material":"鉄筋コンクリート造及び木造3階建","registered":"2022.10.31(令和4.10.31)","register_no":"19 - 0166","desc":"甲斐の山なみ背にするミッションスクールのチャペルで設計は塩川旭。1階は鉄筋コンクリート造煉瓦貼、２・３階の講堂は木造モルタル仕上、屋根は切妻造Ｔ字形スレート葺。講堂はキングポスト・トラスの合掌材を勾配天井に巧みに隠し、洗練された吹抜とする。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014358"},{"id":"00013385","register_sub_id":"101","register_pk":"368471","name":"山梨大学水晶庫","kana":"やまなしだいがくすいしょうこ","category":"学校","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"山梨県","address":"山梨県甲府市武田四丁目74-1","lat":35.67909722,"lng":138.57348889,"geo_status":"db","era":"昭和2年／平成30年移築","year":1927,"year_source":"db","year_min":1927,"year_max":1927,"year_label":null,"structure":"鉄筋コンクリート造平屋建、建築面積40㎡","structure_material":"鉄筋コンクリート造平屋建","registered":"2020.08.17(令和2.08.17)","register_no":"19 － 0148","desc":"山梨大学甲府キャンパスの正門北側に位置し、西面して建つ。鉄筋コンクリート造平屋建てで、内部は水晶の展示室と倉庫の二室に分かれる。四面に配した窓の上部に、水晶をモチーフにしたレリーフを飾る。山梨県内の初期の鉄筋コンクリート造建築として貴重。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013385"},{"id":"00005164","register_sub_id":"101","register_pk":"106154","name":"飯田市立追手町小学校校舎","kana":"いいだしりつおうてまちしょうがっこうこうしゃ","category":"学校","subcategory":"建築物","type_guess":"校舎","type_guess_confidence":"high","period":"昭和前","pref":"長野県","address":"長野県飯田市追手町2-673-1","lat":35.513035,"lng":137.829208,"geo_status":"db","era":"昭和4","year":1929,"year_source":"db","year_min":1929,"year_max":1929,"year_label":null,"structure":"鉄筋コンクリート造地上3階地下1階建、建築面積3753㎡","structure_material":"鉄筋コンクリート造地上3階地下1階建","registered":"2005.12.26(平成17.12.26)","register_no":"20 － 0232","desc":"敷地の北辺一杯に建つＲＣ造３階建校舎。東西両端を円弧として校庭側にわずかに折った平面をもつ。一般教室は４間に５間の規模である。昇降口は円弧部に設け，竪溝付の円柱，三中心アーチ，短い庇で飾る。長大な外壁は柱形を強調してリズムを造り出している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005164"},{"id":"00005165","register_sub_id":"101","register_pk":"106155","name":"飯田市立追手町小学校講堂","kana":"いいだしりつおうてまちしょうがっこうこうどう","category":"学校","subcategory":"建築物","type_guess":"講堂","type_guess_confidence":"high","period":"昭和前","pref":"長野県","address":"長野県飯田市追手町2-673-1","lat":35.512287,"lng":137.829102,"geo_status":"db","era":"昭和6","year":1931,"year_source":"db","year_min":1931,"year_max":1931,"year_label":null,"structure":"鉄骨造平屋建、鉄板葺、建築面積893㎡","structure_material":"鉄骨造平屋建","registered":"2005.12.26(平成17.12.26)","register_no":"20 － 0233","desc":"敷地の南辺東寄りに建つ鉄骨造，平屋建で，桁行２５間，梁間１０間。半切妻屋根を鉄板葺とする。外壁は付柱に下見板張で，出入口には切妻庇がつく。内壁は白漆喰塗で，腰を竪羽目板張とし，室内を折上格天井とし，鉄骨構造部材を見せない形式とする。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005165"},{"id":"00009455","register_sub_id":"101","register_pk":"194248","name":"旧麻績小学校北校舎","kana":"きゅうおみしょうがっこうきたこうしゃ","category":"学校","subcategory":"建築物","type_guess":"校舎","type_guess_confidence":"high","period":"昭和前","pref":"長野県","address":"長野県東筑摩郡麻績村麻字苗代3848-4他","lat":36.45713075,"lng":138.04497485,"geo_status":"db","era":"昭和11年","year":1936,"year_source":"db","year_min":1936,"year_max":1936,"year_label":null,"structure":"木造2階建、瓦葺、建築面積621㎡","structure_material":"木造2階建","registered":"2013.03.29(平成25.03.29)","register_no":"20 － 0426","desc":"木造二階建、桁行五四・五メートル梁間一〇メートル、寄棟造桟瓦葺で、正面中央に玄関ポーチ、背面に階段室二箇所を張出す。外壁は白色スレート板横張とし、内部は片廊下式で各室や廊下の天井を斜めに折上げる。長野県内における昭和前期の校舎の特徴を示す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009455"},{"id":"00003423","register_sub_id":"101","register_pk":"104413","name":"旧常田幼稚園園舎","kana":"きゅうときたようちえんえんしゃ","category":"学校","subcategory":"建築物","type_guess":"校舎","type_guess_confidence":"high","period":"大正","pref":"長野県","address":"長野県上田市常田2-30-17","lat":36.39662517,"lng":138.25688028,"geo_status":"db","era":"大正8","year":1919,"year_source":"db","year_min":1919,"year_max":1919,"year_label":null,"structure":"木造2階建、瓦葺、建築面積129㎡","structure_material":"木造2階建","registered":"2003.07.01(平成15.07.01)","register_no":"20 － 0130","desc":"木造２階建，建築面積１９４㎡で，設計はヴォーリズ合名会社による。外壁はモルタル塗ドイツ壁風仕上で，切妻造，桟瓦葺の長方形平面を基本とし，正面に遊戯室をベイウィンドー状に突出させた左右対称の構成をなす。小振りな幼稚園建築の好例である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003423"},{"id":"00005166","register_sub_id":"101","register_pk":"106156","name":"旧山本中学校杵原校舎管理教室棟","kana":"きゅうやまもとちゅうがっこうきねはらこうしゃかんりきょうしつとう","category":"学校","subcategory":"建築物","type_guess":"校舎","type_guess_confidence":"high","period":"昭和中","pref":"長野県","address":"長野県飯田市竹佐377-1","lat":35.467678,"lng":137.766342,"geo_status":"db","era":"昭和24","year":1949,"year_source":"db","year_min":1949,"year_max":1949,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積609㎡","structure_material":"木造平屋建","registered":"2005.12.26(平成17.12.26)","register_no":"20 － 0234","desc":"敷地の北寄りに建つ東西棟で，桁行３５間，梁間５間余の木造平屋建である。切妻造，桟瓦葺で，南面中央に寄棟造の玄関ポーチを突出する。外壁は下見板張で，小壁を白漆喰塗とする。内部は壁を白漆喰塗，腰を竪羽目板張とし，教室，廊下共に竿縁天井とする。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005166"},{"id":"00005167","register_sub_id":"101","register_pk":"106157","name":"旧山本中学校杵原校舎教室棟","kana":"きゅうやまもとちゅうがっこうきねはらこうしゃきょうしつとう","category":"学校","subcategory":"建築物","type_guess":"校舎","type_guess_confidence":"high","period":"昭和中","pref":"長野県","address":"長野県飯田市竹佐377-1","lat":35.467888,"lng":137.766357,"geo_status":"db","era":"昭和24","year":1949,"year_source":"db","year_min":1949,"year_max":1949,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積768㎡","structure_material":"木造平屋建","registered":"2005.12.26(平成17.12.26)","register_no":"20 － 0235","desc":"管理教室棟と同規模で北側に並ぶ。教室は桁行５間，梁行４間規模で７室並び，北側に幅７．５尺の廊下が通る。建物東西端の渡廊下で南の管理教室棟と接続する。外回りには欄間付の引違い窓を３連一組で配し，教室と廊下の境には欄間無しの引違い窓を建て込む。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005167"},{"id":"00003233","register_sub_id":"101","register_pk":"104223","name":"金鵄会館（長野県長野高等学校旧南校舎）","kana":"きんしかいかん（ながのけんながのこうとうがっこうきゅうみなみこうしゃ）","category":"学校","subcategory":"建築物","type_guess":"校舎","type_guess_confidence":"high","period":"昭和前","pref":"長野県","address":"長野県長野市大字上松1-824-1","lat":36.66925299,"lng":138.19879602,"geo_status":"db","era":"昭和14","year":1939,"year_source":"db","year_min":1939,"year_max":1939,"year_label":null,"structure":"木造2階建、瓦葺、建築面積752㎡、塔屋付","structure_material":"木造2階建","registered":"2003.03.18(平成15.03.18)","register_no":"20 － 0120","desc":"木造２階建校舎で，正面側１階をモルタル仕上げ，２階をドイツ下見とし，ほぼ中央に玄関車寄を突出させる。中央部の前面はタイル張とし，宝形屋根を戴く塔屋を立ち上げる。教室の連続窓風の横長窓と塔屋部及び車寄の造形意匠に時代の特徴がよく示されている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003233"},{"id":"00010970","register_sub_id":"101","register_pk":"208940","name":"三水第一小学校茶室","kana":"さみずだいいちしょうがっこうちゃしつ","category":"学校","subcategory":"建築物","type_guess":"校舎","type_guess_confidence":"low","period":"昭和前","pref":"長野県","address":"長野県上水内郡飯綱町大字普光寺179","lat":36.761662,"lng":138.251966,"geo_status":"db","era":"昭和17／昭和58移築","year":1942,"year_source":"db","year_min":1942,"year_max":1942,"year_label":null,"structure":"木造平屋建、鉄板葺、建築面積41㎡","structure_material":"木造平屋建","registered":"2016.02.25(平成28.02.25)","register_no":"20-0499","desc":"茶道を通じた学習の場として建築された。三畳と四畳半の茶室二間が水屋を共有する平面で、四畳半の二辺に矩折れに入側縁を廻らす。三畳茶室は躙り口を備え、掛込天井とする。四畳半茶室は柱を面皮付とし、コブシの皮付丸太を床柱とする数寄屋風である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010970"},{"id":"00000763","register_sub_id":"101","register_pk":"101753","name":"信州大学繊維学部講堂（旧上田蚕糸専門学校講堂）","kana":"しんしゅうだいがくせんいがくぶこうどう（きゅううえださんしせんもんがっこうこうどう）","category":"学校","subcategory":"建築物","type_guess":"講堂","type_guess_confidence":"high","period":"昭和前","pref":"長野県","address":"長野県上田市常田3-15-1","lat":36.39212915,"lng":138.26142788,"geo_status":"db","era":"昭和4","year":1929,"year_source":"db","year_min":1929,"year_max":1929,"year_label":null,"structure":"木造２階建，鉄板葺，建築面積357㎡","structure_material":"木造２階建","registered":"1998.09.02(平成10.09.02)","register_no":"20 － 0005","desc":"養蚕業の盛んなこの地方で繊維教育のために設立された上田蚕糸専門学校の講堂として建てられた。木造下見板貼の上質な建築で，玄関部の三角に張り出す窓の形状は特異。内部には蚕糸に因んだ彫刻がある。設計は文部省（建築課長は柴垣鼎太郎），施工は柳屋組。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000763"},{"id":"00009597","register_sub_id":"101","register_pk":"194593","name":"信州大学繊維学部守衛所（旧上田蚕糸専門学校門衛詰所）","kana":"しんしゅうだいがくせんいがくぶしゅえいじょ（きゅううえださんしせんもんがっこうもんえいつめしょ）","category":"学校","subcategory":"建築物","type_guess":"正門","type_guess_confidence":"high","period":"大正","pref":"長野県","address":"長野県上田市常田3-480他","lat":36.3928483,"lng":138.26005049,"geo_status":"db","era":"大正元／昭和4・昭和39移築・昭和45改修","year":1912,"year_source":"db","year_min":1912,"year_max":1912,"year_label":null,"structure":"木造平屋建、鉄板葺、建築面積24㎡","structure_material":"木造平屋建","registered":"2013.06.21(平成25.06.21)","register_no":"20 － 0428","desc":"大学正門北脇に建つ。木造平屋建、寄棟造鋼板葺の小規模な建物。正面は両角を隅切した半八角平面で事務室と窓口を設け、背面に畳敷の休憩室を置く。外観は下見板張とし窓上部や棟飾りに装飾を配する。学内で二度の移築を経てなお学舎の歴史的景観を伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009597"},{"id":"00009596","register_sub_id":"101","register_pk":"194592","name":"信州大学繊維学部資料館（旧上田蚕糸専門学校貯繭庫）","kana":"しんしゅうだいがくせんいがくぶしりょうかん（きゅううえださんしせんもんがっこうちょけんこ）","category":"学校","subcategory":"建築物","type_guess":"記念館・資料室","type_guess_confidence":"high","period":"明治","pref":"長野県","address":"長野県上田市常田3-480他","lat":36.39291969,"lng":138.26296295,"geo_status":"db","era":"明治43","year":1910,"year_source":"db","year_min":1910,"year_max":1910,"year_label":null,"structure":"煉瓦造2階建、瓦葺、建築面積67㎡","structure_material":"煉瓦造2階建","registered":"2013.06.21(平成25.06.21)","register_no":"20 － 0427","desc":"大学構内中央北寄りに位置する。煉瓦造二階建、寄棟造桟瓦葺で、外壁に柱形を表し、各間中央は窓とし鉄扉両開とする。開口上部は一階は欠円アーチ、二階はフラットアーチとし意匠を引き立てる。繭の保管庫として建築された貯繭庫の特徴を良好に残す遺構。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009596"},{"id":"00012148","register_sub_id":"101","register_pk":"352947","name":"筑波大学山岳科学センター菅平高原実験所大明神寮","kana":"つくばだいがくさんがくかがくせんたーすがだいらこうげんじっけんしょだいみょうじんりょう","category":"学校","subcategory":"建築物","type_guess":"寄宿舎","type_guess_confidence":"high","period":"昭和中","pref":"長野県","address":"長野県上田市菅平高原1278-294","lat":36.522915,"lng":138.348672,"geo_status":"db","era":"昭和40年","year":1965,"year_source":"db","year_min":1965,"year_max":1965,"year_label":null,"structure":"木造平屋建、金属板葺、建築面積147㎡","structure_material":"木造平屋建","registered":"2018.03.27(平成30.03.27)","register_no":"20-519","desc":"高原の緩斜面に建つ。東西に長い木造平屋建、切妻造で、外壁下見板張。北側に廊下を通し、東寄りに八畳四室、西寄りに食堂と厨房、風呂などを配する。各室の南面に出窓を設けて二重窓とし採光と断熱を図り、寒冷な気候に対処する。特異な環境下の大学宿舎。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012148"},{"id":"00012534","register_sub_id":"101","register_pk":"367829","name":"東京藝術大学山岳部黒沢ヒュッテ","kana":"とうきょうげいじゅつだいがくさんがくぶくろさわひゅって","category":"学校","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和中","pref":"長野県","address":"長野県大町市平字黒沢4976-3","lat":36.498711,"lng":137.734756,"geo_status":"geocoded","era":"昭和35年／平成10年改修","year":1960,"year_source":"db","year_min":1960,"year_max":1960,"year_label":null,"structure":"木造及びコンクリートブロック造2階建、金属板葺、建築面積79㎡","structure_material":"木造及びコンクリートブロック造2階建","registered":"2018.11.02(平成30.11.02)","register_no":"20 － 0537","desc":"標高1200メートルの尾根上に建つ大学山岳部の山小屋で、折板状の片流れ屋根の軒を深く張出す。コンクリートブロック造の一階は寝室、木造の二階は居間中心で南西面に広い開口を設け、テラスから後立山連峰を望む。戦後の登山ブームの一端を示す山岳施設。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012534"},{"id":"00003240","register_sub_id":"101","register_pk":"104230","name":"長野県松本深志高等学校管理普通教室棟","kana":"ながのけんまつもとふかしこうとうがっこうかんりふつうきょうしつとう","category":"学校","subcategory":"建築物","type_guess":"校舎","type_guess_confidence":"high","period":"昭和前","pref":"長野県","address":"長野県松本市蟻ケ崎3-8-1","lat":36.24745783,"lng":137.96637403,"geo_status":"db","era":"昭和8","year":1933,"year_source":"db","year_min":1933,"year_max":1933,"year_label":null,"structure":"鉄筋コンクリート造3階建、建築面積2579㎡","structure_material":"鉄筋コンクリート造3階建","registered":"2003.03.18(平成15.03.18)","register_no":"20 － 0127","desc":"長野県内における初期鉄筋コンクリート造学校建築。３階建，スクラッチタイル張で，正面中央玄関ポーチの緩やかな尖頭アーチ，２階３階通しの先を尖らせた柱型などゴシック風意匠に特徴。東京帝大安田講堂（東京大学大講堂）が手本と伝える。県営繕の設計。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003240"},{"id":"00003241","register_sub_id":"101","register_pk":"104231","name":"長野県松本深志高等学校講堂","kana":"ながのけんまつもとふかしこうとうがっこうこうどう","category":"学校","subcategory":"建築物","type_guess":"講堂","type_guess_confidence":"high","period":"昭和前","pref":"長野県","address":"長野県松本市蟻ケ崎3-8-1","lat":36.247726,"lng":137.966843,"geo_status":"db","era":"昭和9","year":1934,"year_source":"db","year_min":1934,"year_max":1934,"year_label":null,"structure":"鉄筋コンクリート造平屋建、建築面積835㎡","structure_material":"鉄筋コンクリート造平屋建","registered":"2003.03.18(平成15.03.18)","register_no":"20 － 0128","desc":"体育館を兼ねた講堂。壁体は鉄筋コンクリート造とし，山形の鉄骨トラスで桟瓦葺の切妻屋根を支持する。南妻面には先を尖らせた柱型を表し，５連の尖頭アーチによるアーケード風正面玄関を設けスクラッチタイルを張るなど管理普通教室棟に呼応した意匠とする。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003241"},{"id":"00007634","register_sub_id":"101","register_pk":"108616","name":"長野県南安曇農業高等学校第二農場日輪舎","kana":"ながのけんみなみあづみのうぎょうこうとうがっこうだいにのうじょうにちりんしゃ","category":"学校","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"長野県","address":"長野県安曇野市堀金烏川1773-2","lat":36.303986,"lng":137.862274,"geo_status":"db","era":"昭和20","year":1945,"year_source":"db","year_min":1945,"year_max":1945,"year_label":null,"structure":"木造2階建、鉄板葺、建築面積139㎡","structure_material":"木造2階建","registered":"2009.04.28(平成21.04.28)","register_no":"20 － 0351","desc":"直径１３ｍ規模で、ほぼ円形平面とする木造総２階建。外壁を下見板張とし、軒天井を板張、入口に庇をかけ、簡素な持送りを付ける。壁面全方向に幅広の窓をとり採光を確保する。円筒形の躯体に円錐形の屋根をかける独特の外観で、全国的にも残存例が少ない。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007634"},{"id":"00008982","register_sub_id":"101","register_pk":"162342","name":"松商学園高等学校講堂","kana":"まつしょうがくえんこうとうがっこうこうどう","category":"学校","subcategory":"建築物","type_guess":"講堂","type_guess_confidence":"high","period":"昭和前","pref":"長野県","address":"長野県松本市県3-2301-4他","lat":36.22966721,"lng":137.98623137,"geo_status":"db","era":"昭和11年","year":1936,"year_source":"db","year_min":1936,"year_max":1936,"year_label":null,"structure":"鉄筋コンクリート造平屋建、鉄板葺、建築面積741㎡","structure_material":"鉄筋コンクリート造平屋建","registered":"2011.10.28(平成23.10.28)","register_no":"20 － 0379","desc":"本館東側に建ち、鉄筋コンクリート造、桁行三六・九メートル梁間一九・五メートル、切妻造妻入、鉄板葺である。妻面は中央に細い柱形を三本立てて外観を引き締め、側面は臥梁と外面を揃えた高い柱形を見せる。昭和初期における鉄筋コンクリート造講堂の好例。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008982"},{"id":"00008983","register_sub_id":"101","register_pk":"162343","name":"松商学園高等学校柔剣道場","kana":"まつしょうがくえんこうとうがっこうじゅうけんどうじょう","category":"学校","subcategory":"建築物","type_guess":"体育館","type_guess_confidence":"high","period":"昭和前","pref":"長野県","address":"長野県松本市県3-2301-4他","lat":36.22954098,"lng":137.98461944,"geo_status":"db","era":"昭和11年","year":1936,"year_source":"db","year_min":1936,"year_max":1936,"year_label":null,"structure":"鉄筋コンクリート造2階建、鉄板葺、建築面積595㎡","structure_material":"鉄筋コンクリート造2階建","registered":"2011.10.28(平成23.10.28)","register_no":"20 － 0380","desc":"本館西側に建ち、鉄筋コンクリート造二階建、桁行３６．４ｍ梁間１６．４ｍ、切妻造妻入、鉄板葺である。外観は講堂と同様に高い柱形を見せ、各間に半円アーチ形を現し、アーチ窓や矩形窓を配置する。本館、講堂とともに特徴的な景観をつくる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008983"},{"id":"00008981","register_sub_id":"101","register_pk":"162341","name":"松商学園高等学校本館","kana":"まつしょうがくえんこうとうがっこうほんかん","category":"学校","subcategory":"建築物","type_guess":"記念館・資料室","type_guess_confidence":"low","period":"昭和前","pref":"長野県","address":"長野県松本市県3-2312-2他","lat":36.229473,"lng":137.98543511,"geo_status":"db","era":"昭和11年／昭和54年・平成21年改修","year":1936,"year_source":"db","year_min":1936,"year_max":1936,"year_label":null,"structure":"木造2階建、瓦葺、建築面積1140㎡","structure_material":"木造2階建","registered":"2011.10.28(平成23.10.28)","register_no":"20 － 0378","desc":"校地北辺中央に北面して建ち、木造二階建、建築面積１１４０㎡、入母屋造桟瓦葺である。中央に張出した入母屋屋根の玄関に石造風のポーチを設ける。外壁を下見板張、屋根に千鳥破風を配するなど和洋の意匠を折衷した、大型の木造校舎である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008981"},{"id":"00014830","register_sub_id":"101","register_pk":"519090","name":"加藤学園暁秀初等学校本館","kana":"かとうがくえんぎょうしゅうしょとうがっこうほんかん","category":"学校","subcategory":"建築物","type_guess":"記念館・資料室","type_guess_confidence":"low","period":"昭和後","pref":"静岡県","address":"静岡県沼津市岡宮字八島348-2他","lat":35.11755,"lng":138.86899444,"geo_status":"db","era":"昭和47年／平成17年・令和3年改修","year":1972,"year_source":"db","year_min":1972,"year_max":1972,"year_label":null,"structure":"鉄筋コンクリート造地上2階地下1階建、建築面積2，228㎡","structure_material":"鉄筋コンクリート造地上2階地下1階建","registered":"2024.03.06(令和6.03.06)","register_no":"22 - 0325","desc":"市街の校地北端に建つ鉄筋コンクリート造校舎。設計は槇総合計画事務所。学習センターを中心に中庭を介して普通教室などを配し、界壁を極力省き開放性を高める。多様な自然採光、色彩豊かな室内グラフィックも秀逸。日本初オープンプランスクールとして重要。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014830"},{"id":"00010974","register_sub_id":"101","register_pk":"208944","name":"旧気多村立勝坂小学校校舎","kana":"きゅうけたそんりつかつさかしょうがっこうこうしゃ","category":"学校","subcategory":"建築物","type_guess":"校舎","type_guess_confidence":"high","period":"昭和中","pref":"静岡県","address":"静岡県浜松市天竜区春野町豊岡字キタノシマ240-3他","lat":35.06246,"lng":137.913681,"geo_status":"db","era":"昭和30","year":1955,"year_source":"db","year_min":1955,"year_max":1955,"year_label":null,"structure":"木造2階建、鉄板葺、建築面積208㎡","structure_material":"木造2階建","registered":"2016.02.25(平成28.02.25)","register_no":"22-0218","desc":"外壁下見板張の校舎。当初から複式学級を想定し、一階に職員室と普通教室、二階に講堂兼特別教室を配す。柱の添柱や小屋の方杖、採光に配慮して広めた窓部や反射光を取り入れる中庇などに当時の学校建築の特徴を示す。山村風景に彩りを添える木造校舎。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010974"},{"id":"00011507","register_sub_id":"101","register_pk":"210466","name":"旧中村洋裁学院","kana":"きゅうなかむらようさいがくいん","category":"学校","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和中","pref":"静岡県","address":"静岡県袋井市袋井260-1","lat":34.74693389,"lng":137.92325389,"geo_status":"db","era":"昭和25年／昭和28年増築、平成24年改修","year":1950,"year_source":"db","year_min":1950,"year_max":1950,"year_label":null,"structure":"木造2階建、瓦葺、建築面積191㎡","structure_material":"木造2階建","registered":"2017.05.02(平成29.05.02)","register_no":"22-0234","desc":"原野谷川沿いに南北棟で建つ。木造二階建、切妻造桟瓦葺で、棟端のフィニアルに校章を表す。外壁下見板張で妻にガラリを付け、軒天井を廻す。内部は上下階とも南半を広い一室の教室とし、北半に和室・洋室を配する。戦後復興期の各種学校校舎の特徴を示す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011507"},{"id":"00002395","register_sub_id":"101","register_pk":"103385","name":"静岡県立磐田農業高等学校記念館","kana":"しずおかけんりついわたのうぎょうこうとうがっこうきねんかん","category":"学校","subcategory":"建築物","type_guess":"記念館・資料室","type_guess_confidence":"high","period":"明治","pref":"静岡県","address":"静岡県磐田市中泉168","lat":34.71601035,"lng":137.853149,"geo_status":"db","era":"明治42／昭和60移築","year":1909,"year_source":"db","year_min":1909,"year_max":1909,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積217㎡","structure_material":"木造平屋建","registered":"2001.10.12(平成13.10.12)","register_no":"22 － 0076","desc":"県立農学校が見付町から中泉地区に移転してきた時に講堂として建設。桁行１７．５ｍ，梁間１２ｍ，寄棟造，桟瓦葺で，外壁は下見板張とし，上げ下げの単窓を連ね，正面妻側に後年改装のアーチ型の玄関ポーチを張り出す。明治後期公立学校建築遺構のひとつ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002395"},{"id":"00004976","register_sub_id":"101","register_pk":"105966","name":"豊門公園西洋館（旧豊門青年学校）","kana":"ほうもんかいかんせいようかん（きゅうほうもんせいねんがっこう）","category":"学校","subcategory":"建築物","type_guess":"正門","type_guess_confidence":"low","period":"昭和前","pref":"静岡県","address":"静岡県駿東郡小山町藤曲144-8","lat":35.36287766,"lng":138.98616463,"geo_status":"db","era":"昭和初期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和初期","structure":"木造2階建、スレート葺、建築面積235㎡、塔屋付","structure_material":"木造2階建","registered":"2005.11.10(平成17.11.10)","register_no":"22 － 0102","desc":"豊門公園の北側に南面して建つ。木造２階建，スレート葺で，寄棟造，外装下見板張とし，欄間付縦長窓を四周に配す。正面中央に設けられた車寄付塔屋の左右で２階壁面を前後させ，西半は帯状の小壁を巡らして外観を引き締める等，変化に富んだ瀟洒な洋風建築。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004976"},{"id":"00000434","register_sub_id":"101","register_pk":"101424","name":"愛知学院大学楠元学舎第１号館","kana":"あいちがくいんだいがくくすもとがくしゃだいいちごうかん","category":"学校","subcategory":"建築物","type_guess":"記念館・資料室","type_guess_confidence":"low","period":"昭和前","pref":"愛知県","address":"愛知県名古屋市千種区楠元町1-1","lat":35.16702318,"lng":136.96146983,"geo_status":"db","era":"昭和3","year":1928,"year_source":"db","year_min":1928,"year_max":1928,"year_label":null,"structure":"鉄筋コンクリート造2階建，建築面積805㎡","structure_material":"鉄筋コンクリート造2階建","registered":"1998.01.16(平成10.01.16)","register_no":"23 － 0008","desc":"旧制愛知中学本館として建てられた。中央部は玄関ポーチを設け壁を立ち上げ正面性を強調し，左右に翼屋をのばす。スクラッチタイル貼りの外壁，１・２階を通した柱形，柱形頂部の庇状の装飾等に時代の特徴があらわれている。設計佐藤三郎，施工西村工務店。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000434"},{"id":"00011709","register_sub_id":"101","register_pk":"210725","name":"愛知県立旭丘高等学校正門門柱（旧愛知県立第一中学校正門）","kana":"あいちけんりつあさひがおかこうとうがっこうせいもんもんちゅう（きゅうあいちけんだいいちちゅうがっこうせいもん）","category":"学校","subcategory":"その他工作物","type_guess":"正門","type_guess_confidence":"high","period":"昭和前","pref":"愛知県","address":"愛知県名古屋市東区出来町三丁目6-15","lat":35.183821,"lng":136.938729,"geo_status":"db","era":"昭和13年／昭和34年・平成13年改修","year":1938,"year_source":"db","year_min":1938,"year_max":1938,"year_label":null,"structure":"鉄筋コンクリート造、間口8.2m、北方脇柱付","structure_material":"鉄筋コンクリート造","registered":"2017.06.28(平成29.06.28)","register_no":"23-0479","desc":"愛知県第一中学校の現在地への移転に際して建設された。主柱はほぼ正方形平面で、四隅を切り欠く。高さは二・四メートルで、鉄筋コンクリート造。脇柱は九割程度の大きさで、いずれも横目地四本を切る。重厚な意匠で、県下の教育の歴史を今に伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011709"},{"id":"00011720","register_sub_id":"101","register_pk":"210736","name":"愛知県立安城農林高等学校正門門柱（旧愛知県立農林学校正門）","kana":"あいちけんりつあんじょうのうりんこうとうがっこうせいもんもんちゅう（きゅうあいちけんりつのうりんがっこうせいもん）","category":"学校","subcategory":"その他工作物","type_guess":"正門","type_guess_confidence":"high","period":"明治","pref":"愛知県","address":"愛知県安城市池浦町茶筅木1","lat":34.967708,"lng":137.079169,"geo_status":"db","era":"明治36年頃／昭和5年頃改修、昭和35年移設","year":1903,"year_source":"db","year_min":1903,"year_max":1903,"year_label":null,"structure":"石造、間口8.3m、西方脇柱付","structure_material":"石造","registered":"2017.06.28(平成29.06.28)","register_no":"23-0490","desc":"敷地南面に建つ。石造の主柱と鉄筋コンクリート造モルタル仕上げの左脇柱一本からなる。柱頭部は丁寧に繰型を施しており、柱頂部にはかつて擬宝珠状の装飾があった。左脇柱は当初は木製であった。県内における最古の学校門柱として貴重。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011720"},{"id":"00011713","register_sub_id":"101","register_pk":"210729","name":"愛知県立惟信高等学校正門門柱（旧愛知県惟信中学校正門）","kana":"あいちけんりついしんこうとうがっこうせいもんもんちゅう（きゅうあいちけんいしんちゅうがっこうせいもん）","category":"学校","subcategory":"その他工作物","type_guess":"正門","type_guess_confidence":"high","period":"昭和前","pref":"愛知県","address":"愛知県名古屋市港区惟信町2-262","lat":35.106781,"lng":136.841848,"geo_status":"db","era":"昭和4年頃","year":1929,"year_source":"db","year_min":1929,"year_max":1929,"year_label":null,"structure":"鉄筋コンクリート造、間口10m、東西脇柱及び土塁留付","structure_material":"鉄筋コンクリート造","registered":"2017.06.28(平成29.06.28)","register_no":"23-0483","desc":"敷地北面に建つ。主柱と脇柱各二本からなる。鉄筋コンクリート造モルタル仕上げで、外観はセセッション風に直線で構成され、柱身部は目地を切り、柱頭部は幾何学模様で装飾する。門扉を除き保存状態も良く、愛知県営繕課による標準設計の門を今に伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011713"},{"id":"00011715","register_sub_id":"101","register_pk":"210731","name":"愛知県立岩津高等学校正門旧門柱（旧岩津町立愛知県岩津農商学校正門）","kana":"あいちけんりついわづこうとうがっこうせいもんきゅうもんちゅう（きゅういわづちょうりつあいちけんいわづのうしょうがっこうせいもん）","category":"学校","subcategory":"その他工作物","type_guess":"正門","type_guess_confidence":"high","period":"昭和前","pref":"愛知県","address":"愛知県岡崎市東蔵前町字馬場5","lat":34.999063,"lng":137.174453,"geo_status":"db","era":"昭和12年／昭和60年移設","year":1937,"year_source":"db","year_min":1937,"year_max":1937,"year_label":null,"structure":"石造、間口9.1m","structure_material":"石造","registered":"2017.06.28(平成29.06.28)","register_no":"23-0485","desc":"敷地南面に建つ。花崗岩製の主柱二本からなる。主柱は角柱で、柱身部は江戸切こぶ出し仕上げで、笠石を載せ、柱頂部に直径五四センチメートルの半球で飾る特徴的な意匠を持つ。移設されているが、地中に柱礎部も残り、当初の意匠をよく留める。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011715"},{"id":"00011714","register_sub_id":"101","register_pk":"210730","name":"愛知県立岡崎高等学校正門門柱（旧愛知県立第二中学校正門）","kana":"あいちけんりつおかざきこうとうがっこうせいもんもんちゅう（きゅうあいちけんりつだいにちゅうがっこうせいもん）","category":"学校","subcategory":"その他工作物","type_guess":"正門","type_guess_confidence":"high","period":"大正","pref":"愛知県","address":"愛知県岡崎市明大寺町伝馬1","lat":34.946312,"lng":137.169859,"geo_status":"db","era":"大正前期／大正13年・昭和47年移設","year":1917,"year_source":"estimated","year_min":1912,"year_max":1918,"year_label":"大正前期","structure":"石造、間口8.6m、南北脇柱付","structure_material":"石造","registered":"2017.06.28(平成29.06.28)","register_no":"23-0484","desc":"敷地西側に建つ。花崗岩製の主柱と脇柱各二本からなる。西洋建築のオーダーを基調とした意匠で柱礎部、柱身部、柱頭部からなる。柱身部は江戸切こぶ出し仕上げで、柱頭部は繰型を施し大きく張り出す。県内旧制中学校正門の古例で西洋趣味の強い意匠を持つ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011714"},{"id":"00011721","register_sub_id":"101","register_pk":"210737","name":"愛知県立鶴城丘高等学校正門門柱（旧愛知県蚕糸学校正門）","kana":"あいちけんりつかくじょうがおかこうとうがっこうせいもんもんちゅう（きゅうあいちけんさんしがっこうせいもん）","category":"学校","subcategory":"その他工作物","type_guess":"正門","type_guess_confidence":"high","period":"大正","pref":"愛知県","address":"愛知県西尾市亀沢町300","lat":34.87253,"lng":137.048567,"geo_status":"db","era":"大正14年頃","year":1925,"year_source":"db","year_min":1925,"year_max":1925,"year_label":null,"structure":"鉄筋コンクリート造、間口10m、東西脇柱及び土塁留付","structure_material":"鉄筋コンクリート造","registered":"2017.06.28(平成29.06.28)","register_no":"23-0491","desc":"愛知県蚕糸学校の正門として建てられた。鉄筋コンクリート造モルタル仕上げで目地を刻み石造風に三層構成とする県立高校の標準設計に基づく意匠とし、主柱の高さは三・六メートル。脇柱は主柱の九割程度の大きさ。セセッション風意匠で、地域の景観に寄与する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011721"},{"id":"00011719","register_sub_id":"101","register_pk":"210735","name":"愛知県立刈谷高等学校正門門柱（旧愛知県刈谷中学校正門）","kana":"あいちけんりつかりやこうとうがっこうせいもんもんちゅう（きゅうあいちけんかりやちゅうがっこうせいもん）","category":"学校","subcategory":"その他工作物","type_guess":"正門","type_guess_confidence":"high","period":"大正","pref":"愛知県","address":"愛知県刈谷市寿町五丁目101","lat":34.983017,"lng":136.998324,"geo_status":"db","era":"大正12年","year":1923,"year_source":"db","year_min":1923,"year_max":1923,"year_label":null,"structure":"鉄筋コンクリート造、間口10m、東西脇柱付","structure_material":"鉄筋コンクリート造","registered":"2017.06.28(平成29.06.28)","register_no":"23-0489","desc":"敷地南面に建つ。主柱と脇柱各二本からなる鉄筋コンクリート造モルタル仕上げの門である。外観はセセッション風に直線で構成され、柱頭部には幾何学模様の装飾を付す。柱身部は石造風に目地を切る。愛知県営繕課の当時の標準設計の門で、門扉を除き残りも良い。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011719"},{"id":"00011724","register_sub_id":"101","register_pk":"210740","name":"愛知県立小牧高等学校正門門柱（旧愛知県小牧中学校正門）","kana":"あいちけんりつこまきこうとうがっこうせいもんもんちゅう（きゅうあいちけんこまきちゅうがっこうせいもん）","category":"学校","subcategory":"その他工作物","type_guess":"正門","type_guess_confidence":"high","period":"昭和前","pref":"愛知県","address":"愛知県小牧市小牧一丁目321","lat":35.291777,"lng":136.918696,"geo_status":"db","era":"昭和4年","year":1929,"year_source":"db","year_min":1929,"year_max":1929,"year_label":null,"structure":"鉄筋コンクリート造、間口9.1m、東西脇柱及び土塁留付","structure_material":"鉄筋コンクリート造","registered":"2017.06.28(平成29.06.28)","register_no":"23-0494","desc":"鉄筋コンクリート造で、ほぼ正方形の平面、石造風の外観、三層構成など、標準的な構成をとる。主柱高さは三・〇メートルで、脇柱はその九割程度の規模を有する。柱頭部にアカンサスの葉を模した装飾を備える点が特徴で、学校の歴史を今に伝えている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011724"},{"id":"00014243","register_sub_id":"101","register_pk":"509633","name":"愛知県立瑞陵高等学校感喜堂（旧講堂）","kana":"あいちけんりつずいりょうこうとうがっこうかんきどう","category":"学校","subcategory":"建築物","type_guess":"講堂","type_guess_confidence":"high","period":"大正","pref":"愛知県","address":"愛知県名古屋市瑞穂区北原町二丁目1-2","lat":35.13234444,"lng":136.92979722,"geo_status":"db","era":"大正13年／昭和54年・平成27年改修","year":1924,"year_source":"db","year_min":1924,"year_max":1924,"year_label":null,"structure":"鉄筋コンクリート造平屋建、瓦葺、建築面積427㎡","structure_material":"鉄筋コンクリート造平屋建","registered":"2022.06.29(令和4.06.29)","register_no":"23 - 0577","desc":"校地南西隅に建つ鉄筋コンクリート造の旧講堂。寄棟造桟瓦葺で四面に切妻破風を立ち上げ、縦長のガラス窓が上下に意匠を変えて並ぶ。窓間の壁の柱頭飾りや軒持送などの装飾を施してセセッション調にまとめた外観をよく残し、大正期の講堂建築の好例である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014243"},{"id":"00011712","register_sub_id":"101","register_pk":"210728","name":"愛知県立瑞陵高等学校旧正門門柱（旧愛知県商業学校正門）","kana":"あいちけんりつずいりょうこうとうがっこうきゅうせいもんもんちゅう（きゅうあいちけんしょうぎょうがっこうせいもん）","category":"学校","subcategory":"その他工作物","type_guess":"正門","type_guess_confidence":"high","period":"大正","pref":"愛知県","address":"愛知県名古屋市瑞穂区北原町二丁目1","lat":35.132053,"lng":136.930269,"geo_status":"db","era":"大正13年頃","year":1924,"year_source":"db","year_min":1924,"year_max":1924,"year_label":null,"structure":"鉄筋コンクリート造、間口10m、東西脇柱付","structure_material":"鉄筋コンクリート造","registered":"2017.06.28(平成29.06.28)","register_no":"23-0482","desc":"敷地南面に建つ。主柱と脇柱各二本からなる鉄筋コンクリート造モルタル仕上げの門。外観はセセッション風に直線で構成され、柱身部は目地を切り、柱頭部には幾何学模様の装飾を付す。かつては柱頂部に丸い照明器具があった。愛知県営繕課による標準設計の一例。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011712"},{"id":"00011717","register_sub_id":"101","register_pk":"210733","name":"愛知県立津島高等学校正門門柱（旧愛知県津島中学校正門）","kana":"あいちけんりつつしまこうとうがっこうせいもんもんちゅう（きゅうあいちけんつしまちゅうがっこうせいもん）","category":"学校","subcategory":"その他工作物","type_guess":"正門","type_guess_confidence":"high","period":"大正","pref":"愛知県","address":"愛知県津島市宮川町三丁目80","lat":35.165612,"lng":136.715932,"geo_status":"db","era":"大正12年頃","year":1923,"year_source":"db","year_min":1923,"year_max":1923,"year_label":null,"structure":"鉄筋コンクリート造、間口10m、東西脇柱及び土塁留付","structure_material":"鉄筋コンクリート造","registered":"2017.06.28(平成29.06.28)","register_no":"23-0487","desc":"ほぼ正方形の平面の鉄筋コンクリート造モルタル仕上げで、高さは主柱が三・五メートル、脇柱三・一メートルで、同じ意匠でまとめるが、高さ方向の目地間隔を変えている。柱頭部に幾何学模様を配し、三層構成を基調とする門で、学校の歴史を今に伝えている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011717"},{"id":"00011722","register_sub_id":"101","register_pk":"210738","name":"愛知県立西尾高等学校通用門門柱（旧愛知県西尾中学校正門）","kana":"あいちけんりつにしおこうとうがっこうつうようもんもんちゅう（きゅうあいちけんにしおちゅうがっこうせいもん）","category":"学校","subcategory":"その他工作物","type_guess":"正門","type_guess_confidence":"high","period":"昭和前","pref":"愛知県","address":"愛知県西尾市桜町奥新田2-2","lat":34.882286,"lng":137.055667,"geo_status":"db","era":"昭和5年頃","year":1930,"year_source":"db","year_min":1930,"year_max":1930,"year_label":null,"structure":"鉄筋コンクリート造、間口9.1m、東西脇柱及び土塁留付","structure_material":"鉄筋コンクリート造","registered":"2017.06.28(平成29.06.28)","register_no":"23-0492","desc":"鉄筋コンクリート造で、主柱、脇柱各二本からなり、主柱高さは三・〇メートル。副柱は主柱の八割程度の規模とする。愛知県立高校の正門に標準的な手法をとりながら、柱をやや太くし、柱頭部の装飾はアカンサスの葉を模し、古典的要素を強く示す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011722"},{"id":"00011716","register_sub_id":"101","register_pk":"210732","name":"愛知県立半田商業高等学校正門門柱（旧愛知県知多郡立高等女学校正門）","kana":"あいちけんりつはんだしょうぎょうこうとうがっこうせいもんもんちゅう（きゅうあいちけんちたぐんりつこうとうじょがっこうせいもん）","category":"学校","subcategory":"その他工作物","type_guess":"正門","type_guess_confidence":"high","period":"大正","pref":"愛知県","address":"愛知県半田市白山町二丁目30","lat":34.891659,"lng":136.923979,"geo_status":"db","era":"大正10年／平成7年改修、平成20年移設","year":1921,"year_source":"db","year_min":1921,"year_max":1921,"year_label":null,"structure":"コンクリート造、間口9.8m、東西脇柱付","structure_material":"コンクリート造","registered":"2017.06.28(平成29.06.28)","register_no":"23-0486","desc":"小口煉瓦タイルに花崗岩を帯状に三箇所組み合わせる意匠が特徴で、「赤門」として親しまれている。主門柱の高さは二・九五メートルで、柱頭部に花崗岩の飾り石を配し、柱頂部に球形照明を置く。脇柱は七割程度の規模で、意匠は主柱と共通する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011716"},{"id":"00011718","register_sub_id":"101","register_pk":"210734","name":"愛知県立碧南高等学校正門門柱（旧愛知県碧南国民学校正門）","kana":"あいちけんりつへきなんこうとうがっこうせいもんもんちゅう（きゅうあいちけんへきなんこくみんがっこうせいもん）","category":"学校","subcategory":"その他工作物","type_guess":"正門","type_guess_confidence":"high","period":"昭和前","pref":"愛知県","address":"愛知県碧南市向陽町四丁目12","lat":34.885392,"lng":136.993923,"geo_status":"db","era":"昭和4年頃／昭和37年頃改修","year":1929,"year_source":"db","year_min":1929,"year_max":1929,"year_label":null,"structure":"石造、間口6.4m、東西土塁留付","structure_material":"石造","registered":"2017.06.28(平成29.06.28)","register_no":"23-0488","desc":"敷地南面に建つ。正門は花崗岩製の主柱二本からなる。主柱は平らな石基礎に太い江戸切こぶ出し仕上げの角柱を立てたのみの簡素なものであるが、かつては笠石と球形照明器具があった。改変はあるが学校創立期の歴史を今に伝える門。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011718"},{"id":"00001076","register_sub_id":"101","register_pk":"102066","name":"刈谷市郷土資料館（旧亀城小学校本館）","kana":"かりやしきょうどしりょうかん（きゅうきじょうしょうがっこうほんかん）","category":"学校","subcategory":"建築物","type_guess":"記念館・資料室","type_guess_confidence":"high","period":"昭和前","pref":"愛知県","address":"愛知県刈谷市城町1-25-1","lat":34.98784944,"lng":136.98636947,"geo_status":"db","era":"昭和3","year":1928,"year_source":"db","year_min":1928,"year_max":1928,"year_label":null,"structure":"鉄筋コンクリート造２階建，瓦葺，建築面積748㎡","structure_material":"鉄筋コンクリート造２階建","registered":"1999.02.17(平成11.02.17)","register_no":"23 － 0021","desc":"地方都市における初期鉄筋コンクリート造建築の好例。設計は，元愛知県の技手で，刈谷に設計事務所を開いた大中肇。バットレス付きの玄関ポーチと，木造校舎を踏襲した両翼妻面のデザインに特徴がある。関係者の教育にかける思いが伝わってくる建築である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001076"},{"id":"00009762","register_sub_id":"101","register_pk":"195591","name":"旧愛知県岡崎師範学校武道場","kana":"きゅうあいちけんおかざきしはんがっこうぶどうじょう","category":"学校","subcategory":"建築物","type_guess":"体育館","type_guess_confidence":"high","period":"大正","pref":"愛知県","address":"愛知県岡崎市六供町八貫1-1","lat":34.96447593,"lng":137.17086649,"geo_status":"db","era":"大正15／昭和41改修","year":1926,"year_source":"db","year_min":1926,"year_max":1926,"year_label":null,"structure":"鉄筋コンクリート造平屋建、鉄板葺、建築面積427㎡","structure_material":"鉄筋コンクリート造平屋建","registered":"2013.12.24(平成25.12.24)","register_no":"23 － 0383","desc":"校地の北寄りに南北棟で建つ。鉄筋コンクリート造で、外壁に柱や梁形を表し、細部にゼツェッション意匠を取入れる。小屋は引張材である下弦材を鋼材として他を木材とする混構造のトラスを組み、内部の大空間を軽快に見せる。当時先進的な意匠、構造を試みた優品。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009762"},{"id":"00009461","register_sub_id":"101","register_pk":"194254","name":"旧愛知県第二尋常中学校講堂","kana":"きゅうあいちけんだいにじんじょうちゅうがっこうこうどう","category":"学校","subcategory":"建築物","type_guess":"講堂","type_guess_confidence":"high","period":"明治","pref":"愛知県","address":"愛知県岡崎市針崎町字春咲1-1","lat":34.92026901,"lng":137.1627016,"geo_status":"db","era":"明治30年／大正14年移築","year":1897,"year_source":"db","year_min":1897,"year_max":1897,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積347㎡","structure_material":"木造平屋建","registered":"2013.03.29(平成25.03.29)","register_no":"23 － 0359","desc":"木造平家建、寄棟造桟瓦葺で、南北各二箇所の屋根窓を設ける。西正面に切妻の玄関ポーチを付け、玄関欄間は三心アーチとする。東背面に奉安殿が突出。外壁はドイツ下見板張で上下窓の額縁を延ばしたスティックスタイル。内部は東に演壇をもうけ格天井とする。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009461"},{"id":"00014244","register_sub_id":"101","register_pk":"509634","name":"旧愛知県半田中学校武道場（七中記念館）","kana":"きゅうあいちけんはんだちゅうがっこうぶどうじょう（ななちゅうきねんかん）","category":"学校","subcategory":"建築物","type_guess":"体育館","type_guess_confidence":"high","period":"大正","pref":"愛知県","address":"愛知県半田市出口町一丁目30","lat":34.90311389,"lng":136.92191389,"geo_status":"db","era":"大正13年／昭和25年・平成30年改修","year":1924,"year_source":"db","year_min":1924,"year_max":1924,"year_label":null,"structure":"鉄筋コンクリート造平屋建、瓦葺、建築面積275㎡","structure_material":"鉄筋コンクリート造平屋建","registered":"2022.06.29(令和4.06.29)","register_no":"23 - 0578","desc":"校地の中央北寄りに建つ鉄筋コンクリート造の旧武道場。半切妻造桟瓦葺で、西正面に切妻造玄関突出部を設ける。小屋組は木材と丸鋼による混合トラス構造。縦長窓や柱頭飾り等でセセッションを取り入れて外観をまとめて時代相を示し、同校の長い歴史を語る。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014244"},{"id":"00006766","register_sub_id":"101","register_pk":"107748","name":"旧起第二尋常小学校奉安殿","kana":"きゅうおこしだいにじんじょうしょうがっこうほうあんでん","category":"学校","subcategory":"建築物","type_guess":"記念館・資料室","type_guess_confidence":"high","period":"昭和前","pref":"愛知県","address":"愛知県一宮市三条字苅2","lat":35.306324,"lng":136.759415,"geo_status":"db","era":"昭和4／昭和22頃移築","year":1929,"year_source":"db","year_min":1929,"year_max":1929,"year_label":null,"structure":"鉄筋コンクリート造、銅板葺、建築面積6.7㎡、基壇付","structure_material":"鉄筋コンクリート造","registered":"2007.10.02(平成19.10.02)","register_no":"23 － 0253","desc":"三條神社境内、本殿の近い位置に並行して建つ。桁行２．９ｍ、梁間２．３ｍ、入母屋造妻入銅板葺とする。長押が廻り、柱上に舟肘木、一軒疎垂木という木造意匠をコンクリート造で表現する。当初の姿を伝えるコンクリート造の奉安殿である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006766"},{"id":"00000969","register_sub_id":"101","register_pk":"101959","name":"金城学院高等学校榮光館","kana":"きんじょうがくいんこうとうがっこうえいこうかん","category":"学校","subcategory":"建築物","type_guess":"記念館・資料室","type_guess_confidence":"low","period":"昭和前","pref":"愛知県","address":"愛知県名古屋市東区白壁4-64","lat":35.18297743,"lng":136.91859399,"geo_status":"db","era":"昭和11","year":1936,"year_source":"db","year_min":1936,"year_max":1936,"year_label":null,"structure":"鉄筋コンクリート造３階建，建築面積800㎡","structure_material":"鉄筋コンクリート造３階建","registered":"1998.12.11(平成10.12.11)","register_no":"23 － 0016","desc":"生徒が一同に参集できる規模となるよう計画し，学園関係者等の寄付で再建した。屋根に赤いスペイン瓦を用い，外壁を白系統に塗ったスパニッシュスタイルになる清楚な外観が特徴で，礼拝堂を兼ねる。基本設計は佐藤鑑，実施設計は城戸武男，施工は広瀬商会。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000969"},{"id":"00009975","register_sub_id":"101","register_pk":"196122","name":"設楽町立田峯小学校特別教室棟","kana":"したらちょうりつだみねしょうがっこうとくべつきょうしつとう","category":"学校","subcategory":"建築物","type_guess":"校舎","type_guess_confidence":"high","period":"昭和前","pref":"愛知県","address":"愛知県北設楽郡設楽町田峯字下畑14他","lat":35.05723798,"lng":137.53270845,"geo_status":"db","era":"昭和2／平成23改修","year":1927,"year_source":"db","year_min":1927,"year_max":1927,"year_label":null,"structure":"木造平屋建、鋼板葺、建築面積124㎡","structure_material":"木造平屋建","registered":"2014.04.25(平成26.04.25)","register_no":"23 － 0402","desc":"普通教室棟の西昇降口から渡廊下を介して建つ。木造平屋建で東面し、外壁は普通教室棟と同様の下見板張とする。現在は図工美術室や理科室を配するが、もとは畳敷の裁縫室などであった。普通教室棟とともに、昭和初期における山村の小学校の情景を伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009975"},{"id":"00009974","register_sub_id":"101","register_pk":"196121","name":"設楽町立田峯小学校普通教室棟","kana":"したらちょうりつだみねしょうがっこうふつうきょうしつとう","category":"学校","subcategory":"建築物","type_guess":"校舎","type_guess_confidence":"high","period":"昭和前","pref":"愛知県","address":"愛知県北設楽郡設楽町田峯字下畑14他","lat":35.05747755,"lng":137.53275303,"geo_status":"db","era":"昭和2／平成23改修","year":1927,"year_source":"db","year_min":1927,"year_max":1927,"year_label":null,"structure":"木造平屋建、鋼板葺、建築面積689㎡","structure_material":"木造平屋建","registered":"2014.04.25(平成26.04.25)","register_no":"23 － 0401","desc":"山間部の田峯集落の校地に南面して建つ。桁行六五メートルに及ぶ、平屋建で片廊下式の木造校舎である。外壁は下見板張で正面中央に切妻造の玄関を構える。今なお現役使用の木造校舎であるとともに、集落内の地域活動の拠点としても活用され、親しまれている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009974"},{"id":"00002258","register_sub_id":"101","register_pk":"103248","name":"滝学園講堂","kana":"たきがくえんこうどう","category":"学校","subcategory":"建築物","type_guess":"講堂","type_guess_confidence":"high","period":"昭和前","pref":"愛知県","address":"愛知県江南市東野町米野1","lat":35.335815,"lng":136.856033,"geo_status":"db","era":"昭和8","year":1933,"year_source":"db","year_min":1933,"year_max":1933,"year_label":null,"structure":"鉄筋コンクリート一部鉄骨造2階建、セメント瓦葺、建築面積626㎡","structure_material":"鉄筋コンクリート一部鉄骨造2階建","registered":"2001.08.28(平成13.08.28)","register_no":"23 － 0057","desc":"滝学園は名古屋の豪商滝信四郎が創設した。講堂は鉄筋コンクリート造，屋根鉄骨トラス組で本館前広場の東側に建つ。無装飾に近い点が特徴で，正面に設けられた額縁を廻した３連出入口や，ペディメント風の屋根妻面などが，象徴性のある形態を構成している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002258"},{"id":"00011723","register_sub_id":"101","register_pk":"210739","name":"滝学園図書館","kana":"たきがくえんとしょかん","category":"学校","subcategory":"建築物","type_guess":"図書館","type_guess_confidence":"high","period":"昭和前","pref":"愛知県","address":"愛知県江南市東野町米野1","lat":35.335921,"lng":136.856245,"geo_status":"db","era":"昭和8年／昭和40年増築","year":1933,"year_source":"db","year_min":1933,"year_max":1933,"year_label":null,"structure":"鉄筋コンクリート造一部鉄骨鉄筋コンクリート造2階建、鋼板葺、建築面積307㎡","structure_material":"鉄筋コンクリート造一部鉄骨鉄筋コンクリート造2階建","registered":"2017.06.28(平成29.06.28)","register_no":"23-0493","desc":"滝学園講堂の東に接して建つ。一階部分は講堂と同時期に建てられた図書館で閲覧室、カウンターなどの痕跡を残す。これを覆う形で増築された二階部分は戦後モダニズムの特色をよく示し、縦ルーバーが並ぶ立面、ガラス窓を広くとった明るい閲覧室が特色である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011723"},{"id":"00002257","register_sub_id":"101","register_pk":"103247","name":"滝学園本館","kana":"たきがくえんほんかん","category":"学校","subcategory":"建築物","type_guess":"記念館・資料室","type_guess_confidence":"low","period":"昭和前","pref":"愛知県","address":"愛知県江南市東野町米野1","lat":35.335369,"lng":136.855957,"geo_status":"db","era":"昭和1","year":1926,"year_source":"db","year_min":1926,"year_max":1926,"year_label":null,"structure":"鉄筋コンクリート造2階建、鋼板葺、建築面積1482㎡、塔屋付","structure_material":"鉄筋コンクリート造2階建","registered":"2001.08.28(平成13.08.28)","register_no":"23 － 0056","desc":"鉄筋コンクリート造，２階建，長大な主屋の両端に短い翼屋をつけた平面。簡明なデザインであるが，正面中央の頂部ペディメント付の玄関突出部，大屋根中央の時計塔など，地域の景観のシンボルとなっている。設計は村瀬國之助，施工は名古屋の安藤建設という。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002257"},{"id":"00000790","register_sub_id":"101","register_pk":"101780","name":"東海学園大講堂","kana":"とうかいがくえんだいこうどう","category":"学校","subcategory":"建築物","type_guess":"講堂","type_guess_confidence":"high","period":"昭和前","pref":"愛知県","address":"愛知県名古屋市東区筒井1-202-4","lat":35.18000775,"lng":136.92943111,"geo_status":"db","era":"昭和6","year":1931,"year_source":"db","year_min":1931,"year_max":1931,"year_label":null,"structure":"鉄骨鉄筋コンクリート造地下１階地上３階建，建築面積909㎡","structure_material":"鉄骨鉄筋コンクリート造地下１階地上３階建","registered":"1998.09.02(平成10.09.02)","register_no":"23 － 0013","desc":"昭和天皇即位の御大典記念の建造物。ライト調をベースにドイツ表現派の意匠を重ね合わせた意欲的な作品。重厚にして華やかなファサードのデザインに見所がある｡設計は愛知県営繕課長の酒井勝で,卒業生の大脇勲（ともに名高工卒）らが手助けしたとされる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000790"},{"id":"00011514","register_sub_id":"101","register_pk":"210542","name":"豊田市藤岡民俗資料館（旧藤岡中学校特別教室棟）","kana":"とよたしふじおかみんぞくしりょうかん（きゅうふじおかちゅうがっこうとくべつきょうしつとう）","category":"学校","subcategory":"建築物","type_guess":"校舎","type_guess_confidence":"high","period":"昭和中","pref":"愛知県","address":"愛知県豊田市藤岡飯野町井ノ脇401","lat":35.20054389,"lng":137.20762306,"geo_status":"db","era":"昭和29年／昭和56年増築、平成26年改修","year":1954,"year_source":"db","year_min":1954,"year_max":1954,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積342㎡","structure_material":"木造平屋建","registered":"2017.05.02(平成29.05.02)","register_no":"23-0477","desc":"旧藤岡町の中心地に位置する。桁行三六メートル、梁間九・四メートル、木造平屋建、切妻造桟瓦葺で南北棟で建つ。小屋組はキングポストトラス。外壁は下見板張で、東面には出窓を設け、ガラス窓を多用し、採光に工夫を凝らす。特別教室棟の様相を今に伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011514"},{"id":"00010978","register_sub_id":"101","register_pk":"208948","name":"豊橋市民俗資料収蔵室西棟（旧多米小学校西校舎）","kana":"とよはししみんぞくしりょうしゅうぞうしつにしとう（きゅうためしょうがっこうにしこうしゃ）","category":"学校","subcategory":"建築物","type_guess":"校舎","type_guess_confidence":"high","period":"昭和中","pref":"愛知県","address":"愛知県豊橋市多米町字滝ノ谷34-1-1","lat":34.762261,"lng":137.45007,"geo_status":"db","era":"昭和29","year":1954,"year_source":"db","year_min":1954,"year_max":1954,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積312㎡","structure_material":"木造平屋建","registered":"2016.02.25(平成28.02.25)","register_no":"23-0459","desc":"本棟の西側に校庭を囲むようにして、南北棟で建つ。桁行三四メートル、梁間九メートルで、北端間を土間とし、西側に廊下を通す。各室東面に出窓を設けて採光に工夫する。室内天井に塗装を施すなど、本棟と比較して、洋風意匠を意識し、地域の教育史を物語る。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010978"},{"id":"00010977","register_sub_id":"101","register_pk":"208947","name":"豊橋市民俗資料収蔵室本棟（旧多米小学校本校舎）","kana":"とよはししみんぞくしりょうしゅうぞうしつほんとう（きゅうためしょうがっこうほんこうしゃ）","category":"学校","subcategory":"建築物","type_guess":"校舎","type_guess_confidence":"high","period":"昭和前","pref":"愛知県","address":"愛知県豊橋市多米町字滝ノ谷34-1-1","lat":34.762525,"lng":137.450504,"geo_status":"db","era":"昭和19","year":1944,"year_source":"db","year_min":1944,"year_max":1944,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積618㎡","structure_material":"木造平屋建","registered":"2016.02.25(平成28.02.25)","register_no":"23-0458","desc":"多米街道沿いに校地を構える。本棟は、桁行六二メートル、梁間一〇メートルの平屋建校舎で、北に廊下を通す。当時の学校建築に標準とされた方杖が用いられており、内観の特徴となる。西棟とともに市内に唯一残る木造校舎群で、歴史的な景観に寄与している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010977"},{"id":"00006336","register_sub_id":"101","register_pk":"107319","name":"名古屋大学医学部附属病院門及び外塀（旧愛知県立医学専門学校正門及び外塀）","kana":"なごやだいがくいがくぶふぞくびょういんもんおよびそとべい（きゅうあいちけんりついがくせんもんがっこうせいもんおよびそとべい）","category":"学校","subcategory":"その他工作物","type_guess":"正門","type_guess_confidence":"high","period":"大正","pref":"愛知県","address":"愛知県名古屋市昭和区鶴舞町65","lat":35.1575169,"lng":136.91980303,"geo_status":"db","era":"大正3／昭和5・平成11改修","year":1914,"year_source":"db","year_min":1914,"year_max":1914,"year_label":null,"structure":"門 石造門柱2基、間口4.2m、塀 煉瓦造、総延長16m","structure_material":"門 石造門柱2基","registered":"2007.10.02(平成19.10.02)","register_no":"23 － 0246","desc":"名古屋大学鶴舞キャンパス敷地の南辺にあり、道路を挟んで鶴舞公園に面する。門柱は花崗岩の方柱で、中央２本が当初のものである。塀は当初の煉瓦造に昭和５年にスクラッチタイルとテラコッタで改修し仕上げたもので、当時のデザイン傾向が窺える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006336"},{"id":"00008696","register_sub_id":"101","register_pk":"149417","name":"名古屋大学豊田講堂","kana":"なごやだいがくとよだこうどう","category":"学校","subcategory":"建築物","type_guess":"講堂","type_guess_confidence":"high","period":"昭和前","pref":"愛知県","address":"愛知県名古屋市千種区仁座町1","lat":35.15333087,"lng":136.96800455,"geo_status":"db","era":"昭和35年／平成2年・平成19年改修","year":1960,"year_source":"converted","year_min":1960,"year_max":1960,"year_label":null,"structure":"鉄筋コンクリート造3階地下1階建、建築面積2981㎡、デッキ広場及びアプローチ付","structure_material":"鉄筋コンクリート造3階地下1階建","registered":"2011.07.25(平成23.07.25)","register_no":"23 － 0333","desc":"名古屋大学東山キャンパス内に、丘陵を背にして建つ。鉄筋コンクリート造3階地下1階建、前面に人工地盤に造られた広場を設置。コンクリート打放し仕上げを基本とし、右手にピロティ、左手に大規模なホールを配する。モダニズム建築の一つの到達点を示す作品。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008696"},{"id":"00000791","register_sub_id":"101","register_pk":"101781","name":"南山学園ライネルス館","kana":"なんざんがくえんらいねるすかん","category":"学校","subcategory":"建築物","type_guess":"記念館・資料室","type_guess_confidence":"low","period":"昭和前","pref":"愛知県","address":"愛知県名古屋市昭和区五軒家町6-1","lat":35.14259749,"lng":136.95128417,"geo_status":"db","era":"昭和7","year":1932,"year_source":"db","year_min":1932,"year_max":1932,"year_label":null,"structure":"鉄筋コンクリート造地下１階地上４階建，建築面積529㎡","structure_material":"鉄筋コンクリート造地下１階地上４階建","registered":"1998.09.02(平成10.09.02)","register_no":"23 － 0014","desc":"学園創立時(当時は南山中学校)の本館で，現名称は創立者に因む。スイス人建築家ヒンデルの設計で，外壁の色合いはヒンデル好みの黄土色。玄関ポーチの円柱と外壁柱型の横目地が目を惹く。パラペットの三角切り込みは特異で類例を見ない。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000791"},{"id":"00003676","register_sub_id":"101","register_pk":"104666","name":"明治村宗教大学車寄","kana":"めいじむらしゅうきょうだいがくくるまよせ","category":"学校","subcategory":"その他工作物","type_guess":"校舎","type_guess_confidence":"high","period":"明治","pref":"愛知県","address":"愛知県犬山市内山1博物館明治村内","lat":35.34237538,"lng":136.99287472,"geo_status":"db","era":"明治41／昭和55移築","year":1908,"year_source":"db","year_min":1908,"year_max":1908,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積28㎡","structure_material":"木造平屋建","registered":"2003.12.01(平成15.12.01)","register_no":"23 － 0089","desc":"木造平屋建，宝形造，銅板瓦棒葺。元は大学本館車寄で移築時に背面側を正面と同形に仕上げる。花崗岩製腰壁に各隅３本の角柱が建ち，開口部は要石飾付の３心アーチで，迫元の蛇腹を持送りで受ける。柱間の壁は下部が横羽目板，蛇腹上は透彫のパネルを飾る。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003676"},{"id":"00003650","register_sub_id":"101","register_pk":"104640","name":"明治村第八高等学校正門","kana":"めいじむらだいはちこうとうがっこうせいもん","category":"学校","subcategory":"その他工作物","type_guess":"正門","type_guess_confidence":"high","period":"明治","pref":"愛知県","address":"愛知県犬山市内山1博物館明治村内","lat":35.34054113,"lng":136.98867475,"geo_status":"db","era":"明治42／昭和45移築","year":1909,"year_source":"db","year_min":1909,"year_max":1909,"year_label":null,"structure":"煉瓦造、間口9.3m、左右袖塀各5.1m及び鉄製門扉付","structure_material":"煉瓦造","registered":"2003.12.01(平成15.12.01)","register_no":"23 － 0063","desc":"煉瓦造の門で両側に脇門を備え，脇塀が接続する。門柱は赤煉瓦積角柱で胴部に３条の花崗岩の帯を巡らす。門柱頭部は箱形で蛇腹を廻す。鉄製門扉は戦中に供出されたものを移築時に復原した。細い竪格子を粗く配しており，円環と渦巻の装飾が軽快である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003650"},{"id":"00003857","register_sub_id":"101","register_pk":"104847","name":"明治村第四高等学校武術道場無声堂弓道場","kana":"めいじむらだいよんこうとうがっこうぶじゅつどうじょうむせいどうきゅうどうじょう","category":"学校","subcategory":"建築物","type_guess":"体育館","type_guess_confidence":"high","period":"大正","pref":"愛知県","address":"愛知県犬山市内山1博物館明治村内","lat":35.342724,"lng":136.99013911,"geo_status":"db","era":"大正6／昭和45移築","year":1917,"year_source":"db","year_min":1917,"year_max":1917,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積72㎡","structure_material":"木造平屋建","registered":"2004.02.17(平成16.02.17)","register_no":"23 － 0091","desc":"木造平屋建，切妻造，桟瓦葺で，的場側に庇がつく。主屋とは出入口の土間を介して接続する。外壁は隅柱付の洋風下見板張で，妻壁上部を漆喰塗真壁造とし，欄間付の引違窓と横長の引違窓を開く。洋風小屋組を使用し，的場に向かった間口一杯５間を無柱とする。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003857"},{"id":"00003856","register_sub_id":"101","register_pk":"104846","name":"明治村第四高等学校武術道場無声堂主屋","kana":"めいじむらだいよんこうとうがっこうぶじゅつどうじょうむせいどうしゅおく","category":"学校","subcategory":"建築物","type_guess":"体育館","type_guess_confidence":"high","period":"大正","pref":"愛知県","address":"愛知県犬山市内山1博物館明治村内","lat":35.34281804,"lng":136.99041496,"geo_status":"db","era":"大正6／昭和45移築","year":1917,"year_source":"db","year_min":1917,"year_max":1917,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積509㎡","structure_material":"木造平屋建","registered":"2004.02.17(平成16.02.17)","register_no":"23 － 0090","desc":"木造平屋建，切妻造，桟瓦葺。正面中央に切妻造玄関がつく。内部は剣道場と柔道場に二分し，両妻の落ち棟に師範台と更衣室，背後に浴室を設ける。外壁は隅柱付の洋風下見板張，小壁は漆喰塗真壁造，欄間付引違窓を開く。洋風小屋組で無柱の空間を実現した。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003856"},{"id":"00003661","register_sub_id":"101","register_pk":"104651","name":"明治村第四高等学校物理化学教室","kana":"めいじむらだいよんこうとうがっこうぶつりかがくきょうしつ","category":"学校","subcategory":"建築物","type_guess":"校舎","type_guess_confidence":"high","period":"明治","pref":"愛知県","address":"愛知県犬山市内山1博物館明治村内","lat":35.34144356,"lng":136.9890676,"geo_status":"db","era":"明治23／昭和40移築","year":1890,"year_source":"db","year_min":1890,"year_max":1890,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積454㎡","structure_material":"木造平屋建","registered":"2003.12.01(平成15.12.01)","register_no":"23 － 0074","desc":"木造平屋建，中央玄関ホールの両側に階段教室を設けて切妻屋根を一段高く造り，左右に寄棟屋根の実験教室を延ばす。外壁は隅柱付の下見板張で，欄間付上げ下げ窓を配し，木造洋風校舎建築の代表例である。棟札に工事監督山口半六，設計久留正道とある。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003661"},{"id":"00003660","register_sub_id":"101","register_pk":"104650","name":"明治村千早赤阪小学校講堂","kana":"めいじむらちはやあかさかしょうがっこうこうどう","category":"学校","subcategory":"建築物","type_guess":"講堂","type_guess_confidence":"high","period":"明治","pref":"愛知県","address":"愛知県犬山市内山1博物館明治村内","lat":35.341366,"lng":136.989853,"geo_status":"db","era":"明治30頃／昭和51移築","year":1897,"year_source":"db","year_min":1897,"year_max":1897,"year_label":null,"structure":"木造2階建、瓦葺、建築面積463㎡","structure_material":"木造2階建","registered":"2003.12.01(平成15.12.01)","register_no":"23 － 0073","desc":"木造２階建，寄棟造，桟瓦葺で，１階を雨天体操場，２階を講堂とする。１階は櫛形アーチの軽快なアーケードを巡らせ，２階は隅柱付の下見板張外壁にペディメント付の上げ下げ窓を配す。棟飾やせいの高い軒蛇腹など，明治期木造洋風建築の特色ある意匠を示す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003660"},{"id":"00003657","register_sub_id":"101","register_pk":"104647","name":"明治村東京盲学校車寄","kana":"めいじむらとうきょうもうがっこうくるまよせ","category":"学校","subcategory":"その他工作物","type_guess":"校舎","type_guess_confidence":"high","period":"明治","pref":"愛知県","address":"愛知県犬山市内山1博物館明治村内","lat":35.33934983,"lng":136.99101617,"geo_status":"db","era":"明治43／昭和43移築","year":1910,"year_source":"db","year_min":1910,"year_max":1910,"year_label":null,"structure":"木造平屋建、鉄板葺、建築面積20㎡","structure_material":"木造平屋建","registered":"2003.12.01(平成15.12.01)","register_no":"23 － 0070","desc":"ハーフチンバー様式の建物の車寄部分を移築，四阿とする。緩い切妻屋根を鉄板葺とし，花弁と渦巻を組合せた屋根飾りを載せる。天井中心飾りと破風を植物意匠で，持送り，柱の頭部と胴部，腰壁を幾何学意匠で飾る。柱に支持されない３連アーチが目をひく。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003657"},{"id":"00003652","register_sub_id":"101","register_pk":"104642","name":"明治村三重県尋常師範学校・蔵持小学校","kana":"めいじむらみえけんじんじょうしはんがっこう・くらもちしょうがっこう","category":"学校","subcategory":"建築物","type_guess":"校舎","type_guess_confidence":"high","period":"明治","pref":"愛知県","address":"愛知県犬山市内山1博物館明治村内","lat":35.3401419,"lng":136.98797513,"geo_status":"db","era":"明治21／昭和48移築","year":1888,"year_source":"db","year_min":1888,"year_max":1888,"year_label":null,"structure":"木造2階建、瓦葺、建築面積365㎡","structure_material":"木造2階建","registered":"2003.12.01(平成15.12.01)","register_no":"23 － 0065","desc":"木造２階建，桟瓦葺，外壁は玄関部が漆喰塗，教室部が下見板張。軒先持送りと胴蛇腹の下に飾りパネルを付け，簡素な上げ下げ窓を配す。玄関部と１階廊下にトスカナ式円柱を配し，入母屋破風とポーチ扁平アーチを植物意匠で飾る。設計は三重県技師の清水義八。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003652"},{"id":"00009780","register_sub_id":"101","register_pk":"195609","name":"朝日小学校円形校舎","kana":"あさひしょうがっこうえんけいこうしゃ","category":"学校","subcategory":"建築物","type_guess":"校舎","type_guess_confidence":"high","period":"昭和中","pref":"三重県","address":"三重県三重郡朝日町大字柿750","lat":35.0339013,"lng":136.66502723,"geo_status":"db","era":"昭和37／平成15改修","year":1962,"year_source":"db","year_min":1962,"year_max":1962,"year_label":null,"structure":"鉄筋コンクリート造4階建、金属板葺、建築面積573㎡","structure_material":"鉄筋コンクリート造4階建","registered":"2013.12.24(平成25.12.24)","register_no":"24 － 0165","desc":"町域のほぼ中心に所在する小学校で、四階建の円形校舎に特別教室等を配する。一階から三階は中央に無柱の円形ホール、その周囲に特別教室等を配し、外周にベランダを廻す。四階講堂は一室の大空間を実現する。坂本鹿名夫による一連の円形校舎の中で最盛期の作。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009780"},{"id":"00010177","register_sub_id":"101","register_pk":"198010","name":"旧阿下喜小学校門及び石柵","kana":"きゅうあげきしょうがっこうもんおよびせきさく","category":"学校","subcategory":"その他工作物","type_guess":"正門","type_guess_confidence":"high","period":"明治","pref":"三重県","address":"三重県いなべ市北勢町阿下喜字二俣1988他","lat":35.15151171,"lng":136.5192147,"geo_status":"db","era":"明治後期／大正10・大正15改修","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"正門 石造、間口6.0m 門 石造、間口2.8m 石柵 石造、総延長71m","structure_material":"正門 石造","registered":"2014.10.07(平成26.10.07)","register_no":"24 － 0181","desc":"旧校地の南辺を画す石造の門と石柵で、中央に正門を、西方に門を開く。正門は花崗岩の石柱を立てて宝形造の笠石を載せ、左右に控石柱を添える。門も同型式でやや小振りとする。石柵は石積基壇上に配列した石柱に鉄棒を渡す。明治開校時の面影を伝える遺構。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010177"},{"id":"00009030","register_sub_id":"101","register_pk":"162390","name":"旧尾呂志中学校校舎","kana":"きゅうおろしちゅうがっこうこうしゃ","category":"学校","subcategory":"建築物","type_guess":"校舎","type_guess_confidence":"high","period":"昭和中","pref":"三重県","address":"三重県南牟婁郡御浜町大字上野下尾﨑240-2","lat":33.84570992,"lng":135.98268284,"geo_status":"db","era":"昭和24年／平成16年改修","year":1949,"year_source":"db","year_min":1949,"year_max":1949,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積619㎡","structure_material":"木造平屋建","registered":"2011.10.28(平成23.10.28)","register_no":"24 － 0120","desc":"山中の集落の高台に位置する。南に運動場を設け、北の一段高い位置に建つ。桁行６２ｍ梁間１０ｍの細長い建物で、切妻造桟瓦葺。南面に教室を並べ、北側に廊下を通し、中央西寄りに切妻造妻入の玄関を設ける。緑の山並に長く延びる校舎が映える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009030"},{"id":"00008010","register_sub_id":"101","register_pk":"128841","name":"旧鳥羽小学校校舎","kana":"きゅうとばしょうがっこうこうしゃ","category":"学校","subcategory":"建築物","type_guess":"校舎","type_guess_confidence":"high","period":"昭和前","pref":"三重県","address":"三重県鳥羽市鳥羽3-1-60","lat":34.48038676,"lng":136.84473996,"geo_status":"db","era":"昭和4","year":1929,"year_source":"db","year_min":1929,"year_max":1929,"year_label":null,"structure":"鉄筋コンクリート造3階建、建築面積1087㎡","structure_material":"鉄筋コンクリート造3階建","registered":"2010.01.15(平成22.01.15)","register_no":"24-0086","desc":"鳥羽港を望む高台に南面して建つ。正面６７ｍ、Ｅ字形平面の鉄筋コンクリート造３階建で、表面はモルタル仕上げとする。中央３階部分を背後の斜面上に張り出し、内部を大空間の講堂とする独特の構成。中央部分など随所にアールデコ風の意匠を施す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008010"},{"id":"00005622","register_sub_id":"101","register_pk":"106610","name":"皇學館大学記念館（旧神宮皇學館大学本館）","kana":"こうがっかんだいがくきねんかん（きゅうじんぐうこうがくかんだいがくほんかん）","category":"学校","subcategory":"建築物","type_guess":"記念館・資料室","type_guess_confidence":"high","period":"大正","pref":"三重県","address":"三重県伊勢市神田久志本町1704","lat":34.48660585,"lng":136.72627905,"geo_status":"db","era":"大正8","year":1919,"year_source":"db","year_min":1919,"year_max":1919,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積647㎡","structure_material":"木造平屋建","registered":"2006.08.03(平成18.08.03)","register_no":"24 － 0061","desc":"細長い東西棟，桟瓦葺の建物で，正面の東面は入母屋造で唐破風造，銅板葺の玄関を備え，西面は寄棟造とする。内部はもと中廊下式で左右に教室を配した。縦長窓を配し調和のとれた外観や旧貴賓室と旧館長室の内装に当初形式をよく残す。大正期の和風建築の好例。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005622"},{"id":"00007750","register_sub_id":"101","register_pk":"108731","name":"白川小学校校舎北棟","kana":"しらかわしょうがっこうこうしゃきたとう","category":"学校","subcategory":"建築物","type_guess":"校舎","type_guess_confidence":"high","period":"昭和中","pref":"三重県","address":"三重県亀山市白木町2739","lat":34.88339925,"lng":136.41274262,"geo_status":"db","era":"昭和29／平成4改修","year":1954,"year_source":"db","year_min":1954,"year_max":1954,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積573㎡、渡廊下3棟付","structure_material":"木造平屋建","registered":"2009.08.07(平成21.08.07)","register_no":"24-0080","desc":"南棟の北に中庭を挟み平行に建ち、中央及び東西端の渡廊下で繋がる。桁行５８ｍ梁間９．２ｍの木造平屋建、切妻造桟瓦葺で両端に庇を設ける。外壁は上部を白漆喰塗とする下見板張。北側の校庭に面して廊下が通り、南に教室を並べる。地域に親しまれる学校建築。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007750"},{"id":"00007749","register_sub_id":"101","register_pk":"108730","name":"白川小学校校舎南棟","kana":"しらかわしょうがっこうこうしゃみなみとう","category":"学校","subcategory":"建築物","type_guess":"校舎","type_guess_confidence":"high","period":"昭和中","pref":"三重県","address":"三重県亀山市白木町2739","lat":34.88323728,"lng":136.41276576,"geo_status":"db","era":"昭和29／平成4改修","year":1954,"year_source":"db","year_min":1954,"year_max":1954,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積586㎡","structure_material":"木造平屋建","registered":"2009.08.07(平成21.08.07)","register_no":"24-0079","desc":"集落北側山中に校地を占める。桁行５８ｍ梁間９．２ｍ、木造平屋建、東西棟の切妻造桟瓦葺で、両端に庇を付ける。上部白漆喰塗の下見板張。片廊下式で、東半に職員室など、西半に教室を配する。正面中央に千鳥破風と玄関ポーチを付け、学校らしい正面性を示す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007749"},{"id":"00001115","register_sub_id":"101","register_pk":"102105","name":"鈴鹿峠自然の家（旧坂下尋常高等小学校）","kana":"すずかとおげしぜんのいえ（きゅうさかしたじんじょうこうとうしょうがっこう）","category":"学校","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"三重県","address":"三重県亀山市関町沓掛123","lat":34.88263135,"lng":136.36020234,"geo_status":"db","era":"昭和13","year":1938,"year_source":"db","year_min":1938,"year_max":1938,"year_label":null,"structure":"木造平屋建，瓦葺，建築面積939㎡","structure_material":"木造平屋建","registered":"1999.06.07(平成11.06.07)","register_no":"24 － 0022","desc":"木造平屋建、片廊下４教室規模の校舎２棟を並べ建て、左右を片流れ屋根の廊下でつないだロの字型プランを採っているのが特徴。正面中央に妻をハーフティンバー風にみせた車寄をつける。廃校後も宿泊研修施設として活用され、地区の心の故郷たり続けている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001115"},{"id":"00008704","register_sub_id":"101","register_pk":"149425","name":"誓元寺光雲殿（旧常磐尋常高等小学校奉安殿）","kana":"せいげんじこううんでん（きゅうときわじんじょうこうとうしょうがっこうほうあんでん）","category":"学校","subcategory":"建築物","type_guess":"記念館・資料室","type_guess_confidence":"high","period":"昭和前","pref":"三重県","address":"三重県四日市市赤堀2-2009-1","lat":34.96053225,"lng":136.60667312,"geo_status":"db","era":"昭和10年／昭和21年移築・平成16年改修","year":1935,"year_source":"converted","year_min":1935,"year_max":1935,"year_label":null,"structure":"鉄筋コンクリート造平屋建、建築面積23㎡","structure_material":"鉄筋コンクリート造平屋建","registered":"2011.07.25(平成23.07.25)","register_no":"24 － 0102","desc":"境内の南寄りに位置する。切石積基壇上に建つ鉄筋コンクリート造平屋建。4隅に柱型を造り出し、正面に切妻破風を飾る持送り庇を突出する。屋根は陸屋根軒を左右に出し、中央をドーム状に造る。外壁はモルタル洗出し。簡明な意匠でまとめられたRC造奉安殿。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008704"},{"id":"00010176","register_sub_id":"101","register_pk":"198009","name":"桐林館（旧阿下喜小学校校舎）","kana":"とうりんかん（きゅうあげきしょうがっこうこうしゃ）","category":"学校","subcategory":"建築物","type_guess":"校舎","type_guess_confidence":"high","period":"昭和前","pref":"三重県","address":"三重県いなべ市北勢町阿下喜字二俣1974他","lat":35.152473,"lng":136.519362,"geo_status":"db","era":"昭和12／昭和58移築","year":1937,"year_source":"db","year_min":1937,"year_max":1937,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積345㎡、塔屋付","structure_material":"木造平屋建","registered":"2014.10.07(平成26.10.07)","register_no":"24 － 0180","desc":"旧校地の北奥に南面し、木造平屋建、寄棟造桟瓦葺である。南面中央に切妻造の玄関を構え、屋根の中央に塔屋を載せ、左右にドーマー窓を飾る。外壁の腰を下見板張とし、小屋はキングポストトラスを組む。外観や内部造作とも旧規をよくとどめる戦前の木造校舎。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010176"},{"id":"00011973","register_sub_id":"101","register_pk":"211162","name":"福徳公民館（旧明村立明小学校福徳分教場）","kana":"ふくとくこうみんかん（きゅうあきらそんりつあきらしょうがっこうふくとくぶんきょうじょう）","category":"学校","subcategory":"建築物","type_guess":"記念館・資料室","type_guess_confidence":"low","period":"昭和中","pref":"三重県","address":"三重県亀山市関町福徳字下垣内143-1","lat":34.835002,"lng":136.378914,"geo_status":"db","era":"昭和25年頃／昭和50年・平成20年改修","year":1950,"year_source":"db","year_min":1950,"year_max":1950,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積99㎡","structure_material":"木造平屋建","registered":"2017.10.27(平成29.10.27)","register_no":"24-244","desc":"市南西部の山村集落に建つ旧分教場。片廊下を通し、南面に教室一室と一〇畳で床の間をもつ和室を配し、両端に倉庫や物置・便所を備える。最小規模ながら正面に玄関を張り出し格天井とし、外壁は下見板張で窓を大きく開き、学校建築としての意匠をよく留める。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011973"},{"id":"00002629","register_sub_id":"101","register_pk":"103619","name":"三重大学三翠会館","kana":"みえだいがくさんすいかいかん","category":"学校","subcategory":"建築物","type_guess":"記念館・資料室","type_guess_confidence":"low","period":"昭和前","pref":"三重県","address":"三重県津市上浜町1515","lat":34.74567,"lng":136.521744,"geo_status":"db","era":"昭和11","year":1936,"year_source":"db","year_min":1936,"year_max":1936,"year_label":null,"structure":"木造2階建、鉄板葺、建築面積309㎡","structure_material":"木造2階建","registered":"2002.02.14(平成14.02.14)","register_no":"24 － 0041","desc":"三重高等農林学校の開校１０周年事業として建設された同窓会館。木造，鉄板葺（旧スレート葺）で西面して建ち，２階建で正面に車寄を突出した主体部の南に平屋の会議室棟を付属する。外壁に柱型や窓枠を多用し，変化に富んだ屋根を載せ派手な外観を構成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002629"},{"id":"00003243","register_sub_id":"101","register_pk":"104233","name":"三重大学レーモンドホール","kana":"みえだいがくれーもんどほーる","category":"学校","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和中","pref":"三重県","address":"三重県津市上浜町1515","lat":34.739643,"lng":136.524628,"geo_status":"db","era":"昭和26","year":1951,"year_source":"db","year_min":1951,"year_max":1951,"year_label":null,"structure":"木造平屋建、鉄板葺、建築面積230㎡","structure_material":"木造平屋建","registered":"2003.03.18(平成15.03.18)","register_no":"24 － 0047","desc":"アントニン・レーモンド設計の木造平屋建建築。当初は三重県立大学の図書館として建設された。前面ガラス戸とする開放的南面や丸材を用いる架構等が特徴で，戦前から戦後にかけてに建てられた木造によるレーモンドスタイルの好例といえる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003243"},{"id":"00001917","register_sub_id":"101","register_pk":"102907","name":"近江兄弟社学園教育会館","kana":"おうみきょうだいしゃがくえんきょういくかいかん","category":"学校","subcategory":"建築物","type_guess":"記念館・資料室","type_guess_confidence":"low","period":"昭和前","pref":"滋賀県","address":"滋賀県近江八幡市市井町177","lat":35.14028676,"lng":136.09548669,"geo_status":"db","era":"昭和6","year":1931,"year_source":"db","year_min":1931,"year_max":1931,"year_label":null,"structure":"木造平屋一部2階建、瓦葺、建築面積477㎡","structure_material":"木造平屋一部2階建","registered":"2000.10.18(平成12.10.18)","register_no":"25 － 0138","desc":"ハイド記念館と共にメンソレータム社創設者Ａ．Ａ．ハイド夫人の寄付により建造された講堂兼体育館。外装は記念館に類似。切妻造を基調とし，片側面にＴ形窓を並べ，もう片側を用具室等を収めるために下屋庇状に屋根を一段下げる。妻面に出窓を設ける。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001917"},{"id":"00001916","register_sub_id":"101","register_pk":"102906","name":"近江兄弟社学園ハイド記念館","kana":"おうみきょうだいしゃがくえんはいどきねんかん","category":"学校","subcategory":"建築物","type_guess":"記念館・資料室","type_guess_confidence":"high","period":"昭和前","pref":"滋賀県","address":"滋賀県近江八幡市市井町177","lat":35.14004831,"lng":136.09547876,"geo_status":"db","era":"昭和6","year":1931,"year_source":"db","year_min":1931,"year_max":1931,"year_label":null,"structure":"木造2階建、瓦葺、建築面積352㎡","structure_material":"木造2階建","registered":"2000.10.18(平成12.10.18)","register_no":"25 － 0137","desc":"市中心部に位置する。木造２階建，切妻造・赤桟瓦葺，車寄付で，外装スタッコ仕上，腰下見板張とし，単窓・連窓を巧みに配す。採光や内部機能に優れた近代幼稚園園舎。設計ヴォーリズ。ヴォーリズ夫人で建設当時園長の一柳満喜子が計画に参与したと伝わる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001916"},{"id":"00009506","register_sub_id":"101","register_pk":"194299","name":"旧豊郷小学校校舎","kana":"きゅうとよさとしょうがっこうこうしゃ","category":"学校","subcategory":"建築物","type_guess":"校舎","type_guess_confidence":"high","period":"昭和前","pref":"滋賀県","address":"滋賀県犬上郡豊郷町石畑518","lat":35.20339074,"lng":136.23287204,"geo_status":"db","era":"昭和12年／平成21年改修","year":1937,"year_source":"db","year_min":1937,"year_max":1937,"year_label":null,"structure":"鉄筋コンクリート造2階一部3階建、建築面積1839㎡、渡廊下付","structure_material":"鉄筋コンクリート造2階一部3階建","registered":"2013.03.29(平成25.03.29)","register_no":"25 － 0330","desc":"旧中山道に面した校地の中央に西面して建つ。鉄筋コンクリート造二階建、建築面積一、八七九平方メートル、中央部を三階建の塔屋として正面に車寄を出す。モダニズムを基調とした左右対称の威風堂々とした外観は、地域のランドマークとして親しまれる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009506"},{"id":"00009507","register_sub_id":"101","register_pk":"194300","name":"旧豊郷小学校講堂","kana":"きゅうとよさとしょうがっこうこうどう","category":"学校","subcategory":"建築物","type_guess":"講堂","type_guess_confidence":"high","period":"昭和前","pref":"滋賀県","address":"滋賀県犬上郡豊郷町石畑518","lat":35.20305761,"lng":136.23212965,"geo_status":"db","era":"昭和12年／平成21年改修","year":1937,"year_source":"db","year_min":1937,"year_max":1937,"year_label":null,"structure":"鉄筋コンクリート造平屋一部2階建一部地階付、建築面積519㎡","structure_material":"鉄筋コンクリート造平屋一部2階建一部地階付","registered":"2013.03.29(平成25.03.29)","register_no":"25 － 0331","desc":"校舎の南側前方に北面して建ち、渡り廊下で接続する。鉄筋コンクリート造二階建、建築面積五一八平方メートル、南端の地下にボイラー室を設ける。校舎と同様のモダニズムを基調とした整然とした外観で、校舎、図書館とともに建設当時の威容を伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009507"},{"id":"00009508","register_sub_id":"101","register_pk":"194301","name":"旧豊郷小学校酬徳記念図書館","kana":"きゅうとよさとしょうがっこうしゅうとくきねんとしょかん","category":"学校","subcategory":"建築物","type_guess":"図書館","type_guess_confidence":"high","period":"昭和前","pref":"滋賀県","address":"滋賀県犬上郡豊郷町石畑518","lat":35.20401178,"lng":136.23292915,"geo_status":"db","era":"昭和12年／平成21年改修","year":1937,"year_source":"db","year_min":1937,"year_max":1937,"year_label":null,"structure":"鉄筋コンクリート造平屋一部2階建、建築面積355㎡","structure_material":"鉄筋コンクリート造平屋一部2階建","registered":"2013.03.29(平成25.03.29)","register_no":"25 － 0332","desc":"校舎の北側前方に南面して建ち、校舎とは渡り廊下で接続する。鉄筋コンクリート造二階建、建築面積三五五平方メートル、北側の中央部を鉄製三層の本棚を組み込んだ書庫にあてる。外観は校舎に合わせるが、柱頭や手摺りの金具に飾り気のある意匠を用いる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009508"},{"id":"00006318","register_sub_id":"101","register_pk":"107301","name":"旧豊郷尋常高等小学校本館","kana":"きゅうとよさとじんじょうこうとうしょうがっこうほんかん","category":"学校","subcategory":"建築物","type_guess":"記念館・資料室","type_guess_confidence":"low","period":"明治","pref":"滋賀県","address":"滋賀県犬上郡豊郷町四十九院815","lat":35.20653664,"lng":136.23573131,"geo_status":"db","era":"明治20／昭和12改修","year":1887,"year_source":"db","year_min":1887,"year_max":1887,"year_label":null,"structure":"木造2階建、瓦葺、建築面積105㎡","structure_material":"木造2階建","registered":"2007.07.31(平成19.07.31)","register_no":"25 － 0241","desc":"至熟小学校講堂として建設。敷地東奥に西を正面にして建つ桁行７間，梁間４間の木造２階建で，寄棟造，桟瓦葺とする。外壁はモルタル塗で，両開ガラス窓を開く。正面中央の車寄上部のバルコニーにはロクロ挽手摺子を飾り，ペディメント風の切妻屋根を架ける。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006318"},{"id":"00000446","register_sub_id":"101","register_pk":"101436","name":"湖東町歴史民俗資料館（旧西押立国民学校校舎）","kana":"ことうちょうれきしみんぞくしりょうかん（きゅうにしおしたてこくみんがっこうこうしゃ）","category":"学校","subcategory":"建築物","type_guess":"校舎","type_guess_confidence":"high","period":"昭和前","pref":"滋賀県","address":"滋賀県東近江市北菩提寺町126","lat":35.1432793,"lng":136.23699843,"geo_status":"db","era":"昭和18","year":1943,"year_source":"db","year_min":1943,"year_max":1943,"year_label":null,"structure":"木造2階建，瓦葺，建築面積676㎡","structure_material":"木造2階建","registered":"1998.01.16(平成10.01.16)","register_no":"25 － 0027","desc":"実業家松居泰次良・房治郎兄弟の寄付により建設された。コの字形平面の建物で，外壁の下見板と屋根の赤色の桟瓦の対比に特徴がある。大工は泰山閣と同じ木村太兵衛である。昭和56年に資料館となったが，強度の木造校舎として広く親しまれている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000446"},{"id":"00002149","register_sub_id":"101","register_pk":"103139","name":"滋賀大学経済学部講堂（旧彦根高等商業学校講堂）","kana":"しがだいがくけいざいがくぶこうどう（きゅうひこねこうとうしょうぎょうがっこうこうどう）","category":"学校","subcategory":"建築物","type_guess":"講堂","type_guess_confidence":"high","period":"大正","pref":"滋賀県","address":"滋賀県彦根市馬場1-1-1","lat":35.276863,"lng":136.247116,"geo_status":"db","era":"大正13","year":1924,"year_source":"db","year_min":1924,"year_max":1924,"year_label":null,"structure":"木造2階建、瓦葺、建築面積679㎡","structure_material":"木造2階建","registered":"2001.04.24(平成13.04.24)","register_no":"25 － 0143","desc":"彦根城西部の堀に接する滋賀大学敷地内にある。木造２階建の講堂に，平屋建の大教室が接続し，外装ほぼ全体を下見板貼とする。講堂妻面に柱型付玄関を設け，上下階で連続性をもつ矩形窓を側面に配し，半円形屋根窓，瀟洒な小塔を冠す。文部省建築課の設計。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002149"},{"id":"00001116","register_sub_id":"101","register_pk":"102106","name":"曽根東福寺組地蔵堂（旧曽根学校玄関）","kana":"そねとうふくじくみじぞうどう（きゅうそねがっこうげんかん）","category":"学校","subcategory":"建築物","type_guess":"記念館・資料室","type_guess_confidence":"low","period":"明治","pref":"滋賀県","address":"滋賀県長浜市曽根町992-1","lat":35.40819938,"lng":136.25120398,"geo_status":"db","era":"明治9","year":1876,"year_source":"db","year_min":1876,"year_max":1876,"year_label":null,"structure":"木造平屋建，瓦葺，建築面積５㎡","structure_material":"木造平屋建","registered":"1999.06.07(平成11.06.07)","register_no":"25 － 0111","desc":"明治９年に建築された曽根学校の旧校舎玄関部分を分離し、地蔵堂として利用したもの。間口１間で、正面の礎盤付きの円柱上部に組物を置き、両折の桟唐戸を付け円弧状の瓦屋根を乗せた特異な旧態が保たれている。村の辻堂として広く親しまれている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001116"},{"id":"00001915","register_sub_id":"101","register_pk":"102905","name":"長浜旧開知学校","kana":"ながはまきゅうかいちがっこう","category":"学校","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"滋賀県","address":"滋賀県長浜市元浜町2-3","lat":35.379448,"lng":136.267365,"geo_status":"db","era":"明治7／昭和11移築","year":1874,"year_source":"db","year_min":1874,"year_max":1874,"year_label":null,"structure":"木造3階建、瓦葺、建築面積127㎡、塔屋付","structure_material":"木造3階建","registered":"2000.10.18(平成12.10.18)","register_no":"25 － 0136","desc":"駅前通り沿いに建つ木造３階建，八角塔屋付の擬洋風建築。外装モルタル塗，腰石積，隅石付。正面入口とその上部に列柱式開口部を構え，壁面に上げ下げ窓と花形レリーフを均等に配す。学校施設として利用された後，近年改修され，現在展示・会議室として活用。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001915"},{"id":"00000691","register_sub_id":"101","register_pk":"101681","name":"白雲館","kana":"はくうんかん","category":"学校","subcategory":"建築物","type_guess":"記念館・資料室","type_guess_confidence":"low","period":"明治","pref":"滋賀県","address":"滋賀県近江八幡市為心町元９－１","lat":35.13944061,"lng":136.09100612,"geo_status":"db","era":"明治10","year":1877,"year_source":"db","year_min":1877,"year_max":1877,"year_label":null,"structure":"木造２階建，瓦葺，建築面積306㎡","structure_material":"木造２階建","registered":"1998.09.02(平成10.09.02)","register_no":"25 － 0039","desc":"八幡東学校として建設。日牟礼八幡宮参道の鳥居前に位置し，主屋に翼舎をはりだした凹字形の形態をとる。漆喰塗系の擬洋風建築で玄関上部の唐破風と屋根上の太鼓楼との取り合わせは開智学校の造形に類似している。棟梁は近江蒲生郡の大工高木作右衛門。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000691"},{"id":"00000447","register_sub_id":"101","register_pk":"101437","name":"錬成館（旧西押立国民学校講堂）","kana":"れんせいかん（きゅうにしおしたてこくみんがっこうこうどう）","category":"学校","subcategory":"建築物","type_guess":"講堂","type_guess_confidence":"high","period":"昭和前","pref":"滋賀県","address":"滋賀県東近江市北菩提寺町126","lat":35.14308453,"lng":136.23733261,"geo_status":"db","era":"昭和18","year":1943,"year_source":"db","year_min":1943,"year_max":1943,"year_label":null,"structure":"木造平屋建，瓦葺，建築面積534㎡","structure_material":"木造平屋建","registered":"1998.01.16(平成10.01.16)","register_no":"25 － 0028","desc":"校舎と同時期に建てられた講堂を，移築にともない柔道場としたもの。袴腰の大屋根の正面に一段低い屋根や車寄せ等を設け，正面からは複雑にみえるようにしている。外壁に下見板を張り（現在は一部モルタル）屋根に赤色の桟瓦を葺く意匠は校舎に類似する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000447"},{"id":"00003451","register_sub_id":"101","register_pk":"104441","name":"大阪医科大学看護専門学校校舎（旧大阪高等医学専門学校別館）","kana":"おおさかいかだいがくかいごせんもんがっこうこうしゃ（きゅうおおさかこうとういがくせんもんがっこうべっかん）","category":"学校","subcategory":"建築物","type_guess":"校舎","type_guess_confidence":"high","period":"昭和前","pref":"大阪府","address":"大阪府高槻市大学町2-7","lat":34.851574,"lng":135.625916,"geo_status":"db","era":"昭和5","year":1930,"year_source":"db","year_min":1930,"year_max":1930,"year_label":null,"structure":"鉄筋コンクリート造3階建、建築面積325㎡","structure_material":"鉄筋コンクリート造3階建","registered":"2003.07.01(平成15.07.01)","register_no":"27 － 0244","desc":"ヴォーリズ建築事務所の設計による医学専門学校の別館。鉄筋コンクリート造３階建で，玄関部にロンバルディア帯，バトルメント状の装飾を施すほか，窓部のオジーアーチや葱花ドームなどイスラム様式を採り入れている。地域の歴史的建築として親しまれている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003451"},{"id":"00002644","register_sub_id":"101","register_pk":"103634","name":"大阪市立大学本館（一号館）","kana":"おおさかいちりつだいがくほんかん（いちごうかん）","category":"学校","subcategory":"建築物","type_guess":"記念館・資料室","type_guess_confidence":"low","period":"昭和前","pref":"大阪府","address":"大阪府大阪市住吉区杉本三丁目４５９－１５他","lat":34.59060561,"lng":135.50504007,"geo_status":"db","era":"昭和9","year":1934,"year_source":"db","year_min":1934,"year_max":1934,"year_label":null,"structure":"鉄筋コンクリート造3階一部地下1階建、建築面積2522㎡、塔屋付","structure_material":"鉄筋コンクリート造3階一部地下1階建","registered":"2002.02.14(平成14.02.14)","register_no":"27 － 0165","desc":"大阪商科大学本館として建設された鉄筋コンクリート造の建物。南面し，東西に長く伸ばした翼部，背面に講堂を接続し，正面中央玄関上部に塔を高く聳える。全体にクラシックな構成だが，簡略化した柱型や庇による水平線の強調などによる新たな造形志向が顕著。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002644"},{"id":"00004998","register_sub_id":"101","register_pk":"105988","name":"大阪歯科大学牧野学舎本館","kana":"おおさかしかだいがくまきのがくしゃほんかん","category":"学校","subcategory":"建築物","type_guess":"記念館・資料室","type_guess_confidence":"low","period":"昭和前","pref":"大阪府","address":"大阪府枚方市牧野本町1-4-4","lat":34.84073596,"lng":135.66966935,"geo_status":"db","era":"昭和4／昭和37増築","year":1929,"year_source":"db","year_min":1929,"year_max":1929,"year_label":null,"structure":"鉄筋コンクリート造3階建、建築面積1049㎡","structure_material":"鉄筋コンクリート造3階建","registered":"2005.11.10(平成17.11.10)","register_no":"27 － 0330","desc":"鉄筋コンクリート造３階建で，正面中央に塔を立ち上げ，左右に翼部を張り出したほぼ左右対称の建築構成をとる。幾条にも廻した水平帯と西面２階３階の曲面をもつ出窓の表現派風造形意匠に特徴。設計は大林組の今林彦太郎で，施工も大林組。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004998"},{"id":"00011531","register_sub_id":"101","register_pk":"210481","name":"大阪女学院ヘールチャペル","kana":"おおさかじょがくいんへーるちゃぺる","category":"学校","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和中","pref":"大阪府","address":"大阪府大阪市中央区玉造二丁目26-15","lat":34.67691611,"lng":135.527215,"geo_status":"db","era":"昭和26年／昭和59年増築、平成13年改修","year":1951,"year_source":"db","year_min":1951,"year_max":1951,"year_label":null,"structure":"鉄骨鉄筋コンクリート造平屋一部3階建、建築面積727㎡","structure_material":"鉄骨鉄筋コンクリート造平屋一部3階建","registered":"2017.05.02(平成29.05.02)","register_no":"27-0664","desc":"大阪城公園の南方に校地を構える。ヴォーリズ建築事務所の設計による鉄骨鉄筋コンクリート造の礼拝堂と講堂を兼ねた施設。オーディトリアムでは天井を高くして広がりのある上質な空間を実現する。外観は装飾要素を抑えたモダニズム意匠となる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011531"},{"id":"00004147","register_sub_id":"101","register_pk":"105137","name":"大阪大学共通教育本館","kana":"おおさかだいがくきょうつうきょういくほんかん","category":"学校","subcategory":"建築物","type_guess":"記念館・資料室","type_guess_confidence":"low","period":"昭和前","pref":"大阪府","address":"大阪府豊中市待兼山町1-1","lat":34.806614,"lng":135.452484,"geo_status":"db","era":"昭和4","year":1929,"year_source":"db","year_min":1929,"year_max":1929,"year_label":null,"structure":"鉄筋コンクリート造4階建、建築面積1276㎡、塔屋付","structure_material":"鉄筋コンクリート造4階建","registered":"2004.06.09(平成16.06.09)","register_no":"27 － 0290","desc":"旧制浪速高等学校校舎として建設。鉄筋コンクリート造で，南面する４階建，塔屋付の南棟の北面西端に，３階建の北棟が続きＬ字形平面をつくる。平明ながら尖頭形の窓や塔屋部等のネオゴシック風の外観意匠に特徴がある。大阪府営繕課の設計で，大林組の施工。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004147"},{"id":"00007513","register_sub_id":"101","register_pk":"108495","name":"大阪府立桜塚高等学校塀（旧豊中高等女学校周塀）","kana":"おおさかふりつさくらづかこうとうがっこうへい（きゅうとよなかこうとうじょがっこうしゅうべい）","category":"学校","subcategory":"その他工作物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"大阪府","address":"大阪府豊中市中桜塚4-1-1","lat":34.78359025,"lng":135.47168872,"geo_status":"db","era":"昭和13","year":1938,"year_source":"db","year_min":1938,"year_max":1938,"year_label":null,"structure":"煉瓦造及び鉄筋コンクリート造、総延長130m","structure_material":"煉瓦造及び鉄筋コンクリート造","registered":"2009.01.08(平成21.01.08)","register_no":"27 － 0522","desc":"校地の北辺及び南東隅に建ち、総延長１３０ｍである。高さ１．１ｍ煉瓦造の柱の各間に鉄筋コンクリート製のパネルを設け、パネルには一間おきに桜花を象った透かし孔を３ヶ所開ける。高さも抑えめで、もと女学校らしい穏やかで気品のある佇まいを見せる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007513"},{"id":"00004795","register_sub_id":"101","register_pk":"105785","name":"大阪府立四條畷高等学校本館","kana":"おおさかふりつしじょうなわてこうとうがっこうほんかん","category":"学校","subcategory":"建築物","type_guess":"記念館・資料室","type_guess_confidence":"low","period":"昭和前","pref":"大阪府","address":"大阪府四條畷市雁屋北町1-1","lat":34.735458,"lng":135.636597,"geo_status":"db","era":"昭和9～11","year":1934,"year_source":"converted","year_min":1934,"year_max":1934,"year_label":null,"structure":"鉄筋コンクリート造3階建、建築面積1581㎡","structure_material":"鉄筋コンクリート造3階建","registered":"2005.07.12(平成17.07.12)","register_no":"27 － 0328","desc":"大阪府営繕課の設計により，昭和９年から１１年にかけて２期に分けて建設。柱形を露わにした整然とした立面，玄関廻りの庇，円柱や丸窓の意匠，室内廊下のアーチ状梁形などに特色がある。「質実堅牢」を旨としたモダニズム色の強い昭和初期学校建築の好事例。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004795"},{"id":"00001529","register_sub_id":"101","register_pk":"102519","name":"大阪府立三国丘高等学校同窓会館（旧三丘会館）","kana":"おおさかふりつみくにがおかこうとうがっこうどうそうかいかん（きゅうさんきゅうかいかん）","category":"学校","subcategory":"建築物","type_guess":"記念館・資料室","type_guess_confidence":"low","period":"昭和前","pref":"大阪府","address":"大阪府堺市堺区南三国ヶ丘町2-2-36","lat":34.573837,"lng":135.488144,"geo_status":"db","era":"昭和9","year":1934,"year_source":"db","year_min":1934,"year_max":1934,"year_label":null,"structure":"鉄筋コンクリート2階建、建築面積354㎡","structure_material":"鉄筋コンクリート2階建","registered":"2000.02.15(平成12.02.15)","register_no":"27 － 0088","desc":"旧制堺中学校の図書館機能を有する記念館として建設。設計は，同校の１期生で，初代鉄道省建築課長の久野節。玄関庇を支持する先すぼまりの円柱，階段室塔屋の縦長の連続窓と庇の構成などモダニズム色の強い造形に特色が認められる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001529"},{"id":"00005966","register_sub_id":"101","register_pk":"106951","name":"河内長野市立武道館（旧長野町尋常高等小学校講堂）","kana":"かわちながのしりつぶどうかん（きゅうながのちょうじんじょうこうとうしょうがっこうこうどう）","category":"学校","subcategory":"建築物","type_guess":"講堂","type_guess_confidence":"high","period":"昭和前","pref":"大阪府","address":"大阪府河内長野市西代町904-1","lat":34.453053,"lng":135.564728,"geo_status":"db","era":"昭和2／昭和52改修","year":1927,"year_source":"db","year_min":1927,"year_max":1927,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積491㎡","structure_material":"木造平屋建","registered":"2006.11.29(平成18.11.29)","register_no":"27 － 0401","desc":"間口８間，奥行１５間，木造平屋建，銅板葺で，背面に奥行２間の瓦葺下屋が付く。屋根は半切妻で，外壁は上壁をハーフティンバー風とし，腰壁を板張（鉄板仮張）とする。正面に間口４間，奥行２間，切妻造の玄関を設け，安定感のある洋風の意匠とする。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005966"},{"id":"00000358","register_sub_id":"101","register_pk":"101348","name":"旧岸和田村尋常小学校校舎","kana":"きゅうきしわだむらじんじょうしょうがっこうこうしゃ","category":"学校","subcategory":"建築物","type_guess":"校舎","type_guess_confidence":"high","period":"明治","pref":"大阪府","address":"大阪府岸和田市西之内町８","lat":34.46978643,"lng":135.395241,"geo_status":"db","era":"明治36","year":1903,"year_source":"db","year_min":1903,"year_max":1903,"year_label":null,"structure":"木造平屋建，瓦葺，建築面積185㎡","structure_material":"木造平屋建","registered":"1997.11.05(平成9.11.05)","register_no":"27 － 0025","desc":"木造平屋建，瓦葺の校舎。中央部の玄関から左右に教室をのばした左右対称の形態や教室に採光するための大きな窓を持つ外観の意匠に特徴がある。明治期に建設された小規模な学校建築の好例で，現在は岸和田市中央公園に移築保存されている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000358"},{"id":"00014192","register_sub_id":"101","register_pk":"508822","name":"旧京都大学高槻農場加工室","kana":"きゅうきょうとだいがくたかつきのうじょうかこうしつ","category":"学校","subcategory":"建築物","type_guess":"校舎","type_guess_confidence":"low","period":"昭和前","pref":"大阪府","address":"大阪府高槻市八丁畷町190-1他","lat":34.85543611,"lng":135.63064722,"geo_status":"db","era":"昭和8年／同10年増築・令和2年改修","year":1933,"year_source":"db","year_min":1933,"year_max":1933,"year_label":null,"structure":"木造平屋建、鉄板葺、建築面積303㎡","structure_material":"木造平屋建","registered":"2022.02.17(令和4.02.17)","register_no":"27-0842","desc":"大学農場本館の西側に建つ。平屋建切妻造金属板葺。外壁は漆喰仕上で腰下はモルタル仕上。南・東・北棟からなるコ字形平面で、内部は一部に床を張り打上天井、その他は土間で小屋組のキングポスト・トラスを現す。コテージ風意匠で縦長窓が並ぶ農場施設。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014192"},{"id":"00014193","register_sub_id":"101","register_pk":"508823","name":"旧京都大学高槻農場農具舎","kana":"きゅうきょうとだいがくたかつきのうじょうのうきぐこ","category":"学校","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"大阪府","address":"大阪府高槻市八丁畷町190-1他","lat":34.8557,"lng":135.63085556,"geo_status":"db","era":"昭和5年／令和2年改修","year":1930,"year_source":"db","year_min":1930,"year_max":1930,"year_label":null,"structure":"木造平屋建、鉄板葺、建築面積112㎡","structure_material":"木造平屋建","registered":"2022.02.17(令和4.02.17)","register_no":"27-0843","desc":"大学農場本館の背面側に建つ。平屋建、切妻造金属板葺。南北棟で東側に庇を延ばし出入口とする。壁は漆喰仕上、腰下モルタル洗出し。妻壁上部に円形通気口を設置。内部は土間で、南半に根太天井を張り、北半はトラス組を現す。真壁造で他施設と意匠を変える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014193"},{"id":"00014191","register_sub_id":"101","register_pk":"508821","name":"旧京都大学高槻農場別館","kana":"きゅうきょうとだいがくたかつきのうじょうべっかん","category":"学校","subcategory":"建築物","type_guess":"記念館・資料室","type_guess_confidence":"low","period":"昭和前","pref":"大阪府","address":"大阪府高槻市八丁畷町190-1他","lat":34.85540278,"lng":135.63132222,"geo_status":"db","era":"昭和7年／令和2年改修","year":1932,"year_source":"db","year_min":1932,"year_max":1932,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積162㎡","structure_material":"木造平屋建","registered":"2022.02.17(令和4.02.17)","register_no":"27-0841","desc":"大学農場本館の東側に建つ。平屋建、切妻造赤色桟瓦葺、東西妻面に出入口を設ける。アーチ窓と矩形窓を併置し、繰型付方杖を付し、コテージ風意匠を示す。内部は中廊下に北側３室、南側２室を並べ、天井や金物に幾何学調意匠を凝らす。瀟洒な農場施設。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014191"},{"id":"00014190","register_sub_id":"101","register_pk":"508820","name":"旧京都大学高槻農場本館及び付属屋","kana":"きゅうきょうとだいがくたかつきのうじょうほんかんおよびふぞくや","category":"学校","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"大阪府","address":"大阪府高槻市八丁畷町190-1他","lat":34.85541389,"lng":135.63096667,"geo_status":"db","era":"昭和5年／令和2年改修","year":1930,"year_source":"db","year_min":1930,"year_max":1930,"year_label":null,"structure":"木造2階建一部平屋建、瓦葺、建築面積391㎡","structure_material":"木造2階建一部平屋建","registered":"2022.02.17(令和4.02.17)","register_no":"27-0840","desc":"大学農場の旧施設群の本館で安満遺跡に位置する。切妻造赤色桟瓦葺。中央部を２階建とし、正面軒を緩勾配の切妻状に切上げ、玄関にパーゴラ状の庇を付す。背面に平屋建附属屋が建つ。外観は二階に柱形と縦長アーチ窓を配し、スパニッシュを基調とする。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014190"},{"id":"00009654","register_sub_id":"101","register_pk":"194650","name":"行信教校講堂棟","kana":"ぎょうしんきょうこうこうどうとう","category":"学校","subcategory":"建築物","type_guess":"講堂","type_guess_confidence":"high","period":"昭和前","pref":"大阪府","address":"大阪府高槻市東五百住町3-805他","lat":34.8373515,"lng":135.59959435,"geo_status":"db","era":"昭和6／平成5・平成10改修","year":1931,"year_source":"db","year_min":1931,"year_max":1931,"year_label":null,"structure":"木造2階建、瓦葺、建築面積285㎡","structure_material":"木造2階建","registered":"2013.06.21(平成25.06.21)","register_no":"27 － 0569","desc":"敷地中央に東西棟で建ち、木造二階建、寄棟造桟瓦葺である。左右対称平面で、北面中央に唐破風玄関を構える。一階は中廊下式で八畳居室を並べ、生徒室や事務室などとする。二階は畳敷の広い講堂で、西奥に仏壇を構える。類例希な僧侶養成専門学校の遺構。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009654"},{"id":"00009655","register_sub_id":"101","register_pk":"194651","name":"行信教校専精会館","kana":"ぎょうしんきょうこうせんしょうかいかん","category":"学校","subcategory":"建築物","type_guess":"記念館・資料室","type_guess_confidence":"low","period":"昭和前","pref":"大阪府","address":"大阪府高槻市東五百住町3-805","lat":34.83716828,"lng":135.59987751,"geo_status":"db","era":"昭和6／平成5・平成10改修","year":1931,"year_source":"db","year_min":1931,"year_max":1931,"year_label":null,"structure":"木造2階建、瓦葺、建築面積100㎡","structure_material":"木造2階建","registered":"2013.06.21(平成25.06.21)","register_no":"27 － 0570","desc":"敷地南東に建ち、木造二階建、宝形造桟瓦葺で、東西面の戸口に半切妻の庇を付ける。略正方形平面で、一階は中廊下の両側に四室を配する。二階は三六畳の講義室で格天井を張り、北面中央に仏壇を備える。講堂棟とともに昭和初期の僧侶養成学校の様相を伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009655"},{"id":"00005480","register_sub_id":"101","register_pk":"106468","name":"樟蔭学園記念館","kana":"しょういんがくえんきねんかん","category":"学校","subcategory":"建築物","type_guess":"記念館・資料室","type_guess_confidence":"high","period":"昭和前","pref":"大阪府","address":"大阪府東大阪市菱屋西4-258-1","lat":34.66320529,"lng":135.57794648,"geo_status":"db","era":"昭和2","year":1927,"year_source":"db","year_min":1927,"year_max":1927,"year_label":null,"structure":"木造2階建、鋼板葺、建築面積449㎡","structure_material":"木造2階建","registered":"2006.03.27(平成18.03.27)","register_no":"27 － 0367","desc":"木造２階建，寄棟造，鋼板葺で，外壁は目地切のモルタル仕上げとする。南面西寄りに玄関をわずかに突出させ，角塔と駒形の破風で飾る。南東隅部も角塔に扱い，２階窓は３連アーチとする。当初は１階が図書室と書庫，２階が大講義室と会議室兼来賓室であった。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005480"},{"id":"00006282","register_sub_id":"101","register_pk":"107266","name":"樟蔭学園樟古館旧試食室","kana":"しょういんがくえんしょうこかんきゅうししょくしつ","category":"学校","subcategory":"建築物","type_guess":"校舎","type_guess_confidence":"low","period":"大正","pref":"大阪府","address":"大阪府東大阪市菱屋西4-258-1","lat":34.66275642,"lng":135.57700725,"geo_status":"db","era":"大正7／昭和44曳家","year":1918,"year_source":"db","year_min":1918,"year_max":1918,"year_label":null,"structure":"木造平屋建、鉄板葺、建築面積23㎡","structure_material":"木造平屋建","registered":"2007.07.31(平成19.07.31)","register_no":"27 － 0428","desc":"家事実習室として建設。旧洗濯室の南に並ぶ木造平屋建である。方２間半の妻入で，半切妻屋根をかけるが，軒反りをつけてオランダ風につくる。外壁は構造材を現した簡素なスティックスタイル。ポーチの切妻屋根と南面の出窓が小建築にアクセントを与えている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006282"},{"id":"00006281","register_sub_id":"101","register_pk":"107265","name":"樟蔭学園樟古館旧洗濯室","kana":"しょういんがくえんしょうこかんきゅうせんたくしつ","category":"学校","subcategory":"建築物","type_guess":"校舎","type_guess_confidence":"low","period":"大正","pref":"大阪府","address":"大阪府東大阪市菱屋西4-258-1","lat":34.66282365,"lng":135.57698973,"geo_status":"db","era":"大正7／昭和44曳家","year":1918,"year_source":"db","year_min":1918,"year_max":1918,"year_label":null,"structure":"木造平屋建、鉄板葺、建築面積123㎡","structure_material":"木造平屋建","registered":"2007.07.31(平成19.07.31)","register_no":"27 － 0427","desc":"家事実習室として建設。東を正面に建つ木造平屋建で，桁行７間，梁間５間の矩形平面であるが，寄棟屋根に半切妻を組合せて屋根形態に変化を付けている。外壁は構造材を現した簡素なスティックスタイルで，欄間付の引違窓と腰の縦板張がアクセントとなる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006281"},{"id":"00000141","register_sub_id":"101","register_pk":"101131","name":"聖母女学院校舎","kana":"せいぼじょがくいんこうしゃ","category":"学校","subcategory":"建築物","type_guess":"校舎","type_guess_confidence":"high","period":"昭和前","pref":"大阪府","address":"大阪府寝屋川市美井町1011-6","lat":34.78122863,"lng":135.63620655,"geo_status":"db","era":"昭和7","year":1932,"year_source":"db","year_min":1932,"year_max":1932,"year_label":null,"structure":"鉄筋コンクリート造地上2階地下1階建，建築面積3233㎡","structure_material":"鉄筋コンクリート造地上2階地下1階建","registered":"1997.05.07(平成9.05.07)","register_no":"27 － 0017","desc":"大正12年に創立された名門女学校の校舎で，均等な日照や通風のとれるフィンガー型の平面配置を採用した初期の例である。設計はアントニン・レーモンド。スパニッシュ風のコロネードとコンポジット式の柱頭を持つ正面入り口が意匠上の特徴である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000141"},{"id":"00001840","register_sub_id":"101","register_pk":"102830","name":"谷岡記念館","kana":"たにおかきねんかん","category":"学校","subcategory":"建築物","type_guess":"記念館・資料室","type_guess_confidence":"high","period":"昭和前","pref":"大阪府","address":"大阪府東大阪市御厨栄町4-1-10","lat":34.66684231,"lng":135.58416555,"geo_status":"db","era":"昭和10","year":1935,"year_source":"db","year_min":1935,"year_max":1935,"year_label":null,"structure":"鉄筋コンクリート造4階建、建築面積807㎡、塔屋付","structure_material":"鉄筋コンクリート造4階建","registered":"2000.09.26(平成12.09.26)","register_no":"27 － 0105","desc":"昭和９年室戸台風後に復興された城東商業学校（現大阪商業大学）校舎で，現在は資料の展示施設として活用。南北に長いＲＣ造４階建で，正面に時計台，内部に３・４階吹抜けの講堂を設ける。平滑な壁面とアーチや丸窓などの意匠に時代の特色がよく表れている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001840"},{"id":"00002562","register_sub_id":"101","register_pk":"103552","name":"富田林市立川西小学校教育歴史資料室（旧川西尋常小学校）","kana":"とんだばやしりつたちかわにししょうがっこうきょういくれきししりょうしつ（きゅうかわにしじんじょうしょうがっこう）","category":"学校","subcategory":"建築物","type_guess":"記念館・資料室","type_guess_confidence":"high","period":"昭和前","pref":"大阪府","address":"大阪府富田林市新家1-3-1","lat":34.49308,"lng":135.588364,"geo_status":"db","era":"昭和10","year":1935,"year_source":"db","year_min":1935,"year_max":1935,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積161㎡","structure_material":"木造平屋建","registered":"2001.11.20(平成13.11.20)","register_no":"27 － 0164","desc":"昭和９年の室戸台風後の復興校舎で，玄関・職員室と高等科教室１室を残す。教室の天井を船底天井とし，室内天井下に挟み方杖を見せるなどの構造的な特徴のほか，東妻面に玄関ポーチを配して半切妻の２重構成とするなどの意匠的な見所もあわせもつ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002562"},{"id":"00006268","register_sub_id":"101","register_pk":"107252","name":"尼崎市役所開明庁舎（旧開明尋常小学校校舎）","kana":"あまがさきしやくしょかいめいちょうしゃ（きゅうかいめいじんじょうしょうがっこうこうしゃ）","category":"学校","subcategory":"建築物","type_guess":"校舎","type_guess_confidence":"high","period":"昭和前","pref":"兵庫県","address":"兵庫県尼崎市開明町2-1-1","lat":34.71720031,"lng":135.41592847,"geo_status":"db","era":"昭和12／平成17改修","year":1937,"year_source":"db","year_min":1937,"year_max":1937,"year_label":null,"structure":"鉄筋コンクリート造3階一部平屋建、建築面積1253㎡、塔屋付","structure_material":"鉄筋コンクリート造3階一部平屋建","registered":"2007.07.31(平成19.07.31)","register_no":"28 － 0273","desc":"ＲＣ造３階建で，敷地の東側と北側にＬ字形平面で建つ。東棟南端から平屋を延ばし，入隅に設けた四半円平面の玄関ホールとその上の半円筒形階段室がアクセントとなる。外壁は矩形窓を整然と配し，窓庇で水平線を強調している。昭和初期のＲＣ造学校建築の好例。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006268"},{"id":"00001130","register_sub_id":"101","register_pk":"102120","name":"小林聖心女子学院本館","kana":"おばやしせいしんじょしがくいんほんかん","category":"学校","subcategory":"建築物","type_guess":"記念館・資料室","type_guess_confidence":"low","period":"昭和前","pref":"兵庫県","address":"兵庫県宝塚市塔の町125","lat":34.78677085,"lng":135.35005776,"geo_status":"db","era":"昭和2","year":1927,"year_source":"db","year_min":1927,"year_max":1927,"year_label":null,"structure":"鉄筋コンクリート造３階建，建築面積1777㎡","structure_material":"鉄筋コンクリート造３階建","registered":"1999.06.07(平成11.06.07)","register_no":"28 － 0046","desc":"レーモンドによる鉄筋コンクリート造学校建築。日の字型プランの２階建及び３階建校舎に教室、図書室、講堂、礼拝堂、寄宿舎などを巧みに納める。レーモンド＆サイクス建築事務所時代の作品で、隅部に曲面を多用するなどライト式からの脱却の跡が窺える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001130"},{"id":"00007787","register_sub_id":"101","register_pk":"108768","name":"関西学院大学時計台（旧図書館）","kana":"かんせいがくいんだいがくとけいだい（きゅうとしょかん）","category":"学校","subcategory":"建築物","type_guess":"図書館","type_guess_confidence":"high","period":"昭和前","pref":"兵庫県","address":"兵庫県西宮市上ヶ原一番町2-10","lat":34.76969619,"lng":135.34697065,"geo_status":"db","era":"昭和4／昭和30増築・昭和48・平成7改修","year":1929,"year_source":"db","year_min":1929,"year_max":1929,"year_label":null,"structure":"鉄筋コンクリート造2階一部地下1階建、瓦葺、建築面積477㎡、塔屋付","structure_material":"鉄筋コンクリート造2階一部地下1階建","registered":"2009.08.07(平成21.08.07)","register_no":"28-0413","desc":"甲山を背にキャンパス中央に建つ。南北４７ｍに及ぶ左右対称のＲＣ造２階建で、中央に塔屋とポーチ、両端に切妻屋根を付け、アーチの連窓を配する。赤色の瓦、クリーム色のスタッコ塗壁の対比が鮮やかなスパニッシュ・ミッション・スタイルの学校建築。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007787"},{"id":"00014880","register_sub_id":"101","register_pk":"519140","name":"旧尼崎市立高等女学校校舎(尼崎市立歴史博物館・尼崎市立成良中学校琴城分校)","kana":"きゅうあまがさきいちりつこうとうじょがっこうこうしゃ（あまがさきいちりつれきしはくぶつかん・あまがさきいちりつせいりょうちゅうがっこうきんじょうぶんこう）","category":"学校","subcategory":"建築物","type_guess":"校舎","type_guess_confidence":"high","period":"昭和前","pref":"兵庫県","address":"兵庫県尼崎市南城内10-2","lat":34.71479167,"lng":135.42091944,"geo_status":"db","era":"昭和13年／昭和41年・令和2年改修","year":1938,"year_source":"db","year_min":1938,"year_max":1938,"year_label":null,"structure":"鉄筋コンクリート造3階建、建築面積2，106㎡","structure_material":"鉄筋コンクリート造3階建","registered":"2024.03.06(令和6.03.06)","register_no":"28 - 0794","desc":"尼崎城本丸跡にある旧女学校校舎。鉄筋コンクリート造3階建でロの字の平面。正面は横長窓を並べて装飾を抑えつつ、中央部を前方にやや突出させ、片持ちの車寄庇を太い円柱で支えるなど外観を特徴づける。市内で数少ない戦前期の校舎で城内地区の象徴的存在。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014880"},{"id":"00014881","register_sub_id":"101","register_pk":"519141","name":"旧尼崎市立高等女学校校門","kana":"きゅうあまがさきいちりつこうとうじょがっこうこうもんもんちゅう","category":"学校","subcategory":"その他工作物","type_guess":"正門","type_guess_confidence":"high","period":"昭和前","pref":"兵庫県","address":"兵庫県尼崎市南城内10-2","lat":34.71523889,"lng":135.42101111,"geo_status":"db","era":"昭和2年／令和2年改修","year":1927,"year_source":"db","year_min":1927,"year_max":1927,"year_label":null,"structure":"鉄筋コンクリート造、間口4.0m、東脇柱付","structure_material":"鉄筋コンクリート造","registered":"2024.03.06(令和6.03.06)","register_no":"28 - 0795","desc":"校舎の北面に位置する校門。鉄筋コンクリート造、間口４メートルで、親柱を二本立て、東脇柱との間は脇門、西脇柱との間に袖壁を付す。全体に表面を粗く仕上げた石貼とし、親柱上には薄い宝形風屋根を載せる。重厚な外観が城内地区に建つ学校の風格を示す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014881"},{"id":"00012764","register_sub_id":"101","register_pk":"367667","name":"甲南女子大学管理棟","kana":"こうなんじょしだいがくかんりとう","category":"学校","subcategory":"建築物","type_guess":"校舎","type_guess_confidence":"low","period":"昭和中","pref":"兵庫県","address":"兵庫県神戸市東灘区森北町六丁目2-3","lat":34.703475,"lng":135.26556944,"geo_status":"db","era":"昭和39年","year":1964,"year_source":"db","year_min":1964,"year_max":1964,"year_label":null,"structure":"鉄筋コンクリート造地上3階地下1階建、建築面積867㎡","structure_material":"鉄筋コンクリート造地上3階地下1階建","registered":"2019.03.29(平成31.03.29)","register_no":"28 － 699","desc":"六甲山地南麓のキャンパス中央に南面して建つ。鉄筋コンクリート造3階建、75メートルに及ぶ長大な正面の1・2階壁面を後退して独立柱を並べ、柱にテーパーをつけて細くみせるなど重量感を抑えたデザインでまとめる。大学の顔として親しまれる象徴的施設。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012764"},{"id":"00012765","register_sub_id":"101","register_pk":"367668","name":"甲南女子大学３号館","kana":"こうなんじょしだいがくさんごうかん","category":"学校","subcategory":"建築物","type_guess":"記念館・資料室","type_guess_confidence":"low","period":"昭和中","pref":"兵庫県","address":"兵庫県神戸市東灘区森北町六丁目2-3","lat":34.703475,"lng":135.26556944,"geo_status":"db","era":"昭和39年","year":1964,"year_source":"db","year_min":1964,"year_max":1964,"year_label":null,"structure":"鉄筋コンクリート造地上3階地下1階建、建築面積718㎡","structure_material":"鉄筋コンクリート造地上3階地下1階建","registered":"2019.03.29(平成31.03.29)","register_no":"28 － 700","desc":"管理棟の北側に並行して建つ鉄筋コンクリート造3階建の校舎。窓上に設けた長方形枠の高窓など管理棟と共通の造形表現を基調としつつ、片廊下式の均質な教室配置にあわせて変化を加えたデザインで全体をまとめる。管理棟とともにキャンパスの核をなしている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012765"},{"id":"00012766","register_sub_id":"101","register_pk":"367669","name":"甲南女子大学渡廊下","kana":"こうなんじょしだいがくわたりろうか","category":"学校","subcategory":"その他工作物","type_guess":"その他","type_guess_confidence":"low","period":"昭和中","pref":"兵庫県","address":"兵庫県神戸市東灘区森北町六丁目2-3","lat":34.703475,"lng":135.26556944,"geo_status":"db","era":"昭和39年／昭和54年改修","year":1964,"year_source":"db","year_min":1964,"year_max":1964,"year_label":null,"structure":"鉄筋コンクリート造、金属板葺、面積470㎡","structure_material":"鉄筋コンクリート造","registered":"2019.03.29(平成31.03.29)","register_no":"28 － 701","desc":"キャンパス中央部を南北に貫通し、管理棟と３号館を接続する鉄筋コンクリート製の階段。中央部を芝生敷として両端に幅2メートルの屋根付の階段を通す。最下部は幅15メートルの大階段とする。管理棟、３号館と一体でキャンパスの基幹部分を構成している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012766"},{"id":"00013287","register_sub_id":"101","register_pk":"366276","name":"甲南女子中学校・高等学校管理棟","kana":"こうなんじょしちゅうがっこう・こうとうがっこうかんりとう","category":"学校","subcategory":"建築物","type_guess":"校舎","type_guess_confidence":"low","period":"昭和後","pref":"兵庫県","address":"兵庫県神戸市東灘区森北町5丁目4-1他","lat":34.73501389,"lng":135.29181667,"geo_status":"db","era":"昭和43年","year":1968,"year_source":"db","year_min":1968,"year_max":1968,"year_label":null,"structure":"鉄筋コンクリート造地上4階地下1階建、建築面積1703㎡","structure_material":"鉄筋コンクリート造地上4階地下1階建","registered":"2020.04.03(令和2.04.03)","register_no":"28 － 0731","desc":"甲南女子大学東隣のキャンパス中央に建つ。鉄筋コンクリート造二階建、一階中央部をピロティとして車路を通し、車路の東を主玄関とする。玄関から特別棟へは、回廊をつくり教職員と生徒の動線を巧みに分離する。村野藤吾によるキャンパス計画の中心をなす。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013287"},{"id":"00013291","register_sub_id":"101","register_pk":"366280","name":"甲南女子中学校・高等学校講堂","kana":"こうなんじょしちゅうがっこう・こうとうがっこうこうどう","category":"学校","subcategory":"建築物","type_guess":"講堂","type_guess_confidence":"high","period":"昭和後","pref":"兵庫県","address":"兵庫県神戸市東灘区森北町5丁目4-1他","lat":34.73501389,"lng":135.29226667,"geo_status":"db","era":"昭和43年","year":1968,"year_source":"db","year_min":1968,"year_max":1968,"year_label":null,"structure":"鉄筋コンクリート造及び鉄骨造地上2階地下1階建、石綿セメント板葺、建築面積1010㎡","structure_material":"鉄筋コンクリート造及び鉄骨造地上2階地下1階建","registered":"2020.04.03(令和2.04.03)","register_no":"28 － 0735","desc":"管理棟の南側斜面に建つ講堂。六角形平面の北を舞台とし南を台形に突出させて座席とする。平面に対応して屋根を小割にし、その軒を薄くして軽快感を強調している。室内は天井や壁の出隅に曲線を多用する有機的な設えとし、村野藤吾の造形的特徴を伺わせる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013291"},{"id":"00014273","register_sub_id":"101","register_pk":"509663","name":"甲南女子中学校・高等学校茶道教室","kana":"こうなんじょしちゅうがっこう・こうとうがっこうさどうきょうしつ","category":"学校","subcategory":"建築物","type_guess":"校舎","type_guess_confidence":"high","period":"昭和後","pref":"兵庫県","address":"兵庫県神戸市東灘区森北町五丁目4-1他","lat":34.73473333,"lng":135.29255833,"geo_status":"db","era":"昭和46年","year":1971,"year_source":"db","year_min":1971,"year_max":1971,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積70㎡","structure_material":"木造平屋建","registered":"2022.06.29(令和4.06.29)","register_no":"28 - 0778","desc":"校地東の一角に位置する村野藤吾設計の茶室。平屋建寄棟造桟瓦葺で、銅板葺土庇を南西に付す。内部は玄関、六畳と八畳の座敷を東西に並べ、玄関北に水屋と手洗を突出させる。座敷意匠は平明でガラス戸を採り入れ、モダニズムに通じる和風意匠をよく示す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014273"},{"id":"00013292","register_sub_id":"101","register_pk":"366281","name":"甲南女子中学校・高等学校守衛室","kana":"こうなんじょしちゅうがっこう・こうとうがっこうしゅえいしつ","category":"学校","subcategory":"建築物","type_guess":"正門","type_guess_confidence":"high","period":"昭和後","pref":"兵庫県","address":"兵庫県神戸市東灘区森北町5丁目4-1他","lat":34.73459722,"lng":135.29250556,"geo_status":"db","era":"昭和43年","year":1968,"year_source":"db","year_min":1968,"year_max":1968,"year_label":null,"structure":"コンクリートブロック造及び木造平屋建、石綿セメント板葺、建築面積29㎡","structure_material":"コンクリートブロック造及び木造平屋建","registered":"2020.04.03(令和2.04.03)","register_no":"28 － 0736","desc":"キャンパス南側の正門脇に設けられた守衛室。平屋建で、コンクリートブロック壁に木造の宝形を組合わせた屋根を架ける。矩折れに取付く出窓や、煉瓦を二段帯状に積込んだブロック積の壁体など、小規模ながらも細部まで意匠的配慮が行き届いた造形である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013292"},{"id":"00013289","register_sub_id":"101","register_pk":"366278","name":"甲南女子中学校・高等学校体育館","kana":"こうなんじょしちゅうがっこう・こうとうがっこうたいいくかん","category":"学校","subcategory":"建築物","type_guess":"体育館","type_guess_confidence":"high","period":"昭和後","pref":"兵庫県","address":"兵庫県神戸市東灘区森北町5丁目4-1他","lat":34.73487222,"lng":135.29106667,"geo_status":"db","era":"昭和43年","year":1968,"year_source":"db","year_min":1968,"year_max":1968,"year_label":null,"structure":"鉄骨造2階建、金属板葺、建築面積1080㎡","structure_material":"鉄骨造2階建","registered":"2020.04.03(令和2.04.03)","register_no":"28 － 0733","desc":"管理棟の西端北側に建つ体育館。鉄骨造二階建で、一階は中廊下で食堂、卓球場を配し、二階は一室とする。矩形平面の四隅に二本ずつ対をなす鋼管柱を八本立て、大梁を対角に架けて47メートルの大スパンを確保し、軽快な架構を構成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013289"},{"id":"00013290","register_sub_id":"101","register_pk":"366279","name":"甲南女子中学校・高等学校体育研究室","kana":"こうなんじょしちゅうがっこう・こうとうがっこうたいいくけんきゅうしつ","category":"学校","subcategory":"建築物","type_guess":"校舎","type_guess_confidence":"high","period":"昭和後","pref":"兵庫県","address":"兵庫県神戸市東灘区森北町5丁目4-1他","lat":34.73463611,"lng":135.2912,"geo_status":"db","era":"昭和43年","year":1968,"year_source":"db","year_min":1968,"year_max":1968,"year_label":null,"structure":"鉄骨造2階建、金属板葺、建築面積40㎡","structure_material":"鉄骨造2階建","registered":"2020.04.03(令和2.04.03)","register_no":"28 － 0734","desc":"体育館の南西隅に接続する鉄骨造二階建の建物。一階をピロティとし、二階は凸型の平面とする。ピロティの柱はセメント板で被覆した末広がりの角柱とし、二階の連続窓の上に薄い庇を張出し、細い螺旋階段で昇降する軽快なつくりの建物とする。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013290"},{"id":"00013288","register_sub_id":"101","register_pk":"366277","name":"甲南女子中学校・高等学校特別棟","kana":"こうなんじょしちゅうがっこう・こうとうがっこうとくべつとう","category":"学校","subcategory":"建築物","type_guess":"校舎","type_guess_confidence":"low","period":"昭和後","pref":"兵庫県","address":"兵庫県神戸市東灘区森北町5丁目4-1他","lat":34.73533889,"lng":135.29207778,"geo_status":"db","era":"昭和43年／平成24年改修","year":1968,"year_source":"db","year_min":1968,"year_max":1968,"year_label":null,"structure":"鉄筋コンクリート造4階建、建築面積526㎡","structure_material":"鉄筋コンクリート造4階建","registered":"2020.04.03(令和2.04.03)","register_no":"28 － 0732","desc":"管理棟の東側に接続して建つ鉄筋コンクリート造4階建の校舎。同一形状の窓が並ぶ立面だが、西側の窓は上下で窓の横幅を変えて凸字型にし、中央部に水平庇を突き出し、両端の外階段のバルコニー腰壁は煉瓦積とするなど、立面に変化を付ける。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013288"},{"id":"00014274","register_sub_id":"101","register_pk":"509664","name":"甲南女子中学校・高等学校西門守衛室","kana":"こうなんじょしちゅうがっこう・こうとうがっこうにしもんしゅえいしつ","category":"学校","subcategory":"建築物","type_guess":"正門","type_guess_confidence":"high","period":"昭和後","pref":"兵庫県","address":"兵庫県神戸市東灘区森北町五丁目4-1他","lat":34.73532778,"lng":135.29100833,"geo_status":"db","era":"昭和43年","year":1968,"year_source":"db","year_min":1968,"year_max":1968,"year_label":null,"structure":"コンクリートブロック造及び木造平屋建、スレート葺、建築面積11㎡","structure_material":"コンクリートブロック造及び木造平屋建","registered":"2022.06.29(令和4.06.29)","register_no":"28 - 0779","desc":"北西側の西門脇に位置する村野藤吾設計の守衛室。コンクリートブロック造平屋建で、人造スレート葺宝形屋根を載せる。出入口となる東角では入隅にして独立柱を立て、南角では出窓を矩折れに付すなど、小規模ながらも細部にまで意匠的配慮が行き届いた守衛室。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014274"},{"id":"00003294","register_sub_id":"101","register_pk":"104284","name":"神戸大学兼松記念館","kana":"こうべだいがくかねまつきねんかん","category":"学校","subcategory":"建築物","type_guess":"記念館・資料室","type_guess_confidence":"high","period":"昭和前","pref":"兵庫県","address":"兵庫県神戸市灘区六甲台町2-1","lat":34.72933438,"lng":135.23478058,"geo_status":"db","era":"昭和9","year":1934,"year_source":"db","year_min":1934,"year_max":1934,"year_label":null,"structure":"鉄筋コンクリート造3階建、建築面積1172㎡","structure_material":"鉄筋コンクリート造3階建","registered":"2003.03.18(平成15.03.18)","register_no":"28 － 0119","desc":"ＲＣ造３階建で，両脇から後方に延びる短い翼部は２階建とする。内部は中廊下式とし，研究室等を収める。市松タイル敷の階段ホール，階段手摺上部の鋳物飾など優れた意匠を持つが，外観意匠は簡素にまとめる。文部省営繕の設計になる学校建築の好例である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003294"},{"id":"00003293","register_sub_id":"101","register_pk":"104283","name":"神戸大学講堂","kana":"こうべだいがくこうどう","category":"学校","subcategory":"建築物","type_guess":"講堂","type_guess_confidence":"high","period":"昭和前","pref":"兵庫県","address":"兵庫県神戸市灘区六甲台町2-1","lat":34.728329,"lng":135.233932,"geo_status":"db","era":"昭和10","year":1935,"year_source":"db","year_min":1935,"year_max":1935,"year_label":null,"structure":"鉄筋コンクリート造2階建、建築面積750㎡","structure_material":"鉄筋コンクリート造2階建","registered":"2003.03.18(平成15.03.18)","register_no":"28 － 0118","desc":"スクラッチタイル張，ロンバルディア帯など本館と共通の意匠を持つ。奥に演壇を置き，前面側を２階建として聴衆室を設ける。船舶の舵をあしらった両開入口扉を３カ所並べ，両脇と併せて５連の大アーチをもつ正面外壁が，講堂としての強い正面性を見せている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003293"},{"id":"00003295","register_sub_id":"101","register_pk":"104285","name":"神戸大学人文社会系図書館","kana":"こうべだいがくじんぶんしゃかいけいとしょかん","category":"学校","subcategory":"建築物","type_guess":"図書館","type_guess_confidence":"high","period":"昭和前","pref":"兵庫県","address":"兵庫県神戸市灘区六甲台町2-1","lat":34.72929,"lng":135.234055,"geo_status":"db","era":"昭和8","year":1933,"year_source":"db","year_min":1933,"year_max":1933,"year_label":null,"structure":"鉄筋コンクリート造5階建、建築面積904㎡","structure_material":"鉄筋コンクリート造5階建","registered":"2003.03.18(平成15.03.18)","register_no":"28 － 0120","desc":"ＲＣ造５階建の図書館建築。外観は下層のみ正方形タイルとし，軒にはロンバルディア帯を廻らす。２階大閲覧室はアーチによる大空間とし，正面階段上部のステンドグラスのトップライトなど意匠を凝らす。室内外とも質の高いデザインを誇る学校建築の好例。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003295"},{"id":"00009353","register_sub_id":"101","register_pk":"194146","name":"神戸大学武道場（旧神戸商業大学道場）","kana":"こうべだいがくぶどうじょう（きゅうこうべしょうぎょうだいがくどうじょう）","category":"学校","subcategory":"建築物","type_guess":"体育館","type_guess_confidence":"high","period":"昭和前","pref":"兵庫県","address":"兵庫県神戸市灘区六甲台町2-1","lat":34.73128127,"lng":135.23294358,"geo_status":"db","era":"昭和10年","year":1935,"year_source":"db","year_min":1935,"year_max":1935,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積362㎡","structure_material":"木造平屋建","registered":"2012.08.13(平成24.08.13)","register_no":"28 － 0552","desc":"六甲台キャンパスの北西隅に南面して建つ。入母屋造桟瓦葺、桁行二七・三メートル梁間一二・七メートル、正面中央に車寄を出す。内部は中央に道場、東西に附属間を配し、北面中央に神棚を置く。格天井や鰭付懸魚等を用いた格式ある造りで大学の歴史を伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009353"},{"id":"00003292","register_sub_id":"101","register_pk":"104282","name":"神戸大学本館","kana":"こうべだいがくほんかん","category":"学校","subcategory":"建築物","type_guess":"記念館・資料室","type_guess_confidence":"low","period":"昭和前","pref":"兵庫県","address":"兵庫県神戸市灘区六甲台町2-1","lat":34.728237,"lng":135.234695,"geo_status":"db","era":"昭和7","year":1932,"year_source":"db","year_min":1932,"year_max":1932,"year_label":null,"structure":"鉄筋コンクリート造地上3階地下1階建、建築面積2041㎡","structure_material":"鉄筋コンクリート造地上3階地下1階建","registered":"2003.03.18(平成15.03.18)","register_no":"28 － 0117","desc":"神戸大学の前身の一つである旧神戸商業大学の本館として建てられた。ＲＣ造地上３階地下１階建で，左右対称の正面の背後に両翼を延ばす。外観はスクラッチタイル張で軒にはロンバルディア帯を廻らす。室内外とも重厚な意匠を備える昭和初期の学校建築の好例。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003292"},{"id":"00006880","register_sub_id":"101","register_pk":"107862","name":"神戸文学館（旧関西学院ブランチ・メモリアル・チャペル）","kana":"こうべぶんがくかん（きゅうかんせいがくいんぶらんち・めもりある・ちゃぺる）","category":"学校","subcategory":"建築物","type_guess":"記念館・資料室","type_guess_confidence":"low","period":"明治","pref":"兵庫県","address":"兵庫県神戸市灘区王子町3-1-2","lat":34.709103,"lng":135.213226,"geo_status":"db","era":"明治37／昭和24・平成4改修","year":1904,"year_source":"db","year_min":1904,"year_max":1904,"year_label":null,"structure":"煉瓦造平屋建、瓦葺、建築面積342㎡、塔屋付","structure_material":"煉瓦造平屋建","registered":"2008.03.07(平成20.03.07)","register_no":"28 － 0303","desc":"王子公園の西南隅に建つ。当初は学院の礼拝堂兼講堂として建設、南北棟の礼拝堂とその西面北寄りに付く小集会所、南西隅の塔からなる。妻面は飾石で緩やかな尖頭アーチをつくり、その内に円窓と３連の尖頭アーチ窓を配する。明治期における教会堂の好例である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006880"},{"id":"00014893","register_sub_id":"101","register_pk":"519153","name":"篠山小学校一号棟","kana":"ささやましょうがっこう１ごうとう","category":"学校","subcategory":"建築物","type_guess":"校舎","type_guess_confidence":"low","period":"昭和中","pref":"兵庫県","address":"兵庫県丹波篠山市北新町5","lat":35.07387222,"lng":135.21905,"geo_status":"db","era":"昭和28年／昭和30年増築、平成14年・同26年改修","year":1953,"year_source":"db","year_min":1953,"year_max":1953,"year_label":null,"structure":"木造2階建、瓦葺、建築面積718㎡","structure_material":"木造2階建","registered":"2024.03.06(令和6.03.06)","register_no":"28 - 0807","desc":"篠山城跡内に位置する小学校。一号棟は木造二階建切妻造桟瓦葺。北面中央玄関と西階段から南へ渡廊下が五号棟まで延びる。玄関庇を張出し、東は南面一、二階通しの出窓、防火壁西の増築は横連窓。北側片廊下の南に教室を並べる。戦後復興期の学校建築の好例。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014893"},{"id":"00014894","register_sub_id":"101","register_pk":"519154","name":"篠山小学校二号棟","kana":"ささやましょうがっこう２ごうとう","category":"学校","subcategory":"建築物","type_guess":"校舎","type_guess_confidence":"low","period":"昭和中","pref":"兵庫県","address":"兵庫県丹波篠山市北新町5","lat":35.07364444,"lng":135.21899167,"geo_status":"db","era":"昭和30年／平成11年・同26年改修","year":1955,"year_source":"db","year_min":1955,"year_max":1955,"year_label":null,"structure":"木造2階建、瓦葺、建築面積309㎡","structure_material":"木造2階建","registered":"2024.03.06(令和6.03.06)","register_no":"28 - 0808","desc":"一号棟の南、東西の渡廊下の間に建つ。木造二階建で切妻造桟瓦葺とする。片廊下平面の両端が階段室。一、二階に特別教室を各二室配す。南面は上下階とも横連窓で開口を大きくし、窓間と腰を横板張。北面はモルタル塗である。先に竣工した棟より簡素な意匠。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014894"},{"id":"00014895","register_sub_id":"101","register_pk":"519155","name":"篠山小学校三号棟","kana":"ささやましょうがっこう３ごうとう","category":"学校","subcategory":"建築物","type_guess":"校舎","type_guess_confidence":"low","period":"昭和中","pref":"兵庫県","address":"兵庫県丹波篠山市北新町5","lat":35.07340278,"lng":135.21901944,"geo_status":"db","era":"昭和29年／平成11年・同26年改修","year":1954,"year_source":"db","year_min":1954,"year_max":1954,"year_label":null,"structure":"木造2階建、瓦葺、建築面積352㎡","structure_material":"木造2階建","registered":"2024.03.06(令和6.03.06)","register_no":"28 - 0809","desc":"二号棟の南、東西渡廊下の間に建つ木造二階建切妻造桟瓦葺。西の階段室は片廊下の北に取付く直線階段。東渡廊下上に二階が張出す。南面は横連窓で開口大きく、窓間と腰を横板張。北面は窓を一間毎に開け、モルタル塗仕上。竣工が前後する棟と少し異なる構成。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014895"},{"id":"00014896","register_sub_id":"101","register_pk":"519156","name":"篠山小学校四号棟","kana":"ささやましょうがっこう4ごうとう","category":"学校","subcategory":"建築物","type_guess":"校舎","type_guess_confidence":"low","period":"昭和中","pref":"兵庫県","address":"兵庫県丹波篠山市北新町5","lat":35.07319444,"lng":135.21916667,"geo_status":"db","era":"昭和28年／平成10年・同26年改修","year":1953,"year_source":"db","year_min":1953,"year_max":1953,"year_label":null,"structure":"木造2階建、瓦葺、建築面積546㎡","structure_material":"木造2階建","registered":"2024.03.06(令和6.03.06)","register_no":"28 - 0810","desc":"三号棟の南、東渡廊下を越え東に延びる木造二階建切妻造桟瓦葺。北側片廊下の南に普通教室を並べ、中央東寄りに防火壁を立上げる。南面は側柱筋の外に柱を立て出窓とする構成。窓は横長窓で欄間も開け大開口を確保。窓間と腰は横板張。構成に創意ある教室棟。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014896"},{"id":"00014897","register_sub_id":"101","register_pk":"519157","name":"篠山小学校五号棟","kana":"ささやましょうがっこう5ごうとう","category":"学校","subcategory":"建築物","type_guess":"校舎","type_guess_confidence":"low","period":"昭和中","pref":"兵庫県","address":"兵庫県丹波篠山市北新町5","lat":35.07296111,"lng":135.21919722,"geo_status":"db","era":"昭和27年／昭和60年・平成26年改修","year":1952,"year_source":"db","year_min":1952,"year_max":1952,"year_label":null,"structure":"木造2階建、瓦葺、建築面積520㎡","structure_material":"木造2階建","registered":"2024.03.06(令和6.03.06)","register_no":"28 - 0811","desc":"四号棟の南、東渡廊下を越え東に延びる木造二階建切妻造桟瓦葺。北側片廊下の普通教室棟で中央東寄りに防火壁を立上げる。南面は柱を上下階に通した出窓で欄間付の横連窓、窓下は引出収納。二階階段ホールに独立円柱が立つ。創意現れた戦後復興期の学校建築。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014897"},{"id":"00014898","register_sub_id":"101","register_pk":"519158","name":"篠山小学校講堂","kana":"ささやましょうがっこうこうどう","category":"学校","subcategory":"建築物","type_guess":"講堂","type_guess_confidence":"high","period":"昭和前","pref":"兵庫県","address":"兵庫県丹波篠山市北新町5","lat":35.07361389,"lng":135.21935556,"geo_status":"db","era":"昭和10年／昭和中期・平成26年改修","year":1935,"year_source":"db","year_min":1935,"year_max":1935,"year_label":null,"structure":"鉄骨造平屋建、人工スレート葺、建築面積586㎡","structure_material":"鉄骨造平屋建","registered":"2024.03.06(令和6.03.06)","register_no":"28 - 0812","desc":"二号棟と三号棟の東に建つ。鉄骨造平屋建南北棟、屋根は切妻造人工スレート葺。外壁は木下地のモルタル塗で、腰はスクラッチ・タイル貼。内部は北面の幅一杯に舞台を設ける。鉄製のフィンク・トラス小屋組で大空間を実現。戦前期の希少な鉄骨造の学校講堂。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014898"},{"id":"00000745","register_sub_id":"101","register_pk":"101735","name":"三田学園創立二十五周年記念図書館","kana":"さんだがくえんそうりつにじゅうごしゅうねんきねんとしょかん","category":"学校","subcategory":"建築物","type_guess":"図書館","type_guess_confidence":"high","period":"昭和前","pref":"兵庫県","address":"兵庫県三田市南ケ丘2-13-65","lat":34.87694946,"lng":135.21726583,"geo_status":"db","era":"昭和12","year":1937,"year_source":"db","year_min":1937,"year_max":1937,"year_label":null,"structure":"鉄筋コンクリート造３階建，瓦葺，建築面積470㎡","structure_material":"鉄筋コンクリート造３階建","registered":"1998.09.02(平成10.09.02)","register_no":"28 － 0028","desc":"中学本館の北方の丘上に建つスパニッシュスタイルの図書館建築。玄関のある鉄筋コンクリート造平屋建部を主体とし，西に３階建塔屋付き書庫棟を配する。玄関奥左手の大棟と庇の境に３連の屋根窓をつけ，屋根及び小庇ともスペイン瓦を葺く。設計は置塩章。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000745"},{"id":"00000744","register_sub_id":"101","register_pk":"101734","name":"三田学園中学本館","kana":"さんだがくえんちゅうがくほんかん","category":"学校","subcategory":"建築物","type_guess":"記念館・資料室","type_guess_confidence":"low","period":"明治","pref":"兵庫県","address":"兵庫県三田市南ケ丘2-13-65","lat":34.87556237,"lng":135.21732992,"geo_status":"db","era":"明治45","year":1912,"year_source":"db","year_min":1912,"year_max":1912,"year_label":null,"structure":"木造２階建，銅板葺，建築面積1062㎡","structure_material":"木造２階建","registered":"1998.09.02(平成10.09.02)","register_no":"28 － 0027","desc":"木造２階建，石綿スレート葺，下見板貼スティックスタイルの校舎で，中央部に玄関，両端にウィングを張りだす。玄関部頂部の櫛形ペディメントが印象的。神戸の藍原（兵二郎）建築事務所の設計で，イギリスのパブリックスクールを模したと伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000744"},{"id":"00002433","register_sub_id":"101","register_pk":"103423","name":"私立灘中学校・灘高等学校本館","kana":"しりつなだちゅうがっこう・なだこうとうがっこうほんかん","category":"学校","subcategory":"建築物","type_guess":"記念館・資料室","type_guess_confidence":"low","period":"昭和前","pref":"兵庫県","address":"兵庫県神戸市東灘区魚崎北町8-5-1","lat":34.719471,"lng":135.26825,"geo_status":"db","era":"昭和4","year":1929,"year_source":"db","year_min":1929,"year_max":1929,"year_label":null,"structure":"鉄筋コンクリート造2階建、建築面積497㎡、塔屋付","structure_material":"鉄筋コンクリート造2階建","registered":"2001.10.12(平成13.10.12)","register_no":"28 － 0072","desc":"宗建築事務所設計の学校建築。鉄筋コンクリート造２階建で，１階を事務室，２階を講堂とする。外観は縦長窓をデザインの基調とし，１階は石積風の横目地を施し，２階正面は窓に尖りアーチ状の飾り枠をつける。学校のシンボルとして地域に親しまれている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002433"},{"id":"00010986","register_sub_id":"101","register_pk":"208956","name":"柏陵記念館","kana":"はくりょうきねんかん","category":"学校","subcategory":"建築物","type_guess":"記念館・資料室","type_guess_confidence":"high","period":"明治","pref":"兵庫県","address":"兵庫県丹波市柏原町東奥字中道50","lat":35.130958,"lng":135.082398,"geo_status":"db","era":"明治30／昭和16・同35移築","year":1897,"year_source":"db","year_min":1897,"year_max":1897,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積151㎡","structure_material":"木造平屋建","registered":"2016.02.25(平成28.02.25)","register_no":"28-0643","desc":"兵庫県柏原尋常中学校本館の教室及び昇降口を移築改修した擬洋風建築。木造平屋建、寄棟造桟瓦葺、外壁下見板張で背面にベランダを付す。玄関ポーチは胴張りを持つコリント式風の円柱でペディメントを支え、玄関脇の付柱上部には鳩の彫刻を設ける。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010986"},{"id":"00001336","register_sub_id":"101","register_pk":"102326","name":"姫路工業大学講堂（旧姫路高等学校講堂）","kana":"ひめじこうぎょうだいがくこうどう（きゅうひめじこうとうがっこうこうどう）","category":"学校","subcategory":"建築物","type_guess":"講堂","type_guess_confidence":"high","period":"大正","pref":"兵庫県","address":"兵庫県姫路市新在家本町1-1-12","lat":34.84706428,"lng":134.68866779,"geo_status":"db","era":"大正15","year":1926,"year_source":"db","year_min":1926,"year_max":1926,"year_label":null,"structure":"木造2階建、スレート葺、建築面積450㎡","structure_material":"木造2階建","registered":"1999.10.14(平成11.10.14)","register_no":"28 － 0056","desc":"旧本館の右手奥に西面して建つ。木造２階建，下見板貼で，旧本館と共通するデザインでまとめられているが，トスカナ式の角柱を持つ玄関ポーチとその上部の切妻破風を両脇の角塔が挟む立面構成をとることで正面性をより強調したものとしている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001336"},{"id":"00001335","register_sub_id":"101","register_pk":"102325","name":"姫路工業大学ゆりの木会館（旧姫路高等学校本館）","kana":"ひめじこうぎょうだいがくゆりのきかいかん（きゅうひめじこうとうがっこうほんかん）","category":"学校","subcategory":"建築物","type_guess":"記念館・資料室","type_guess_confidence":"low","period":"大正","pref":"兵庫県","address":"兵庫県姫路市新在家本町1-1-12","lat":34.84738287,"lng":134.68791517,"geo_status":"db","era":"大正15","year":1926,"year_source":"db","year_min":1926,"year_max":1926,"year_label":null,"structure":"木造2階建、スレート葺、建築面積483㎡","structure_material":"木造2階建","registered":"1999.10.14(平成11.10.14)","register_no":"28 － 0055","desc":"木造２階建，下見板貼スティックスタイルによる文部省直轄学校建築の一事例。正面中央の破風の処理などにセセッション風の幾何学的装飾が見られる他，車寄を設けずにアーチ形の正面玄関とし，背面に通り抜けるような造りとしている点に特徴がある。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001335"},{"id":"00016418","register_sub_id":"101","register_pk":"536485","name":"兵庫県立明石高等学校中部講堂","kana":"ひょうごけんりつあかしこうとうがっこうなかべこうどう","category":"学校","subcategory":"建築物","type_guess":"講堂","type_guess_confidence":"high","period":"昭和中","pref":"兵庫県","address":"兵庫県明石市荷山町1744","lat":34.65773056,"lng":135.00906111,"geo_status":"db","era":"昭和31年／平成27年改修","year":1956,"year_source":"db","year_min":1956,"year_max":1956,"year_label":null,"structure":"鉄骨造及び鉄筋コンクリート造2階一部3階建、鉄板葺、建築面積1，092㎡","structure_material":"鉄骨造及び鉄筋コンクリート造2階一部3階建","registered":"2025.11.17(令和7.11.17)","register_no":"28 - 0846","desc":"明石城跡の北東に位置する高校に実業家の中部謙吉が寄附した講堂。鉄骨造及び鉄筋コンクリート造２階一部３階建。桁行41メートル、梁間25メートルで、内部は鉄骨造の三弦トラスで無柱の大空間を実現する。尖頭形のヴォールト屋根が外観を印象づける。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00016418"},{"id":"00008312","register_sub_id":"101","register_pk":"133954","name":"兵庫県立長田高等学校神撫会館（旧兵庫県立第三神戸中学校図書館）","kana":"ひょうごけんりつながたこうとうがっこうじんぶかいかん（きゅうひょうごけんりつだいさんこうべちゅうがっこうとしょかん）","category":"学校","subcategory":"建築物","type_guess":"図書館","type_guess_confidence":"high","period":"大正","pref":"兵庫県","address":"兵庫県神戸市長田区池田谷町2-5-1","lat":34.67009084,"lng":135.14275044,"geo_status":"db","era":"大正12年／昭和29年・昭和38年・昭和55年・平成17年改修","year":1923,"year_source":"db","year_min":1923,"year_max":1923,"year_label":null,"structure":"鉄筋コンクリート造平屋建、建築面積173㎡","structure_material":"鉄筋コンクリート造平屋建","registered":"2010.09.10(平成22.09.10)","register_no":"28 － 0455","desc":"校地西方の小丘に建ち、建築面積１７４㎡、鉄筋コンクリート造平屋建である。左右対称の立面構成で、正面中央の玄関ポーチ上部にペディメント状の壁を立ち上げ、両翼の張り出しに太い柱型をつくり頂部に十字を飾る。設計担当の兵庫県営繕課の力量を示す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008312"},{"id":"00005194","register_sub_id":"101","register_pk":"106184","name":"佐保会館","kana":"さほかいかん","category":"学校","subcategory":"建築物","type_guess":"記念館・資料室","type_guess_confidence":"low","period":"昭和前","pref":"奈良県","address":"奈良県奈良市北魚屋西町","lat":34.689018,"lng":135.827576,"geo_status":"db","era":"昭和3","year":1928,"year_source":"db","year_min":1928,"year_max":1928,"year_label":null,"structure":"木造2階建、瓦葺、建築面積324㎡","structure_material":"木造2階建","registered":"2005.12.26(平成17.12.26)","register_no":"29 － 0094","desc":"市中心部に位置する奈良女子大学の構内北端に南面して建つ。桁行１３間，梁間６間の入母屋造，木造２階建で，正面に車寄を設ける。各階腰部を竪板張とした真壁造で，縦長上下窓を四面に配し，妻飾は豕扠首とする。たちの高い堂々とした構えの大学同窓会館。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005194"},{"id":"00014505","register_sub_id":"101","register_pk":"513919","name":"天理図書館西館","kana":"てんりとしょかんにしかん","category":"学校","subcategory":"建築物","type_guess":"図書館","type_guess_confidence":"high","period":"昭和前","pref":"奈良県","address":"奈良県天理市杣之内町元山口方1050-13","lat":34.59466667,"lng":135.846075,"geo_status":"db","era":"昭和5年","year":1930,"year_source":"db","year_min":1930,"year_max":1930,"year_label":null,"structure":"鉄筋コンクリート造5階建、建築面積1，326㎡","structure_material":"鉄筋コンクリート造5階建","registered":"2023.02.27(令和5.02.27)","register_no":"29 - 0336","desc":"天理図書館西館は、ロマネスクを基調とし要所にライト風を取り入れた外観意匠、書庫を中心に閲覧室や事務室などを一体化した平面配置、書棚を構成する鉄骨書架柱で四層のコンクリートスラブを支える書庫の構造等が特徴的な天理教全体の総合図書館である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014505"},{"id":"00014506","register_sub_id":"101","register_pk":"513920","name":"天理図書館東館","kana":"てんりとしょかんひがしかん","category":"学校","subcategory":"建築物","type_guess":"図書館","type_guess_confidence":"high","period":"昭和前","pref":"奈良県","address":"奈良県天理市杣之内町元山口方1050-13","lat":34.59469444,"lng":135.84645278,"geo_status":"db","era":"昭和38年","year":1963,"year_source":"db","year_min":1963,"year_max":1963,"year_label":null,"structure":"鉄筋コンクリート造7階建、建築面積1，211㎡","structure_material":"鉄筋コンクリート造7階建","registered":"2023.02.27(令和5.02.27)","register_no":"29 - 0337","desc":"天理図書館東館は天理大学の校地中央東寄りの傾斜地にあり、西館後方に建つロマネスク調の増築書庫棟。二～四階部分に六層の書庫フロアを設け、外観は下階部瘤出し仕上の凝灰岩貼、上部はスクラッチタイル貼とし、西館と一体とした外観意匠を形成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014506"},{"id":"00009358","register_sub_id":"101","register_pk":"194151","name":"奈良県立畝傍高等学校倉庫（旧動力室）","kana":"ならけんりつうねびこうとうがっこうそうこ（きゅうどうりょくしつ）","category":"学校","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"奈良県","address":"奈良県橿原市八木町3-13-2","lat":34.50921684,"lng":135.79922215,"geo_status":"db","era":"昭和8年","year":1933,"year_source":"db","year_min":1933,"year_max":1933,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積30㎡","structure_material":"木造平屋建","registered":"2012.08.13(平成24.08.13)","register_no":"29 － 0202","desc":"南館の北面西寄りに建ち南北に出入口を開く。木造平屋建、桁行五・五メートル梁間五・五メートル、切妻造桟瓦葺、妻入である。妻面にトラスの架構を現し、鎧板の換気窓を設けるなど洋風意匠でまとめる。昭和初期における学校の附属建物の姿を伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009358"},{"id":"00009355","register_sub_id":"101","register_pk":"194148","name":"奈良県立畝傍高等学校本館北館","kana":"ならけんりつうねびこうとうがっこうほんかんきたかん","category":"学校","subcategory":"建築物","type_guess":"記念館・資料室","type_guess_confidence":"low","period":"昭和前","pref":"奈良県","address":"奈良県橿原市八木町3-13-2","lat":34.50941314,"lng":135.79940418,"geo_status":"db","era":"昭和8年／昭和51年・平成2年改修","year":1933,"year_source":"db","year_min":1933,"year_max":1933,"year_label":null,"structure":"鉄筋コンクリート造3階建、瓦葺、建築面積983㎡、塔屋付","structure_material":"鉄筋コンクリート造3階建","registered":"2012.08.13(平成24.08.13)","register_no":"29 － 0199","desc":"校地の南側中央に位置し、校庭に北面して建つ。鉄筋コンクリート造三階建、東西九四・七メートル南北一〇メートル、正面中央に宝形造本瓦葺の塔屋をつくり車寄を出す。陸屋根の四周は本瓦葺とする。近代的な建物の要所に和風意匠を取り入れた和洋折衷の校舎。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009355"},{"id":"00009356","register_sub_id":"101","register_pk":"194149","name":"奈良県立畝傍高等学校本館南館","kana":"ならけんりつうねびこうとうがっこうほんかんみなみかん","category":"学校","subcategory":"建築物","type_guess":"記念館・資料室","type_guess_confidence":"low","period":"昭和前","pref":"奈良県","address":"奈良県橿原市八木町3-13-2","lat":34.5091169,"lng":135.79940775,"geo_status":"db","era":"昭和8年／昭和44年・昭和48年・平成2年改修","year":1933,"year_source":"db","year_min":1933,"year_max":1933,"year_label":null,"structure":"鉄筋コンクリート造3階建、建築面積755㎡、塔屋付","structure_material":"鉄筋コンクリート造3階建","registered":"2012.08.13(平成24.08.13)","register_no":"29 － 0200","desc":"北館の南側に平行して建ち、渡廊下を介して北館と接続する。鉄筋コンクリート造三階建、東西七五・一メートル南北一〇メートル、背面中央に切妻造本瓦葺の塔屋をのせる。陸屋根の四周は本瓦葺とする。北館とあわせて昭和初期の学校建築の姿を良好に伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009356"},{"id":"00009357","register_sub_id":"101","register_pk":"194150","name":"奈良県立畝傍高等学校本館渡廊下","kana":"ならけんりつうねびこうとうがっこうほんかんわたりろうか","category":"学校","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"奈良県","address":"奈良県橿原市八木町3-13-2","lat":34.50925253,"lng":135.79941132,"geo_status":"db","era":"昭和8年","year":1933,"year_source":"db","year_min":1933,"year_max":1933,"year_label":null,"structure":"鉄筋コンクリート造2階建、建築面積168㎡","structure_material":"鉄筋コンクリート造2階建","registered":"2012.08.13(平成24.08.13)","register_no":"29 － 0201","desc":"北館の南面中央と南館の北面中央を接続する。鉄筋コンクリート造二屋建、南北二一・八メートル東西四・六メートル、東面に平屋建の倉庫等を附属する。パラペットには雁振瓦をのせ、和風意匠を演出する。北館、南館とあわせて工の字平面の大型校舎を構成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009357"},{"id":"00014199","register_sub_id":"101","register_pk":"508829","name":"旧上秋津小学校校舎（秋津野ガルテン）","kana":"きゅうかみあきづしょうがっこうこうしゃ（あきづのがるてん）","category":"学校","subcategory":"建築物","type_guess":"校舎","type_guess_confidence":"high","period":"昭和中","pref":"和歌山県","address":"和歌山県田辺市上秋津字平岡4558-8","lat":33.75601667,"lng":135.40703611,"geo_status":"db","era":"昭和28年／平成20年改修","year":1953,"year_source":"db","year_min":1953,"year_max":1953,"year_label":null,"structure":"木造2階建、瓦葺、建築面積667㎡","structure_material":"木造2階建","registered":"2022.02.17(令和4.02.17)","register_no":"30-0319","desc":"右会津川沿い農村の長大な木造校舎。二階建切妻造桟瓦葺、外壁は下見板張、軒際漆喰仕上とする。内部は片廊下式で、二階に背面側丘上へ避難路を設け、鉄筋コンクリート界壁と防火扉、キングポスト・トラス小屋組に土壁界壁、筋交と方杖など防災を重視する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014199"},{"id":"00014665","register_sub_id":"101","register_pk":"515207","name":"旧制粉河高等女学校同窓会館（粉河高等学校同窓会館）洋館","kana":"きゅうせいこかわこうとうじょがっこうどうそうかいかん（こかわこうとうがっこうどうそうかいかん）ようかん","category":"学校","subcategory":"建築物","type_guess":"記念館・資料室","type_guess_confidence":"low","period":"昭和前","pref":"和歌山県","address":"和歌山県紀の川市粉河字植田4600","lat":34.27448889,"lng":135.40863056,"geo_status":"db","era":"昭和9年／昭和38年・同60年・令和4年改修","year":1934,"year_source":"db","year_min":1934,"year_max":1934,"year_label":null,"structure":"木造2階建一部平屋建、瓦葺及びスレート葺、建築面積218㎡","structure_material":"木造2階建一部平屋建","registered":"2023.08.07(令和5.08.07)","register_no":"30 - 0339","desc":"粉河市街地東の高台にある女学校の開校２０周年記念に建築した同窓会館。切妻造スペイン瓦葺の木造二階建。二階は一五畳二間続きの大広間で、三面に広縁を巡らす。赤色の急勾配大屋根で、白壁に縦長窓を連続して並べ、スパニッシュを基調とする外観が特徴的。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014665"},{"id":"00014666","register_sub_id":"101","register_pk":"515208","name":"旧制粉河高等女学校同窓会館（粉河高等学校同窓会館）和館","kana":"きゅうせいこかわこうとうじょがっこうどうそうかいかん（こかわこうとうがっこうどうそうかいかん）わかん","category":"学校","subcategory":"建築物","type_guess":"記念館・資料室","type_guess_confidence":"low","period":"昭和前","pref":"和歌山県","address":"和歌山県紀の川市粉河字植田4600","lat":34.27437778,"lng":135.40888333,"geo_status":"db","era":"昭和9年／昭和60年・令和4年改修","year":1934,"year_source":"db","year_min":1934,"year_max":1934,"year_label":null,"structure":"木造平屋建、スレート葺、建築面積131㎡","structure_material":"木造平屋建","registered":"2023.08.07(令和5.08.07)","register_no":"30 - 0340","desc":"女学校の同窓会館として開校２０周年記念に建てた和館。宝形造スレート葺、真壁造で和風を基調とする平屋建で、同窓会館洋館東に接続。欄間を多用する明るい続き間座敷が中心の間取りで、玄関脇に洋風応接間を配する。かつては炊事等の宿泊実習に用いた。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014666"},{"id":"00013620","register_sub_id":"101","register_pk":"504989","name":"旧制和歌山中学校運動場スタンド（桐蔭高等学校運動場スタンド）","kana":"きゅうせいわかやまちゅうがっこううんどうじょうすたんど（とういんこうとうがっこううんどうじょうすたんど）","category":"学校","subcategory":"その他工作物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"和歌山県","address":"和歌山県和歌山市吹上5丁目39-1他","lat":34.21888333,"lng":135.17592222,"geo_status":"db","era":"大正11年／昭和後期改修","year":1922,"year_source":"db","year_min":1922,"year_max":1922,"year_label":null,"structure":"鉄筋コンクリート造、延長156m","structure_material":"鉄筋コンクリート造","registered":"2021.02.04(令和3.02.04)","register_no":"30 － 0290","desc":"校地東半を占める運動場の北辺から東辺に設けた観覧席である。敷地東の丘陵斜面を利用し、コンクリート製客席は北面では中央階段の西が一一段、東が一〇段、東面は一二段で中間に二箇所の階段を設ける。建設以来、同校のグラウンドを象徴する施設である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013620"},{"id":"00013619","register_sub_id":"101","register_pk":"504988","name":"旧制和歌山中学校図書館（桐蔭高等学校同窓会館）","kana":"きゅうせいわかやまちゅうがっこうとしょかん（とういんこうとうがっこうどうそうかいかん）","category":"学校","subcategory":"建築物","type_guess":"図書館","type_guess_confidence":"high","period":"昭和前","pref":"和歌山県","address":"和歌山県和歌山市吹上5丁目1-17","lat":34.2186,"lng":135.17436389,"geo_status":"db","era":"昭和4年／昭和53年改修","year":1929,"year_source":"db","year_min":1929,"year_max":1929,"year_label":null,"structure":"鉄筋コンクリート造平屋建、陸屋根、建築面積125㎡","structure_material":"鉄筋コンクリート造平屋建","registered":"2021.02.04(令和3.02.04)","register_no":"30 － 0289","desc":"敷地の北面中央に建つ旧図書館の閲覧室部分。鉄筋コンクリート造平屋建の陸屋根で西面玄関ポーチは太い円柱が厚みを減じた水平庇を受ける。正面壁面中央にモルタル塗で旧制中学校章を飾る。床下換気口グリルに中の字をあしらう。簡明な意匠の近代建築である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013619"},{"id":"00015215","register_sub_id":"101","register_pk":"530639","name":"旧羽根学園熊野高等経理学校校舎","kana":"きゅうはねがくえんくまのこうとうけいりがっこうこうしゃ","category":"学校","subcategory":"建築物","type_guess":"校舎","type_guess_confidence":"high","period":"昭和前","pref":"和歌山県","address":"和歌山県新宮市丹鶴二丁目7683-51","lat":33.728875,"lng":135.99200833,"geo_status":"db","era":"昭和12年／昭和40年増築","year":1937,"year_source":"db","year_min":1937,"year_max":1937,"year_label":null,"structure":"木造一部鉄骨造2階建、瓦葺一部鉄板葺、建築面積215㎡","structure_material":"木造一部鉄骨造2階建","registered":"2024.12.03(令和6.12.03)","register_no":"30 - 0376","desc":"新宮城跡の南に位置する旧経理学校校舎。通りに西面する木造２階建入母屋造桟瓦葺で玄関ポーチを付し外壁下見板張。一階は中廊下形式、二階は一室の大教室で、東半は鉄骨造の別棟増築部。玄関ポーチに四つ玉算盤の欄間を掲げ、開学時の息吹を伝える洋風校舎。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015215"},{"id":"00016716","register_sub_id":"101","register_pk":"579200","name":"高野山高等学校講堂","kana":"こうやさんこうとうがっこうこうどう","category":"学校","subcategory":"建築物","type_guess":"講堂","type_guess_confidence":"high","period":"昭和前","pref":"和歌山県","address":"和歌山県伊都郡高野町大字高野山字谷上183-1他","lat":34.216711,"lng":135.577178,"geo_status":"db","era":"昭和11年／昭和49年改修、同53年頃移築","year":1936,"year_source":"db","year_min":1936,"year_max":1936,"year_label":null,"structure":"木造平屋建、鉄板葺、建築面積435㎡","structure_material":"木造平屋建","registered":"2026.07.09(令和8.07.09)","register_no":"30 - 0426","desc":"壇上伽藍の北西に位置する高校の講堂。校舎群中央部に建つ入母屋造妻入鉄板葺で外壁漆喰塗、腰は簓子下見板張。外陣は１２６畳の広大な畳敷で、格天井に玉杢の杉板を用いる。内陣は一段高い板敷とし、両脇に護摩堂、香華場を配す。当校を象徴する巨大な講堂。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00016716"},{"id":"00016717","register_sub_id":"101","register_pk":"579201","name":"高野山高等学校校門","kana":"こうやさんこうとうがっこうこうもん","category":"学校","subcategory":"その他工作物","type_guess":"正門","type_guess_confidence":"high","period":"昭和前","pref":"和歌山県","address":"和歌山県伊都郡高野町大字高野山字谷上207","lat":34.214982,"lng":135.578156,"geo_status":"db","era":"昭和12年","year":1937,"year_source":"db","year_min":1937,"year_max":1937,"year_label":null,"structure":"鉄筋コンクリート造、間口6.8m","structure_material":"鉄筋コンクリート造","registered":"2026.07.09(令和8.07.09)","register_no":"30 - 0427","desc":"敷地南端に建つ正門。一対の門柱は鉄筋コンクリート造、正方形平面、高さ２・２メートル。表面は頁岩貼仕上とする。頂部に載せる灯塔は宝形造鉄板葺で段葺とし軒を反らせる。灯身は格子にガラスを嵌め、内部に電灯を入れる。極太の門柱で堂々とした姿の校門。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00016717"},{"id":"00001014","register_sub_id":"101","register_pk":"102004","name":"高野山大学図書館","kana":"こうやさんだいがくとしょかん","category":"学校","subcategory":"建築物","type_guess":"図書館","type_guess_confidence":"high","period":"昭和前","pref":"和歌山県","address":"和歌山県伊都郡高野町高野山385","lat":34.21152504,"lng":135.58593081,"geo_status":"db","era":"昭和4","year":1929,"year_source":"db","year_min":1929,"year_max":1929,"year_label":null,"structure":"鉄筋コンクリート造地上３階地下１階建，建築面積569㎡","structure_material":"鉄筋コンクリート造地上３階地下１階建","registered":"1998.12.11(平成10.12.11)","register_no":"30 － 0035","desc":"３０万冊の仏教書を収蔵・公開する施設として武田五一の設計，清水組の施工により建設された。鉄筋コンクリート造地下室付３階建の質実な図書館建築で，正面中央玄関の左手を研究室，右手を閲覧室に充て，閲覧室の背後に内部５層の書庫を配する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001014"},{"id":"00009523","register_sub_id":"101","register_pk":"194316","name":"北海道大学和歌山研究林本館","kana":"ほっかいどうだいがくわかやまけんきゅうりんほんかん","category":"学校","subcategory":"建築物","type_guess":"記念館・資料室","type_guess_confidence":"low","period":"昭和前","pref":"和歌山県","address":"和歌山県東牟婁郡古座川町平井560-1他","lat":33.64273293,"lng":135.68955524,"geo_status":"db","era":"昭和2年／平成7年改修","year":1927,"year_source":"db","year_min":1927,"year_max":1927,"year_label":null,"structure":"木造2階建、鉄板葺、建築面積182㎡","structure_material":"木造2階建","registered":"2013.03.29(平成25.03.29)","register_no":"30 － 0170","desc":"平井川左岸、平井集落の中に建つ演習林宿舎。Ｈ形平面の木造二階建で、両翼部の妻壁を見せた切妻造鉄板葺。外壁は下見板張で、両翼妻壁はシングル張とする。窓は二連、三連の上下窓を引違に改修。小屋組は繋梁入の垂木小屋。紀伊山中に建つ札幌農学校建築。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009523"},{"id":"00003297","register_sub_id":"101","register_pk":"104287","name":"湯浅小学校講堂","kana":"ゆあさしょうがっこうこうどう","category":"学校","subcategory":"建築物","type_guess":"講堂","type_guess_confidence":"high","period":"昭和前","pref":"和歌山県","address":"和歌山県有田郡湯浅町湯浅1570","lat":34.035488,"lng":135.181366,"geo_status":"db","era":"昭和11","year":1936,"year_source":"db","year_min":1936,"year_max":1936,"year_label":null,"structure":"鉄骨造平屋建、瓦葺、建築面積978㎡","structure_material":"鉄骨造平屋建","registered":"2003.03.18(平成15.03.18)","register_no":"30 － 0049","desc":"鉄骨造の講堂。内部は後方に舞台と左右二室を設ける他は一室とする。正面ポーチには三連アーチを設け，左右の側面は柱型を見せた横板張に出目地を走らせ，上部は平坦なモルタル塗りとする。凹凸のリズミカルな側面と荘重な正面の対比で特徴的な外観を見せる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003297"},{"id":"00001524","register_sub_id":"101","register_pk":"102514","name":"大谷大学尋源館（旧本館）","kana":"おおたにだいがくじんげんかん（きゅうほんかん）","category":"学校","subcategory":"建築物","type_guess":"記念館・資料室","type_guess_confidence":"low","period":"大正","pref":"京都府","address":"京都府京都市北区小山上総町20-1","lat":35.04185345,"lng":135.75849987,"geo_status":"db","era":"大正2","year":1913,"year_source":"db","year_min":1913,"year_max":1913,"year_label":null,"structure":"煉瓦造2階建、瓦葺、建築面積587㎡","structure_material":"煉瓦造2階建","registered":"2000.02.15(平成12.02.15)","register_no":"26 － 0058","desc":"烏丸通北大路下るの現在地にキャンパスを移した際の大学本館。赤煉瓦に石でドレッシングした明治調の躯体に軽快な玄関ポーチと小塔を付ける。ゲーブルには大正期のセセッション的意匠が認められる。設計は須藤勉と山本八太郎とされる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001524"},{"id":"00004595","register_sub_id":"101","register_pk":"105585","name":"旧京都市立有済小学校太鼓望楼","kana":"きゅうきょうとしりつゆうさいしょうがっこうたいこぼうろう","category":"学校","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"京都府","address":"京都府京都市東山区大和大路通三条下る東側大黒町169","lat":35.00788844,"lng":135.77363412,"geo_status":"db","era":"明治9／昭和27移築","year":1876,"year_source":"db","year_min":1876,"year_max":1876,"year_label":null,"structure":"木造2層、鉄板葺、建築面積9㎡","structure_material":"木造2層","registered":"2005.02.09(平成17.02.09)","register_no":"26 － 0195","desc":"木造２階建の有済小学校講堂の大棟中央に付設されていた。ＲＣ造校舎新築に伴い，屋上に保存された。木造で，内部は２層構成になる。宝形造の望楼部を高く立て，庇を付けた下部を袴腰風の縦板張で覆う簡素なつくりであるが，地域の人々に広く親しまれている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004595"},{"id":"00007220","register_sub_id":"101","register_pk":"108202","name":"京都芸術センター北館（旧京都市立明倫小学校北校舎）","kana":"きょうとげいじゅつせんたーきたかん（きゅうきょうとしりつめいりんしょうがっこうきたこうしゃ）","category":"学校","subcategory":"建築物","type_guess":"校舎","type_guess_confidence":"high","period":"昭和前","pref":"京都府","address":"京都府京都市中京区室町通蛸薬師下る山伏山町546-2他","lat":35.005695,"lng":135.758881,"geo_status":"db","era":"昭和6／平成11改修","year":1931,"year_source":"db","year_min":1931,"year_max":1931,"year_label":null,"structure":"鉄筋コンクリート造3階建、建築面積499㎡","structure_material":"鉄筋コンクリート造3階建","registered":"2008.07.08(平成20.07.08)","register_no":"26 － 0305","desc":"西館の北面東端と渡廊下で接続する鉄筋コンクリート造３階建。西端の南への突出部は２、３階へのスロープで、端部を四半円形につくる。南面東寄りに運動場への出入口を開く。内部は北側片廊下で教室が並び、東端は特別教室とした。３階窓上庇が水平線を強調。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007220"},{"id":"00007221","register_sub_id":"101","register_pk":"108203","name":"京都芸術センター正門及び塀（旧京都市立明倫小学校正門及び塀）","kana":"きょうとげいじゅつせんたーせいもんおよびへい（きゅうきょうとしりつめいりんしょうがっこうせいもんおよびへい）","category":"学校","subcategory":"その他工作物","type_guess":"正門","type_guess_confidence":"high","period":"昭和前","pref":"京都府","address":"京都府京都市中京区室町通蛸薬師下る山伏山町546-2他","lat":35.00544318,"lng":135.75813008,"geo_status":"db","era":"昭和6／平成11改修","year":1931,"year_source":"db","year_min":1931,"year_max":1931,"year_label":null,"structure":"門 鉄筋コンクリート造門柱2基、間口2.9m、両側通用門付 塀 鉄筋コンクリート造、延長25m","structure_material":"門 鉄筋コンクリート造門柱2基","registered":"2008.07.08(平成20.07.08)","register_no":"26 － 0306","desc":"敷地西側の室町通に開く門。鉄筋コンクリート造の門柱は断面八角形で、各角に柱形をつけ、セセッション風の造形をみせる。頂部はドーム形である。両側に同形で一まわり小さな門柱を建て、脇門とする。塀の親柱も門柱と同意匠で、一体感のある景観を呈している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007221"},{"id":"00007218","register_sub_id":"101","register_pk":"108200","name":"京都芸術センター西館（旧京都市立明倫小学校本館）","kana":"きょうとげいじゅつせんたーにしかん（きゅうきょうとしりつめいりんしょうがっこうほんかん）","category":"学校","subcategory":"建築物","type_guess":"記念館・資料室","type_guess_confidence":"low","period":"昭和前","pref":"京都府","address":"京都府京都市中京区室町通蛸薬師下る山伏山町546-2他","lat":35.00542731,"lng":135.75837231,"geo_status":"db","era":"昭和6／平成11改修","year":1931,"year_source":"db","year_min":1931,"year_max":1931,"year_label":null,"structure":"鉄筋コンクリート造2階地下1階建、建築面積661㎡","structure_material":"鉄筋コンクリート造2階地下1階建","registered":"2008.07.08(平成20.07.08)","register_no":"26 － 0303","desc":"東西に長い鉄筋コンクリート造２階建。室町通に開く門から南面の切妻屋根の玄関にアプローチする。１階は西半が事務室、東半が旧体操場、２階は西半が和風の大広間、東半が旧講堂である。パラペットのスペイン瓦と、西妻２階のバルコニーが外観を特徴づける。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007218"},{"id":"00007219","register_sub_id":"101","register_pk":"108201","name":"京都芸術センター南館（旧京都市立明倫小学校南校舎）","kana":"きょうとげいじゅつせんたーみなみかん（きゅうきょうとしりつめいりんしょうがっこうみなみこうしゃ）","category":"学校","subcategory":"建築物","type_guess":"校舎","type_guess_confidence":"high","period":"昭和前","pref":"京都府","address":"京都府京都市中京区室町通蛸薬師下る山伏山町546-2他","lat":35.00530362,"lng":135.7589087,"geo_status":"db","era":"昭和6／平成11改修","year":1931,"year_source":"db","year_min":1931,"year_max":1931,"year_label":null,"structure":"鉄筋コンクリート造3階一部4階建、建築面積652㎡","structure_material":"鉄筋コンクリート造3階一部4階建","registered":"2008.07.08(平成20.07.08)","register_no":"26 － 0304","desc":"西館の南面東端から東へ延びる、鉄筋コンクリート造３階一部４階建。西端に半円アーチの入口を設け、北面東寄りに運動場への出入口を開く。北側片廊下で教室が並び、東端は特別教室、４階に作法室を配した。西端塔屋の寄棟屋根と３連の円形窓の意匠が特徴的。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007219"},{"id":"00006972","register_sub_id":"101","register_pk":"107954","name":"京都工芸繊維大学（旧京都高等工藝學校）自動車庫","kana":"きょうとこうげいせんいだいがく（きゅうきょうとこうとうこうげいがっこう）じどうしゃこ","category":"学校","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"京都府","address":"京都府京都市左京区松ヶ崎正田町18-1他","lat":35.0493391,"lng":135.78229031,"geo_status":"db","era":"昭和6","year":1931,"year_source":"db","year_min":1931,"year_max":1931,"year_label":null,"structure":"鉄筋コンクリート造平屋建、建築面積30㎡","structure_material":"鉄筋コンクリート造平屋建","registered":"2008.03.07(平成20.03.07)","register_no":"26 － 0271","desc":"本館の北東方、現中央西門の南の敷地外周沿いに南面して建つ。鉄筋コンクリート造平屋建、陸屋根造、スクラッチタイル貼で、平面規模は正面５．１ｍ奥行５．５ｍとし、東面及び西面北端に張出しを設ける。水平線を強調した庇や各部軒の意匠に特徴がある。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006972"},{"id":"00006973","register_sub_id":"101","register_pk":"107955","name":"京都工芸繊維大学（旧京都高等工藝學校）正門及び門衛所","kana":"きょうとこうげいせんいだいがく（きゅうきょうとこうとうこうげいがっこう）せいもんおよびもんえいじょ","category":"学校","subcategory":"建築物","type_guess":"正門","type_guess_confidence":"high","period":"昭和前","pref":"京都府","address":"京都府京都市左京区松ヶ崎正田町18-1他","lat":35.048374,"lng":135.782211,"geo_status":"db","era":"昭和6","year":1931,"year_source":"db","year_min":1931,"year_max":1931,"year_label":null,"structure":"門 コンクリート造門柱2基、間口5.4m、左右通用門付 門衛所 鉄筋コンクリート造平屋建、建築面積30㎡","structure_material":"門 コンクリート造門柱2基","registered":"2008.03.07(平成20.03.07)","register_no":"26 － 0272","desc":"本館の南東方、構内敷地の東南隅部に位置する。正門は鉄筋コンクリート造石貼で、東に脇門、西の門衛所寄りに通用門を開く。門衛所は、鉄筋コンクリート造平屋建、陸屋根造、スクラッチタイル貼で、五角形平面とし、西側に台所、便所等を備えた宿直室とする。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006973"},{"id":"00006971","register_sub_id":"101","register_pk":"107953","name":"京都工芸繊維大学（旧京都高等工藝學校）倉庫","kana":"きょうとこうげいせんいだいがく（きゅうきょうとこうとうこうげいがっこう）そうこ","category":"学校","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"京都府","address":"京都府京都市左京区松ヶ崎正田町18-1他","lat":35.04836528,"lng":135.78152262,"geo_status":"db","era":"昭和6／昭和39移築","year":1931,"year_source":"db","year_min":1931,"year_max":1931,"year_label":null,"structure":"鉄筋コンクリート造2階建、建築面積80㎡","structure_material":"鉄筋コンクリート造2階建","registered":"2008.03.07(平成20.03.07)","register_no":"26 － 0270","desc":"本館南翼の南方に北面して建つ。鉄筋コンクリート造２階建、陸屋根造、スクラッチタイル貼で、規模は正面１０ｍ奥行８．０ｍとし、北東隅部に階段を配し、屋上に塔屋を上げる。北面と南面には柱形を現し、壁面頂部にコーニスをまわす。窓には内側に鉄扉を付ける。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006971"},{"id":"00006970","register_sub_id":"101","register_pk":"107952","name":"京都工芸繊維大学（旧京都高等工藝學校）本館及び講堂","kana":"きょうとこうげいせんいだいがく（きゅうきょうとこうとうこうげいがっこう）ほんかんおよびこうどう","category":"学校","subcategory":"建築物","type_guess":"講堂","type_guess_confidence":"high","period":"昭和前","pref":"京都府","address":"京都府京都市左京区松ヶ崎正田町18-1他","lat":35.048817,"lng":135.78186,"geo_status":"db","era":"昭和5／平成15改修","year":1930,"year_source":"db","year_min":1930,"year_max":1930,"year_label":null,"structure":"鉄筋コンクリート造3階建、建築面積2251㎡","structure_material":"鉄筋コンクリート造3階建","registered":"2008.03.07(平成20.03.07)","register_no":"26 － 0269","desc":"京都高等工藝學校教授本野精吾の設計に基づく。鉄筋コンクリート造３階建、スクラッチタイル貼で、平面は背面に両翼を伸ばし、正面玄関の奥に講堂部を突き出したＥ字形とする。北面及び南面の２、３階を薄く張出し連続窓としたモダニズム色の強い意匠に特徴。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006970"},{"id":"00007224","register_sub_id":"101","register_pk":"108206","name":"京都国際マンガミュージアム旧北校舎棟（旧京都市立龍池小学校北校舎）","kana":"きょうとこくさいまんがみゅーじあむきゅうきたこうしゃとう（きゅうきょうとしりつたついけしょうがっこうきたこうしゃ）","category":"学校","subcategory":"建築物","type_guess":"校舎","type_guess_confidence":"high","period":"昭和前","pref":"京都府","address":"京都府京都市中京区両替町通押小路下る金吹町452他","lat":35.011951,"lng":135.759232,"geo_status":"db","era":"昭和12／平成18改修","year":1937,"year_source":"db","year_min":1937,"year_max":1937,"year_label":null,"structure":"鉄筋コンクリート造3階地下1階建、建築面積415㎡","structure_material":"鉄筋コンクリート造3階地下1階建","registered":"2008.07.08(平成20.07.08)","register_no":"26 － 0309","desc":"敷地の北辺、旧講堂棟の東に位置する鉄筋コンクリート造３階建。西端と中央東寄りに階段室があり、もとは北側片廊下であったが、１、２階は一部の間仕切を撤去している。外壁の各柱間には縦長の方形窓を３つずつ配し、垂直性を強調した外観としている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007224"},{"id":"00007223","register_sub_id":"101","register_pk":"108205","name":"京都国際マンガミュージアム旧講堂棟（旧京都市立龍池小学校講堂）","kana":"きょうとこくさいまんがみゅーじあむきゅうきゅうこうどうとう（きゅうきょうとしりつたついけしょうがっこうこうどう）","category":"学校","subcategory":"建築物","type_guess":"講堂","type_guess_confidence":"high","period":"昭和前","pref":"京都府","address":"京都府京都市中京区両替町通押小路下る金吹町452他","lat":35.011871,"lng":135.758957,"geo_status":"db","era":"昭和3／平成18改修","year":1928,"year_source":"db","year_min":1928,"year_max":1928,"year_label":null,"structure":"鉄筋コンクリート造2階建、建築面積507㎡","structure_material":"鉄筋コンクリート造2階建","registered":"2008.07.08(平成20.07.08)","register_no":"26 － 0308","desc":"旧本館棟の北に連続する鉄筋コンクリート造２階建。西面南寄りに片持ちの庇をつけた入口を開く。内部は１階を体操場、２階を講堂とした。１階はアーチ窓、２階は縦長の方形窓を開き、窓間に突出したアール・デコ意匠の方立と柱形で、リズム感のある外観をなす。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007223"},{"id":"00007225","register_sub_id":"101","register_pk":"108207","name":"京都国際マンガミュージアム旧正門及び塀（旧京都市立龍池小学校正門及び塀）","kana":"きょうとこくさいまんがみゅーじあむきゅうせいもんおよびへい（きゅうきょうとしりつたついけしょうがっこうせいもんおよびへい）","category":"学校","subcategory":"その他工作物","type_guess":"正門","type_guess_confidence":"high","period":"昭和前","pref":"京都府","address":"京都府京都市中京区両替町通押小路下る金吹町452他","lat":35.01157783,"lng":135.75885555,"geo_status":"db","era":"昭和初期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和初期","structure":"門 石造門柱2基、間口4.7m 塀 鉄筋コンクリート造、延長53m","structure_material":"門 石造門柱2基","registered":"2008.07.08(平成20.07.08)","register_no":"26 － 0310","desc":"敷地西側の両替町通に開く門。単純な正方形断面の石造の門柱である。門両側の塀は腰高の連続壁で、上端を笠石形とし、その上に角柱を建てて金属柵を付ける。旧講堂棟出入口の両脇には通用門が開く。要所に段状繰形を施し、簡素ながら繊細な意匠。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007225"},{"id":"00007222","register_sub_id":"101","register_pk":"108204","name":"京都国際マンガミュージアム旧本館棟（旧京都市立龍池小学校本館）","kana":"きょうとこくさいまんがみゅーじあむきゅうほんかんとう（きゅうきょうとしりつたついけしょうがっこうほんかん）","category":"学校","subcategory":"建築物","type_guess":"校舎","type_guess_confidence":"low","period":"昭和前","pref":"京都府","address":"京都府京都市中京区両替町通押小路下る金吹町452他","lat":35.011559,"lng":135.758972,"geo_status":"db","era":"昭和4／平成18改修","year":1929,"year_source":"db","year_min":1929,"year_max":1929,"year_label":null,"structure":"鉄筋コンクリート造2階地下1階建、建築面積669㎡","structure_material":"鉄筋コンクリート造2階地下1階建","registered":"2008.07.08(平成20.07.08)","register_no":"26 － 0307","desc":"敷地西側の両替町通に面して建つ鉄筋コンクリート造２階建。正面中央に玄関を開き、南・北に翼棟をつけたＨ形平面をもつ。玄関は片持ちの庇を付け、上部の窓は額縁と方立はアール・デコ風の意匠。西面窓の方立で垂直性を強調し、簡潔で特色ある外観を呈する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007222"},{"id":"00004597","register_sub_id":"101","register_pk":"105587","name":"京都市学校歴史博物館（旧京都市立開智小学校）石塀","kana":"きょうとしがっこうれきしはくぶつかん（きゅうきょうとしりつかいちしょうがっこう）いしべい","category":"学校","subcategory":"その他工作物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"京都府","address":"京都府京都市下京区御幸町通仏光寺下る橘町437","lat":35.00053082,"lng":135.76623294,"geo_status":"db","era":"大正7","year":1918,"year_source":"db","year_min":1918,"year_max":1918,"year_label":null,"structure":"石造、延長56m","structure_material":"石造","registered":"2005.02.09(平成17.02.09)","register_no":"26 － 0197","desc":"大正期の敷地拡張時に建設された。正門南北に延び，門廻りの隅は円形に築く。京都白川石を用いた重厚な間知石布積で，通り側は丁寧な瘤出仕上げとする。頂部には笠石を置き，現在は土盛に芝を張っている。往時の有様を伝えるとともに，街路景観を整えている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004597"},{"id":"00004596","register_sub_id":"101","register_pk":"105586","name":"京都市学校歴史博物館（旧京都市立開智小学校）正門","kana":"きょうとしがっこうれきしはくぶつかん（きゅうきょうとしりつかいちしょうがっこう）せいもん","category":"学校","subcategory":"その他工作物","type_guess":"正門","type_guess_confidence":"high","period":"明治","pref":"京都府","address":"京都府京都市下京区御幸町通仏光寺下る橘町437","lat":35.00076614,"lng":135.766227,"geo_status":"db","era":"明治34／大正7移築","year":1901,"year_source":"db","year_min":1901,"year_max":1901,"year_label":null,"structure":"木造、瓦葺、間口3.5m、両側袖塀付","structure_material":"木造","registered":"2005.02.09(平成17.02.09)","register_no":"26 － 0196","desc":"御幸町通に東面して建つ。間口３．５ｍの背面に控柱を立てた高麗門形式で，屋根は切妻造，本瓦葺になる。南北に袖塀をつけ，南には潜戸を設ける。親柱は高く延ばして棟木を支え，桁は前後とも腕木で受ける。明治期における学校建築の形式の一端を伝えている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004596"},{"id":"00006644","register_sub_id":"101","register_pk":"107627","name":"京都市学校歴史博物館玄関（旧成徳小学校玄関車寄）","kana":"きょうとしがっこうれきしはくぶつかんげんかん（きゅうせいとくしょうがっこうげんかんくるまよせ）","category":"学校","subcategory":"その他工作物","type_guess":"校舎","type_guess_confidence":"high","period":"明治","pref":"京都府","address":"京都府京都市下京区麩屋町通仏光寺下る鍋屋町248-2","lat":35.000854,"lng":135.765762,"geo_status":"db","era":"明治8／明治42・平成18移築","year":1875,"year_source":"db","year_min":1875,"year_max":1875,"year_label":null,"structure":"木造、瓦葺、面積8.1㎡","structure_material":"木造","registered":"2007.12.05(平成19.12.05)","register_no":"26 － 0268","desc":"明治２年開校の「下京第九番組小学校」（移転時に成徳小学校と改称）の校舎の玄関車寄。間口４．０ｍ規模で、正面に起りをつけた切妻破風を見せる。トスカナ式のオーダーを模した素木の柱がほほえましい。擬洋風になる番組小学校校舎の遺構である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006644"},{"id":"00001921","register_sub_id":"101","register_pk":"102911","name":"京都大学総合人間学部正門（旧第三高等学校正門）","kana":"きょうとだいがくそうごうにんげんがくぶせいもん（きゅうだいさんこうとうがっこうせいもん）","category":"学校","subcategory":"その他工作物","type_guess":"正門","type_guess_confidence":"high","period":"明治","pref":"京都府","address":"京都府京都市左京区吉田二本松町","lat":35.02516183,"lng":135.7804451,"geo_status":"db","era":"明治30","year":1897,"year_source":"db","year_min":1897,"year_max":1897,"year_label":null,"structure":"木造、間口3.3m、左右通用門及び袖壁付","structure_material":"木造","registered":"2000.10.18(平成12.10.18)","register_no":"26 － 0070","desc":"京大構内南部吉田二本松地区に位置する。木造門柱の両脇に，通用門が付く。大門柱の礎石部と木製柱身部が追掛大栓継ぎで結合される点に特徴があり，門扉は上桟をアーチ状とし，全体で和洋が混在したデザインとする。門衛所と共に真水英夫の設計と伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001921"},{"id":"00001922","register_sub_id":"101","register_pk":"102912","name":"京都大学総合人間学部門衛所（旧第三高等学校門番所）","kana":"きょうとだいがくそうごうにんげんがくぶもんえいじょ（きゅうだいさんこうとうがっこうもんばんしょ）","category":"学校","subcategory":"建築物","type_guess":"正門","type_guess_confidence":"high","period":"明治","pref":"京都府","address":"京都府京都市左京区吉田二本松町","lat":35.02510024,"lng":135.78034121,"geo_status":"db","era":"明治30","year":1897,"year_source":"db","year_min":1897,"year_max":1897,"year_label":null,"structure":"木造平屋建、鉄板葺、建築面積19㎡","structure_material":"木造平屋建","registered":"2000.10.18(平成12.10.18)","register_no":"26 － 0071","desc":"三高吉田学舎が京都帝国大学に譲渡されるに伴い，新三高キャンパスの門衛所として正門と同時に建設。木造，鉄板葺，ドイツ下見の平屋建。東面の受付部を八角屋根状に造り，居室部の切妻屋根と組み合わせる。二本松学舎における明治期建造物の数少ない遺構。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001922"},{"id":"00000740","register_sub_id":"101","register_pk":"101730","name":"京都大学尊攘堂","kana":"きょうとだいがくそんじょうどう","category":"学校","subcategory":"建築物","type_guess":"記念館・資料室","type_guess_confidence":"high","period":"明治","pref":"京都府","address":"京都府京都市左京区吉田本町","lat":35.02679647,"lng":135.77904892,"geo_status":"db","era":"明治36","year":1903,"year_source":"db","year_min":1903,"year_max":1903,"year_label":null,"structure":"煉瓦造平屋建，瓦葺，建築面積172㎡","structure_material":"煉瓦造平屋建","registered":"1998.09.02(平成10.09.02)","register_no":"26 － 0021","desc":"品川弥次郎が創設した記念堂に由来する。品川の死後、関係資料と建設資金が京大に寄付され、京大構内に新築された。煉瓦造スタッコ塗りで鉄造の玄関ポーチを有し，開口部など平明な意匠で仕上げられており，小堂ながら構内では異色の建築になっている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000740"},{"id":"00000741","register_sub_id":"101","register_pk":"101731","name":"京都大学農学部演習林事務室","kana":"きょうとだいがくのうがくぶえんしゅうりんじむしつ","category":"学校","subcategory":"建築物","type_guess":"校舎","type_guess_confidence":"low","period":"昭和前","pref":"京都府","address":"京都府京都市左京区北白川追分町","lat":35.03118827,"lng":135.78542664,"geo_status":"db","era":"昭和6","year":1931,"year_source":"db","year_min":1931,"year_max":1931,"year_label":null,"structure":"木造平屋建，瓦葺，建築面積438㎡","structure_material":"木造平屋建","registered":"1998.09.02(平成10.09.02)","register_no":"26 － 0022","desc":"大倉三郎の設計。スパニッシュ瓦葺，ベランダをめぐらしたバンガロー風の木造建築で，ベランダ天井の意匠などモダニズムの清新さ溢れる作品に仕上がっている。京大北部構内の独特の農村的景観形成にも大きく寄与している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000741"},{"id":"00000595","register_sub_id":"101","register_pk":"101585","name":"京都大学農学部表門及び門衛所","kana":"きょうとだいがくのうがくぶおもてもんおよびもんえいじょ","category":"学校","subcategory":"建築物","type_guess":"正門","type_guess_confidence":"low","period":"大正","pref":"京都府","address":"京都府京都市左京区北白川追分町","lat":35.02974921,"lng":135.78548307,"geo_status":"db","era":"大正13","year":1924,"year_source":"db","year_min":1924,"year_max":1924,"year_label":null,"structure":"鉄筋コンクリート造平屋建，瓦葺，建築面積17㎡","structure_material":"鉄筋コンクリート造平屋建","registered":"1998.07.23(平成10.07.23)","register_no":"26 － 0017","desc":"分離派建築会に参加した森田慶一の秀作で，通用口の尖頭アーチなど楽友会館と共通するディテールが認められる。ドイツ表現派のモチーフを採りながら，日本瓦を載せた薄い屋根が頂部を明確に水平に区切って節度を与え，全体意匠を品格あるものに仕立てている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000595"},{"id":"00001920","register_sub_id":"101","register_pk":"102910","name":"京都大学本部構内正門（旧第三高等中学校正門）","kana":"きょうとだいがくほんぶこうないせいもん（きゅうだいさんこうとうちゅうがっこうせいもん）","category":"学校","subcategory":"その他工作物","type_guess":"正門","type_guess_confidence":"high","period":"明治","pref":"京都府","address":"京都府京都市左京区吉田本町","lat":35.02539028,"lng":135.78089186,"geo_status":"db","era":"明治26","year":1893,"year_source":"db","year_min":1893,"year_max":1893,"year_label":null,"structure":"石造、間口3.3m、片側通用門及び左右袖壁付","structure_material":"石造","registered":"2000.10.18(平成12.10.18)","register_no":"26 － 0069","desc":"京都大学キャンパスの中枢をなす本部の正門。当キャンパス内で最初期の建造物で，第三高等中学校正門として建設。門柱は石面と擬石面を交互に重ね，背面に大きな控えをとる。門柱の左右に石造袖塀を付け，西側に通用口を開ける。設計は山口半六と久留正道。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001920"},{"id":"00013584","register_sub_id":"101","register_pk":"504947","name":"光華女子学園旧正門及び石垣","kana":"こうかじょしがくえんきゅうせいもんおよびいしがき","category":"学校","subcategory":"その他工作物","type_guess":"正門","type_guess_confidence":"high","period":"昭和前","pref":"京都府","address":"京都府京都市右京区西京極野田町39","lat":34.995225,"lng":135.71915833,"geo_status":"db","era":"昭和16年頃","year":1941,"year_source":"db","year_min":1941,"year_max":1941,"year_label":null,"structure":"旧正門 鉄筋コンクリート造門柱、間口4.0m、両側脇門柱付 石垣 石造、総延長88m","structure_material":"旧正門 鉄筋コンクリート造門柱","registered":"2021.02.04(令和3.02.04)","register_no":"26 － 0612","desc":"西京極に位置する。東本願寺の大谷智子が開学した女子学園の正門。間口四メートルで石張の門柱両脇に脇門を構える。門柱の笠石は直方体の内部を刳り抜く独特な意匠。左右に伸びる石垣は延長八八メートルで表側は切石布積とし、上部を生垣として景観を形成。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013584"},{"id":"00013585","register_sub_id":"101","register_pk":"504948","name":"光華女子学園旧通用門及び石垣","kana":"こうかじょしがくえんきゅうつうようもんおよびいしがき","category":"学校","subcategory":"その他工作物","type_guess":"正門","type_guess_confidence":"low","period":"昭和前","pref":"京都府","address":"京都府京都市右京区西京極野田町39","lat":34.99521944,"lng":135.71809722,"geo_status":"db","era":"昭和16年頃","year":1941,"year_source":"db","year_min":1941,"year_max":1941,"year_label":null,"structure":"旧通用門 石造門柱、間口2.6m、脇門柱付、石垣 石造、総延長20m","structure_material":"旧通用門 石造門柱","registered":"2021.02.04(令和3.02.04)","register_no":"26 － 0613","desc":"通用門は間口二・六メートルの石造門柱の西脇に脇門がつくが、脇門はコンクリートで閉塞されている。両脇に伸びる石垣の延長は二〇メートルで正門石垣同様上部を生垣とする。正門石垣とともに学校敷地周囲の景観を形成し、歴史ある女子学園のよすがを伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013585"},{"id":"00010835","register_sub_id":"101","register_pk":"201670","name":"紫明会館","kana":"しめいかいかん","category":"学校","subcategory":"建築物","type_guess":"記念館・資料室","type_guess_confidence":"low","period":"昭和前","pref":"京都府","address":"京都府京都市北区小山南大野町1-3他","lat":35.039643,"lng":135.756289,"geo_status":"db","era":"昭和7","year":1932,"year_source":"db","year_min":1932,"year_max":1932,"year_label":null,"structure":"鉄筋コンクリート造3階建、建築面積335㎡","structure_material":"鉄筋コンクリート造3階建","registered":"2015.11.17(平成27.11.17)","register_no":"26 ‐ 0491","desc":"京都府師範学校の同窓会館として、紫明通に面して建てられた鉄筋コンクリート造三階建。外壁はスタッコ塗でアーチ窓を並べ、パラペット頂部をスペイン瓦葺、内外の細部をアール・デコ風意匠で飾る。講堂や和室を有するなど社会教育目的の建築的特徴を備える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010835"},{"id":"00004991","register_sub_id":"101","register_pk":"105981","name":"同志社アーモスト館","kana":"どうししゃあーもすとかん","category":"学校","subcategory":"建築物","type_guess":"記念館・資料室","type_guess_confidence":"low","period":"昭和前","pref":"京都府","address":"京都府京都市上京区今出川通烏丸東入相国寺門前町632","lat":35.03010835,"lng":135.76255728,"geo_status":"db","era":"昭和7","year":1932,"year_source":"db","year_min":1932,"year_max":1932,"year_label":null,"structure":"鉄筋コンクリート造地上3階地下1階建、スレート葺、建築面積343㎡","structure_material":"鉄筋コンクリート造地上3階地下1階建","registered":"2005.11.10(平成17.11.10)","register_no":"26 － 0200","desc":"構内ほぼ中央で西面して建つ。桁行２２ｍ，梁間１２ｍのＲＣ造３階建，平入で，南面にサンルームを張出し，大型の腰折れ屋根には煙突や屋根窓を左右対称に配す。外装煉瓦張で，隅部では竜山石を算木積状に張るなど，材料を丁寧に使い分け華やかさを演出する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004991"},{"id":"00006539","register_sub_id":"101","register_pk":"107522","name":"同志社啓明館西館","kana":"どうししゃけいめいかんにしかん","category":"学校","subcategory":"建築物","type_guess":"記念館・資料室","type_guess_confidence":"low","period":"大正","pref":"京都府","address":"京都府京都市上京区今出川通烏丸東入玄武町602-1","lat":35.029812,"lng":135.762497,"geo_status":"db","era":"大正4","year":1915,"year_source":"db","year_min":1915,"year_max":1915,"year_label":null,"structure":"煉瓦及び鉄筋コンクリート造4階建、スレート葺、建築面積153㎡、渡廊下付","structure_material":"煉瓦及び鉄筋コンクリート造4階建","registered":"2007.07.31(平成19.07.31)","register_no":"26 － 0257","desc":"図書館書庫として建設。煉瓦造及びＲＣ造４階建で，切妻屋根をスレート葺とする。本館から延びる煉瓦造２階建の渡廊下が接続する。両側面には２階以上を一連に扱ったアーチ形窓を反復し，外観意匠の主題としている。両妻の壁面にも大きなアーチを描いている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006539"},{"id":"00006538","register_sub_id":"101","register_pk":"107521","name":"同志社啓明館本館","kana":"どうししゃけいめいかんほんかん","category":"学校","subcategory":"建築物","type_guess":"記念館・資料室","type_guess_confidence":"low","period":"大正","pref":"京都府","address":"京都府京都市上京区今出川通烏丸東入玄武町602-1","lat":35.029629,"lng":135.762573,"geo_status":"db","era":"大正9","year":1920,"year_source":"db","year_min":1920,"year_max":1920,"year_label":null,"structure":"煉瓦及び鉄筋コンクリート造5階建、スレート葺、建築面積406㎡","structure_material":"煉瓦及び鉄筋コンクリート造5階建","registered":"2007.07.31(平成19.07.31)","register_no":"26 － 0256","desc":"図書館本館として，書庫である西館の南に建設された。煉瓦造及びＲＣ造５階建で，スレート葺の切妻屋根とし，南西隅の塔は入口ホールと階段室とする。外壁にバットレスを現し，アーチ形窓枠はタイルで装飾する。入口上部の重厚なアーチ形庇など洗練された意匠。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006538"},{"id":"00001919","register_sub_id":"101","register_pk":"102909","name":"同志社女子大学栄光館","kana":"どうししゃじょしだいがくえいこうかん","category":"学校","subcategory":"建築物","type_guess":"記念館・資料室","type_guess_confidence":"low","period":"昭和前","pref":"京都府","address":"京都府京都市上京区今出川通烏丸東入玄武町602-1","lat":35.029728,"lng":135.764267,"geo_status":"db","era":"昭和7","year":1932,"year_source":"db","year_min":1932,"year_max":1932,"year_label":null,"structure":"鉄筋コンクリート造地上2階一部3階地下1階建、瓦葺、建築面積1637㎡、塔屋付","structure_material":"鉄筋コンクリート造地上2階一部3階地下1階建","registered":"2000.10.18(平成12.10.18)","register_no":"26 － 0068","desc":"ジェームズ館と静和館（現存せず）間に建造。ＲＣ造２階一部３階建。煉瓦造の前述２館との景観的統一性に配慮し煉瓦タイル張とする。中央玄関上の庇とテラス高欄に浅彫を施し，その上部に大規模な八角塔屋を冠す。玄関と背面に突出する講堂の内部意匠は秀逸。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001919"},{"id":"00001918","register_sub_id":"101","register_pk":"102908","name":"同志社女子大学ジェームズ館","kana":"どうししゃじょしだいがくじぇーむずかん","category":"学校","subcategory":"建築物","type_guess":"記念館・資料室","type_guess_confidence":"low","period":"大正","pref":"京都府","address":"京都府京都市上京区今出川通烏丸東入玄武町602-1","lat":35.02962096,"lng":135.76364518,"geo_status":"db","era":"大正2","year":1913,"year_source":"db","year_min":1913,"year_max":1913,"year_label":null,"structure":"煉瓦造地上2階地下1階建、瓦葺、建築面積697㎡","structure_material":"煉瓦造地上2階地下1階建","registered":"2000.10.18(平成12.10.18)","register_no":"26 － 0067","desc":"明治末期に始まるキャンパス内校舎改築時に，Ｗ・ジェームズ夫人の寄付により建設。煉瓦造２階建，桟瓦葺で正面玄関に歯飾をあしらった櫛形ペディメントを構える。カルフォルニアの民家建築を参考にしたと伝わる。栄光館と同じく武田五一の設計。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001918"},{"id":"00001334","register_sub_id":"101","register_pk":"102324","name":"福知山市立惇明小学校本館","kana":"ふくちやましりつじゅんめいしょうがっこうほんかん","category":"学校","subcategory":"建築物","type_guess":"記念館・資料室","type_guess_confidence":"low","period":"昭和前","pref":"京都府","address":"京都府福知山市字内記21","lat":35.29658973,"lng":135.124832,"geo_status":"db","era":"昭和12","year":1937,"year_source":"db","year_min":1937,"year_max":1937,"year_label":null,"structure":"木造・鉄骨造2階建、鉄板葺、建築面積755㎡","structure_material":"木造・鉄骨造2階建","registered":"1999.10.14(平成11.10.14)","register_no":"26 － 0050","desc":"木造を主体としつつ梁・小屋組に鉄骨を用いた２階建の学校建築。装飾要素は少なく，特に正面入口横と２階隅部の大小の丸窓と連続窓にモダニズム建築の影響が見られ，２階全体を占める講堂は光に溢れる空間となっている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001334"},{"id":"00006142","register_sub_id":"101","register_pk":"107126","name":"平安女学院昭和館","kana":"へいあんじょがくいんしょうわかん","category":"学校","subcategory":"建築物","type_guess":"記念館・資料室","type_guess_confidence":"low","period":"昭和前","pref":"京都府","address":"京都府京都市上京区室町通下立売下る武衛陣町220","lat":35.01976,"lng":135.758087,"geo_status":"db","era":"昭和4","year":1929,"year_source":"db","year_min":1929,"year_max":1929,"year_label":null,"structure":"鉄骨鉄筋コンクリート造2階一部3階建、建築面積975㎡、半地階付","structure_material":"鉄骨鉄筋コンクリート造2階一部3階建","registered":"2007.05.15(平成19.05.15)","register_no":"26 － 0242","desc":"敷地北西隅に建ち。間口１８ｍ，奥行５５ｍの規模で，鉄骨鉄筋コンクリート造２階一部３階建とする。半地下部分に講堂，１階に職員室，２階に教室，３階にピアノ室を設ける。外壁を１階モルタル塗，２階煉瓦タイル貼とする。昭和初期のＳＲＣ造の学校建築。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006142"},{"id":"00004140","register_sub_id":"101","register_pk":"105130","name":"平安女学院明治館","kana":"へいあんじょがくいんめいじかん","category":"学校","subcategory":"建築物","type_guess":"記念館・資料室","type_guess_confidence":"low","period":"明治","pref":"京都府","address":"京都府京都市上京区下立売通室町東入五町目町178-2","lat":35.01952676,"lng":135.75875555,"geo_status":"db","era":"明治27","year":1894,"year_source":"db","year_min":1894,"year_max":1894,"year_label":null,"structure":"煉瓦造2階建、瓦葺、建築面積370㎡","structure_material":"煉瓦造2階建","registered":"2004.06.09(平成16.06.09)","register_no":"26 － 0166","desc":"平安女学院の現在地への移転に際して建てられた校舎建築。煉瓦造の南北棟，桟瓦葺，切妻造３棟を並べ，妻面はダッチ・ゲイブルを持ち特色ある外観をつくる。設計はＡ・Ｎ・ハンセル。我国におけるクイーン・アン・リバイバル様式の最初期の事例である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004140"},{"id":"00004816","register_sub_id":"101","register_pk":"105806","name":"智頭町立山形小学校校舎","kana":"ちづちょうりつやまがたしょうがっこうこうしゃ","category":"学校","subcategory":"建築物","type_guess":"校舎","type_guess_confidence":"high","period":"昭和前","pref":"鳥取県","address":"鳥取県八頭郡智頭町大字郷原238","lat":35.26405949,"lng":134.27601016,"geo_status":"db","era":"昭和17","year":1942,"year_source":"db","year_min":1942,"year_max":1942,"year_label":null,"structure":"木造2階建、鉄板葺、建築面積1061㎡","structure_material":"木造2階建","registered":"2005.07.12(平成17.07.12)","register_no":"31 － 0091","desc":"町中心部から東方を流れる北股川の右岸に位置する。桁行８１ｍ，梁間１０ｍの長大な木造２階建で，鉄板葺，平入，外装下見板張とする。簡素ながら，西面全長にわたり窓を連続させるなど，水平性を強調したデザインが特徴的。山間部に良好に残る近代木造校舎。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004816"},{"id":"00000085","register_sub_id":"101","register_pk":"101075","name":"いなさ会館（旧島根県立第三中学校講堂）","kana":"いなさかいかん（きゅうしまねけんりつだいさんちゅうがっこうこうどう）","category":"学校","subcategory":"建築物","type_guess":"講堂","type_guess_confidence":"high","period":"明治","pref":"島根県","address":"島根県出雲市大社町北荒木1473","lat":35.38145165,"lng":132.70312718,"geo_status":"db","era":"明治35","year":1902,"year_source":"db","year_min":1902,"year_max":1902,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積324㎡","structure_material":"木造平屋建","registered":"1996.12.20(平成8.12.20)","register_no":"32 － 0004","desc":"旧制中学校の講堂として建てられ，開口部の上げ下げ窓や下見板張りとする外観は，擬洋風様式でまとめあげる。昭和５５年に現在地に移築されたが，同時に解体された旧校舎の玄関ポーチが組み込まれ，思い出の校舎として一体的に保存活用されている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000085"},{"id":"00000548","register_sub_id":"101","register_pk":"101538","name":"旧田所小学校講堂","kana":"きゅうたどころしょうがっこうこうどう","category":"学校","subcategory":"建築物","type_guess":"講堂","type_guess_confidence":"high","period":"昭和前","pref":"島根県","address":"島根県邑智郡邑南町大字下亀谷210","lat":34.85028054,"lng":132.51950408,"geo_status":"db","era":"昭和3","year":1928,"year_source":"db","year_min":1928,"year_max":1928,"year_label":null,"structure":"木造平屋建，瓦葺，建築面積395㎡","structure_material":"木造平屋建","registered":"1998.04.21(平成10.04.21)","register_no":"32 － 0010","desc":"入母屋の大屋根を架す典型的な小学校講堂建築。側面出入口の腰折れ型の庇，妻面開口部枠の扁平アーチ，妻飾りなどに大正昭和期木造建築の特徴が示されている。瑞穂町教育の歴史を物語る施設として，卒業生のみならず多くの町民から親しまれている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000548"},{"id":"00016603","register_sub_id":"101","register_pk":"574965","name":"旧吉田村尋常高等小学校講堂（吉田町生涯学習交流館）","kana":"きゅうよしだむらじんじょうこうとうしょうがっこうこうどう（よしだちょうしょうがいがくしゅうこうりゅうかん）","category":"学校","subcategory":"建築物","type_guess":"講堂","type_guess_confidence":"high","period":"昭和前","pref":"島根県","address":"島根県雲南市吉田町吉田1082-8","lat":35.28778861,"lng":132.90037778,"geo_status":"db","era":"昭和12年／平成6年移築","year":1937,"year_source":"db","year_min":1937,"year_max":1937,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積475㎡","structure_material":"木造平屋建","registered":"2026.02.10(令和8.02.10)","register_no":"32 - 0222","desc":"市街地中心部に位置する旧小学校講堂。平屋建切妻造妻入桟瓦葺で北に半切妻造玄関を張出す。外壁下見板張で腰は竪板張とし両側面に控壁を設ける。内部はトラスを用いた無柱の大空間で天井を折上げ、飾縁で軽快にみせる。旧小学校の歴史を伝えるモダンな講堂。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00016603"},{"id":"00006090","register_sub_id":"101","register_pk":"107075","name":"島根大学旧奥谷宿舎（旧制松江高等学校外国人宿舎）","kana":"しまねだいがくきゅうおくだにしゅくしゃ（きゅうせいまつえこうとうがっこうがいこくじんしゅくしゃ）","category":"学校","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"島根県","address":"島根県松江市奥谷町140","lat":35.481041,"lng":133.053772,"geo_status":"db","era":"大正13","year":1924,"year_source":"db","year_min":1924,"year_max":1924,"year_label":null,"structure":"木造2階建、瓦葺、建築面積94㎡","structure_material":"木造2階建","registered":"2007.05.15(平成19.05.15)","register_no":"32 － 0046","desc":"松江城よりほぼ７００ｍ北方に位置する。正面９ｍ，奥行１４ｍ規模，南側を半切妻とした木造２階建で，正面２階の張り出し部分を玄関ポーチの柱で支える。１階下見板張，２階モルタル塗仕上げとし，２連及び３連の連続窓を四周に配する瀟洒な住宅建築。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006090"},{"id":"00006092","register_sub_id":"101","register_pk":"107077","name":"島根大学正門（旧制松江高等学校正門）","kana":"しまねだいがくせいもん（きゅうせいまつえこうとうがっこうせいもん）","category":"学校","subcategory":"その他工作物","type_guess":"正門","type_guess_confidence":"high","period":"大正","pref":"島根県","address":"島根県松江市西川津町1060","lat":35.484669,"lng":133.06813,"geo_status":"db","era":"大正13／昭和45移築","year":1924,"year_source":"db","year_min":1924,"year_max":1924,"year_label":null,"structure":"石造門柱4基、間口16m","structure_material":"石造門柱4基","registered":"2007.05.15(平成19.05.15)","register_no":"32 － 0047","desc":"市街地東北部に位置する島根大学の正門で，南面して構える。方１．２ｍ，高さ２．１ｍ規模の門柱を間口１６ｍで配し，両脇には高さ１．７ｍの袖柱を添え，いずれも花崗岩で築く。頂部を十字形平面で象り，全体にセセッション風のデザインをあしらうのが特徴的。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006092"},{"id":"00006010","register_sub_id":"101","register_pk":"106995","name":"赤磐市吉井郷土資料館（旧仁堀尋常高等小学校本館）","kana":"あかいわしよしいきょうどしりょうかん（きゅうにぼりじんじょうこうとうしょうがっこうほんかん）","category":"学校","subcategory":"建築物","type_guess":"記念館・資料室","type_guess_confidence":"high","period":"昭和前","pref":"岡山県","address":"岡山県赤磐市周匝136","lat":34.91838288,"lng":134.09180807,"geo_status":"db","era":"昭和2／昭和59移築改造","year":1927,"year_source":"db","year_min":1927,"year_max":1927,"year_label":null,"structure":"木造2階建、鉄板葺、建築面積199㎡","structure_material":"木造2階建","registered":"2007.05.15(平成19.05.15)","register_no":"33 － 0153","desc":"市東北部の旧吉井町役場に隣接して建つ。桁行２２ｍ，梁間９．１ｍ規模，寄棟造，平入の木造２階建。外壁を下見板張とドイツ壁で仕上げ，正面中央に懸魚付の駒形破風と玄関ポーチ，端部には表現主義的意匠の通用口を設けるスティックスタイルの校舎建築。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006010"},{"id":"00008567","register_sub_id":"101","register_pk":"134963","name":"岡山県立岡山朝日高等学校（旧第六高等学校）柔道場","kana":"おかやまけんりつおかやまあさひこうとうがっこう（きゅうだいろくこうとうがっこう）じゅうどうじょう","category":"学校","subcategory":"建築物","type_guess":"体育館","type_guess_confidence":"high","period":"大正","pref":"岡山県","address":"岡山県岡山市中区古京町2-1241-1","lat":34.66028747,"lng":133.94550434,"geo_status":"db","era":"大正8年／昭和63年・平成19年改修","year":1919,"year_source":"db","year_min":1919,"year_max":1919,"year_label":null,"structure":"木造平屋建、鉄板葺、建築面積241㎡","structure_material":"木造平屋建","registered":"2011.01.26(平成23.01.26)","register_no":"33 － 0235","desc":"校地の東寄りに建ち、桁行一八メートル梁間一三メートル、木造平屋建、切妻造妻入鉄板葺である。煉瓦基礎に建ち、外壁は簓子下見板張で、当初から方杖で支持する。小屋は洋小屋とし、床組にバネを装置して弾力をもたせる。大正期の柔道場の好例である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008567"},{"id":"00008570","register_sub_id":"101","register_pk":"134966","name":"岡山県立岡山朝日高等学校（旧第六高等学校）正門及び石積","kana":"おかやまけんりつおかやまあさひこうとうがっこう（きゅうだいろくこうとうがっこう）せいもんおよびいしづみ","category":"学校","subcategory":"その他工作物","type_guess":"正門","type_guess_confidence":"high","period":"明治","pref":"岡山県","address":"岡山県岡山市中区古京町2-80-2他","lat":34.66113924,"lng":133.94265448,"geo_status":"db","era":"明治33年／昭和前期・平成元年改修","year":1900,"year_source":"db","year_min":1900,"year_max":1900,"year_label":null,"structure":"正門 石造、間口4.1m、両側通用門付 石積 石造、延長1032m","structure_material":"正門 石造","registered":"2011.01.26(平成23.01.26)","register_no":"33 － 0238","desc":"校地西辺の正門と、校地を囲う石積である。正門は矩形の石柱を四本たて、中央間四・二メートル脇間一・五メートルとし、各間に木扉を開く。石積は総延長一、〇三二メートル高さ一・五メートル、割石の谷積と布積とする。伝統校に相応しい風格を醸している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008570"},{"id":"00008569","register_sub_id":"101","register_pk":"134965","name":"岡山県立岡山朝日高等学校（旧第六高等学校）西書庫","kana":"おかやまけんりつおかやまあさひこうとうがっこう（きゅうだいろくこうとうがっこう）にししょこ","category":"学校","subcategory":"建築物","type_guess":"図書館","type_guess_confidence":"high","period":"昭和前","pref":"岡山県","address":"岡山県岡山市中区古京町2-200-2","lat":34.66146583,"lng":133.94363947,"geo_status":"db","era":"昭和5年","year":1930,"year_source":"db","year_min":1930,"year_max":1930,"year_label":null,"structure":"鉄筋コンクリート造3階建、建築面積82㎡","structure_material":"鉄筋コンクリート造3階建","registered":"2011.01.26(平成23.01.26)","register_no":"33 － 0237","desc":"校地北辺に東書庫と並び建つ。東西八・七メートル南北九・六メートル、鉄筋コンクリート造三階建、陸屋根である。煉瓦造の基礎のほか、各階に付したコーニスや矩形の連続窓など、東書庫の外観と調和が図られ、東書庫とともに旧制第六高等学校の伝統を伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008569"},{"id":"00008568","register_sub_id":"101","register_pk":"134964","name":"岡山県立岡山朝日高等学校（旧第六高等学校）東書庫","kana":"おかやまけんりつおかやまあさひこうとうがっこう（きゅうだいろくこうとうがっこう）ひがししょこ","category":"学校","subcategory":"建築物","type_guess":"図書館","type_guess_confidence":"high","period":"明治","pref":"岡山県","address":"岡山県岡山市中区古京町2-200-2","lat":34.66145046,"lng":133.94374194,"geo_status":"db","era":"明治35年／昭和前期・昭和中期・昭和60年改修","year":1902,"year_source":"db","year_min":1902,"year_max":1902,"year_label":null,"structure":"煉瓦造3階建、瓦葺、建築面積68㎡","structure_material":"煉瓦造3階建","registered":"2011.01.26(平成23.01.26)","register_no":"33 － 0236","desc":"校地北辺に西書庫と並び建つ。桁行九・三メートル梁間七・四メートル、煉瓦造三階建、切妻造桟瓦葺である。煉瓦基礎に建ち、小屋は洋小屋を組む。外壁はモルタル塗で、各階にコーニスを三筋付け、均等に配した窓に鉄格子をはめる。堅牢なつくりの書庫である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008568"},{"id":"00006410","register_sub_id":"101","register_pk":"107393","name":"岡山県立倉敷天城高等学校武道場（旧岡山県天城中学校武道場）","kana":"おかやまけんりつくらしきあまきこうとうがっこうぶどうじょう（きゅうおかやまけんあまきちゅうがっこうぶどうじょう）","category":"学校","subcategory":"建築物","type_guess":"体育館","type_guess_confidence":"high","period":"昭和前","pref":"岡山県","address":"岡山県倉敷市藤戸町天城269","lat":34.56395137,"lng":133.8111891,"geo_status":"db","era":"昭和2","year":1927,"year_source":"db","year_min":1927,"year_max":1927,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積307㎡","structure_material":"木造平屋建","registered":"2007.10.02(平成19.10.02)","register_no":"33 － 0160","desc":"校地中央に建つ木造平屋建。桁行１５間、梁間６間の入母屋造桟瓦葺。東正面の切妻造玄関とその上部の千鳥破風を豕叉首で飾る。外壁は真壁造白漆喰塗で、腰を竪板張とする。内部は南北に分けて柔道場と剣道場とする。造作も丁寧な武道場の標準的事例である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006410"},{"id":"00006409","register_sub_id":"101","register_pk":"107392","name":"岡山県立高松農業高等学校資料館（旧岡山県立農学校堆肥舎）","kana":"おかやまけんりつたかまつのうぎょうこうとうがっこうしりょうかん（きゅうおかやまけんりつのうがっこうたいひしゃ）","category":"学校","subcategory":"建築物","type_guess":"記念館・資料室","type_guess_confidence":"high","period":"明治","pref":"岡山県","address":"岡山県岡山市北区高松原古才336-2","lat":34.68310625,"lng":133.82058806,"geo_status":"db","era":"明治42","year":1909,"year_source":"db","year_min":1909,"year_max":1909,"year_label":null,"structure":"煉瓦造平屋建、茅葺、建築面積99㎡","structure_material":"煉瓦造平屋建","registered":"2007.10.02(平成19.10.02)","register_no":"33 － 0159","desc":"校地の南寄り中央に建つ煉瓦造平屋建である。桁行１１ｍ、梁間９．１ｍの南北棟で、トラス小屋の入母屋造茅葺とする。煉瓦外壁はフランス積で、各面２箇所にバットレスをつけ、壁上部を漆喰塗とする。虫籠窓風高窓は後の改造。煉瓦造に茅葺屋根の特異な建物。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006409"},{"id":"00006039","register_sub_id":"101","register_pk":"107024","name":"岡山大学医学部正門（旧岡山医科大学正門）","kana":"おかやまだいがくいがくぶせいもん（きゅうおかやまいかだいがくせいもん）","category":"学校","subcategory":"その他工作物","type_guess":"正門","type_guess_confidence":"high","period":"大正","pref":"岡山県","address":"岡山県岡山市北区鹿田町2-5-1","lat":34.65252462,"lng":133.91983642,"geo_status":"db","era":"大正11","year":1922,"year_source":"db","year_min":1922,"year_max":1922,"year_label":null,"structure":"煉瓦造門柱4基、間口10m","structure_material":"煉瓦造門柱4基","registered":"2007.05.15(平成19.05.15)","register_no":"33 － 0152","desc":"岡山大学鹿田キャンパスの正門で，照明を含め高さ３．６ｍ，門口６．２ｍで配された門柱と，両脇の高さ２．６ｍの袖柱からなる。いずれも基礎に花崗岩を用い，柱身を赤煉瓦の小口積とし，柱頭部にセセッション風のデザインをあしらう華やかなつくり。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006039"},{"id":"00006038","register_sub_id":"101","register_pk":"107023","name":"岡山大学医学部門衛所（旧岡山医科大学門衛所）","kana":"おかやまだいがくいがくぶもんえいじょ（きゅうおかやまいかだいがくもんえいじょ）","category":"学校","subcategory":"建築物","type_guess":"正門","type_guess_confidence":"low","period":"大正","pref":"岡山県","address":"岡山県岡山市北区鹿田町2-5-1","lat":34.65252909,"lng":133.91970166,"geo_status":"db","era":"大正11","year":1922,"year_source":"db","year_min":1922,"year_max":1922,"year_label":null,"structure":"木造平屋建、スレート葺、建築面積22㎡","structure_material":"木造平屋建","registered":"2007.05.15(平成19.05.15)","register_no":"33 － 0151","desc":"市街地の南方に位置する岡山大学鹿田キャンパスの正門脇に建つ。桁行６．４ｍ，梁間３．６ｍ規模の寄棟造，平屋建で，外壁は下見板張，腰縦板張，玄関廻りには上下窓を配する。変形六角平面の屋根で，鱗形の天然スレートを葺く特徴ある外観とする。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006038"},{"id":"00012638","register_sub_id":"101","register_pk":"367932","name":"旧赤坂尋常高等小学校校舎","kana":"きゅうあかさかじんじょうこうとうしょうがっこうこうしゃ","category":"学校","subcategory":"建築物","type_guess":"校舎","type_guess_confidence":"high","period":"明治","pref":"岡山県","address":"岡山県赤磐市馬屋字上山1434-7","lat":34.735298,"lng":133.993317,"geo_status":"geocoded","era":"明治43年／昭和48年移築","year":1910,"year_source":"db","year_min":1910,"year_max":1910,"year_label":null,"structure":"木造2階建、瓦葺、建築面積268㎡","structure_material":"木造2階建","registered":"2018.11.02(平成30.11.02)","register_no":"33 － 0303","desc":"久米南町から移築した、もと赤坂尋常高等小学校の校舎。寄棟造二階建で、左手に平屋棟を附属する。正面玄関のアーチ状装飾や小壁の襷状意匠、屋根上に円形窓を載せる外観、独特な形式をもつトラスの小屋組等の特徴が、県技師・江川三郎八の関与を窺わせる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012638"},{"id":"00001941","register_sub_id":"101","register_pk":"102931","name":"倉敷市歴史民俗資料館（旧倉敷幼稚園園舎）","kana":"くらしきしれきしみんぞくしりょうかん（きゅうくらしきようちえんえんしゃ）","category":"学校","subcategory":"建築物","type_guess":"校舎","type_guess_confidence":"high","period":"大正","pref":"岡山県","address":"岡山県倉敷市西中新田655","lat":34.58470021,"lng":133.77397907,"geo_status":"db","era":"大正4／昭和56移築","year":1915,"year_source":"db","year_min":1915,"year_max":1915,"year_label":null,"structure":"木造平屋建、瓦一部銅板葺、建築面積307㎡","structure_material":"木造平屋建","registered":"2000.10.18(平成12.10.18)","register_no":"33 － 0051","desc":"倉敷幼稚園園舎として造られ現在市役所東側に建つ，木造平屋建の洋風建築。東西に延びる正面棟の背面に，天井が放射状に分割された八角棟が接続。屋根構成が変化に富む。外壁真壁漆喰塗，腰縦及び横板張とし，玄関上部の切妻破風に桜花文様レリーフを掲げる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001941"},{"id":"00010235","register_sub_id":"101","register_pk":"198068","name":"金光学園中学高等学校記念講堂","kana":"こんこうがくえんちゅうがくこうとうがっこうきねんこうどう","category":"学校","subcategory":"建築物","type_guess":"講堂","type_guess_confidence":"high","period":"明治","pref":"岡山県","address":"岡山県浅口市金光町占見新田1350-6","lat":34.545169,"lng":133.62491,"geo_status":"db","era":"明治37／昭和31移築","year":1904,"year_source":"db","year_min":1904,"year_max":1904,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積238㎡","structure_material":"木造平屋建","registered":"2014.10.07(平成26.10.07)","register_no":"33 － 0266","desc":"校地南辺に建ち、寄棟造の屋根に半円形屋根窓を設ける。外壁は下見板張で腰を竪板張、小壁は漆喰塗とし、軒を雲形持送で飾る。内部柱は柱頭に円弧形方杖を付ける。天井は二重折上格天井で、灯具釣元は三重に折上げる。和洋の意匠を巧みに融和させた明治期の学舎。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010235"},{"id":"00002311","register_sub_id":"101","register_pk":"103301","name":"閑谷学校資料館","kana":"しずたにがっこうしりょうかん","category":"学校","subcategory":"建築物","type_guess":"記念館・資料室","type_guess_confidence":"high","period":"明治","pref":"岡山県","address":"岡山県備前市閑谷740","lat":34.796993,"lng":134.21817,"geo_status":"db","era":"明治38","year":1905,"year_source":"db","year_min":1905,"year_max":1905,"year_label":null,"structure":"木造2階建、瓦葺、建築面積762㎡","structure_material":"木造2階建","registered":"2001.08.28(平成13.08.28)","register_no":"33 － 0054","desc":"私立閑谷中学校本館として建設。寄棟造，桟瓦葺の木造２階建校舎で，両翼を南前方に張り出したコの字型平面をとり，北側に廊下，その両端に階段を配する。外観は木骨を表に現したスティックスタイルをとる。設計は，遷喬小学校と同じ岡山県工師の江川三郎八。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002311"},{"id":"00006130","register_sub_id":"101","register_pk":"107114","name":"ノートルダム清心女子大学ノートルダムホール東棟","kana":"のーとるだむせいしんじょしだいがくのーとるだむほーるひがしとう","category":"学校","subcategory":"建築物","type_guess":"校舎","type_guess_confidence":"low","period":"昭和前","pref":"岡山県","address":"岡山県岡山市北区伊福町2-16-9","lat":34.672749,"lng":133.91713,"geo_status":"db","era":"昭和4","year":1929,"year_source":"db","year_min":1929,"year_max":1929,"year_label":null,"structure":"鉄筋コンクリート造3階建、建築面積2176㎡","structure_material":"鉄筋コンクリート造3階建","registered":"2007.07.31(平成19.07.31)","register_no":"33 － 0155","desc":"本館の東に位置し，東面するＲＣ造３階建。正面は色ガラスの入った小窓を整然と並べ，鐘楼には丸柱を配す等，幾何学的なデザイン要素がふんだんに採り入れられている。礼拝堂の天井は緩やかなアーチを描く。室内の照明器具はオリジナル。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006130"},{"id":"00006129","register_sub_id":"101","register_pk":"107113","name":"ノートルダム清心女子大学ノートルダムホール本館","kana":"のーとるだむせいしんじょしだいがくのーとるだむほーるほんかん","category":"学校","subcategory":"建築物","type_guess":"記念館・資料室","type_guess_confidence":"low","period":"昭和前","pref":"岡山県","address":"岡山県岡山市北区伊福町2-16-9","lat":34.67250824,"lng":133.91627842,"geo_status":"db","era":"昭和4","year":1929,"year_source":"db","year_min":1929,"year_max":1929,"year_label":null,"structure":"鉄筋コンクリート造2階建、建築面積3250㎡","structure_material":"鉄筋コンクリート造2階建","registered":"2007.07.31(平成19.07.31)","register_no":"33 － 0154","desc":"敷地南に配置され南面する。南東角に正面玄関が設けられている。ＲＣ造２階建で，中庭を囲むロの字型の平面計画。外観は，連続する庇により水平線を強調し，柱と連続する窓枠は規律的なデザインである。昭和初期のモダニズム建築の好例である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006129"},{"id":"00003470","register_sub_id":"101","register_pk":"104460","name":"小野公民館（旧小野尋常小学校校舎）","kana":"おのこうみんかん（きゅうおのじんじょうしょうがっこうこうしゃ）","category":"学校","subcategory":"建築物","type_guess":"校舎","type_guess_confidence":"high","period":"昭和前","pref":"広島県","address":"広島県神石郡神石高原町大字小野900-2","lat":34.83411197,"lng":133.31080468,"geo_status":"db","era":"昭和4","year":1929,"year_source":"db","year_min":1929,"year_max":1929,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積761㎡","structure_material":"木造平屋建","registered":"2003.07.01(平成15.07.01)","register_no":"34 － 0042","desc":"昭和４年建築の木造小学校校舎。平屋建で，東西に長い長方形平面を持つ。北側に２.１ｍ幅の廊下を通し，南側に教室を配する。中央に玄関を開くとともに，西端に児童昇降所を設ける。木造校舎は県内でも数少なく，昭和初期学校建築の有様を伝える建築である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003470"},{"id":"00008571","register_sub_id":"101","register_pk":"134967","name":"旧大草尋常高等小学校奉安殿","kana":"きゅうおおぐさじんじょうこうとうしょうがっこうほうあんでん","category":"学校","subcategory":"建築物","type_guess":"記念館・資料室","type_guess_confidence":"high","period":"昭和前","pref":"広島県","address":"広島県三原市大和町大草9068-1","lat":34.50016852,"lng":132.95728535,"geo_status":"db","era":"昭和11年／昭和44年改修","year":1936,"year_source":"db","year_min":1936,"year_max":1936,"year_label":null,"structure":"石造平屋建、建築面積2.9㎡、基壇付","structure_material":"石造平屋建","registered":"2011.01.26(平成23.01.26)","register_no":"34 － 0104","desc":"小学校庭隅の石積基壇上に建ち、間口一・七メートル奥行一・七メートル、石造である。切石布積の躯体前面にたつドリス式風の円柱で庇を受ける。隅反りのある屋根石上に宝珠状の頂石を載せ、四方に切妻の小屋根を置く。独特な形式になる石造奉安殿。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008571"},{"id":"00000707","register_sub_id":"101","register_pk":"101697","name":"広島大学附属中・高等学校講堂（旧制広島高等学校講堂）","kana":"ひろしまだいがくふぞくちゅう・こうとうがっこうこうどう（きゅうせいひろしまこうとうがっこうこうどう）","category":"学校","subcategory":"建築物","type_guess":"講堂","type_guess_confidence":"high","period":"昭和前","pref":"広島県","address":"広島県広島市南区翠1-1-1","lat":34.3719472,"lng":132.46552774,"geo_status":"db","era":"昭和2","year":1927,"year_source":"db","year_min":1927,"year_max":1927,"year_label":null,"structure":"鉄筋コンクリート造２階建，建築面積507㎡","structure_material":"鉄筋コンクリート造２階建","registered":"1998.09.02(平成10.09.02)","register_no":"34 － 0016","desc":"旧制広島高等学校の講堂として昭和２年に建築されたもので，正面に車寄が付く。外壁は石造風に仕上げ，１・２階通しの柱型付きとし軒先に装飾タイルを貼る。全体として様式建築を簡素にまとめた意匠構成となるが，仕事は丁寧で技術的に見るべき点は多い。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000707"},{"id":"00002439","register_sub_id":"101","register_pk":"103429","name":"福山誠之館高等学校記念館","kana":"ふくやませいしかんこうとうがっこうきねんかん","category":"学校","subcategory":"建築物","type_guess":"記念館・資料室","type_guess_confidence":"high","period":"江戸","pref":"広島県","address":"広島県福山市木之庄町6-822-1","lat":34.502331,"lng":133.360901,"geo_status":"db","era":"安政1／昭和8増築／昭和44移築","year":1854,"year_source":"db","year_min":1854,"year_max":1854,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積73㎡","structure_material":"木造平屋建","registered":"2001.10.12(平成13.10.12)","register_no":"34 － 0036","desc":"福山誠之館は安政元年に創設された福山藩校である。昭和８年に当初の学堂の玄関部分と新築の主屋を組み合わせ，記念館として開館した。近世の雄大な唐破風玄関と近代の入母屋造の主屋が巧みに融合した構成で，和風の意匠と造形の連続性をよく示している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002439"},{"id":"00008579","register_sub_id":"101","register_pk":"134975","name":"普光寺観音堂（旧大田尋常高等小学校奉安殿）","kana":"ふこうじかんのんどう（きゅうおおたじんじょうこうとうしょうがっこうほうあんでん）","category":"学校","subcategory":"建築物","type_guess":"記念館・資料室","type_guess_confidence":"high","period":"昭和前","pref":"広島県","address":"広島県世羅郡世羅町大字井折288","lat":34.59491481,"lng":133.04132549,"geo_status":"db","era":"昭和10年／昭和21年移築","year":1935,"year_source":"db","year_min":1935,"year_max":1935,"year_label":null,"structure":"石造平屋建、建築面積3.3㎡、基壇付","structure_material":"石造平屋建","registered":"2011.01.26(平成23.01.26)","register_no":"34 － 0112","desc":"境内南寄りの山門西側に築いた亀甲石積の基壇上に建ち、間口、奥行とも一・八メートル、石造である。切石布積の躯体前面にたてたドリス式風の円柱で庇を受ける。屋根は三段構成で、下段は下端を蛇腹状につくり、上段は切妻形で、妻面に蔓状の紋様を彫る。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008579"},{"id":"00000098","register_sub_id":"101","register_pk":"101088","name":"明倫小学校本館","kana":"めいりんしょうがっこうほんかん","category":"学校","subcategory":"建築物","type_guess":"記念館・資料室","type_guess_confidence":"low","period":"昭和前","pref":"山口県","address":"山口県萩市大字江向602","lat":34.40921795,"lng":131.39976123,"geo_status":"db","era":"昭和10","year":1935,"year_source":"db","year_min":1935,"year_max":1935,"year_label":null,"structure":"木造2階建、瓦葺、建築面積1104㎡","structure_material":"木造2階建","registered":"1996.12.20(平成8.12.20)","register_no":"35 － 0001","desc":"隣接する史跡有備館に合わせた意匠で，外壁は１階部分は押しぶち下見板張り，２階部分は白漆喰塗りである。屋根のフランス瓦や連続する窓の意匠が特徴的で，モダニズムへの萌芽も見られる。既にほとんど失われてしまった木造学校建築の好例。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000098"},{"id":"00001293","register_sub_id":"101","register_pk":"102283","name":"山口県立山口高等学校記念館（旧制山口高等学校講堂）","kana":"やまぐちけんりつやまぐちこうとうがっこうきねんかん（きゅうせいやまぐちこうとうがっこうこうどう）","category":"学校","subcategory":"建築物","type_guess":"講堂","type_guess_confidence":"high","period":"大正","pref":"山口県","address":"山口県山口市糸米1-9-1","lat":34.17482707,"lng":131.46670514,"geo_status":"db","era":"大正11","year":1922,"year_source":"db","year_min":1922,"year_max":1922,"year_label":null,"structure":"木造２階建，銅板葺，建築面積371㎡","structure_material":"木造２階建","registered":"1999.08.23(平成11.08.23)","register_no":"35 － 0024","desc":"高等学校令に基づきつくられた学校建築。マンサード屋根の主体部の正面左右に三角屋根の塔屋が取り付いた形で，幾何学的な装飾を多用した点によく時代の特徴があらわれている。文部省建築課山口出張所が建設したもので，同省技師の谷口鼎が担当した。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001293"},{"id":"00010689","register_sub_id":"101","register_pk":"201263","name":"徳島県立城北高等学校人形会館","kana":"とくしまけんりつじょうほくこうとうがっこうにんぎょうかいかん","category":"学校","subcategory":"建築物","type_guess":"記念館・資料室","type_guess_confidence":"low","period":"昭和中","pref":"徳島県","address":"徳島県徳島市北田宮4-13-6","lat":34.08888,"lng":134.531294,"geo_status":"db","era":"昭和40年","year":1965,"year_source":"db","year_min":1965,"year_max":1965,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積282㎡","structure_material":"木造平屋建","registered":"2015.08.04(平成27.08.04)","register_no":"36－0125","desc":"人形浄瑠璃の盛んな当地で、学校に併設された本格的な芝居小屋。舞台は二段構成とし、右手前に太夫座を張出す。舞台上部に葡萄棚を設けて舞台裏に控室などを配し、客席は升席とする。海鼠壁と赤塗の高欄ともに特徴的な外観になり、伝統芸能の伝承拠点となる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010689"},{"id":"00001142","register_sub_id":"101","register_pk":"102132","name":"粟島海洋記念館研修棟（旧粟島海員学校教室）","kana":"あわしまかいようきねんかんけんしゅうとう（きゅうあわしまかいいんがっこうきょうしつ）","category":"学校","subcategory":"建築物","type_guess":"校舎","type_guess_confidence":"high","period":"大正","pref":"香川県","address":"香川県三豊市詫間町粟島1541","lat":34.26823731,"lng":133.63134796,"geo_status":"db","era":"大正9","year":1920,"year_source":"db","year_min":1920,"year_max":1920,"year_label":null,"structure":"木造平屋建，瓦葺，建築面積471㎡","structure_material":"木造平屋建","registered":"1999.06.07(平成11.06.07)","register_no":"37 － 0022","desc":"資料室に隣接して敷地の西側に建つ南北棟の建物で，片廊下型の教室棟を研修施設としたもの。外観は，概ね本館に意匠をあわせた形だが，正面にみせた妻飾や出入口上部に付けた庇の意匠を本館正面とかえるなどの工夫もみられる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001142"},{"id":"00001141","register_sub_id":"101","register_pk":"102131","name":"粟島海洋記念館資料館（旧粟島海員学校教室）","kana":"あわしまかいようきねんかんしりょうかん（きゅうあわしまかいいんがっこうきょうしつ）","category":"学校","subcategory":"建築物","type_guess":"校舎","type_guess_confidence":"high","period":"大正","pref":"香川県","address":"香川県三豊市詫間町粟島1541","lat":34.26837193,"lng":133.63156509,"geo_status":"db","era":"大正9","year":1920,"year_source":"db","year_min":1920,"year_max":1920,"year_label":null,"structure":"木造平屋建，瓦葺，建築面積280㎡","structure_material":"木造平屋建","registered":"1999.06.07(平成11.06.07)","register_no":"37 － 0021","desc":"本館の西に隣接して建つ木造平屋建，片廊下型平面の教室棟を海洋関係の資料展示室としたもの。海から見える正面側は本館と意匠をあわせ，校庭に面した背面側の意匠は簡略なものとしている。本館とともに海員学校正面の堂々とした構えをつくっている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001141"},{"id":"00001143","register_sub_id":"101","register_pk":"102133","name":"粟島海洋記念館武道場（旧粟島海員学校柔道場）","kana":"あわしまかいようきねんかんぶどうじょう（きゅうあわしまかいいんがっこうじゅうどうじょう）","category":"学校","subcategory":"建築物","type_guess":"体育館","type_guess_confidence":"high","period":"大正","pref":"香川県","address":"香川県三豊市詫間町粟島1541","lat":34.2686846,"lng":133.63140007,"geo_status":"db","era":"大正9","year":1920,"year_source":"db","year_min":1920,"year_max":1920,"year_label":null,"structure":"木造平屋建，瓦葺，建築面積151㎡","structure_material":"木造平屋建","registered":"1999.06.07(平成11.06.07)","register_no":"37 － 0023","desc":"本館の後方に中庭を挟んで建つ木造平屋建の建物。本館等に比較すると外観の意匠はきわめて簡素だが，小屋組にトラスを用い内部に柱を立てないなど，柔道場にふさわしいつくりになる。往時の海員養成の様子を物語る施設のひとつとして貴重な存在である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001143"},{"id":"00001140","register_sub_id":"101","register_pk":"102130","name":"粟島海洋記念館本館（旧粟島海員学校本館）","kana":"あわしまかいようきねんかんほんかん（きゅうあわしまかいいんがっこうほんかん）","category":"学校","subcategory":"建築物","type_guess":"記念館・資料室","type_guess_confidence":"high","period":"大正","pref":"香川県","address":"香川県三豊市詫間町粟島1541","lat":34.26854129,"lng":133.63178005,"geo_status":"db","era":"大正9","year":1920,"year_source":"db","year_min":1920,"year_max":1920,"year_label":null,"structure":"木造２階建，瓦葺，建築面積208㎡","structure_material":"木造２階建","registered":"1999.06.07(平成11.06.07)","register_no":"37 － 0020","desc":"粟島海員学校は明治３０年に我が国最初の海員養成校として開校した。現在残る校舎等は大正９年の建築。本館は木造２階建で，２階を講堂にあてる。粟島のシンボル的な存在で，外壁の下見板や正面中央にみせたハーフティンバーの妻飾等に特徴がある。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001140"},{"id":"00001144","register_sub_id":"101","register_pk":"102134","name":"粟島海洋記念館門柱（旧粟島海員学校門柱）","kana":"あわしまかいようきねんかんもんちゅう（きゅうあわしまかいいんがっこうもんちゅう）","category":"学校","subcategory":"その他工作物","type_guess":"正門","type_guess_confidence":"high","period":"大正","pref":"香川県","address":"香川県三豊市詫間町粟島1541","lat":34.26840884,"lng":133.63193855,"geo_status":"db","era":"大正9","year":1920,"year_source":"db","year_min":1920,"year_max":1920,"year_label":null,"structure":"石造，高さ109cm","structure_material":"石造","registered":"1999.06.07(平成11.06.07)","register_no":"37 － 0024","desc":"地元産の花崗岩を用いてつくった門柱で，本館の正面に２本並んで建つ。４隅に傾斜を付けた大面を取り，上部中央を球状に仕上げるなど幾何学的なモチーフを用いた意匠は，よく時代の特徴をあらわしている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001144"},{"id":"00015514","register_sub_id":"101","register_pk":"533529","name":"香川県立善通寺第一高等学校（旧私立善通寺高等女学校）旧正門","kana":"かがわけんりつぜんつうじだいいちこうとうがっこう（きゅうしりつぜんつうじこうとうじょがっこう）きゅうせいもん","category":"学校","subcategory":"その他工作物","type_guess":"正門","type_guess_confidence":"high","period":"大正","pref":"香川県","address":"香川県善通寺市文京町一丁目1391","lat":34.22699722,"lng":133.78918333,"geo_status":"db","era":"大正11年","year":1922,"year_source":"db","year_min":1922,"year_max":1922,"year_label":null,"structure":"煉瓦造、間口4.0m、左右脇門付","structure_material":"煉瓦造","registered":"2025.08.06(令和7.08.06)","register_no":"37 - 0493","desc":"ＪＲ善通寺駅南方に位置する旧女学校の正門。大正11年の陸軍特別大演習統監部設置を記念して建てた門で、親柱の東西脇に脇柱を配し、柱はいずれも花崗岩基礎に煉瓦を積上げ、頂部は花崗岩製の帯飾と笠石を載せる。煉瓦造の重厚な外観で地域の歴史を伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015514"},{"id":"00000100","register_sub_id":"101","register_pk":"101090","name":"丸亀高校記念館（旧香川県立高松尋常中学校丸亀分校本館）","kana":"まるがめこうこうきねんかん（きゅうかがわけんりつたかまつじんじょうちゅうがっこうまるがめぶんこうほんかん）","category":"学校","subcategory":"建築物","type_guess":"記念館・資料室","type_guess_confidence":"high","period":"明治","pref":"香川県","address":"香川県丸亀市6-1","lat":34.28270339,"lng":133.7974882,"geo_status":"db","era":"明治26","year":1893,"year_source":"db","year_min":1893,"year_max":1893,"year_label":null,"structure":"木造2階建、瓦葺、建築面積694㎡","structure_material":"木造2階建","registered":"1996.12.20(平成8.12.20)","register_no":"37 － 0001","desc":"香川県立の尋常中学校分校の本館として建設されたもので，２階を講堂，１階を職員室としていた。下見板，正面の玄関ポーチ，ペディメントのついた上下窓等を用いた洋風の意匠をもつ建物で，明治期の学校建築の技術の水準の高さをよく示している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000100"},{"id":"00000746","register_sub_id":"101","register_pk":"101736","name":"愛媛大学附属中学校講堂（旧旧制松山高等学校講堂）","kana":"えひめだいがくふぞくちゅうがっこうこうどう（きゅうきゅうせいまつやまこうとうがっこうこうどう）","category":"学校","subcategory":"建築物","type_guess":"講堂","type_guess_confidence":"high","period":"大正","pref":"愛媛県","address":"愛媛県松山市持田町1-5-22","lat":33.84227013,"lng":132.78212241,"geo_status":"db","era":"大正11","year":1922,"year_source":"db","year_min":1922,"year_max":1922,"year_label":null,"structure":"木造２階建，建築面積501㎡","structure_material":"木造２階建","registered":"1998.09.02(平成10.09.02)","register_no":"38 － 0002","desc":"文部省営繕による直轄学校の講堂建築。文部技師の鳥海他郎の設計と推定される。２階にギャラリーを設けるなど設備面では定型的であるが，外見はドイツ下見により穏健なルネサンス風に仕上げ，トスカナ式オーダーの大きな車寄に特徴をもたせている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000746"},{"id":"00013765","register_sub_id":"101","register_pk":"505327","name":"西条栄光幼稚園園舎","kana":"さいじょうえいこうようちえんえんしゃ","category":"学校","subcategory":"建築物","type_guess":"校舎","type_guess_confidence":"high","period":"昭和中","pref":"愛媛県","address":"愛媛県西条市明屋敷字旧陣屋内236-17他","lat":33.92116111,"lng":133.17899444,"geo_status":"db","era":"昭和26年","year":1951,"year_source":"db","year_min":1951,"year_max":1951,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積351㎡","structure_material":"木造平屋建","registered":"2021.02.26(令和3.02.26)","register_no":"38 － 153","desc":"礼拝堂の西に渡廊下で接続。平屋建切妻造桟瓦葺。長大な平面に保育室等を配する。南の園庭に面した屋外廊下は円柱と矩形の開口が並び、天井と面一とした軒の高窓からは自然光が入る、木造モダニズムの佳品。隣接三棟で意匠を微妙に変えた設計に妙味がある。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013765"},{"id":"00014542","register_sub_id":"101","register_pk":"513956","name":"高知追手前高等学校本館","kana":"こうちおうてまえこうとうがっこうほんかん","category":"学校","subcategory":"建築物","type_guess":"記念館・資料室","type_guess_confidence":"low","period":"昭和前","pref":"高知県","address":"高知県高知市追手筋二丁目2-10","lat":33.56160833,"lng":133.53649444,"geo_status":"db","era":"昭和6年／同中期改修","year":1931,"year_source":"db","year_min":1931,"year_max":1931,"year_label":null,"structure":"鉄筋コンクリート造3階建、建築面積1，758㎡、塔屋付","structure_material":"鉄筋コンクリート造3階建","registered":"2023.02.27(令和5.02.27)","register_no":"39 - 0308","desc":"高知城に通じる追手筋に面して建つ。鉄筋コンクリート造三階建で、左右に翼部を設け、屋上に奉安所を構える。武田五一指導のもと県営繕技師高崎正隆が設計を担当。左右対称の外観の中央に宝形屋根の高塔が聳える記念碑的な外観。県下を代表する近代学校建築。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014542"},{"id":"00015394","register_sub_id":"101","register_pk":"532518","name":"旧九州芸術工科大学音響特殊施設棟","kana":"きゅうきゅうしゅうげいじゅつこうかだいがくおんきょうとくしゅしせつとう","category":"学校","subcategory":"建築物","type_guess":"校舎","type_guess_confidence":"low","period":"昭和後","pref":"福岡県","address":"福岡県福岡市南区塩原四丁目9-1","lat":33.56023611,"lng":130.43085,"geo_status":"db","era":"昭和45年／令和3年改修","year":1970,"year_source":"db","year_min":1970,"year_max":1970,"year_label":null,"structure":"鉄筋コンクリート造3階建、建築面積372㎡、渡廊下付","structure_material":"鉄筋コンクリート造3階建","registered":"2025.03.13(令和7.03.13)","register_no":"40 - 0234","desc":"広場南東に位置し、無響室など配する音響工学専門施設。設計は香山壽夫＋環境設計学科。鉄筋コンクリート造3階建、躯体打放仕上。二階レベルで中庭状広場と接続。画像特殊施設棟の立面を反転、渡廊下を挟んで左右対称の外観とし、二棟で広場東面を構成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015394"},{"id":"00015393","register_sub_id":"101","register_pk":"532517","name":"旧九州芸術工科大学画像特殊施設棟","kana":"きゅうきゅうしゅうげいじゅつこうかだいがくがぞうとくしゅしせつとう","category":"学校","subcategory":"建築物","type_guess":"校舎","type_guess_confidence":"low","period":"昭和後","pref":"福岡県","address":"福岡県福岡市南区塩原四丁目9-1","lat":33.56045556,"lng":130.43086389,"geo_status":"db","era":"昭和45年／令和元年改修","year":1970,"year_source":"db","year_min":1970,"year_max":1970,"year_label":null,"structure":"鉄筋コンクリート造3階建、建築面積275㎡","structure_material":"鉄筋コンクリート造3階建","registered":"2025.03.13(令和7.03.13)","register_no":"40 - 0233","desc":"広場の北東に位置し写真スタジオなど配する画像工学専門施設。設計は香山壽夫＋環境設計学科。鉄筋コンクリート造3階建、躯体打放仕上。二階レベルで中庭状の広場に接続。中央玄関上部の壁面を浅く窪ませてバルコニーとし、左右対称の均整取れた外観の校舎。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015393"},{"id":"00015391","register_sub_id":"101","register_pk":"532515","name":"旧九州芸術工科大学環境画像棟","kana":"きゅうきゅうしゅうげいじゅつこうかだいがくかんきょうがぞうとう","category":"学校","subcategory":"建築物","type_guess":"校舎","type_guess_confidence":"low","period":"昭和後","pref":"福岡県","address":"福岡県福岡市南区塩原四丁目9-1","lat":33.56063889,"lng":130.43052778,"geo_status":"db","era":"昭和45年／平成26年・令和元年改修","year":1970,"year_source":"db","year_min":1970,"year_max":1970,"year_label":null,"structure":"鉄筋コンクリート造6階建、建築面積808㎡、広場付","structure_material":"鉄筋コンクリート造6階建","registered":"2025.03.13(令和7.03.13)","register_no":"40 - 0231","desc":"西鉄大橋駅東方にある大学校舎。設計は香山壽夫＋環境設計学科。鉄筋コンクリート造6階建、躯体打放仕上。下層を吹抜ラウンジ、上層をバルコニーとした階段状の立面が２階レベルの中庭状広場と巧みに調和。香山によるキャンパス計画の中心的な校舎の一つ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015391"},{"id":"00015392","register_sub_id":"101","register_pk":"532516","name":"旧九州芸術工科大学工業音響棟","kana":"きゅうきゅうしゅうげいじゅつこうかだいがくこうぎょうおんきょうとう","category":"学校","subcategory":"建築物","type_guess":"校舎","type_guess_confidence":"low","period":"昭和後","pref":"福岡県","address":"福岡県福岡市南区塩原四丁目9-1","lat":33.56009167,"lng":130.43048333,"geo_status":"db","era":"昭和45年／令和3年改修","year":1970,"year_source":"db","year_min":1970,"year_max":1970,"year_label":null,"structure":"鉄筋コンクリート造6階建、建築面積813㎡","structure_material":"鉄筋コンクリート造6階建","registered":"2025.03.13(令和7.03.13)","register_no":"40 - 0232","desc":"環境画像棟と中庭状の広場を挟み正対して建つ校舎。設計は香山壽夫＋環境設計学科。鉄筋コンクリート造6階建、躯体打放仕上。上層をセットバックした変化のある外観で二階レベルで広場に接続する。環境画像棟と同意匠で対峙し、壮麗な広場景観をつくる校舎。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015392"},{"id":"00015395","register_sub_id":"101","register_pk":"532519","name":"旧九州芸術工科大学工作工房","kana":"きゅうきゅうしゅうげいじゅつこうかだいがくこうさくこうぼう","category":"学校","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和後","pref":"福岡県","address":"福岡県福岡市南区塩原四丁目9-1","lat":33.56035278,"lng":130.43014167,"geo_status":"db","era":"昭和45年／平成26年改修","year":1970,"year_source":"db","year_min":1970,"year_max":1970,"year_label":null,"structure":"鉄筋コンクリート造3階一部2階建、建築面積486㎡","structure_material":"鉄筋コンクリート造3階一部2階建","registered":"2025.03.13(令和7.03.13)","register_no":"40 - 0235","desc":"広場の南西に位置し、デッサンや木工用の作業棟。設計は香山壽夫＋環境設計学科。鉄筋コンクリート造3階建、躯体打放仕上。2階レベルで接続する広場から正面渡廊下の下を潜り抜けて小広場に至る。中央を見通す左右対称の均整取れた外観で広場の一角を構成。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015395"},{"id":"00014543","register_sub_id":"101","register_pk":"513957","name":"旧九州帝国大学工学部本館","kana":"きゅうきゅうしゅうていこくだいがくこうがくぶほんかん","category":"学校","subcategory":"建築物","type_guess":"記念館・資料室","type_guess_confidence":"low","period":"昭和前","pref":"福岡県","address":"福岡県福岡市東区箱崎六丁目10-1","lat":33.62278611,"lng":130.42535,"geo_status":"db","era":"昭和5年／昭和63年改修","year":1930,"year_source":"db","year_min":1930,"year_max":1930,"year_label":null,"structure":"鉄筋コンクリート造一部鉄骨鉄筋コンクリート造地上3階地下1階建、建築面積3，152㎡、塔屋付","structure_material":"鉄筋コンクリート造一部鉄骨鉄筋コンクリート造地上3階地下1階建","registered":"2023.02.27(令和5.02.27)","register_no":"40 - 0207","desc":"鉄筋コンクリート造３階地下１階建の校舎。中央塔屋の両脇には半円筒の張出を付し、外壁はスクラッチタイル貼で腰を石張、上層はアール付の役物タイルで陰影をつける。内部には意匠に凝った会議室や大講義室が残る。城塞のような重厚な外観がシンボリック。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014543"},{"id":"00015103","register_sub_id":"101","register_pk":"529381","name":"旧九州帝国大学正門及び塀","kana":"きゅうきゅうしゅうていこくだいがくせいもんおよびへい","category":"学校","subcategory":"その他工作物","type_guess":"正門","type_guess_confidence":"high","period":"大正","pref":"福岡県","address":"福岡県福岡市東区箱崎六丁目10-1","lat":33.62141667,"lng":130.42561389,"geo_status":"db","era":"大正3年／大正13年移築、令和5年改修","year":1914,"year_source":"db","year_min":1914,"year_max":1914,"year_label":null,"structure":"門柱 煉瓦造、間口4.5m、脇門付 塀 コンクリートブロック造及び煉瓦造、総延長41m","structure_material":"門柱 煉瓦造","registered":"2024.08.15(令和6.08.15)","register_no":"40 - 0225","desc":"通りに東面して建つ旧正門と両脇に続く塀。正門門柱は煉瓦造の角柱で頂部を古典主義的意匠の花崗岩で飾り、左右は控柱を立て通用口とする。塀はコンクリートブロック造壁体に石製笠木を置き、煉瓦造の柵柱を立てる。大学を象徴する重厚な外観の正門及び塀。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015103"},{"id":"00014545","register_sub_id":"101","register_pk":"513959","name":"旧九州帝国大学本部建築課棟","kana":"きゅうきゅうしゅうていこくだいがくほんぶけんちくかとう","category":"学校","subcategory":"建築物","type_guess":"校舎","type_guess_confidence":"low","period":"大正","pref":"福岡県","address":"福岡県福岡市東区箱崎六丁目10-1","lat":33.62196389,"lng":130.42581111,"geo_status":"db","era":"大正14年／昭和40年・同48年改修","year":1925,"year_source":"db","year_min":1925,"year_max":1925,"year_label":null,"structure":"煉瓦造地上2階地下1階建、建築面積230㎡、塔屋付","structure_material":"煉瓦造地上2階地下1階建","registered":"2023.02.27(令和5.02.27)","register_no":"40 - 0209","desc":"工学部本館の南東に位置する煉瓦造２階地下1階建の建築課棟。西面中央を玄関として塔屋を載せ、内部は中廊下式平面とする。外壁は化粧煉瓦で、腰と軒をモルタル洗出仕上とし、塔屋の窓上部を石造アーチで飾る。均整の取れた外観は事務室棟と共通する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014545"},{"id":"00014544","register_sub_id":"101","register_pk":"513958","name":"旧九州帝国大学本部事務室棟","kana":"きゅうきゅうしゅうていこくだいがくほんぶじむしつとう","category":"学校","subcategory":"建築物","type_guess":"校舎","type_guess_confidence":"low","period":"大正","pref":"福岡県","address":"福岡県福岡市東区箱崎六丁目10-1","lat":33.62243056,"lng":130.42605833,"geo_status":"db","era":"大正14年／昭和39年・同43年改修","year":1925,"year_source":"db","year_min":1925,"year_max":1925,"year_label":null,"structure":"煉瓦造2階建、建築面積1，276㎡、塔屋付","structure_material":"煉瓦造2階建","registered":"2023.02.27(令和5.02.27)","register_no":"40 - 0208","desc":"工学部本館と相対する煉瓦造２階建の事務室棟。西面中央の玄関に塔屋を載せ、内部は中廊下式平面で、中央階段上部を吹抜とする。外壁は化粧煉瓦で、腰と上層はモルタル洗出で石張風。窓廻りやアーチの要所を花崗岩で飾る。整った外観は校舎の時代差を示す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014544"},{"id":"00014546","register_sub_id":"101","register_pk":"513960","name":"旧九州帝国大学門衛所","kana":"きゅうきゅうしゅうていこくだいがくもんえいじょ","category":"学校","subcategory":"建築物","type_guess":"正門","type_guess_confidence":"low","period":"大正","pref":"福岡県","address":"福岡県福岡市東区箱崎六丁目10-1","lat":33.62155,"lng":130.42561944,"geo_status":"db","era":"大正3年／同13年移築、昭和33年・平成24年改修","year":1914,"year_source":"db","year_min":1914,"year_max":1914,"year_label":null,"structure":"煉瓦造平屋建、スレート葺、建築面積29㎡","structure_material":"煉瓦造平屋建","registered":"2023.02.27(令和5.02.27)","register_no":"40 - 0210","desc":"工学部本館の南に位置する煉瓦造平屋建、寄棟造スレート葺の門衛所。Ｌ字型平面で南を玄関とし、内部は事務室と休憩室の２室とする。玄関上部はブロークンペディメントで飾り、窓廻りは要所の花崗岩で意匠を凝らす。装飾豊かな外観で箱崎地区最古の門衛所。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014546"},{"id":"00013666","register_sub_id":"101","register_pk":"504896","name":"久留米大学本館","kana":"くるめだいがくほんかん","category":"学校","subcategory":"建築物","type_guess":"記念館・資料室","type_guess_confidence":"low","period":"昭和前","pref":"福岡県","address":"福岡県久留米市旭町67","lat":33.32870833,"lng":130.51114167,"geo_status":"db","era":"昭和4年／昭和58年改修","year":1929,"year_source":"db","year_min":1929,"year_max":1929,"year_label":null,"structure":"鉄筋コンクリート造3階建、陸屋根、建築面積1297㎡、西面・南面スロープ及び中庭階段付","structure_material":"鉄筋コンクリート造3階建","registered":"2021.02.04(令和3.02.04)","register_no":"40 － 0182","desc":"久留米城の東に位置。設計は松田昌平で施工は松田組。コの字形平面で、正面二階の中央に車寄玄関を設けロンバルティア帯で飾る。車寄上部を三連アーチ窓とし、両翼は三層を通した二連のアーチ枠を並べて窓を穿つ。ロマネスクを基調とした格調高い大学本館。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013666"},{"id":"00009080","register_sub_id":"101","register_pk":"162440","name":"筑紫女学園香風亭","kana":"ちくしじょがくえんこうふうてい","category":"学校","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和中","pref":"福岡県","address":"福岡県福岡市中央区警固2-24-3","lat":33.58267391,"lng":130.3889483,"geo_status":"db","era":"昭和30年／平成15年改修","year":1955,"year_source":"db","year_min":1955,"year_max":1955,"year_label":null,"structure":"木造平屋建、瓦葺一部銅板葺、建築面積123㎡","structure_material":"木造平屋建","registered":"2011.10.28(平成23.10.28)","register_no":"40 － 0071","desc":"洗心庵の南に位置する。南北棟の切妻造桟瓦葺で、軒先を銅板葺とし、北面に角屋を付設する。十畳の主座敷と十五畳の次の間を中心に縁を廻らして下屋とし、三畳台目の茶室や納戸、玄関を付ける。装飾を廃した開放的な書院座敷で、品格ある雰囲気を有する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009080"},{"id":"00009078","register_sub_id":"101","register_pk":"162438","name":"筑紫女学園洗心庵","kana":"ちくしじょがくえんせんしんあん","category":"学校","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"福岡県","address":"福岡県福岡市中央区警固2-24-3","lat":33.58280176,"lng":130.38904012,"geo_status":"db","era":"昭和15年／平成15年改修","year":1940,"year_source":"db","year_min":1940,"year_max":1940,"year_label":null,"structure":"木造平屋建、瓦葺一部銅板葺、建築面積38㎡","structure_material":"木造平屋建","registered":"2011.10.28(平成23.10.28)","register_no":"40 － 0069","desc":"校地の東北隅に位置する。北に四畳半の茶室、南に六畳の水屋を配し、茶室には台目のトコを構え、水屋にも丸炉を切る。屋根は東西棟からＴ字型に南北棟が延び、妻などに土庇を付設する。丸太柱を多用し、外壁は漆喰仕上げとする。軽快で変化に富む外観をなす。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009078"},{"id":"00009079","register_sub_id":"101","register_pk":"162439","name":"筑紫女学園待合","kana":"ちくしじょがくえんまちあい","category":"学校","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"福岡県","address":"福岡県福岡市中央区警固2-24-3","lat":33.58275178,"lng":130.38914123,"geo_status":"db","era":"昭和15年／平成15年改修","year":1940,"year_source":"db","year_min":1940,"year_max":1940,"year_label":null,"structure":"木造平屋建、杉皮葺、建築面積1.4㎡","structure_material":"木造平屋建","registered":"2011.10.28(平成23.10.28)","register_no":"40 － 0070","desc":"洗心庵東南に位置する。桁行1.8メートル梁間南0.9メートル北0.6メートル、招屋根杉皮葺。丸太柱で側・背面を漆喰仕上げ真壁とし、南妻に下地窓を開ける。南北で妻壁の出を変え、座板は途中で折れ、杉板と竹を交互に張る。繊細なデザインの庭園建築。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009079"},{"id":"00001309","register_sub_id":"101","register_pk":"102299","name":"如蘭塾塾舎及び寄宿舎","kana":"じょらんじゅくじゅくしゃおよびきしゅくしゃ","category":"学校","subcategory":"建築物","type_guess":"寄宿舎","type_guess_confidence":"high","period":"昭和前","pref":"佐賀県","address":"佐賀県武雄市武雄町大字武雄4322","lat":33.18456286,"lng":130.02336345,"geo_status":"db","era":"昭和18頃","year":1943,"year_source":"db","year_min":1943,"year_max":1943,"year_label":null,"structure":"木造平屋建一部２階建，瓦葺，建築面積489㎡","structure_material":"木造平屋建一部２階建","registered":"1999.08.23(平成11.08.23)","register_no":"41 － 0012","desc":"中国子女の留学施設として実業家野中忠太が開設した如蘭塾の主要施設で、玄関及び教室等からなる東西棟の塾舎に、南北棟の寄宿舎棟がＬ型に取り付く。設計は当時満州で活躍していた遠藤新といわれ、凝灰岩を用いた玄関の親柱はライト風の独特の構えになる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001309"},{"id":"00014436","register_sub_id":"101","register_pk":"511425","name":"脊振小学校石門","kana":"せふりしょうがっこういしもん","category":"学校","subcategory":"その他工作物","type_guess":"正門","type_guess_confidence":"low","period":"大正","pref":"佐賀県","address":"佐賀県神埼市脊振町広滝字井ノ上574-1","lat":33.37722778,"lng":130.32740278,"geo_status":"db","era":"大正3年／昭和30年移築","year":1914,"year_source":"db","year_min":1914,"year_max":1914,"year_label":null,"structure":"石造、間口7.1m","structure_material":"石造","registered":"2022.10.31(令和4.10.31)","register_no":"41 - 0130","desc":"市北部の山間に所在する小学校の門。高さ四・三メートル、一・〇九メートル角の花崗岩江戸切り仕上の石柱を、間口７・１メートルに立てる。石材は裏山の石切り場で切り出し、大正天皇即位記念で村民有志が建設した。学校のシンボルで、稀に見る大きさの石門。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014436"},{"id":"00008074","register_sub_id":"101","register_pk":"128905","name":"旧波佐見町立中央小学校講堂兼公会堂","kana":"きゅうはさみちょうりつちゅうおうしょうがっこうこうどうけんこうかいどう","category":"学校","subcategory":"建築物","type_guess":"講堂","type_guess_confidence":"high","period":"昭和前","pref":"長崎県","address":"長崎県東彼杵郡波佐見町井石郷2191","lat":33.14201834,"lng":129.90762081,"geo_status":"db","era":"昭和12","year":1937,"year_source":"db","year_min":1937,"year_max":1937,"year_label":null,"structure":"木造平屋一部2階建、瓦葺、建築面積974㎡","structure_material":"木造平屋一部2階建","registered":"2010.01.15(平成22.01.15)","register_no":"42-0088","desc":"旧校庭の東端に建ち、建築面積９７４㎡、木造平屋一部２階建、屋根は東西を半切妻とし、セメント瓦を葺く。南北面に下屋を付け、外壁は下見板張とする。正面はペディメント付の玄関ポーチを設け、２階にベイウィンドゥ付の切妻屋根を張り出すなど意匠を凝らす。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008074"},{"id":"00006439","register_sub_id":"101","register_pk":"107422","name":"長崎大学(旧長崎高等商業学校）拱橋","kana":"ながさきだいがく（きゅうながさきこうとうしょうぎょうがっこう）こまねきばし","category":"学校","subcategory":"土木構造物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"長崎県","address":"長崎県長崎市片淵4-2-1","lat":32.758881,"lng":129.887405,"geo_status":"db","era":"明治36","year":1903,"year_source":"db","year_min":1903,"year_max":1903,"year_label":null,"structure":"石造単アーチ橋、橋長17m、幅員9.1m","structure_material":"石造単アーチ橋","registered":"2007.12.05(平成19.12.05)","register_no":"42 － 0069","desc":"長崎大学経済学部構内の西側を南北に流れる西山川に架かる。橋長１７ｍ、幅員９．１ｍの石造単アーチ橋。表面を平滑に仕上げた切石で欠円アーチをつくり、路面縦断面線形を直線状とするなど、近代的な外観を呈する。旧長崎高等商業学校創立当初から残る遺構。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006439"},{"id":"00006441","register_sub_id":"101","register_pk":"107424","name":"長崎大学経済学部倉庫（旧長崎高等商業学校倉庫）","kana":"ながさきだいがくけいざいがくぶそうこ（きゅうながさきこうとうしょうぎょうがっこうそうこ）","category":"学校","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"長崎県","address":"長崎県長崎市片淵4-2-1","lat":32.759724,"lng":129.88768,"geo_status":"db","era":"明治40","year":1907,"year_source":"db","year_min":1907,"year_max":1907,"year_label":null,"structure":"煉瓦造2階建、瓦葺、建築面積64㎡","structure_material":"煉瓦造2階建","registered":"2007.10.02(平成19.10.02)","register_no":"42 － 0067","desc":"長崎大学経済学部構内の西側に位置する。桁行９．０ｍ、梁間７．１ｍ規模の切妻造、桟瓦葺、妻入の煉瓦造２階建で、東面して建つ。基礎を花崗岩布積、壁面をイギリス積で築き、四周に縦長窓を配する。旧長崎高等商業学校の創立当初から残る唯一の建築物。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006441"},{"id":"00006440","register_sub_id":"101","register_pk":"107423","name":"長崎大学瓊林会館（旧長崎高等商業学校研究館）","kana":"ながさきだいがくけいりんかいかん（きゅうながさきこうとうしょうぎょうがっこうけんきゅうかん）","category":"学校","subcategory":"建築物","type_guess":"記念館・資料室","type_guess_confidence":"low","period":"大正","pref":"長崎県","address":"長崎県長崎市片淵4-2-1","lat":32.758743,"lng":129.88858,"geo_status":"db","era":"大正8","year":1919,"year_source":"db","year_min":1919,"year_max":1919,"year_label":null,"structure":"煉瓦造2階建、スレート葺、建築面積258㎡、車寄付","structure_material":"煉瓦造2階建","registered":"2007.10.02(平成19.10.02)","register_no":"42 － 0066","desc":"長崎大学経済学部構内の東側に位置する。桁行２２ｍ、梁間１２ｍ規模の寄棟造、スレート葺、平入の煉瓦造２階建で、西面して建つ。モルタル塗のゲーブル及び車寄を中心として縦長上下窓を四周に配した左右対称のつくりで、随所にセセッション風の装飾を施す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006440"},{"id":"00000109","register_sub_id":"101","register_pk":"101099","name":"九州学院高等学校講堂兼礼拝堂","kana":"きゅうしゅうがくいんこうとうがっこうこうどうけんれいはいどう","category":"学校","subcategory":"建築物","type_guess":"講堂","type_guess_confidence":"high","period":"大正","pref":"熊本県","address":"熊本県熊本市大江５-2-1","lat":32.79815841,"lng":130.72306627,"geo_status":"db","era":"大正13","year":1924,"year_source":"db","year_min":1924,"year_max":1924,"year_label":null,"structure":"鉄筋コンクリート造平屋建、瓦葺、建築面積525㎡","structure_material":"鉄筋コンクリート造平屋建","registered":"1996.12.20(平成8.12.20)","register_no":"43 － 0002","desc":"学校の設立者ブラウンを記念して建設された。教会と同様の三身廊式の平面を持ち，白い人造石の柱型と黒モルタルの壁を対比させた正面の意匠に特徴がある。我が国に多数の作品を残した米国人宣教師ヴォーリズの設計で，その作風の一端を示す好例である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000109"},{"id":"00000176","register_sub_id":"101","register_pk":"101166","name":"九州女学院高等学校本館","kana":"きゅうしゅうじょがくいんこうとうがっこうほんかん","category":"学校","subcategory":"建築物","type_guess":"記念館・資料室","type_guess_confidence":"low","period":"大正","pref":"熊本県","address":"熊本県熊本市黒髪3-12-16","lat":32.81974948,"lng":130.72293102,"geo_status":"db","era":"大正15","year":1926,"year_source":"db","year_min":1926,"year_max":1926,"year_label":null,"structure":"鉄筋コンクリート造地上2階（一部3階）地下1階建，建築面積1131㎡","structure_material":"鉄筋コンクリート造地上2階（一部3階）地下1階建","registered":"1997.05.07(平成9.05.07)","register_no":"43 － 0003","desc":"ミッション・スクールの本館で，小高い丘の上に立つＲＣ造の校舎である。設計は米人の建築家ヴォーゲル。正面の一段高い列柱と巨大な日本瓦の切妻屋根が特徴で，当時の学校建築等が洋風を基調としている中で細部まで和風の装いを保っている点は興味深い。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000176"},{"id":"00009244","register_sub_id":"101","register_pk":"164797","name":"京都大学理学研究科附属地球熱学研究施設火山研究センター（旧京都帝国大学阿蘇火山研究所）本館","kana":"きょうとだいがくりがくけんきゅうかふぞくちきゅうねつがくけんきゅうしせつかざんけんきゅうせんたー（きゅうきょうとていこくだいがくあそかざんけんきゅうじょ）ほんかん","category":"学校","subcategory":"建築物","type_guess":"校舎","type_guess_confidence":"low","period":"昭和前","pref":"熊本県","address":"熊本県阿蘇郡南阿蘇村河陽5280","lat":32.88547655,"lng":131.00656367,"geo_status":"db","era":"昭和4年","year":1929,"year_source":"db","year_min":1929,"year_max":1929,"year_label":null,"structure":"鉄筋コンクリート造6階建、建築面積681㎡","structure_material":"鉄筋コンクリート造6階建","registered":"2012.02.23(平成24.02.23)","register_no":null,"desc":"阿蘇山麓に建つ火山に関する研究や教育のための施設である。鉄筋コンクリート造、建築面積681平方メートルで、中央部を6階建の塔状とする。傾斜した外壁や異様に太い円柱など、随所に特異な意匠を用いる。昭和初期における日本建築界の様相の一端を示す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009244"},{"id":"00002324","register_sub_id":"101","register_pk":"103314","name":"熊本県立玉名高等学校正門","kana":"くまもとけんりつたまなこうとうがっこうせいもん","category":"学校","subcategory":"その他工作物","type_guess":"正門","type_guess_confidence":"high","period":"昭和前","pref":"熊本県","address":"熊本県玉名市中1853","lat":32.929993,"lng":130.548538,"geo_status":"db","era":"昭和12","year":1937,"year_source":"db","year_min":1937,"year_max":1937,"year_label":null,"structure":"鉄筋コンクリート造、間口5m、左右脇門及び袖塀付","structure_material":"鉄筋コンクリート造","registered":"2001.08.28(平成13.08.28)","register_no":"43 － 0048","desc":"ＪＲ鹿児島本線玉名駅から北へ向かう駅前通りの突き当たりに位置する。道路より退いて間口５ｍの門を開き，両脇塀にアーチ形の通用口を開ける。通用口上部に起り形のカーブをつけ，末端部は楠木を囲うように曲面状にするなど流動感のある造形に特徴がある。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002324"},{"id":"00002322","register_sub_id":"101","register_pk":"103312","name":"熊本県立玉名高等学校本館","kana":"くまもとけんりつたまなこうとうがっこうほんかん","category":"学校","subcategory":"建築物","type_guess":"記念館・資料室","type_guess_confidence":"low","period":"昭和前","pref":"熊本県","address":"熊本県玉名市中1853","lat":32.93063309,"lng":130.54879339,"geo_status":"db","era":"昭和12","year":1937,"year_source":"db","year_min":1937,"year_max":1937,"year_label":null,"structure":"鉄筋コンクリート造3階建、建築面積671㎡","structure_material":"鉄筋コンクリート造3階建","registered":"2001.08.28(平成13.08.28)","register_no":"43 － 0046","desc":"旧制玉名中学校本館として建設。鉄筋コンクリート造３階建のアールデコ建築で，正面東端寄りの時計塔頂部及び正面中央の玄関車寄部とその上部に装飾を効果的に集中させるデザインでまとめる。設計担当は名高工出身で熊本県学校営繕技師の近藤良馬。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002322"},{"id":"00002323","register_sub_id":"101","register_pk":"103313","name":"熊本県立玉名高等学校前庭池","kana":"くまもとけんりつたまなこうとうがっこうまえにわいけ","category":"学校","subcategory":"その他工作物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"熊本県","address":"熊本県玉名市中1853","lat":32.93036844,"lng":130.54845974,"geo_status":"db","era":"昭和12","year":1937,"year_source":"db","year_min":1937,"year_max":1937,"year_label":null,"structure":"コンクリート造、面積367㎡","structure_material":"コンクリート造","registered":"2001.08.28(平成13.08.28)","register_no":"43 － 0047","desc":"本館の南前庭に位置するコンクリート造，笠石付きの池で，水深約１ｍ，周長約５０ｍの半円形２池から成る。２池の間に通路を通しており，上から見ると「中」の字の形になる。３棟の校舎の玉字形配置に呼応して「玉中」を表現したものと伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002323"},{"id":"00000748","register_sub_id":"101","register_pk":"101738","name":"熊本大学医学部山崎記念館（旧熊本医科大学図書館）","kana":"くまもとだいがくいがくぶやまざききねんかん（きゅうくまもといかだいがくとしょかん）","category":"学校","subcategory":"建築物","type_guess":"図書館","type_guess_confidence":"high","period":"昭和前","pref":"熊本県","address":"熊本県熊本市本荘1-1-1","lat":32.79571569,"lng":130.71074758,"geo_status":"db","era":"昭和6","year":1931,"year_source":"db","year_min":1931,"year_max":1931,"year_label":null,"structure":"鉄筋コンクリート造２階建，建築面積446㎡","structure_material":"鉄筋コンクリート造２階建","registered":"1998.09.02(平成10.09.02)","register_no":"43 － 0012","desc":"熊本医科大学長兼教授山崎正董博士を記念した建物で，武田五一の設計になる。鉄筋コンクリート造２階建の図書館建築。２階開口部方立のデザインに特徴がある。箱形マッスの構成で建築形態をつくり，水平帯の意匠により全体に統一感を与えている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000748"},{"id":"00000747","register_sub_id":"101","register_pk":"101737","name":"熊本大学本部（旧熊本高等工業学校本館）","kana":"くまもとだいがくほんぶ（きゅうくまもとこうとうこうぎょうがっこうほんかん）","category":"学校","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"熊本県","address":"熊本県熊本市黒髪2-39-1","lat":32.81384557,"lng":130.72783116,"geo_status":"db","era":"大正13","year":1924,"year_source":"db","year_min":1924,"year_max":1924,"year_label":null,"structure":"鉄筋コンクリート造３階建，建築面積1038㎡","structure_material":"鉄筋コンクリート造３階建","registered":"1998.09.02(平成10.09.02)","register_no":"43 － 0011","desc":"創立時木造校舎の焼失後の再建校舎で，文部省直轄学校における鉄筋コンクリート造校舎の初期のものになる。設計担当は文部技師の長岡勇衛。柱型とセセッション風の柱頭飾りなどに鉄筋コンクリート建築に対する取組の跡がよく示されている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000747"},{"id":"00005211","register_sub_id":"101","register_pk":"106201","name":"熊本ルーテル学園神水幼稚園園舎","kana":"くまもとるーてるがくえんくわみずようちえんえんしゃ","category":"学校","subcategory":"建築物","type_guess":"校舎","type_guess_confidence":"high","period":"昭和前","pref":"熊本県","address":"熊本県熊本市神水1-633-2","lat":32.78462917,"lng":130.74123321,"geo_status":"db","era":"昭和4／昭和9頃・昭和40増改築","year":1929,"year_source":"db","year_min":1929,"year_max":1929,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積341㎡","structure_material":"木造平屋建","registered":"2005.12.26(平成17.12.26)","register_no":"43 － 0077","desc":"水前寺公園から南東に位置する敷地に東面して建つ。桁行２７ｍの切妻造，桟瓦葺で，玄関を中心として左右に張出部を設ける。開口部を広くとる，採光と換気に配慮したつくり。半円アーチ窓に対応させてむくりをつけた玄関の切妻屋根のおさまりが特徴的。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005211"},{"id":"00000231","register_sub_id":"101","register_pk":"101221","name":"京都大学理学部附属地球熱学研究施設","kana":"きょうとだいがくりがくぶふぞくちきゅうねつがくけんきゅうしせつ","category":"学校","subcategory":"建築物","type_guess":"校舎","type_guess_confidence":"low","period":"大正","pref":"大分県","address":"大分県別府市野口原3088-176","lat":33.284288,"lng":131.48568878,"geo_status":"db","era":"大正13","year":1924,"year_source":"db","year_min":1924,"year_max":1924,"year_label":null,"structure":"煉瓦造地上2階地下1階建棟屋付，建築面積510㎡","structure_material":"煉瓦造地上2階地下1階建棟屋付","registered":"1997.06.12(平成9.06.12)","register_no":"44 － 0006","desc":"中央部に塔屋を持つ煉瓦造の研究施設。平面はＬ字型である。設計は京大施設部の永瀬狂三。煉瓦の赤と石貼りの白との対照や、イオニア式を模した柱頭飾りを持つ特徴的な外観で、別府湾を見おろすシンボルとして親しまれている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000231"},{"id":"00012078","register_sub_id":"101","register_pk":"211019","name":"高原町民体育館分館","kana":"たかはるちょうみんたいいくかんぶんかん","category":"学校","subcategory":"建築物","type_guess":"体育館","type_guess_confidence":"high","period":"昭和前","pref":"宮崎県","address":"宮崎県西諸県郡高原町大字西麓338-2","lat":31.9281,"lng":131.007083,"geo_status":"db","era":"昭和11年／昭和40年代改修","year":1936,"year_source":"db","year_min":1936,"year_max":1936,"year_label":null,"structure":"木造平屋建、鉄板葺、建築面積980㎡","structure_material":"木造平屋建","registered":"2017.10.27(平成29.10.27)","register_no":"45-90","desc":"高原小学校講堂として建てられた規模の大きな講堂。建築面積九八〇平方メートルで、建ちが高く、柱形を見せる洋風外観が特徴的。外部両側面には当初よりバットレスを取り、内部は当初はバルコニーを巡らしていた。地域の歴史的景観を今に伝える建物である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012078"},{"id":"00012268","register_sub_id":"101","register_pk":"353069","name":"綾陽校記念館","kana":"りょうようこうきねんかん","category":"学校","subcategory":"建築物","type_guess":"記念館・資料室","type_guess_confidence":"high","period":"明治","pref":"宮崎県","address":"宮崎県東諸県郡綾町大字北俣1012","lat":32.004241,"lng":131.248717,"geo_status":"db","era":"明治21年／昭和32年・同53年・同60年移築、昭和53年増築","year":1888,"year_source":"db","year_min":1888,"year_max":1888,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積212㎡","structure_material":"木造平屋建","registered":"2018.03.27(平成30.03.27)","register_no":"45-94","desc":"綾小学校校舎として建築され、三度の移築を経て現在地に移されたもの。桁行二七メートルに及ぶ寄棟造桟瓦葺。外壁簓子下見板張、内部漆喰壁とし、西側に廊下を通し、東側に教室３室を並べる構成をとる。当時の標準的な小学校校舎の有様をよく示す建築である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012268"},{"id":"00005692","register_sub_id":"101","register_pk":"106680","name":"池地小中学校旧奉安殿","kana":"いけじしょうちゅうがっこうきゅうほうあんでん","category":"学校","subcategory":"建築物","type_guess":"記念館・資料室","type_guess_confidence":"high","period":"昭和前","pref":"鹿児島県","address":"鹿児島県大島郡瀬戸内町池地","lat":28.02990182,"lng":129.239258,"geo_status":"db","era":"昭和10","year":1935,"year_source":"db","year_min":1935,"year_max":1935,"year_label":null,"structure":"鉄筋コンクリート造平屋建、建築面積4.2㎡、基壇及び柵付","structure_material":"鉄筋コンクリート造平屋建","registered":"2006.08.03(平成18.08.03)","register_no":"46 － 0028","desc":"校庭側を向いて西面して建つ。御真影と教育勅語を奉安していた。下に柵付の基壇，上には平高欄付の基壇を築く。鉄筋コンクリート造，切妻造，平入で，四隅に角柱を型取り，軒は一軒疎垂木とし，棟には千木，堅男木をつける。神社建築を範とした奉安殿である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005692"},{"id":"00006663","register_sub_id":"101","register_pk":"107646","name":"今里小中学校旧奉安殿","kana":"いまざとしょうちゅうがっこうきゅうほうあんでん","category":"学校","subcategory":"建築物","type_guess":"記念館・資料室","type_guess_confidence":"high","period":"昭和前","pref":"鹿児島県","address":"鹿児島県大島郡大和村今里字クツレ361-1","lat":28.326511,"lng":129.278366,"geo_status":"db","era":"昭和13","year":1938,"year_source":"db","year_min":1938,"year_max":1938,"year_label":null,"structure":"鉄筋コンクリート造平屋建、建築面積4.5㎡、基壇付","structure_material":"鉄筋コンクリート造平屋建","registered":"2007.12.05(平成19.12.05)","register_no":"46 － 0059","desc":"敷地の最奥、山裾に北面して建つ。切妻造平入の鉄筋コンクリート造で、正面に戸口を開け、周囲に組高欄を廻す。方柱で、組物はなく、一軒疎垂木とし、妻には懸魚を付ける。建築当初位置に残り、基壇を２段に造り、正面に石段７級を設け、威厳のある外貌を造る。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006663"},{"id":"00004194","register_sub_id":"101","register_pk":"105184","name":"鹿児島県立鹿児島工業高等学校大煙突","kana":"かごしまけんりつかごしまこうぎょうこうとうがっこうだいえんとつ","category":"学校","subcategory":"その他工作物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"鹿児島県","address":"鹿児島県鹿児島市草牟田2-57-1","lat":31.60855194,"lng":130.53835522,"geo_status":"db","era":"大正9","year":1920,"year_source":"db","year_min":1920,"year_max":1920,"year_label":null,"structure":"煉瓦造、高さ18m、ボイラー付","structure_material":"煉瓦造","registered":"2004.06.09(平成16.06.09)","register_no":"46 － 0015","desc":"機械科で使用する工作機械を稼働させるためのスチームボイラーとともに建設。高さ１８ｍの煉瓦造煙突で，八角形の基部をイギリス積，塔身を小口積として構築する。径１．２ｍ長４．５ｍの鉄製ボイラーとともに学校や地域の景観に欠かせない存在となっている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004194"},{"id":"00006293","register_sub_id":"101","register_pk":"107276","name":"鹿児島県立鹿児島中央高等学校本館及び講堂","kana":"かごしまけんりつかごしまちゅうおうこうとうがっこうほんかんおよびこうどう","category":"学校","subcategory":"建築物","type_guess":"講堂","type_guess_confidence":"high","period":"昭和前","pref":"鹿児島県","address":"鹿児島県鹿児島市加治屋町10-1","lat":31.586428,"lng":130.54985,"geo_status":"db","era":"昭和10","year":1935,"year_source":"db","year_min":1935,"year_max":1935,"year_label":null,"structure":"鉄筋コンクリート造3階一部4階建、建築面積2866㎡、塔屋付","structure_material":"鉄筋コンクリート造3階一部4階建","registered":"2007.07.31(平成19.07.31)","register_no":"46 － 0038","desc":"敷地西側に建つ。ＲＣ造３階一部４階建で，平面はロの字形で，南北５５ｍ，東西７７ｍ，幅１１ｍの規模とする。南東に講堂を置き，北西隅を曲面でつくり正面玄関とし，上部アーチ状の縦型窓を開き，円形平面の４階部分をつくるなど，ＲＣ造の特徴を活かす。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006293"},{"id":"00006292","register_sub_id":"101","register_pk":"107275","name":"鹿児島県立甲南高等学校本館","kana":"かごしまけんりつこうなんこうとうがっこうほんかん","category":"学校","subcategory":"建築物","type_guess":"記念館・資料室","type_guess_confidence":"low","period":"昭和前","pref":"鹿児島県","address":"鹿児島県鹿児島市上之園町23-1","lat":31.57931987,"lng":130.54649656,"geo_status":"db","era":"昭和5","year":1930,"year_source":"db","year_min":1930,"year_max":1930,"year_label":null,"structure":"鉄筋コンクリート造3階建、建築面積2412㎡、塔屋付","structure_material":"鉄筋コンクリート造3階建","registered":"2007.07.31(平成19.07.31)","register_no":"46 － 0037","desc":"敷地北側及び東側に寄って建つ。鉄筋コンクリート造３階建で，平面はＬ字形で，幅１０ｍ，北側長さ１１２ｍ，東側長さ８２ｍの規模とする。北東隅の曲面部に正面玄関を置き，上部はドーム状の塔屋とする。初期のＲＣ造の学校建築として貴重。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006292"},{"id":"00005775","register_sub_id":"101","register_pk":"106763","name":"鹿児島大学総合研究博物館常設展示室","kana":"かごしまだいがくそうごうけんきゅうはくぶつかんじょうせつてんじしつ","category":"学校","subcategory":"建築物","type_guess":"校舎","type_guess_confidence":"low","period":"昭和前","pref":"鹿児島県","address":"鹿児島県鹿児島市郡元1-21-24","lat":31.57162985,"lng":130.54604416,"geo_status":"db","era":"昭和3／平成15改修","year":1928,"year_source":"db","year_min":1928,"year_max":1928,"year_label":null,"structure":"鉄筋コンクリート造2階建、建築面積105㎡","structure_material":"鉄筋コンクリート造2階建","registered":"2006.10.18(平成18.10.18)","register_no":"46 － 0032","desc":"敷地の北東方に位置し，北面して建つ。間口１１ｍ，奥行９ｍ，鉄筋コンクリート造２階建とする。前身の鹿児島高等農林学校の図書館書庫として建てられた建物で，学校建築における初期の鉄筋コンクリート建造物として貴重である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005775"},{"id":"00007706","register_sub_id":"101","register_pk":"108688","name":"川上中学校本校舎","kana":"かわかみちゅうがっこうほんこうしゃ","category":"学校","subcategory":"建築物","type_guess":"校舎","type_guess_confidence":"high","period":"昭和中","pref":"鹿児島県","address":"鹿児島県肝属郡肝付町後田6339-23","lat":31.28424734,"lng":130.9507361,"geo_status":"db","era":"昭和24／昭和36・昭和47改修","year":1949,"year_source":"db","year_min":1949,"year_max":1949,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積331㎡","structure_material":"木造平屋建","registered":"2009.04.28(平成21.04.28)","register_no":"46 － 0081","desc":"校地の東寄りに南北棟で建つ。切妻造桟瓦葺で、外壁を下見板張とし、東・西面各４ヶ所にバットレスを付ける。運動場側の西側を廊下とし、当初は中央南寄りを土間床の通路とし、北に３教室、南に職員室を配した。山間に残る木造校舎で、風情ある佇まいを見せる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007706"},{"id":"00007147","register_sub_id":"101","register_pk":"108129","name":"旧鹿児島県立尋常中学校門","kana":"きゅうかごしまけんりつじんじょうちゅうがっこうもん","category":"学校","subcategory":"その他工作物","type_guess":"正門","type_guess_confidence":"high","period":"明治","pref":"鹿児島県","address":"鹿児島県鹿児島市山下町14-1","lat":31.5997441,"lng":130.5572479,"geo_status":"db","era":"明治27","year":1894,"year_source":"db","year_min":1894,"year_max":1894,"year_label":null,"structure":"石造門柱2基、間口3.1m、両側通用門付","structure_material":"石造門柱2基","registered":"2008.04.18(平成20.04.18)","register_no":"46 － 0064","desc":"旧県庁舎敷地西辺中央に位置する。鹿児島県立尋常中学校創設時の正門で、間口３．１ｍ、本柱の高さ２．３ｍ、脇柱の高さ２．２ｍの規模をもつ洋風石造門。県立尋常中学校正門、県立図書館正門、県庁舎裏門として使用され、旧県庁舎敷地の変遷を見続けてきた。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007147"},{"id":"00005695","register_sub_id":"101","register_pk":"106683","name":"旧木慈小学校奉安殿","kana":"きゅうきじしょうがっこうほうあんでん","category":"学校","subcategory":"建築物","type_guess":"記念館・資料室","type_guess_confidence":"high","period":"昭和前","pref":"鹿児島県","address":"鹿児島県大島郡瀬戸内町木慈","lat":28.16023791,"lng":129.21902529,"geo_status":"db","era":"昭和10","year":1935,"year_source":"db","year_min":1935,"year_max":1935,"year_label":null,"structure":"鉄筋コンクリート造平屋建、建築面積3.7㎡、基壇付","structure_material":"鉄筋コンクリート造平屋建","registered":"2006.08.03(平成18.08.03)","register_no":"46 － 0031","desc":"旧校内に西面して建ち，御真影と教育勅語を奉安していた。高欄付の基壇上にあり，鉄筋コンクリート造，切妻造，平入で，軒は一軒疎垂木，破風に懸魚，棟に千木と堅男木をつける。四隅に角柱を型取り，壁面は洗い出し仕上げとする。神社建築を範とした奉安殿。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005695"},{"id":"00014127","register_sub_id":"101","register_pk":"508387","name":"旧山尋常高等小学校校舎","kana":"きゅうさんじんじょうしょうがっこうこうしゃ","category":"学校","subcategory":"建築物","type_guess":"校舎","type_guess_confidence":"high","period":"昭和前","pref":"鹿児島県","address":"鹿児島県大島郡徳之島町山字兼久田1808-イ","lat":27.86682778,"lng":128.95683333,"geo_status":"db","era":"昭和4年","year":1929,"year_source":"db","year_min":1929,"year_max":1929,"year_label":null,"structure":"鉄筋コンクリート造2階建、建築面積65㎡","structure_material":"鉄筋コンクリート造2階建","registered":"2021.10.14(令和3.10.14)","register_no":"46 - 0127","desc":"徳之島北東部に位置し、敷地奥に南面して建つ。鉄筋コンクリート造二階建。外観は隅の柱型を見せ、入口に庇を付し、壁面は等間隔に横目地を切る。内部は前面に玄関や階段室を配し、一、二階とも奥を教室とする。島内現存最古の鉄筋コンクリート造学校建築。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014127"},{"id":"00005690","register_sub_id":"101","register_pk":"106678","name":"古仁屋小学校旧奉安殿","kana":"こにやしょうがっこうきゅうほうあんでん","category":"学校","subcategory":"建築物","type_guess":"記念館・資料室","type_guess_confidence":"high","period":"昭和前","pref":"鹿児島県","address":"鹿児島県大島郡瀬戸内町古仁屋小勝原","lat":28.15006225,"lng":129.31444903,"geo_status":"db","era":"昭和4頃","year":1929,"year_source":"db","year_min":1929,"year_max":1929,"year_label":null,"structure":"鉄筋コンクリート造平屋建、建築面積6.0㎡、柵付","structure_material":"鉄筋コンクリート造平屋建","registered":"2006.08.03(平成18.08.03)","register_no":"46 － 0026","desc":"御真影と教育勅語を奉安していた。鉄筋コンクリート造で，四隅に角柱を型取り，上部にコーニスを廻し，陸屋根で正背面にペディメント風の飾りをつける。洋風建築細部を備え，堅牢で風格あるつくりである。一段低い校庭側に西面して建ち，今なお存在感がある。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005690"},{"id":"00005693","register_sub_id":"101","register_pk":"106681","name":"薩川小学校旧奉安殿","kana":"さつかわしょうがっこうきゅうほうあんでん","category":"学校","subcategory":"建築物","type_guess":"記念館・資料室","type_guess_confidence":"high","period":"昭和前","pref":"鹿児島県","address":"鹿児島県大島郡瀬戸内町薩川","lat":28.18034901,"lng":129.20320043,"geo_status":"db","era":"昭和10","year":1935,"year_source":"db","year_min":1935,"year_max":1935,"year_label":null,"structure":"鉄筋コンクリート造平屋建、鉄板葺、建築面積3.5㎡、基壇及び柵付","structure_material":"鉄筋コンクリート造平屋建","registered":"2006.08.03(平成18.08.03)","register_no":"46 － 0029","desc":"校内南東隅に西面して建ち，御真影と教育勅語を奉安していた。下に柵付の基壇，上に刎高欄付の基壇を築く。鉄筋コンクリート造，切妻造，平入で，四隅に角柱を型取り，内法長押を廻し，軒は一軒疎垂木とする。神社建築を範とした奉安殿で，良好な状態を保つ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005693"},{"id":"00014444","register_sub_id":"101","register_pk":"511433","name":"山小学校校舎","kana":"さんしょうがっこうこうしゃ","category":"学校","subcategory":"建築物","type_guess":"校舎","type_guess_confidence":"high","period":"昭和中","pref":"鹿児島県","address":"鹿児島県大島郡徳之島町山1808-イ","lat":27.86695,"lng":128.95671667,"geo_status":"db","era":"昭和30年／同44年増築","year":1955,"year_source":"db","year_min":1955,"year_max":1955,"year_label":null,"structure":"鉄筋コンクリート造2階建、建築面積334㎡","structure_material":"鉄筋コンクリート造2階建","registered":"2022.10.31(令和4.10.31)","register_no":"46 - 0128","desc":"徳之島北東部に所在する校舎。鉄筋コンクリート造二階建、各階北側に教室を二室並べ、南側は開放廊下とし、西端に階段室を付す。後年更に西側に各階一室増築。平面等が米国民政府工務交通局の二階建４教室標準設計に共通し、正面の開放廊下が印象的な校舎。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014444"},{"id":"00006562","register_sub_id":"101","register_pk":"107545","name":"鹿浦小学校旧奉安殿","kana":"しかうらしょうがっこうきゅうほうあんでん","category":"学校","subcategory":"建築物","type_guess":"記念館・資料室","type_guess_confidence":"high","period":"昭和前","pref":"鹿児島県","address":"鹿児島県大島郡伊仙町阿三字為の当2206-5","lat":27.69112015,"lng":128.91987461,"geo_status":"db","era":"昭和13頃","year":1938,"year_source":"db","year_min":1938,"year_max":1938,"year_label":null,"structure":"鉄筋コンクリート造平屋建、建築面積4.3㎡、基壇付","structure_material":"鉄筋コンクリート造平屋建","registered":"2007.07.31(平成19.07.31)","register_no":"46 － 0045","desc":"学校敷地の東端に建つ。間口２．２ｍ，奥行１．９ｍの規模で，鉄筋コンクリート造平屋建とする。石造の基壇の上に建ち，切妻屋根正面に柱２本を立て，向拝唐破風の屋根を付けた形式とし，四隅に円柱の柱形や長押形を造り出し，伝統的な外観とする。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006562"},{"id":"00005694","register_sub_id":"101","register_pk":"106682","name":"須子茂小学校旧奉安殿","kana":"すこもしょうがっこうきゅうほうあんでん","category":"学校","subcategory":"建築物","type_guess":"記念館・資料室","type_guess_confidence":"high","period":"昭和前","pref":"鹿児島県","address":"鹿児島県大島郡瀬戸内町須子茂","lat":28.147732,"lng":129.210541,"geo_status":"db","era":"昭和10","year":1935,"year_source":"db","year_min":1935,"year_max":1935,"year_label":null,"structure":"鉄筋コンクリート造平屋建、建築面積4.2㎡、基壇付","structure_material":"鉄筋コンクリート造平屋建","registered":"2006.08.03(平成18.08.03)","register_no":"46 － 0030","desc":"校内北東部に西面して建ち，御真影と教育勅語を奉安していた。刎高欄付の基壇上にあり，鉄筋コンクリート造，切妻造，平入で，軒は一軒疎垂木，棟に千木と堅男木をつける。四隅に角柱を型取り，壁面は洗い出し仕上げとする。神社建築を範とした奉安殿である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005694"},{"id":"00005691","register_sub_id":"101","register_pk":"106679","name":"節子小中学校旧奉安殿","kana":"せつこしょうちゅうがっこうきゅうほうあんでん","category":"学校","subcategory":"建築物","type_guess":"記念館・資料室","type_guess_confidence":"high","period":"昭和前","pref":"鹿児島県","address":"鹿児島県大島郡瀬戸内町節子","lat":28.16591834,"lng":129.38298706,"geo_status":"db","era":"昭和10","year":1935,"year_source":"db","year_min":1935,"year_max":1935,"year_label":null,"structure":"鉄筋コンクリート造平屋建、建築面積4.6㎡、基壇付","structure_material":"鉄筋コンクリート造平屋建","registered":"2006.08.03(平成18.08.03)","register_no":"46 － 0027","desc":"校庭側を向いて西面してあり，御真影と教育勅語を奉安していた。鉄筋コンクリート造で，高欄を廻した壇正積風の基壇上に建つ。切妻造，平入の形式で，四隅に円柱を型取り，内法長押を廻し，桁を受け，軒は一軒疎垂木を型取る。神社建築を範とした奉安殿である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005691"},{"id":"00005696","register_sub_id":"101","register_pk":"106684","name":"旧国頭農学校玄関","kana":"きゅうくにがみのうがっこうげんかん","category":"学校","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"沖縄県","address":"沖縄県名護市字宇茂佐13","lat":26.595928,"lng":127.96312,"geo_status":"db","era":"明治35／昭和40移築","year":1902,"year_source":"db","year_min":1902,"year_max":1902,"year_label":null,"structure":"木造、瓦葺、面積9.4㎡","structure_material":"木造","registered":"2006.08.03(平成18.08.03)","register_no":"47 － 0017","desc":"唐破風造の吹放ち玄関で，正面柱間３．６ｍ。琉球赤瓦葺とする。角柱上の組物は大斗，実肘木で，虹梁を受け，板蟇股と斗，実肘木で棟木を受ける。破風は拝みと起りの中程に茨をつけ，拝懸魚を飾り，竿縁天井とする。沖縄における伝統意匠の数少ない遺構である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005696"}];
